export interface ContextSnapshot {
  /** Role this context targeted. */
  role: string;
  /** The base orchestrator system prompt. */
  systemPrompt: string;
  /** Whether tools were sent natively (true) vs. as prompted JSON instructions. */
  nativeTools: boolean;
  /** Project direction in effect, or null when the workspace ships none. */
  projectContext: string;
  /**
   * Tool descriptors advertised to the role, captured in the order advertised.
   * Any change to the tool set (membership or order) yields a different hash and
   * therefore a new context snapshot.
   */
  tools: ToolDescriptor[];
}

// Use a namespaced subdirectory so the file is clearly Agent.Local's
// (rather than something a different tool might also try to read).
const DEFAULT_RELATIVE_PATH = path.join("src", "context", "agentcontext.md");

export class ContextLoader
{
  constructor(private readonly contextsDir: string) {};

  resolveTarget(workspaceRoot: string, override: string | undefined): string {
    if (!override || override.length === 0) {
      return path.resolve(workspaceRoot, DEFAULT_RELATIVE_PATH);
    }
    return path.isAbsolute(override)
      ? path.resolve(override)
      : path.resolve(workspaceRoot, override);
  }

  hashContextSnapshot(snapshot: ContextSnapshot): string {
    return createHash("sha256").update(JSON.stringify(snapshot)).digest("hex").slice(0, 16);
  }

  public buildContext(
    role: string,
    systemPrompt: string,
    projectTemplate: string,
    tools: ToolDescriptor[],
    nativeTools: boolean
  ): ContextSnapshot {
    return {
      role,
      systemPrompt,
      nativeTools,
      projectContext: projectTemplate,
      tools,
    };
  }

  public async saveContextSnapshot(
    snapshot: ContextSnapshot
  ): Promise<string> {
    const dir = path.resolve(this.contextsDir);
    const hash = this.hashContextSnapshot(snapshot);
    const target = path.join(dir, `${hash}.json`);

    try {
      await fs.access(target);
      return hash; // already captured — nothing to do
    } catch {
      // not present — fall through and write it
    }

    await fs.mkdir(dir, { recursive: true });
    const tmp = `${target}.tmp`;
    await fs.writeFile(tmp, JSON.stringify(snapshot, null, 2), "utf8");
    await fs.rename(tmp, target);
    return hash;
  }

  /**
   * Read a previously saved snapshot by hash. Returns null when no such snapshot
   * exists (e.g. a session persisted before snapshots, or a pruned contexts dir).
   */
  public async getContextSnapshot(
    hash: string
  ): Promise<ContextSnapshot | null> {
    // Sanitise the hash so a malformed pointer can't escape the contexts dir.
    const safe = hash.replace(/[^a-zA-Z0-9_.-]/g, "_");
    const target = path.join(path.resolve(this.contextsDir), `${safe}.json`);
    try {
      return JSON.parse(await fs.readFile(target, "utf8")) as ContextSnapshot;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }
}

/**
 * Substitute the {TOOLS_LIST} placeholder in a role prompt template.
 */
export function fillToolsList(template: string, tools: ToolDescriptor[]): string {
  const list = tools.map((t) => `  - ${t.name}`).join("\n");
  return template.replace("{TOOLS_LIST}", list);
}

import fs from "node:fs/promises";
import path from "node:path";

import type { ChatMessage } from "../providers/provider.js";

/**
 * Per-conversation lifecycle record, persisted as a `<id>.meta.json` sidecar
 * next to the transcript. Deletion is SOFT: `deletedAt` marks the conversation
 * dead for every normal read path, while the JSONL file itself is retained as
 * the audit copy until some future retention sweep hard-deletes it.
 */
export interface ConversationMeta {
  conversationId: string;
  /** Epoch millis when the conversation was first opened. */
  createdAt: number;
  /** Epoch millis when it was soft-deleted; null while alive. */
  deletedAt: number | null;
}

/**
 * ConversationStore — Repository layer.
 *
 * Persists one JSONL file per conversation under `<sessionsDir>/conversations`.
 * JSONL (one JSON-encoded message per line) was chosen over the session's
 * pretty-printed JSON because the hot operation is APPEND: adding a message is
 * a single `appendFile` of one line, never a rewrite of the whole transcript.
 * Full rewrites happen only on the rare structural events (summarize, compact,
 * reset) and go through temp file + rename so a crash mid-write can never
 * corrupt an existing conversation file.
 */
export class ConversationStore {
  private constructor(private readonly directory: string) {}

  /** `sessionsDir` is the session store's directory; conversations live in a
   *  sibling-free subfolder so session pickers globbing `*.json` never see them. */
  public static create(sessionsDir: string): ConversationStore {
    return new ConversationStore(path.resolve(sessionsDir, "conversations"));
  }

  public async append(conversationId: string, messages: readonly ChatMessage[]): Promise<void> {
    if (messages.length === 0) return;
    await fs.mkdir(this.directory, { recursive: true });
    const lines = messages.map((message) => JSON.stringify(message)).join("\n") + "\n";
    await fs.appendFile(this.fileFor(conversationId), lines, "utf8");
  }

  /**
   * Load every message of a conversation; null when no file exists yet OR the
   * conversation is soft-deleted — deleted transcripts are filtered out of
   * every normal select, readable only by going to the file directly (audit).
   * Unparseable lines (a torn last line from a crash mid-append) are skipped
   * rather than failing the whole load — the transcript up to the tear is
   * still usable.
   */
  public async load(conversationId: string): Promise<ChatMessage[] | null> {
    const meta = await this.readMeta(conversationId);
    if (meta?.deletedAt) return null;

    let raw: string;
    try {
      raw = await fs.readFile(this.fileFor(conversationId), "utf8");
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }

    const messages: ChatMessage[] = [];
    for (const line of raw.split(/\r?\n/)) {
      if (line.trim().length === 0) continue;
      try {
        messages.push(JSON.parse(line) as ChatMessage);
      } catch {
        /* torn line — skip */
      }
    }
    return messages;
  }

  /**
   * Replace the whole file atomically — for summarize/compact/trim. With
   * `backup`, the outgoing transcript is first preserved by a plain rename to
   * `<id>.bak.json` (O(1), no copy): summarization is lossy, so the
   * pre-summary generation stays on disk for audit/undo. Trim passes
   * false — dropping one dangling tool_use is healing, not history.
   */
  public async rewrite(
    conversationId: string,
    messages: readonly ChatMessage[],
    options: { backup?: boolean } = {}
  ): Promise<void> {
    await fs.mkdir(this.directory, { recursive: true });
    const target = this.fileFor(conversationId);
    if (options.backup) {
      await this.renameIfExists(target, this.backupFileFor(conversationId, "bak"));
    }
    const tmp = `${target}.tmp`;
    const body = messages.map((message) => JSON.stringify(message)).join("\n");
    await fs.writeFile(tmp, body.length > 0 ? body + "\n" : "", "utf8");
    await fs.rename(tmp, target);
  }

  // --------------------------------------------------------------------------
  // Lifecycle metadata (create/delete dates, soft-delete flag)
  // --------------------------------------------------------------------------

  /** Read the lifecycle record; null when none was ever written. */
  public async readMeta(conversationId: string): Promise<ConversationMeta | null> {
    try {
      const raw = await fs.readFile(this.metaFileFor(conversationId), "utf8");
      return JSON.parse(raw) as ConversationMeta;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  /** Create the lifecycle record if missing; returns the current one either way. */
  public async ensureMeta(conversationId: string): Promise<ConversationMeta> {
    const existing = await this.readMeta(conversationId);
    if (existing) return existing;
    const meta: ConversationMeta = {
      conversationId,
      createdAt: Date.now(),
      deletedAt: null,
    };
    await this.writeMeta(meta);
    return meta;
  }

  /**
   * Soft-delete: stamp `deletedAt` and move the transcript aside by a plain
   * rename to `<id>.deleted.json` — the audit copy a future retention sweep
   * can hard-delete. Idempotent — a second call keeps the original timestamp
   * and finds no live file to rename.
   */
  public async markDeleted(conversationId: string): Promise<ConversationMeta> {
    const meta = await this.ensureMeta(conversationId);
    if (meta.deletedAt === null) {
      meta.deletedAt = Date.now();
      await this.writeMeta(meta);
    }
    await this.renameIfExists(
      this.fileFor(conversationId),
      this.backupFileFor(conversationId, "deleted")
    );
    return meta;
  }

  public async isDeleted(conversationId: string): Promise<boolean> {
    const meta = await this.readMeta(conversationId);
    return meta?.deletedAt != null;
  }

  private async writeMeta(meta: ConversationMeta): Promise<void> {
    await fs.mkdir(this.directory, { recursive: true });
    const target = this.metaFileFor(meta.conversationId);
    const tmp = `${target}.tmp`;
    await fs.writeFile(tmp, JSON.stringify(meta, null, 2), "utf8");
    await fs.rename(tmp, target);
  }

  /**
   * Map a conversationId to its file. The id is sanitised so a hostile or
   * malformed value can't escape the store directory via path traversal.
   */
  private fileFor(conversationId: string): string {
    return path.join(this.directory, `${sanitize(conversationId)}.jsonl`);
  }

  private metaFileFor(conversationId: string): string {
    return path.join(this.directory, `${sanitize(conversationId)}.meta.json`);
  }

  /** `<id>.bak.json` / `<id>.deleted.json`. Fixed names by design: a new
   *  backup replaces the previous one (rename overwrites), so only the latest
   *  pre-rewrite generation is kept per conversation. */
  private backupFileFor(conversationId: string, kind: "bak" | "deleted"): string {
    return path.join(this.directory, `${sanitize(conversationId)}.${kind}.json`);
  }

  private async renameIfExists(from: string, to: string): Promise<void> {
    try {
      await fs.rename(from, to);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
      throw err;
    }
  }
}

function sanitize(conversationId: string): string {
  return conversationId.replace(/[^a-zA-Z0-9_.-]/g, "_");
}

/**
 * Conversation — the unit of transcript state, split out of `Session`.
 *
 * The session keeps only the `conversationId` link; the messages live here and
 * in a rolling JSONL file owned by the ConversationStore. The in-memory array
 * is the working copy the orchestrator appends to during a turn; `flushedCount`
 * is the watermark of how many of those messages are already on disk, so a
 * flush appends ONLY the new tail instead of rewriting the transcript.
 *
 * Writes are chained through `pendingWrite` so an end-of-round flush can never
 * interleave with a summarization rewrite racing it.
 */
export class Conversation {
  private flushedCount: number;
  private pendingWrite: Promise<void> = Promise.resolve();

  private constructor(
    public readonly conversationId: string,
    private readonly store: ConversationStore,
    private readonly messages: ChatMessage[]
  ) {
    this.flushedCount = messages.length;
  }

  /**
   * Open a conversation by id: load the rolling file when it exists, start
   * empty otherwise. Loaded messages count as flushed — they came FROM disk.
   * Ensures the lifecycle record exists so `createdAt` is stamped the first
   * time a conversation comes alive.
   */
  public static async open(store: ConversationStore, conversationId: string): Promise<Conversation> {
    await store.ensureMeta(conversationId);
    const messages = (await store.load(conversationId)) ?? [];
    return new Conversation(conversationId, store, messages);
  }

  public get length(): number {
    return this.messages.length;
  }

  /** Live view of the transcript. Readonly: all mutation must go through
   *  append/replaceAll so the disk watermark stays truthful. */
  public getMessages(): readonly ChatMessage[] {
    return this.messages;
  }

  /** Add messages to the in-memory transcript. Cheap and synchronous — disk is
   *  only touched by the next flush (end of round / finalize). */
  public append(...messages: ChatMessage[]): void {
    this.messages.push(...messages);
  }

  /** Append every not-yet-persisted message to the rolling file. */
  public flush(): Promise<void> {
    return this.enqueue(async () => {
      if (this.flushedCount >= this.messages.length) return;
      // Capture the slice bounds before awaiting: append() may add more
      // messages while the write is in flight; they belong to the NEXT flush.
      const upTo = this.messages.length;
      await this.store.append(this.conversationId, this.messages.slice(this.flushedCount, upTo));
      this.flushedCount = upTo;
    });
  }

  /**
   * Replace the whole transcript (summarization, compaction) and rewrite the
   * file atomically; the outgoing generation is kept as `<id>.bak.json`.
   * After this the entire new content is on disk.
   */
  public replaceAll(messages: ChatMessage[]): Promise<void> {
    this.messages.length = 0;
    this.messages.push(...messages);
    // Move the watermark synchronously with the swap: a flush already queued
    // ahead of the rewrite must see "nothing to append", not splice new-
    // transcript lines onto the old file.
    this.flushedCount = this.messages.length;
    return this.enqueue(async () => {
      await this.store.rewrite(this.conversationId, this.messages, { backup: true });
      this.flushedCount = this.messages.length;
    });
  }

  /**
   * Soft-delete this conversation — the session-reset path. The transcript is
   * retained on disk as `<id>.deleted.json` for audit; from here on the
   * conversation must not be appended to (the session links a fresh one).
   */
  public markDeleted(): Promise<void> {
    return this.enqueue(async () => {
      await this.store.markDeleted(this.conversationId);
    });
  }

  /**
   * Drop a dangling tool_use tail: if a previous run was interrupted after the
   * assistant's tool_use was recorded but before its result arrived, the next
   * user message would land right after an unanswered tool_use. Called on
   * resume; rewrites the file when the trimmed message was already persisted.
   */
  public async trimDanglingToolCalls(): Promise<boolean> {
    const last = this.messages[this.messages.length - 1];
    if (!(last?.role === "assistant" && last.toolCalls && last.toolCalls.length > 0)) {
      return false;
    }
    this.messages.pop();
    if (this.flushedCount > this.messages.length) {
      await this.enqueue(async () => {
        // No backup: dropping one dangling tool_use is healing, not history.
        await this.store.rewrite(this.conversationId, this.messages);
        this.flushedCount = this.messages.length;
      });
    }
    return true;
  }

  /** Serialize disk operations so flushes and rewrites never interleave. */
  private enqueue(operation: () => Promise<void>): Promise<void> {
    this.pendingWrite = this.pendingWrite.then(operation);
    return this.pendingWrite;
  }
}

export interface Principal {
  /** Subject identifier — the canonical "who" (OIDC `sub` claim). */
  sub: string;
  /** Issuer that granted this identity, if known. */
  iss?: string;
  /** True only when a handler successfully validated real credentials. */
  isAuthenticated: boolean;
  /** Raw claim bag — standard OIDC names (`name`, `email`, `roles`, …). */
  claims: Record<string, string | string[]>;
  /** Capability grants, e.g. `["read:workspace", "execute:tools"]`. */
  scopes: string[];
}

/**
 * Tri-state result produced by an IAuthenticationHandler:
 *   authenticated — handler validated credentials and built a principal
 *   failed        — credentials were presented but rejected (e.g. expired JWT)
 *   none          — no credentials present; pipeline may try the next handler
 */
export type AuthenticateResult =
  | { state: "authenticated"; principal: Principal }
  | { state: "failed"; reason: string }
  | { state: "none" };

/** Credentials forwarded into the identity pipeline. */
export interface IdentityContext {
  /** Bearer token, API key, or any opaque credential string. */
  token?: string;
  userId?: string;
}

/**
 * Sentinel returned when no handler authenticates the caller. The session
 * still gets a valid Principal — downstream code only checks `isAuthenticated`.
 */
export const ANONYMOUS_PRINCIPAL: Principal = {
  sub: "anonymous",
  isAuthenticated: false,
  claims: {},
  scopes: [],
};

/**
 * One tool owned by a `LocalMcp`: an advertised descriptor (bare,
 * unnamespaced name) plus a direct in-process invocation. The invoke
 * function is expected to catch its own domain errors and shape them into a
 * `ToolExecutionResult`, so each server keeps its historical error wording.
 */
export interface LocalTool {
  readonly descriptor: ToolDescriptor;
  invoke(args: Record<string, unknown>): Promise<ToolExecutionResult>;
}

/**
 * An in-process MCP: same shape as a spawned server from the registry's
 * perspective, but tool calls are plain function calls — no SDK `Server`,
 * no transport, no JSON-RPC round-trip.
 */
export class LocalMcp implements Mcp {
  private readonly toolsByName = new Map<string, LocalTool>();

  constructor(public readonly name: string, tools: LocalTool[]) {
    for (const tool of tools) {
      this.toolsByName.set(tool.descriptor.name, tool);
    }
  }

  public listTools(): ToolDescriptor[] {
    return [...this.toolsByName.values()].map((tool) => ({
      name: `${this.name}__${tool.descriptor.name}`,
      description: tool.descriptor.description,
      inputSchema: tool.descriptor.inputSchema,
    }));
  }

  public async callTool(toolName: string, args: Record<string, unknown>): Promise<ToolExecutionResult> {
    const tool = this.toolsByName.get(toolName);
    if (!tool) {
      return {
        isError: true,
        content: `Unknown tool "${toolName}" on server "${this.name}".`,
      };
    }

    try {
      return await tool.invoke(args);
    } catch (err) {
      // Safety net only — tool adapters shape their own errors above this.
      return {
        isError: true,
        content: `Tool "${toolName}" threw: ${(err as Error).message}`,
      };
    }
  }

  public async shutdown(): Promise<void> {
    // Nothing to release: no process, no connection.
  }
}

import { Client } from "@modelcontextprotocol/sdk/client/index.js";

import type { ToolDescriptor } from "../providers/provider.js";
import type { ToolExecutionResult } from "./mcp.js";

export type { ToolExecutionResult } from "./mcp.js";

/**
 * Minimal tool-dispatch surface. Both the concrete `McpClient` and the
 * per-workspace `ScopedToolClient` satisfy it, so callers that only need to
 * invoke a tool (the executor, the orchestrator's direct read calls) can depend
 * on the abstraction rather than the concrete client.
 */
export interface ToolInvoker {
  callTool(name: string, args: Record<string, unknown>): Promise<ToolExecutionResult>;
}

/**
 * Single-server MCP client.
 *
 * Wraps one MCP server connection. Manages tool discovery and invocation
 * for that server only. Stateless — returns POCO results to the caller,
 * which decides what to do (emit, log, etc.).
 */
export class McpClient {
  private tools: ToolDescriptor[];
  private readonly toolIndex = new Map<string, string>();
  constructor(
    private readonly serverName: string,
    private readonly client: Client,
    tools: ToolDescriptor[]
  ) {
    this.tools = tools;
    for (const tool of tools) {
      this.toolIndex.set(tool.name, tool.name);
    }
  }

  public get name(): string {
    return this.serverName;
  }

  public listTools(): ToolDescriptor[] {
    return this.tools.map((tool) => ({
      name: `${this.serverName}__${tool.name}`,
      description: tool.description,
      inputSchema: tool.inputSchema,
    }));
  }

  public async callTool(toolName: string, args: Record<string, unknown>): Promise<ToolExecutionResult> {
    if (!this.toolIndex.has(toolName)) {
      return {
        isError: true,
        content: `Unknown tool "${toolName}" on server "${this.serverName}".`,
      };
    }

    try {
      const response = await this.client.callTool({
        name: toolName,
        arguments: args,
      });

      const text = extractTextContent(response.content);
      return {
        isError: response.isError === true,
        content: text,
      };
    } catch (err) {
      return {
        isError: true,
        content: `Tool "${toolName}" threw: ${(err as Error).message}`,
      };
    }
  }

  public async shutdown(): Promise<void> {
    try {
      await this.client.close();
    } catch {
      // Best-effort
    }
  }

  public static async createFromConnection(
    serverName: string,
    client: Client
  ): Promise<McpClient> {
    const toolsResponse = await client.listTools();
    const tools: ToolDescriptor[] = toolsResponse.tools.map((tool) => ({
      name: tool.name,
      description: tool.description ?? "",
      inputSchema: (tool.inputSchema ?? {}) as Record<string, unknown>,
    }));

    return new McpClient(serverName, client, tools);
  }
}

function extractTextContent(content: unknown): string {
  if (!Array.isArray(content)) return "";
  const parts: string[] = [];
  for (const block of content) {
    if (block && typeof block === "object" && "type" in block && (block as { type: string }).type === "text") {
      parts.push((block as { text?: string }).text ?? "");
    }
  }
  return parts.join("\n");
}

export interface ToolExecutionResult {
  isError: boolean;
  content: string;
  /**
   * Token cost the tool itself incurred (e.g. an executor dispatch running a
   * child model loop). The orchestrator folds this into the calling session's
   * counters, so delegated usage is part of the standard tool contract rather
   * than a side channel. Omitted by tools that consume no model tokens.
   */
  usage?: TokenUsage;
}

/**
 * Minimal tool-dispatch surface. Both the `McpRegistry` and the per-workspace
 * `ScopedToolClient` satisfy it, so callers that only need to invoke a tool
 * (the executor, the orchestrator's direct read calls) can depend on the
 * abstraction rather than the concrete client.
 */
export interface ToolInvoker {
  callTool(name: string, args: Record<string, unknown>): Promise<ToolExecutionResult>;
}

/**
 * A mounted MCP: a named server that owns a set of tools.
 *
 * This is the registry's only view of a server — it never sees transports or
 * processes. Two implementations exist:
 *
 *   - `ExternalMcp` — a spawned executable (e.g. codemcp) reached over stdio
 *     JSON-RPC; a genuinely separate service.
 *   - `LocalMcp`    — plain in-process code that looks like an MCP but invokes
 *     its tool handlers directly (fsmcp, excel, subsessions).
 *
 * Contract: `listTools()` advertises namespaced descriptors
 * (`<name>__<tool>`); `callTool()` takes the bare tool name — the registry
 * strips the namespace when routing.
 */
export interface Mcp {
  readonly name: string;
  listTools(): ToolDescriptor[];
  callTool(toolName: string, args: Record<string, unknown>): Promise<ToolExecutionResult>;
  shutdown(): Promise<void>;
}

export interface AnthropicProviderConfig {
  apiKey: string;
  model: string;
  supportsNativeTools: boolean;
  /**
   * Per-request output cap when a caller does not specify one. The default is
   * comfortably high because chat() streams the response — see DEFAULT_MAX_TOKENS.
   */
  defaultMaxTokens?: number;
}

// Safe to set high because chat() streams via messages.stream() + finalMessage()
// rather than the non-streaming create(), which would hit SDK HTTP timeouts as
// max_tokens climbs past ~16K. Opus supports up to 128K output over a stream.
const DEFAULT_MAX_TOKENS = 16000;
const DEFAULT_TEMPERATURE = 0.2;

/**
 * Span back to the second conversation breakpoint. Cache lookup walks back at
 * most 20 content blocks from a breakpoint; a dispatch-heavy iteration can
 * append more than that in one go, so a trailing breakpoint alone would fail
 * to find the entry the previous call wrote. Keeping a second breakpoint ~15
 * blocks behind the tail guarantees a hit point inside the window.
 */
const LOOKBACK_BLOCK_SPAN = 15;

export class AnthropicProvider implements LLMProvider {
  public readonly providerName = "anthropic";
  public readonly modelId: string;
  public readonly supportsNativeTools: boolean;

  private readonly client: Anthropic;
  private readonly defaultMaxTokens: number;

  constructor(config: AnthropicProviderConfig) {
    this.modelId = config.model;
    this.supportsNativeTools = config.supportsNativeTools;
    this.defaultMaxTokens = config.defaultMaxTokens ?? DEFAULT_MAX_TOKENS;
    this.client = new Anthropic({ apiKey: config.apiKey });
  }

  public async chat(messages: ChatMessage[], options: ChatOptions): Promise<ChatResponse> {
    const { system, anthropicMessages } = toAnthropicMessages(messages);

    // Rolling conversation cache: each call's prompt extends the previous
    // call's, so breakpoints near the tail let iteration N read iteration
    // N-1's entire prompt at cache-read price and pay full price only for
    // the delta (new tool results + the new user turn).
    applyMessageBreakpoints(anthropicMessages);

    const request: Anthropic.MessageCreateParamsNonStreaming = {
      model: this.modelId,
      max_tokens: options.maxTokens ?? this.defaultMaxTokens,
      temperature: options.temperature ?? DEFAULT_TEMPERATURE,
      messages: anthropicMessages,
    };

    if (system.length > 0) {
      // Prompt caching: mark the last system block as a cache breakpoint. Render
      // order is tools -> system -> messages, so a breakpoint here caches the
      // whole stable prefix (tool definitions + system) as one ephemeral entry.
      // The orchestrator re-sends this identical prefix every iteration; after
      // the first write it reads back at ~0.1x input cost. 5-minute TTL (the
      // ephemeral default) comfortably outlasts a single chatty turn.
      system[system.length - 1] = {
        ...system[system.length - 1],
        cache_control: { type: "ephemeral" },
      };
      request.system = system;
    }

    // Only advertise tools when the model supports native function calling and
    // the caller actually offered some — matching OllamaProvider's contract.
    if (this.supportsNativeTools && options.tools.length > 0) {
      request.tools = options.tools.map(toAnthropicTool);
    }

    const startedAt = Date.now();
    let response;
    try {
      // Stream the response so high max_tokens values don't trip the SDK's
      // non-streaming HTTP timeout. We still collect the full message before
      // returning — finalMessage() yields the same Anthropic.Message that
      // create() would have, so everything downstream is unchanged.
      const stream = this.client.messages.stream(request, { signal: options.signal });
      response = await stream.finalMessage();
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Provider(anthropic:${this.modelId}) failed: ${errorMsg}. ` +
        `Check that the API key is valid and the model "${this.modelId}" is available.`
      );
    }
    const totalDurationMs = Date.now() - startedAt;

    const { content, toolCalls } = fromAnthropicContent(response.content);

    const message: ChatMessage = {
      role: "assistant",
      content,
      toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
    };

    return {
      message,
      hasToolCalls: toolCalls.length > 0,
      usage: {
        inputTokens: response.usage.input_tokens,
        outputTokens: response.usage.output_tokens,
        // null (no caching this request) is normalised to undefined so callers
        // can treat "unsupported" and "zero" uniformly via ?? 0.
        cacheReadInputTokens: response.usage.cache_read_input_tokens ?? undefined,
        cacheCreationInputTokens: response.usage.cache_creation_input_tokens ?? undefined,
        totalDurationMs,
      },
    };
  }
}

/**
 * Place the two moving conversation breakpoints, walking blocks from the end:
 * one on the very last content block (the next call extends this prompt, so
 * it reads everything up to here as a cache hit), and one LOOKBACK_BLOCK_SPAN
 * blocks earlier (so THIS call still finds the entry the previous call wrote
 * even when a single iteration appended more than the 20-block window).
 *
 * String message content is normalised to a single text block when it has to
 * carry a marker — byte-equivalent for the API; only block objects can hold
 * cache_control. Counts CONTENT BLOCKS, not messages: a user turn batching
 * five tool_results is five blocks. Budget: 2 here + 1 on system = 3 of the
 * allowed 4 breakpoints.
 *
 * Mutates in place — chat() builds these arrays fresh per call.
 */
export function applyMessageBreakpoints(messages: Anthropic.MessageParam[]): void {
  let blocksFromEnd = 0;

  for (let m = messages.length - 1; m >= 0; m -= 1) {
    const message = messages[m];
    const blocks: Anthropic.ContentBlockParam[] =
      typeof message.content === "string"
        ? [{ type: "text", text: message.content }]
        : message.content;

    for (let b = blocks.length - 1; b >= 0; b -= 1) {
      blocksFromEnd += 1;
      if (blocksFromEnd === 1 || blocksFromEnd === LOOKBACK_BLOCK_SPAN + 1) {
        (blocks[b] as { cache_control?: { type: "ephemeral" } }).cache_control = {
          type: "ephemeral",
        };
        message.content = blocks; // persist the string→block normalisation
        if (blocksFromEnd > 1) return; // both breakpoints placed
      }
    }
  }
}

/**
 * Split a flat ChatMessage[] into Anthropic's (system, messages) pair.
 * System messages are concatenated into a single top-level system text block
 * (so chat() can attach one cache breakpoint to it); tool results are folded
 * into user-turn `tool_result` blocks.
 */
function toAnthropicMessages(messages: ChatMessage[]): {
  system: Anthropic.TextBlockParam[];
  anthropicMessages: Anthropic.MessageParam[];
} {
  const systemParts: string[] = [];
  const out: Anthropic.MessageParam[] = [];

  for (const message of messages) {
    switch (message.role) {
      case "system": {
        if (message.content.length > 0) systemParts.push(message.content);
        break;
      }

      case "tool": {
        const block: Anthropic.ToolResultBlockParam = {
          type: "tool_result",
          tool_use_id: message.toolCallId ?? "",
          content: message.content,
        };
        // Merge into the previous user turn if it is already a tool_result
        // batch; otherwise open a new user turn for it.
        const last = out[out.length - 1];
        if (last && last.role === "user" && isToolResultBatch(last.content)) {
          (last.content as Anthropic.ContentBlockParam[]).push(block);
        } else {
          out.push({ role: "user", content: [block] });
        }
        break;
      }

      case "assistant": {
        if (message.toolCalls && message.toolCalls.length > 0) {
          const blocks: Anthropic.ContentBlockParam[] = [];
          if (message.content.trim().length > 0) {
            blocks.push({ type: "text", text: message.content });
          }
          for (const call of message.toolCalls) {
            blocks.push({
              type: "tool_use",
              id: call.id,
              name: call.name,
              input: call.arguments,
            });
          }
          out.push({ role: "assistant", content: blocks });
        } else {
          out.push({ role: "assistant", content: nonEmpty(message.content) });
        }
        break;
      }

      case "user": {
        out.push({ role: "user", content: nonEmpty(message.content) });
        break;
      }
    }
  }

  // Heal any tool_use ⇄ tool_result pairing the source transcript left broken
  // (e.g. a turn interrupted after the assistant's tool_use was recorded but
  // before its results) before handing the array to the API, which rejects an
  // unmatched tool_use outright.
  // System parts collapse into a single text block (one cacheable unit). An
  // empty array means "no system prompt" — chat() omits the field entirely.
  const system: Anthropic.TextBlockParam[] =
    systemParts.length > 0 ? [{ type: "text", text: systemParts.join("\n\n") }] : [];

  return { system, anthropicMessages: repairToolPairing(out) };
}

/** Placeholder result for a tool_use whose real result was never recorded. */
const MISSING_TOOL_RESULT =
  "[tool result unavailable — the previous run was interrupted before this tool completed]";

/**
 * Ensure every assistant `tool_use` block is answered by a `tool_result` in the
 * immediately-following user turn — the invariant the Messages API enforces.
 *
 * A persisted transcript can violate it: if a turn is interrupted (error,
 * abort) after the assistant's tool_use is recorded but before the tool runs,
 * the session is saved ending on a dangling tool_use, and the next user message
 * lands right after it. Rather than reject such a transcript, we synthesize an
 * error-flagged tool_result for each unanswered id and fold it into the
 * following user turn (so no two consecutive user turns are created), or append
 * a fresh user turn when nothing follows.
 */
export function repairToolPairing(messages: Anthropic.MessageParam[]): Anthropic.MessageParam[] {
  const result: Anthropic.MessageParam[] = [];

  for (let i = 0; i < messages.length; i += 1) {
    const message = messages[i];
    result.push(message);

    if (message.role !== "assistant" || !Array.isArray(message.content)) continue;

    const toolUseIds = message.content
      .filter((block) => blockType(block) === "tool_use")
      .map((block) => (block as Anthropic.ToolUseBlockParam).id);
    if (toolUseIds.length === 0) continue;

    const next = messages[i + 1];
    const providedIds =
      next && next.role === "user" && Array.isArray(next.content)
        ? next.content
            .filter((block) => blockType(block) === "tool_result")
            .map((block) => (block as Anthropic.ToolResultBlockParam).tool_use_id)
        : [];

    const missing = toolUseIds.filter((id) => !providedIds.includes(id));
    if (missing.length === 0) continue;

    const synthetic: Anthropic.ToolResultBlockParam[] = missing.map((id) => ({
      type: "tool_result",
      tool_use_id: id,
      content: MISSING_TOOL_RESULT,
      is_error: true,
    }));

    if (next && next.role === "user") {
      // Lead the next user turn with the synthetic results, keeping it a single
      // user turn. Replace the upcoming element so it is emitted merged.
      const nextBlocks: Anthropic.ContentBlockParam[] = Array.isArray(next.content)
        ? next.content
        : [{ type: "text", text: next.content }];
      messages[i + 1] = { role: "user", content: [...synthetic, ...nextBlocks] };
    } else {
      // Nothing (or an assistant turn) follows: insert a standalone results turn.
      result.push({ role: "user", content: synthetic });
    }
  }

  return result;
}

/** The discriminant `type` of a content block param, or undefined for a string. */
function blockType(block: Anthropic.ContentBlockParam | string): string | undefined {
  return typeof block === "object" && block !== null
    ? (block as { type?: string }).type
    : undefined;
}

/** True when every block in a user turn is a tool_result (a result batch). */
function isToolResultBatch(content: Anthropic.MessageParam["content"]): boolean {
  return (
    Array.isArray(content) &&
    content.length > 0 &&
    content.every((b) => typeof b === "object" && b !== null && (b as { type?: string }).type === "tool_result")
  );
}

/** Anthropic rejects empty message content; substitute a placeholder. */
function nonEmpty(text: string): string {
  return text.length > 0 ? text : "(no content)";
}

function fromAnthropicContent(content: Anthropic.ContentBlock[]): {
  content: string;
  toolCalls: ToolCall[];
} {
  const texts: string[] = [];
  const toolCalls: ToolCall[] = [];

  for (const block of content) {
    if (block.type === "text") {
      texts.push(block.text);
    } else if (block.type === "tool_use") {
      toolCalls.push({
        id: block.id,
        name: block.name,
        arguments: (block.input ?? {}) as Record<string, unknown>,
      });
    }
  }

  return { content: texts.join("\n"), toolCalls };
}

function toAnthropicTool(descriptor: ToolDescriptor): Anthropic.Tool {
  return {
    name: descriptor.name,
    description: descriptor.description,
    input_schema: descriptor.inputSchema as Anthropic.Tool.InputSchema,
  };
}

import { GoogleGenAI } from "@google/genai";
import type {
  Content,
  FunctionDeclaration,
  GenerateContentResponse,
  Part,
  Tool,
} from "@google/genai";

import type {
  ChatMessage,
  ChatOptions,
  ChatResponse,
  LLMProvider,
  ToolCall,
  ToolDescriptor,
} from "./provider.js";

export interface GeminiProviderConfig {
  apiKey: string;
  model: string;
  supportsNativeTools: boolean;
  defaultMaxTokens?: number;
}

const DEFAULT_MAX_TOKENS = 8192;
const DEFAULT_TEMPERATURE = 0.2;
const CACHE_TTL_SECONDS = 300;
const CACHE_TTL = `${CACHE_TTL_SECONDS}s`;
/** Recreate the cache this long before server-side expiry, so an in-flight
 *  request can't reference an entry that lapses mid-call. */
const CACHE_EXPIRY_MARGIN_MS = 30_000;

export class GeminiProvider implements LLMProvider {
  public readonly providerName = "gemini";
  public readonly modelId: string;
  public readonly supportsNativeTools: boolean;

  private readonly client: GoogleGenAI;
  private readonly defaultMaxTokens: number;

  // Prompt cache for the stable prefix (system instruction + tools).
  // One cache entry per provider instance; invalidated when the key changes
  // or the server-side TTL lapses (entries are deleted server-side at
  // expireTime — reusing a lapsed name fails the request outright).
  private cachedContentName: string | undefined;
  private cacheKey: string | undefined;
  private cacheExpiresAtMs: number | undefined;

  constructor(config: GeminiProviderConfig) {
    this.modelId = config.model;
    this.supportsNativeTools = config.supportsNativeTools;
    this.defaultMaxTokens = config.defaultMaxTokens ?? DEFAULT_MAX_TOKENS;
    this.client = new GoogleGenAI({ apiKey: config.apiKey });
  }

  public async chat(messages: ChatMessage[], options: ChatOptions): Promise<ChatResponse> {
    const { systemInstruction, contents } = toGeminiMessages(messages);
    const tools: Tool[] =
      this.supportsNativeTools && options.tools.length > 0
        ? [{ functionDeclarations: options.tools.map(toGeminiTool) }]
        : [];

    const startedAt = Date.now();

    const cachedContent = await this.ensureCache(systemInstruction, tools);

    // When a cache is active it already contains system + tools, so they must
    // be omitted from the per-request config to avoid an API conflict.
    const config: Record<string, unknown> = {
      temperature: options.temperature ?? DEFAULT_TEMPERATURE,
      maxOutputTokens: options.maxTokens ?? this.defaultMaxTokens,
      abortSignal: options.signal,
    };
    if (cachedContent) {
      config.cachedContent = cachedContent;
    } else {
      if (systemInstruction) config.systemInstruction = systemInstruction;
      if (tools.length > 0) config.tools = tools;
    }

    let response;
    try {
      response = await this.client.models.generateContent({
        model: this.modelId,
        contents,
        config,
      });
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Provider(gemini:${this.modelId}) failed: ${errorMsg}. ` +
        `Check that the API key is valid and the model "${this.modelId}" is available.`
      );
    }

    const totalDurationMs = Date.now() - startedAt;
    const { content, toolCalls } = fromGeminiResponse(response);

    const message: ChatMessage = {
      role: "assistant",
      content,
      toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
    };

    return {
      message,
      hasToolCalls: toolCalls.length > 0,
      usage: {
        inputTokens: response.usageMetadata?.promptTokenCount ?? undefined,
        outputTokens: response.usageMetadata?.candidatesTokenCount ?? undefined,
        // Tokens served from the cache (~0.1x input price).
        cacheReadInputTokens: response.usageMetadata?.cachedContentTokenCount ?? undefined,
        totalDurationMs,
      },
    };
  }

  /**
   * Create or reuse a Gemini context cache for the stable system+tools prefix.
   * Cache creation silently fails when the content is below Gemini's minimum
   * token threshold (typically 32 K) or the model doesn't support caching;
   * in those cases we fall through to passing system/tools inline every call.
   */
  private async ensureCache(
    systemInstruction: string | undefined,
    tools: Tool[]
  ): Promise<string | undefined> {
    if (!systemInstruction && tools.length === 0) return undefined;

    const key = JSON.stringify({ systemInstruction, tools });
    if (
      key === this.cacheKey &&
      this.cachedContentName &&
      this.cacheExpiresAtMs !== undefined &&
      Date.now() < this.cacheExpiresAtMs - CACHE_EXPIRY_MARGIN_MS
    ) {
      return this.cachedContentName;
    }

    try {
      const cacheConfig: Record<string, unknown> = { ttl: CACHE_TTL };
      if (systemInstruction) cacheConfig.systemInstruction = systemInstruction;
      if (tools.length > 0) cacheConfig.tools = tools;

      const cache = await this.client.caches.create({
        model: this.modelId,
        config: cacheConfig,
      });

      this.cachedContentName = cache.name;
      this.cacheKey = key;
      this.cacheExpiresAtMs = cacheExpiryMs(cache.expireTime, Date.now());
      return cache.name;
    } catch {
      // Too few tokens or model doesn't support context caching — inline fallback.
      this.cachedContentName = undefined;
      this.cacheKey = undefined;
      this.cacheExpiresAtMs = undefined;
      return undefined;
    }
  }
}

/**
 * Resolve when a created cache entry lapses, as epoch millis. Prefers the
 * server-reported `expireTime` (authoritative — the server deletes the entry
 * then); falls back to now + the requested TTL when the field is absent or
 * unparseable, which errs on the early side and merely recreates sooner.
 */
export function cacheExpiryMs(expireTime: string | undefined, nowMs: number): number {
  const parsed = expireTime ? Date.parse(expireTime) : NaN;
  return Number.isFinite(parsed) ? parsed : nowMs + CACHE_TTL_SECONDS * 1000;
}

/**
 * Split a flat ChatMessage[] into Gemini's (systemInstruction, Content[]) pair.
 *
 * Differences from the Anthropic format:
 *  - System messages become the top-level systemInstruction string.
 *  - Assistant messages use role "model" instead of "assistant".
 *  - Tool calls are functionCall parts inside a model turn.
 *  - Tool results are functionResponse parts inside a user turn, merged with
 *    any immediately preceding user turn to keep role alternation intact.
 */
export function toGeminiMessages(messages: ChatMessage[]): {
  systemInstruction: string | undefined;
  contents: Content[];
} {
  const systemParts: string[] = [];
  const contents: Content[] = [];

  for (const message of messages) {
    switch (message.role) {
      case "system": {
        if (message.content.length > 0) systemParts.push(message.content);
        break;
      }

      case "user": {
        const last = contents[contents.length - 1];
        if (last?.role === "user") {
          last.parts = [...(last.parts ?? []), { text: message.content }];
        } else {
          contents.push({ role: "user", parts: [{ text: message.content }] });
        }
        break;
      }

      case "assistant": {
        const parts: Part[] = [];
        if (message.content.trim().length > 0) {
          parts.push({ text: message.content });
        }
        if (message.toolCalls && message.toolCalls.length > 0) {
          for (const call of message.toolCalls) {
            const part: Part = {
              functionCall: { id: call.id, name: call.name, args: call.arguments },
            };
            // Echo the thinking-model signature back verbatim. Gemini 400s on a
            // replayed functionCall part that is missing its original signature.
            if (call.signature) part.thoughtSignature = call.signature;
            parts.push(part);
          }
        }
        if (parts.length === 0) parts.push({ text: "(no content)" });
        contents.push({ role: "model", parts });
        break;
      }

      case "tool": {
        // functionResponse blocks belong in user turns. Merge into the previous
        // user turn when possible (same pattern as Anthropic's tool_result batch).
        const part: Part = {
          functionResponse: {
            id: message.toolCallId,
            name: message.toolName ?? "",
            response: { output: message.content },
          },
        };
        const last = contents[contents.length - 1];
        if (last?.role === "user") {
          last.parts = [...(last.parts ?? []), part];
        } else {
          contents.push({ role: "user", parts: [part] });
        }
        break;
      }
    }
  }

  return {
    systemInstruction: systemParts.length > 0 ? systemParts.join("\n\n") : undefined,
    contents,
  };
}

/**
 * Reduce a Gemini response to (content, toolCalls).
 *
 * We walk `candidates[0].content.parts` directly rather than using the SDK's
 * `response.functionCalls` / `response.text` getters, because those convenience
 * getters discard the per-part `thoughtSignature`. Thinking models require that
 * signature to be echoed back on the next turn, so we must read it off the raw
 * part and carry it on the ToolCall. `thought` parts are the model's reasoning
 * summary, not answer text, so they're skipped when assembling `content`.
 */
export function fromGeminiResponse(response: GenerateContentResponse): {
  content: string;
  toolCalls: ToolCall[];
} {
  const parts: Part[] = response.candidates?.[0]?.content?.parts ?? [];
  const textChunks: string[] = [];
  const toolCalls: ToolCall[] = [];

  for (const part of parts) {
    if (part.functionCall) {
      const fc = part.functionCall;
      toolCalls.push({
        // Gemini function call ids are optional; fall back to the name so the
        // toolCallId on the matching tool-result message stays consistent.
        id: fc.id ?? fc.name ?? "unknown",
        name: fc.name ?? "unknown",
        arguments: fc.args ?? {},
        signature: part.thoughtSignature,
      });
    } else if (typeof part.text === "string" && !part.thought) {
      textChunks.push(part.text);
    }
  }

  return { content: textChunks.join(""), toolCalls };
}

function toGeminiTool(descriptor: ToolDescriptor): FunctionDeclaration {
  return {
    name: descriptor.name,
    description: descriptor.description,
    parametersJsonSchema: descriptor.inputSchema,
  };
}

import { AnthropicProvider } from "./anthropic-provider.js";
import { GeminiProvider } from "./gemini-provider.js";
import { OllamaProvider } from "./ollama-provider.js";
import type { LLMProvider } from "./provider.js";

/**
 * Provider factory registry.
 *
 * To plug in a new backend, add a case here and ship the implementation
 * file alongside ollama-provider.ts. The model registry calls
 * `createProvider` to materialise providers from models.json entries.
 */

export interface ProviderFactoryInput {
  provider: string;
  model: string;
  supportsTools: boolean;
  reasoning?: boolean;
  host: string;
  /** API key for cloud providers (e.g. Anthropic, Gemini). Undefined for local backends. */
  apiKey?: string;
  /** Gemini-specific API key. Falls back to apiKey when absent. */
  geminiApiKey?: string;
}

export function createProvider(input: ProviderFactoryInput): LLMProvider {
  switch (input.provider) {
    case "ollama":
      return new OllamaProvider({
        host: input.host,
        model: input.model,
        supportsNativeTools: input.supportsTools,
        stripThinkBlocks: input.reasoning ?? false,
      });

    case "anthropic": {
      if (!input.apiKey) {
        throw new Error(
          `Model "${input.model}" uses provider "anthropic" but no API key is set. ` +
            "Add ANTHROPIC_API_KEY to your environment (.env)."
        );
      }
      return new AnthropicProvider({
        apiKey: input.apiKey,
        model: input.model,
        supportsNativeTools: input.supportsTools,
      });
    }

    case "gemini": {
      const key = input.geminiApiKey ?? input.apiKey;
      if (!key) {
        throw new Error(
          `Model "${input.model}" uses provider "gemini" but no API key is set. ` +
            "Add GEMINI_API_KEY to your environment (.env)."
        );
      }
      return new GeminiProvider({
        apiKey: key,
        model: input.model,
        supportsNativeTools: input.supportsTools,
      });
    }

    default:
      throw new Error(
        `Unknown provider "${input.provider}". Add a factory case in src/agent/providers/index.ts.`
      );
  }
}

import { Ollama, type ChatRequest, type Message as OllamaMessage, type Tool as OllamaTool } from "ollama";

import type {
  ChatMessage,
  ChatOptions,
  ChatResponse,
  LLMProvider,
  ToolCall,
} from "./provider.js";

/**
 * OllamaProvider — talks to a local Ollama daemon over HTTP.
 *
 * One instance binds to one (host, model) pair. The model registry creates
 * a fresh provider per entry in models.json.
 */

export interface OllamaProviderConfig {
  host: string;
  model: string;
  supportsNativeTools: boolean;

  /**
   * If true, strip `<think>...</think>` blocks from the assistant's
   * reply before exposing it to the agent loop. Used for reasoning
   * models like deepseek-r1 whose internal monologue should not leak
   * into the downstream prompt.
   */
  stripThinkBlocks?: boolean;
}

export class OllamaProvider implements LLMProvider {
  public readonly providerName = "ollama";
  public readonly modelId: string;
  public readonly supportsNativeTools: boolean;

  private readonly client: Ollama;
  private readonly stripThinkBlocks: boolean;

  constructor(config: OllamaProviderConfig) {
    this.modelId = config.model;
    this.supportsNativeTools = config.supportsNativeTools;
    this.stripThinkBlocks = config.stripThinkBlocks ?? false;
    this.client = new Ollama({ host: config.host });
  }

  public async chat(messages: ChatMessage[], options: ChatOptions): Promise<ChatResponse> {
    const request: ChatRequest & { stream?: false } = {
      model: this.modelId,
      messages: messages.map(toOllamaMessage),
      stream: false,
      options: {
        temperature: options.temperature ?? 0.2,
        num_predict: options.maxTokens,
      },
    };

    // Only attach tools when the model supports native function calling.
    // For non-tool models we deliberately omit the field so Ollama doesn't
    // refuse the request, and rely on the prompted-JSON adapter higher up.
    if (this.supportsNativeTools && options.tools.length > 0) {
      request.tools = options.tools.map(toOllamaTool);
    }

    const startedAt = Date.now();
    let response;
    try {
      response = await raceWithAbort(this.client.chat(request), options.signal);
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Provider(ollama:${this.modelId}) failed: ${errorMsg}. ` +
        `Check that Ollama is running and the model "${this.modelId}" is available.`
      );
    }
    const totalDurationMs = Date.now() - startedAt;

    const rawContent = response.message.content ?? "";
    const cleanedContent = this.stripThinkBlocks ? stripThinkTags(rawContent) : rawContent;

    const toolCalls = extractToolCalls(response.message);

    const message: ChatMessage = {
      role: "assistant",
      content: cleanedContent,
      toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
    };

    return {
      message,
      hasToolCalls: toolCalls.length > 0,
      usage: {
        inputTokens: response.prompt_eval_count,
        outputTokens: response.eval_count,
        totalDurationMs,
      },
    };
  }
}

function toOllamaMessage(message: ChatMessage): OllamaMessage {
  // Ollama treats tool responses as `role: "tool"` with the result in `content`.
  // Assistant tool-call requests get serialized into the `tool_calls` field.
  if (message.role === "tool") {
    return {
      role: "tool",
      content: message.content,
    };
  }

  if (message.role === "assistant" && message.toolCalls && message.toolCalls.length > 0) {
    return {
      role: "assistant",
      content: message.content,
      tool_calls: message.toolCalls.map((call) => ({
        function: {
          name: call.name,
          arguments: call.arguments,
        },
      })),
    };
  }

  return {
    role: message.role,
    content: message.content,
  };
}

function toOllamaTool(descriptor: {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}): OllamaTool {
  return {
    type: "function",
    function: {
      name: descriptor.name,
      description: descriptor.description,
      parameters: descriptor.inputSchema as OllamaTool["function"]["parameters"],
    },
  };
}

function extractToolCalls(message: OllamaMessage): ToolCall[] {
  const rawCalls = (message as OllamaMessage & { tool_calls?: Array<{ function: { name: string; arguments: Record<string, unknown> } }> }).tool_calls;
  if (!rawCalls || rawCalls.length === 0) return [];

  return rawCalls.map((raw, index) => ({
    // Ollama does not assign IDs to tool calls; we synthesise stable ones.
    id: `call_${Date.now()}_${index}`,
    name: raw.function.name,
    arguments: raw.function.arguments ?? {},
  }));
}

/**
 * Reasoning models (deepseek-r1, qwq, etc.) wrap their chain-of-thought in
 * `<think>...</think>` blocks. We keep the thinking off the wire to the
 * executor model so the prompt stays focused on the conclusions.
 */
function stripThinkTags(content: string): string {
  return content.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
}

/**
 * The ollama client offers no per-request AbortSignal, so without this a user
 * stop would hang until a long generation finished. Racing the request against
 * the signal unwinds the agent promptly; the daemon still completes (and
 * discards) the generation server-side — abandoning it is the best the client
 * API allows.
 */
function raceWithAbort<T>(work: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return work;
  return new Promise<T>((resolve, reject) => {
    if (signal.aborted) {
      reject(new Error("request aborted before send"));
      return;
    }
    const onAbort = () => reject(new Error("request aborted"));
    signal.addEventListener("abort", onAbort, { once: true });
    work.then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (err) => {
        signal.removeEventListener("abort", onAbort);
        reject(err);
      }
    );
  });
}

export interface ChatMessage {
  role: "system" | "user" | "assistant" | "tool";
  content: string;

  /**
   * Present on assistant messages that requested tool execution.
   * The agent loop reads this to know which tools to dispatch next.
   */
  toolCalls?: ToolCall[];

  /**
   * Present on `role: "tool"` messages. Identifies which tool call
   * this message is responding to (must match a prior toolCalls[].id).
   */
  toolCallId?: string;

  /**
   * Optional human-readable label for tool responses.
   */
  toolName?: string;
}

export interface ToolCall {
  id: string;
  name: string;
  arguments: Record<string, unknown>;

  /**
   * Opaque provider round-trip token. Some thinking models (Gemini) attach a
   * `thoughtSignature` to each function-call part and reject (HTTP 400) any
   * later request that replays the call without it. Capturing it here lets the
   * signature survive session persistence and be echoed back verbatim on the
   * next turn. Undefined for providers that don't use it (Anthropic, Ollama).
   */
  signature?: string;
}

export interface ToolDescriptor {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

export interface ChatOptions {
  /**
   * Tools the model is allowed to call this turn. Empty array = no tool use.
   * The provider must honour this — never invent or pre-fill tools.
   */
  tools: ToolDescriptor[];

  /** Sampling temperature. Lower = more deterministic. */
  temperature?: number;

  /** Maximum tokens to generate this turn. Provider may clamp. */
  maxTokens?: number;

  /**
   * AbortSignal callers can use to cancel an in-flight request
   * (e.g. when the user hits Ctrl+C in the REPL).
   */
  signal?: AbortSignal;
}

export interface ChatResponse {
  message: ChatMessage;

  /**
   * True if the provider produced one or more tool calls this turn.
   * Equivalent to `message.toolCalls && message.toolCalls.length > 0`,
   * provided here as a convenience so callers can switch on it cleanly.
   */
  hasToolCalls: boolean;

  /**
   * Optional usage stats for cost/latency visibility. Providers that
   * don't expose this may leave it undefined.
   */
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    /**
     * Tokens served from the prompt cache (~0.1x input price). Present only
     * for providers that support prompt caching; verifies cache hits land.
     */
    cacheReadInputTokens?: number;
    /** Tokens written to the prompt cache this request (~1.25x input price). */
    cacheCreationInputTokens?: number;
    totalDurationMs?: number;
  };
}

export interface LLMProvider {
  /**
   * Stable name used in logs and errors, e.g. "ollama" or "lmstudio".
   * Does NOT identify a specific model — see `modelId` for that.
   */
  readonly providerName: string;

  /**
   * The underlying model identifier the provider will hit
   * (e.g. "qwen2.5-coder:14b" for Ollama). Used for telemetry only.
   */
  readonly modelId: string;

  /**
   * Whether this model can be given an Ollama/OpenAI-style `tools`
   * array and respond with structured tool calls. False means the
   * agent should fall back to prompted JSON tool calls.
   */
  readonly supportsNativeTools: boolean;

  chat(messages: ChatMessage[], options: ChatOptions): Promise<ChatResponse>;
}

export interface ModelDefinition {
  provider: string;
  model: string;
  supportsTools: boolean;
  reasoning?: boolean;
  description?: string;
  mcp?: string[];
}

export interface OrchestrationConfig {
  /** Hard cap on orchestrator LLM turns per user message. */
  maxOrchestratorIterations: number;
  /** Hard cap on executor__dispatch calls per user message. */
  maxExecutorDispatchesPerTurn: number;
  /** Hard cap on executor LLM turns per single dispatch. */
  maxExecutorIterationsPerAsk: number;
  orchestratorTemperature: number;
  executorTemperature: number;
  /** Sampling temperature for the evaluator (completion-gate) judge. */
  evaluatorTemperature: number;
  /**
   * Run the evaluator as a progress check every this-many successful
   * executor dispatches, not only at completion. Catches no-progress
   * loops mid-flight. Set very high to effectively disable.
   */
  validatorCheckIntervalDispatches: number;
  /**
   * Summarize the conversation prefix once it grows beyond this many
   * messages. Lower = more aggressive compaction, more summarizer LLM
   * calls. Set very high to effectively disable.
   */
  summarizeAtMessages: number;
  /**
   * After summarizing, keep this many recent messages verbatim. The
   * orchestrator may keep slightly more to avoid splitting a tool-call /
   * tool-result pairing.
   */
  summarizerKeepLastN: number;
}

export interface ModelsFile {
  models: Record<string, ModelDefinition>;
  roles: Record<string, string>;
  orchestration: Partial<OrchestrationConfig>
}

export class ConfigurationRegistry
{
    private modelsConfig? : ModelsFile;

    constructor(private configPath: string) {
    }

    public async getModelsConfiguration() : Promise<ModelsFile> {
        if (this.modelsConfig)
        {
            return this.modelsConfig;
        }
        const absolutePath = path.resolve(this.configPath);
        const raw = await fs.readFile(absolutePath, "utf8");
        const parsed = JSON.parse(raw) as ModelsFile;

        if (!parsed.models || Object.keys(parsed.models).length === 0) {
        throw new Error(`${absolutePath} declares no models.`);
        }
        if (!parsed.roles || Object.keys(parsed.roles).length === 0) {
        throw new Error(`${absolutePath} declares no role assignments.`);
        }

        parsed.orchestration = this.mergeOrchestration(parsed.orchestration);

        this.modelsConfig = parsed;
        return this.modelsConfig;
    }

    private mergeOrchestration(
        raw: Partial<OrchestrationConfig> | undefined
        ): OrchestrationConfig {
        if (!raw) return { ...DEFAULT_ORCHESTRATION };

        // Strip the legacy keys before merging.
        const {
            ...current
        } = raw;

        return { ...DEFAULT_ORCHESTRATION, ...current };
    }
}

export { WorkspaceRegistry, type Workspace } from "./workspace-registry.js";
export { ModelRegistry } from "./model-registry.js";
export { ProvidersRegistry } from "./providers-registry.js";
export { ConfigurationRegistry, ModelDefinition, ModelsFile } from "./configuration-registry.js";
export { McpClientRegistry } from "./mcp-registry.js";

export class McpClientRegistry {
  private clients = new Map<string, Mcp>();
  private workspaceRootValue: string;

  constructor(workspaceRoot: string) {
    this.workspaceRootValue = workspaceRoot;
  }

  public get sandboxRoot(): string {
    return this.workspaceRootValue;
  }

  public registerClient(client: Mcp): void {
    // server name
    this.clients.set(client.name, client);
  }
  public getClient(serverName: string): Mcp | undefined {
    return this.clients.get(serverName);
  }
  public listTools(): ToolDescriptor[] {
    const flattened: ToolDescriptor[] = [];
    for (const client of this.clients.values()) {
      flattened.push(...client.listTools());
    }
    return flattened;
  }
}

import { ORCHESTRATOR_SYSTEM_PROMPT, EXECUTOR_SYSTEM_PROMPT, REQUEST_ANCHOR_TEMPLATE } from "../context/system-prompt.js";
import { PROJECT_CONTEXT } from '../context/agentcontext.js';
import { ModelsFile, ModelDefinition } from "./configuration-registry.js";
/**
 * Model registry.
 *
 * Loads models.json, instantiates one provider per declared model, and
 * maps logical roles ("planner", "coder", "summarizer") onto those providers.
 *
 * The orchestrator only ever asks: "give me the provider for role X".
 * Swapping models therefore means editing models.json or calling
 * `assignRole`, never touching agent code.
 */

export class ModelRegistry {

  private definitions: Record<string, ModelDefinition>;
  private roleAssignments: Record<string, string>;

  constructor(private modelsFile: ModelsFile) {
    this.definitions = { ...modelsFile.models };
    this.roleAssignments = { ...modelsFile.roles };
  }

  public getProviderForRole(role: string): string {
    return this.roleAssignments[role];
  }

  public getPromptTemplate(role: string): string {
    switch (role) {
      case "project":
        return PROJECT_CONTEXT;
      case "orchestrator":
        return ORCHESTRATOR_SYSTEM_PROMPT;
      case "executor":
        return EXECUTOR_SYSTEM_PROMPT;
      default:
        throw new Error(`No prompt template for role "${role}".`);
    }
  }

  /**
   * The per-call ACTIVE REQUEST anchor with the turn's request filled in.
   * Served through the registry (not imported from the template directly) so
   * the anchor wording can be swapped — per-deployment, per-model, or from
   * config — without touching orchestrator code.
   */
  public getAnchorText(request: string): string {
    return REQUEST_ANCHOR_TEMPLATE.replace("{REQUEST}", request);
  }

  public getValidModels(): Array<string>
  {
    var result = new Array<string>();
     for (const [_, modelName] of Object.entries(this.modelsFile.roles)) {
        if (this.definitions[modelName])
          result.push(modelName)
     }
     return result;
  }

  public getRoles(): Array<string>
  {
    var result = new Array<string>();
     for (const [roleName, _] of Object.entries(this.modelsFile.roles)) {
          result.push(roleName)
     }
     return result;
  }

  public getValidMcpForModel(role: string): string[] {
    var modelName = this.roleAssignments[role];
    var model = this.definitions[modelName];
    return model.mcp || [];
  }

  public assignRole(role: string, modelId: string): void {
    if (!this.definitions[modelId]) {
      throw new Error(`Model "${modelId}" is not defined in models.json`);
    }
    this.roleAssignments[role] = modelId;
  }
}

export class ProvidersRegistry
{
    private definitions = {} as Record<string, ModelDefinition>;
    private providers = {} as Record<string, LLMProvider>;

    constructor(readonly modelsFile: ModelsFile) {}

    public loadModels()
    {
        // Build one provider per role-referenced model. models.json is the
        // sole source of truth for model selection — no env-var overrides.
        const anthropicApiKey = process.env.ANTHROPIC_API_KEY;
        const geminiApiKey = process.env.GEMINI_API_KEY;            
        const ollamaHost = process.env.OLLAMA_HOST ?? "http://localhost:11434";

        // active models
        for (const [_, def] of Object.entries(this.modelsFile.roles)) {

            var m = this.modelsFile.models[def];
            this.definitions[def] = m;
        };

        for (const [id, def] of Object.entries(this.definitions)) {
            this.providers[id] = createProvider({
                provider: def.provider,
                model: def.model,
                supportsTools: def.supportsTools,
                reasoning: def.reasoning,
                host: ollamaHost,
                apiKey: anthropicApiKey,
                geminiApiKey,
            });
        }
    }
    public getModel(name: string): ModelDefinition
    {
        return this.definitions[name];
    }
    public getProvider(name: string): LLMProvider
    {
        return this.providers[name];
    }
}

export interface Workspace {
  workspaceId: string;
  /** Root used to resolve project context (agentcontext.md). */
  root: string;
}

export class WorkspaceRegistry {
  private readonly workspaces = new Map<string, Workspace>();

  /**
   * Register a workspace, loading its context from disk. Idempotent: a
   * second call with an already-known id returns the existing entry without
   * re-reading, so joining a shared workspace is cheap.
   */
  public async register(workspaceId: string, root: string): Promise<Workspace> {
    const existing = this.workspaces.get(workspaceId);
    if (existing) return existing;

    const workspace: Workspace = { workspaceId, root };
    this.workspaces.set(workspaceId, workspace);
    return workspace;
  }

  public get(workspaceId: string): Workspace {
    const workspace = this.workspaces.get(workspaceId);
    if (!workspace) {
      throw new Error(`Unknown workspaceId "${workspaceId}". Register it before use.`);
    }
    return workspace;
  }

  public has(workspaceId: string): boolean {
    return this.workspaces.has(workspaceId);
  }

  /**
   * Re-read the context file for an already-registered workspace, picking up
   * any mid-session edits to agentcontext.md. Returns the refreshed entry.
   */
  public async reload(workspaceId: string): Promise<Workspace> {
    const workspace = this.get(workspaceId);
    const updated: Workspace = { ...workspace };
    this.workspaces.set(workspaceId, updated);
    return updated;
  }
}

export interface EvaluationVerdict {
  state: EvaluationState;
  reason: string;
}

export interface EvaluateParams {
  /** The user's original request for this turn. */
  question: string;
  /** The orchestrator's candidate final answer (its tool-free message). */
  proposedAnswer: string;
  /** The turn's working transcript, used to see what actually happened. */
  transcript: ChatMessage[];
}

export interface EvaluateOptions {
  signal?: AbortSignal;
  temperature?: number;
}

export class Evaluator {
  constructor(private readonly runtime: AgentRuntimeQueryable) {}

  public async evaluate(
    params: EvaluateParams,
    options: EvaluateOptions = {}
  ): Promise<EvaluationVerdict> {
    const modelsRegistry = this.runtime.getModelsRegistry();
    const provider = this.runtime.getProvidersRegistry().getProvider(modelsRegistry.getProviderForRole("evaluator"));
    const userMessage = [
      "ORIGINAL REQUEST:",
      params.question,
      "",
      "PROPOSED FINAL ANSWER:",
      params.proposedAnswer.trim().length > 0
        ? params.proposedAnswer
        : "(the orchestrator produced an empty message)",
      "",
      "TRANSCRIPT OF WORK DONE THIS TURN:",
      params.transcript.map(formatMessageForEvaluation).join("\n"),
    ].join("\n");

    let response;
    try {
      response = await provider.chat(
        [
          { role: "system", content: EVALUATOR_SYSTEM_PROMPT },
          { role: "user", content: userMessage },
        ],
        {
          tools: [],
          temperature: options.temperature ?? DEFAULT_TEMPERATURE,
          signal: options.signal,
        }
      );
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Evaluator (${provider.providerName}:${provider.modelId}) failed: ${errorMsg}`
      );
    }

    return parseVerdict(response.message.content);
  }
}

/**
 * Parse the single EVALUATOR verdict line. Fails OPEN: if no recognisable
 * verdict is present, we treat the turn as satisfied so a malformed judge
 * response can never trap the orchestrator in an endless loop.
 */
function parseVerdict(content: string): EvaluationVerdict {
  for (const raw of content.split("\n")) {
    const line = raw.trim();
    const match = line.match(/^EVALUATOR:\s*(SATISFIED|CONTINUE|UNSATISFIED|AWAITING-INPUT|AWAITING_INPUT)\b\s*(.*)$/i);
    if (match) {
      let state = match[1].toLowerCase().replace(/_/g, "-") as EvaluationState;
      const reason = match[2].trim() || DEFAULT_REASON[state];
      return { state, reason };
    }
  }
  return {
    state: "satisfied",
    reason: "evaluator returned no parseable verdict; defaulting to satisfied",
  };
}

const DEFAULT_REASON: Record<EvaluationState, string> = {
  satisfied: "request addressed",
  continue: "making progress; continue with the next step",
  unsatisfied: "not making progress; change approach",
  "awaiting-input": "orchestrator is waiting for user input",
};

function formatMessageForEvaluation(message: ChatMessage): string {
  switch (message.role) {
    case "user":
      return `USER: ${message.content}`;
    case "system":
      return `SYSTEM: ${truncate(message.content, 400)}`;
    case "assistant": {
      const calls = message.toolCalls?.length
        ? " [tool-calls: " + message.toolCalls.map((c) => c.name).join(", ") + "]"
        : "";
      return `ASSISTANT: ${message.content}${calls}`;
    }
    case "tool":
      return `TOOL[${message.toolName ?? ""}]: ${truncate(message.content, 600)}`;
  }
}

function truncate(text: string, max: number): string {
  return text.length > max ? text.slice(0, max) + "…" : text;
}

/**
 * InputInbox — Service-layer seam for injecting prompts into a live session.
 *
 * The orchestrator is the SOLE writer of the session's Conversation; letting an
 * outside caller mutate the transcript directly would race the in-flight loop (the
 * same race the Initializer's `running` guard exists to prevent). So injection
 * is modelled as PULL, not push: external producers (a REPL command today, an
 * HTTP API tomorrow) enqueue here, and the orchestrator DRAINS the queue at a
 * safe boundary (the top of each loop iteration) and appends the items as
 * `role:"user"` messages itself.
 *
 * Keyed by `sessionId` so one shared inbox serves the top-level session and
 * every detached sub-session. In-memory only — pending prompts do not survive
 * a restart, which is acceptable: they are transient steering, not state.
 */
export class InputInbox {
  private readonly queues = new Map<string, string[]>();

  /** Enqueue a prompt for `sessionId`. The `source` tag is reserved for future
   *  provenance (e.g. "api", "parent"); unused today but kept in the signature
   *  so producers can start passing it without a later breaking change. */
  public push(sessionId: string, content: string, _source?: string): void {
    const trimmed = content.trim();
    if (trimmed.length === 0) return;
    const queue = this.queues.get(sessionId);
    if (queue) {
      queue.push(trimmed);
    } else {
      this.queues.set(sessionId, [trimmed]);
    }
  }

  /**
   * Return everything queued for `sessionId` in FIFO order and clear it.
   * Returns an empty array when nothing is pending. The orchestrator calls
   * this once per iteration, so a drained-and-empty session costs one Map miss.
   */
  public drain(sessionId: string): string[] {
    const queue = this.queues.get(sessionId);
    if (!queue || queue.length === 0) return [];
    this.queues.delete(sessionId);
    return queue;
  }

  /** True if `sessionId` has prompts waiting (diagnostics / tests). */
  public hasPending(sessionId: string): boolean {
    const queue = this.queues.get(sessionId);
    return queue !== undefined && queue.length > 0;
  }
}

import type { Conversation } from "../conversation/conversation.js";
import type { ToolExecutionResult } from "../mcp/mcp-client.js";
import type {
  ChatMessage,
  ChatResponse,
  LLMProvider,
  ToolCall,
  ToolDescriptor,
} from "../providers/provider.js";
import {
  buildPromptedToolInstructions,
  extractPromptedToolCalls,
} from "../tool-adapter.js";
import { Summarizer, buildSummaryMessage } from "./summarizer.js";
import { Evaluator, type EvaluationVerdict } from "./evaluator.js";
import { ScopedToolClient } from "../scoped-tool-client.js";
import { foldCounters, foldDelegatedUsage } from "../session/session.js";
import type { SubSessionCoordinator } from "./subsession.js";
import { DispatchTracker } from "../synthetic-mcp/dispatch-tracker.js";
import type { ToolContext, TurnBindable } from "../synthetic-mcp/types.js";
import { createSubsessionsLocalMcp } from "../synthetic-mcp/subsessions-server.js";
import type { AgentRuntimeQueryable } from "../runtime/types.js";
import { OrchestratorEventTypes } from "./runner-events.js";
import type { OrchestratorListener, RunnerListener } from "./runner-events.js";
import { ContextSnapshot } from "../context/context-loader.js";

// Re-export for backwards compatibility
export type { OrchestratorEvent, OrchestratorListener } from "./runner-events.js";

/**
 * Orchestrator.
 *
 * Runs the agentic loop for any role (orchestrator or executor). The role
 * determines which model is used, which tools are visible, which system
 * prompt is applied, and the iteration cap.
 *
 * For the "orchestrator" role the loop coordinates via read-only tools plus
 * `executor__dispatch`; for the "executor" role it runs the write tools and
 * terminates on the first tool-free response (no evaluator gate).
 *
 * The Orchestrator is STATELESS. It holds only app-level dependencies
 * (the model registry and tool client); every piece of per-turn state —
 * the transcript and the project context — arrives as arguments to `run`
 * via the `Session` and `Workspace` it is handed. The Initializer owns
 * those objects, their lifecycle, and their persistence.
 */

export interface RunOptions {
  signal?: AbortSignal;
  onEvent?: RunnerListener;
  /**
   * Coordinator that lets this run spawn and manage sub-sessions. When present,
   * the orchestrator exposes the synthetic create/status/finalize sub-session
   * tools and intercepts them. Detached sub-session runs are launched WITHOUT a
   * coordinator, so sub-sessions are one level deep.
   */
  coordinator?: SubSessionCoordinator;
  /**
   * Pull seam for externally-injected prompts. Called at the top of each loop
   * iteration; any returned strings are appended to the conversation as user
   * turns before the model is asked. This is how an outside producer (a REPL
   * command, a future API call) steers a live run without racing the loop.
   */
  pullInjectedPrompts?: () => string[];
}

export interface RunResult {
  finalMessage: ChatMessage;
  iterations: number;
  dispatches: number;
  /**
   * How the run ended. "satisfied" — the evaluator accepted the final answer;
   * "capped" — the loop hit the orchestrator iteration cap without a satisfied
   * verdict (the natural "tried too many times / all fails" bound). Lets a
   * caller distinguish a real completion from a give-up without inspecting the
   * transcript, and drives the headless exit code.
   */
  outcome: "satisfied" | "capped";
}

/**
 * The capability the SessionManager needs to drive a sub-session: run a session
 * to completion. Declared here and satisfied structurally by `Orchestrator`, so
 * the manager depends on this narrow contract rather than the concrete class —
 * keeping the orchestrator ⇄ manager construction acyclic.
 */
export interface SessionRunner {
  run(userInput: string, options?: RunOptions): Promise<RunResult>;
}

export class Orchestrator {
  private runtime!: AgentRuntimeQueryable;

  constructor(private readonly role: string, runtime?: AgentRuntimeQueryable) {
    if (runtime) {
      this.runtime = runtime;
    }
  }

  /** Set the runtime after construction (used by AgentRuntime.build). */
  setRuntime(runtime: AgentRuntimeQueryable): void {
    this.runtime = runtime;
  }

  /**
   * Run one user turn end-to-end for the session in the runtime.
   * Appends to the runtime's Conversation (the turn's work product); holds
   * no reference to it afterward. The transcript is flushed to its rolling
   * file at the end of every round; the runtime's finalize() backstops the
   * tail on every exit path.
   */
  public async run(userInput: string, options: RunOptions = {}): Promise<RunResult> {
    const emit = options.onEvent ?? (() => {});
    const session = this.runtime.getSession();
    const workspace = this.runtime.getWorkspace();
    const modelsRegistry = this.runtime.getModelsRegistry();
    const mcpRegistry = this.runtime.getMcpClientRegistry();
    const providersRegistry = this.runtime.getProvidersRegistry();
    const conversation = this.runtime.getConversation();

    // Resolve a role's tool servers (role → model → models.json `mcp` list),
    // skipping any that are declared but not mounted (e.g. codemcp before
    // ConnectMcpServers lands), so a single scoped client fronts the whole set.
    const clientsFor = (role: string) =>
      modelsRegistry.getValidMcpForModel(role).flatMap((serverName) => {
        const client = mcpRegistry.getClient(serverName);
        return client ? [client] : [];
      });

    const config = await this.runtime.getConfigurationRegistry().getModelsConfiguration()!;
    const contextLoader = this.runtime.getContextLoader();
    // The snapshot stamped by ContextMiddleware is the ONLY source of the
    // system prompt and project direction — the runner never assembles
    // context itself, so what ran is always exactly what the hash records.
    const contextHash = session.contextHashes ? session.contextHashes[this.role] : null;
    const context = contextHash ? await contextLoader.getContextSnapshot(contextHash) : null;
    if (!context) {
      throw new Error(
        `Orchestrator: no context snapshot for role "${this.role}" ` +
          `(hash: ${contextHash ?? "unstamped"}). ContextMiddleware must run before any turn.`
      );
    }

    await this.maybeSummarize(conversation, emit, options.signal);
    conversation.append({ role: "user", content: userInput });

    const provider = providersRegistry.getProvider(modelsRegistry.getProviderForRole(this.role));

    // Re-bind the subsessions server to this turn's live coordinator so tool
    // calls land on the right instance. registerClient is keyed by server name,
    // so this replaces the placeholder in the registry.
    const coordinator = options.coordinator;
    if (coordinator) {
      const subsessionToolCtx: ToolContext = {
        session,
        workspace,
        sandboxRoot: mcpRegistry.sandboxRoot,
        coordinator,
        signal: options.signal,
      };
      mcpRegistry.registerClient(createSubsessionsLocalMcp(subsessionToolCtx));
    }

    const scopedClient = new ScopedToolClient(clientsFor(this.role), emit);
    const visibleTools = scopedClient.listTools();

    const maxDispatches = config.orchestration.maxExecutorDispatchesPerTurn!;
    const checkInterval = config.orchestration.validatorCheckIntervalDispatches ?? 0;
    const tracker = new DispatchTracker(maxDispatches, checkInterval);

    // Bind per-turn context on the executor LocalMcp only for roles that
    // actually dispatch to it (orchestrator-family). The executor sub-run
    // itself does not dispatch further, so we skip binding there to avoid
    // overwriting the parent turn's tracker while a dispatch is in-flight.
    if (this.role !== "executor") {
      const executorMcp = mcpRegistry.getClient("executor");
      if (executorMcp && typeof (executorMcp as unknown as TurnBindable).bindTurn === "function") {
        (executorMcp as unknown as TurnBindable).bindTurn(
          options.signal,
          emit as OrchestratorListener,
          tracker
        );
      }
    }

    emit({
      type: OrchestratorEventTypes.START,
      data: {
        orchestratorModel: provider.modelId,
        orchestratorTools: visibleTools,
        readToolCount: visibleTools.length,
      },
    });

    const systemMessages = this.buildSystemMessages(provider, visibleTools, context);
    const workingMessages: ChatMessage[] = [...systemMessages, ...conversation.getMessages()];

    const turnStartIndex = workingMessages.length - 1;

    // Anchor parity with the evaluator. The judge is re-told the ORIGINAL
    // REQUEST verbatim on every call — that is why it stays grounded — while
    // the orchestrator only had the request as one aging line in a transcript
    // dominated by finished goals. Re-assert it as the LAST message of every
    // chat call, transient (never pushed to the conversation).
    const requestAnchor: ChatMessage = {
      role: "system",
      content: modelsRegistry.getAnchorText(userInput),
    };

    const maxIterations =
      this.role === "executor"
        ? (config.orchestration.maxExecutorIterationsPerAsk ?? 6)
        : (config.orchestration.maxOrchestratorIterations ?? 16);

    const orchestratorTemperature = config.orchestration.orchestratorTemperature;
    const executorTemperature = config.orchestration.executorTemperature;
    const temperature = this.role === "executor" ? executorTemperature! : orchestratorTemperature!;

    for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
      if (options.signal?.aborted) {
        throw new Error("turn aborted: user requested stop");
      }

      // Drain any externally-injected prompts before asking the model.
      const injectedPrompts = options.pullInjectedPrompts?.() ?? [];
      for (const text of injectedPrompts) {
        const injected: ChatMessage = { role: "user", content: text };
        conversation.append(injected);
        workingMessages.push(injected);
        emit({ type: OrchestratorEventTypes.INJECTED_INPUT, data: { iteration, content: text } });
      }

      emit({ type: OrchestratorEventTypes.ITERATION, data: { iteration, max: maxIterations } });

      let response: ChatResponse;
      try {
        response = await provider.chat([...workingMessages, requestAnchor], {
          tools: provider.supportsNativeTools ? visibleTools : [],
          temperature,
          signal: options.signal,
        });
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        throw new Error(
          `Orchestrator (${provider.providerName}:${provider.modelId}) failed at iteration ${iteration}: ${errorMsg}`
        );
      }

      foldCounters(session.counters, response.usage);

      const { assistantMessage, toolCalls } = this.normaliseAssistantTurn(provider, response, emit);

      emit({
        type: OrchestratorEventTypes.MESSAGE,
        data: {
          iteration,
          content: assistantMessage.content,
          toolCallCount: toolCalls.length,
          usage: response.usage,
        },
      });

      conversation.append(assistantMessage);
      workingMessages.push(assistantMessage);

      if (toolCalls.length === 0) {
        // Executor: first tool-free response is the RESULT — no evaluator gate.
        if (this.role === "executor") {
          return {
            finalMessage: assistantMessage,
            iterations: iteration,
            dispatches: tracker.count,
            outcome: "satisfied",
          };
        }

        // Orchestrator: gate through the evaluator.
        const verdict = await this.evaluateCompletion(
          userInput,
          assistantMessage.content,
          workingMessages.slice(turnStartIndex),
          emit,
          options.signal
        );

        if (verdict.state === "satisfied" || verdict.state === "awaiting-input") {
          return {
            finalMessage: assistantMessage,
            iterations: iteration,
            dispatches: tracker.count,
            outcome: "satisfied",
          };
        }

        // Nudges quote the request verbatim to prevent goal drift.
        const nudge: ChatMessage = {
          role: "user",
          content:
            verdict.state === "continue"
              ? `EVALUATOR: on track — ${verdict.reason}\n` +
                `The request for THIS turn is exactly: «${userInput}»\n` +
                "Keep going: take the next concrete action toward fulfilling it. " +
                "Do not stop until it is complete."
              : `EVALUATOR: off track — ${verdict.reason}\n` +
                `The request for THIS turn is exactly: «${userInput}»\n` +
                "Stop repeating what isn't working and change your approach. Re-check this " +
                "request and the current workspace state, then take a different next action.",
        };
        conversation.append(nudge);
        workingMessages.push(nudge);
        await conversation.flush();
        continue;
      }

      const toolMessages: ChatMessage[] = [];

      for (const call of toolCalls) {
        if (options.signal?.aborted) {
          throw new Error("turn aborted: user requested stop");
        }

        const execution: ToolExecutionResult = await scopedClient.callTool(call.name, call.arguments);
        // Tools that ran a model of their own (executor dispatch) report the
        // delegated cost on the result; it lands in the *Tallied counters so
        // own chat spend and dependency spend stay separately readable.
        foldDelegatedUsage(session.counters, execution.usage);
        toolMessages.push(
          wrapToolResult(call, execution.isError ? `[tool-error] ${execution.content}` : execution.content)
        );
      }

      conversation.append(...toolMessages);
      workingMessages.push(...toolMessages);

      // Periodic progress gate (orchestrator only). Every N successful dispatches,
      // run the validator mid-flight to catch no-progress loops before they cap.
      if (this.role !== "executor" && tracker.dueForPeriodicCheck()) {
        const verdict = await this.evaluateCompletion(
          userInput,
          "(in-progress checkpoint — no final answer yet)",
          workingMessages.slice(turnStartIndex),
          emit,
          options.signal
        );
        if (verdict.state === "unsatisfied") {
          const nudge: ChatMessage = {
            role: "user",
            content:
              `EVALUATOR: off track — ${verdict.reason}\n` +
              `The request for THIS turn is exactly: «${userInput}»\n` +
              "Stop repeating what isn't working and change your approach. Re-check this " +
              "request and the current workspace state, then take a different next action.",
          };
          conversation.append(nudge);
          workingMessages.push(nudge);
        }
      }

      // End of round: persist this iteration's appends to the rolling file so
      // a crash mid-turn loses at most the round in flight.
      await conversation.flush();
    }

    const truncationNotice: ChatMessage = {
      role: "assistant",
      content:
        `ORCHESTRATOR: hit iteration cap of ${maxIterations} without a final answer. ` +
        "Try a narrower request or raise maxOrchestratorIterations in models.json.",
    };
    conversation.append(truncationNotice);
    emit({
      type: OrchestratorEventTypes.WARNING,
      data: { message: `${this.role} hit iteration cap`, iterations: maxIterations },
    });
    return {
      finalMessage: truncationNotice,
      iterations: maxIterations,
      dispatches: tracker.count,
      outcome: "capped",
    };
  }

  // --------------------------------------------------------------------------

  private async maybeSummarize(
    conversation: Conversation,
    emit: RunnerListener,
    signal?: AbortSignal
  ): Promise<void> {
    const config = await this.runtime.getConfigurationRegistry().getModelsConfiguration();
    const threshold = config.orchestration.summarizeAtMessages!;
    const messages = conversation.getMessages();
    if (messages.length <= threshold) return;

    const desiredKeep = config.orchestration.summarizerKeepLastN!;
    const tailStart = findCleanTailStart(messages, desiredKeep);
    if (tailStart === 0) return;

    const prefix = messages.slice(0, tailStart);
    const tail = messages.slice(tailStart);

    emit({
      type: OrchestratorEventTypes.SUMMARIZATION_START,
      data: { messageCount: prefix.length },
    });

    let summaryText: string;
    try {
      const summarizer = new Summarizer(this.runtime);
      summaryText = await summarizer.summarize(prefix, { signal });
    } catch (err) {
      emit({
        type: OrchestratorEventTypes.WARNING,
        data: { message: `summarization failed: ${(err as Error).message}` },
      });
      return;
    }

    const summaryMessage = buildSummaryMessage(summaryText, prefix.length);

    await conversation.replaceAll([summaryMessage, ...tail]);

    emit({
      type: OrchestratorEventTypes.SUMMARIZATION,
      data: {
        summarizedCount: prefix.length,
        keptCount: tail.length,
        summaryChars: summaryText.length,
      },
    });
  }

  private async evaluateCompletion(
    question: string,
    proposedAnswer: string,
    transcript: ChatMessage[],
    emit: OrchestratorListener,
    signal?: AbortSignal
  ): Promise<EvaluationVerdict> {
    emit({ type: OrchestratorEventTypes.EVALUATION_START, data: {} });

    try {
      const config = await this.runtime.getConfigurationRegistry().getModelsConfiguration();
      const evaluator = new Evaluator(this.runtime);
      const verdict = await evaluator.evaluate(
        { question, proposedAnswer, transcript },
        { signal, temperature: config.orchestration.evaluatorTemperature }
      );
      emit({
        type: OrchestratorEventTypes.EVALUATION_VERDICT,
        data: { state: verdict.state, reason: verdict.reason },
      });
      return verdict;
    } catch (err) {
      // Fail open — never trap the user because the judge errored.
      emit({
        type: OrchestratorEventTypes.WARNING,
        data: { message: `evaluation failed, treating as satisfied: ${(err as Error).message}` },
      });
      return { state: "satisfied", reason: "evaluator error; defaulting to satisfied" };
    }
  }

  private buildSystemMessages(
    provider: LLMProvider,
    visibleTools: ToolDescriptor[],
    context: ContextSnapshot
  ): ChatMessage[] {
    const messages: ChatMessage[] = [];

    if (context.projectContext) {
      messages.push({
        role: "system",
        content:
          `Treat this as standing direction from the user; follow it unless ` +
          `a specific request overrides it.\n\n` +
          context.projectContext,
      });
    }

    // Prompted-JSON instructions stay per-turn: the live tool set can differ
    // from the snapshot's (the subsessions server is rebound each turn).
    const promptedInstructions = provider.supportsNativeTools
      ? ""
      : buildPromptedToolInstructions(visibleTools);

    messages.push({
      role: "system",
      content: context.systemPrompt + promptedInstructions,
    });

    return messages;
  }

  private normaliseAssistantTurn(
    provider: LLMProvider,
    response: ChatResponse,
    emit: OrchestratorListener
  ): { assistantMessage: ChatMessage; toolCalls: ToolCall[] } {
    if (provider.supportsNativeTools) {
      const nativeCalls = response.message.toolCalls ?? [];
      if (nativeCalls.length > 0) {
        return { assistantMessage: response.message, toolCalls: nativeCalls };
      }

      const { toolCalls: recoveredCalls, cleanedContent } = extractPromptedToolCalls(response.message);
      if (recoveredCalls.length > 0) {
        emit({
          type: OrchestratorEventTypes.WARNING,
          data: {
            message:
              "Native-tool model emitted tool call as JSON in prose; recovered via prompted-JSON fallback.",
            model: provider.modelId,
            recoveredCount: recoveredCalls.length,
          },
        });
        return {
          assistantMessage: {
            role: "assistant",
            content: cleanedContent,
            toolCalls: recoveredCalls,
          },
          toolCalls: recoveredCalls,
        };
      }
      return { assistantMessage: response.message, toolCalls: nativeCalls };
    }

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(response.message);
    return {
      assistantMessage: {
        role: "assistant",
        content: cleanedContent,
        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
      },
      toolCalls,
    };
  }
}

function wrapToolResult(call: ToolCall, content: string): ChatMessage {
  return {
    role: "tool",
    content,
    toolCallId: call.id,
    toolName: call.name,
  };
}

/**
 * Find a tail-start index that begins on a turn which can legally HEAD a
 * provider contents array: a `user` turn, or an `assistant` turn that is NOT
 * itself a tool-call. Two kinds of head are orphans and must be skipped:
 *
 *   - a `role:"tool"` message — it must follow the assistant turn that called
 *     it; kept alone it breaks providers that validate tool_call_id pairing.
 *   - an `assistant` turn carrying `toolCalls` — it becomes a model
 *     functionCall turn, which Gemini rejects unless it immediately follows a
 *     user turn or a functionResponse.
 */
function findCleanTailStart(messages: readonly ChatMessage[], desiredTailLen: number): number {
  const initial = Math.max(0, messages.length - desiredTailLen);
  for (let i = initial; i < messages.length; i += 1) {
    const message = messages[i];
    if (message.role === "user") return i;
    if (message.role === "assistant" && !(message.toolCalls && message.toolCalls.length > 0)) {
      return i;
    }
  }
  return messages.length;
}

export interface OrchestratorEvent {
  type: OrchestratorEventType;
  data: Record<string, unknown>;
}

export interface ExecutorEvent {
  type: ExecutorEventType;
  data: Record<string, unknown>;
}

export type OrchestratorListener = (event: OrchestratorEvent) => void;
export type ExecutorListener = (event: ExecutorEvent) => void;

/** Union type for events from either role. */
export type RunnerEvent = OrchestratorEvent | ExecutorEvent;

/** Generic listener that can handle either role's events. */
export type RunnerListener = (event: RunnerEvent) => void;

export interface SubSession {
  subSessionId: string;
  parentSessionId: string;
  /** The goal this sub-session was spawned to resolve. */
  intent: string;
  status: SubSessionStatus;
  /**
   * The live conversational state the detached run mutates. Owned by the child
   * runtime and populated once it is built, so it is absent in the brief window
   * between the synchronous create call and the runtime coming up.
   */
  session?: Session;
  /** Handle to the child's own runtime, set after build — drives + steers the run. */
  runtime?: ChildRuntime;
  /** Final assistant message content once the run completes. */
  result?: string;
  /** Failure detail when status is "error". */
  error?: string;
  /** Orchestrator iterations the run consumed (populated on completion). */
  iterations?: number;
  /** Executor dispatches the run made (populated on completion). */
  dispatches?: number;
  /** Cancels the detached run; fired by finalize() on a still-running child. */
  abort: AbortController;
  /**
   * Resolves when the detached run settles (done OR error — it never rejects,
   * since launch() handles both arms). Lets a caller block on a child's
   * completion: the interactive path ignores it (children report back via
   * notifications), but a headless single run awaits it so no sub-task is left
   * pending when the process exits.
   */
  settled?: Promise<void>;
  /** Status returned to the most recent get_status poll — drives poll backoff. */
  lastPolledStatus?: SubSessionStatus;
  /** Count of consecutive polls that saw `lastPolledStatus` unchanged. */
  pollRepeat: number;
  /** Epoch millis. */
  createdAt: number;
  /** Epoch millis; bumped on every status change. */
  updatedAt: number;
}

/**
 * Serializable view of a sub-session — the shape returned to the orchestrator
 * LLM as a tool result. Deliberately omits the live `session` and the abort
 * controller, which are runtime-only.
 */
export interface SubSessionSnapshot {
  subSessionId: string;
  parentSessionId: string;
  intent: string;
  status: SubSessionStatus;
  result?: string;
  error?: string;
  iterations?: number;
  dispatches?: number;
  createdAt: number;
  updatedAt: number;
}

/**
 * Result of a get_status poll: the snapshot plus how long the coordinator
 * backed off before returning. `backoffMs > 0` means the SAME status has been
 * polled repeatedly and the call was deliberately slowed to curb a tight
 * polling loop.
 */
export interface StatusResult {
  snapshot: SubSessionSnapshot;
  backoffMs: number;
}

/**
 * Push notification fired when a detached child reaches a terminal state. This
 * is the report-back seam that replaces polling: the parent does NOT block on
 * get_status — it spawns the child, ends its turn, and is told the outcome
 * through this channel when the run actually settles. Carries only the terminal
 * facts an outside listener (the REPL today, an external transport later) needs
 * to surface the result; the live session is never exposed.
 */
export interface SubSessionNotification {
  subSessionId: string;
  parentSessionId: string;
  intent: string;
  /** Terminal outcome only — `running` is never notified. */
  status: "done" | "error";
  /** Final assistant message when status is "done". */
  result?: string;
  /** Failure detail when status is "error". */
  error?: string;
}

export interface CreateSubSessionParams {
  parentSessionId: string;
  /** Workspace the child shares with its parent (same sandbox segment). */
  workspace: Workspace;
  intent: string;
  /** Optional standing context seeded as a system message before the intent. */
  context?: string;
  /** Identity inherited from the parent, stamped onto the child session. */
  user?: Principal;
}

/**
 * Identity + linkage the sub-runtime pipeline needs to provision a child. The
 * coordinator mints `sessionId` up front (so it can answer synchronously) and
 * the factory feeds these into the child's InheritedUser + ChildSession steps.
 */
export interface SubRuntimeRefs {
  sessionId: string;
  parentSessionId: string;
  workspaceId: string;
  user?: Principal;
  standingContext?: string;
}

/**
 * The slice of a freshly-composed child AgentRuntime the coordinator drives:
 * build it, run its single turn, and read/steer its session. Declared here
 * rather than imported from the runtime layer so SessionManager depends only on
 * this contract — AgentRuntime satisfies it structurally, keeping the Service
 * layer off the composition layer (no import inversion).
 */
export interface ChildRuntime {
  build(): Promise<ChildRuntime>;
  getSession(): Session;
  dispatchAsync(input: string, options?: { signal?: AbortSignal }): Promise<RunResult>;
  injectInput(content: string, source?: string): void;
  awaitAllSubSessions(): Promise<void>;
  /** Persist the child session — used to stamp its terminal done/error status. */
  finalize(): Promise<void>;
}

/**
 * Outcome of a createSubSession call. Creation is GUARDED: an identical
 * outstanding intent is reused rather than duplicated, and a per-parent cap
 * refuses further spawns. The orchestrator turns each outcome into a distinct
 * tool reply so the LLM can react (reuse the id it got back, or stop spawning).
 */
export interface CreateSubSessionResult {
  outcome: "created" | "reused" | "rejected";
  /** The new (created) or matching (reused) child; null when rejected. */
  snapshot: SubSessionSnapshot | null;
  /** Human-readable explanation for reused / rejected outcomes. */
  reason?: string;
}

/**
 * Contract the orchestrator depends on to manage sub-sessions. Implemented by
 * SessionManager; declared here (next to the data shapes) so the orchestrator
 * imports only this interface and never the concrete service — keeping the
 * orchestrator → manager → orchestrator construction acyclic.
 */
export interface SubSessionCoordinator {
  createSubSession(params: CreateSubSessionParams): CreateSubSessionResult;
  /**
   * Snapshot a child. Async because it applies an (abortable) backoff delay
   * when the same status is polled repeatedly. Returns null for an unknown id.
   */
  getStatus(
    parentSessionId: string,
    subSessionId: string,
    signal?: AbortSignal
  ): Promise<StatusResult | null>;
  /** Active (non-archived) children of a parent — powers list_subsessions. */
  list(parentSessionId: string): SubSessionSnapshot[];
  finalize(
    parentSessionId: string,
    subSessionId: string,
    finalStatus?: "done" | "error"
  ): SubSessionSnapshot | null;
}

/**
 * Build a fresh sub-session record in the `running` state. Pure but for the
 * AbortController construction; id minting and the detached run launch are the
 * SessionManager's job, mirroring how createSession leaves persistence to the
 * Initializer.
 */
export function makeSubSession(params: {
  subSessionId: string;
  parentSessionId: string;
  intent: string;
}): SubSession {
  const now = Date.now();
  return {
    subSessionId: params.subSessionId,
    parentSessionId: params.parentSessionId,
    intent: params.intent,
    status: "running",
    abort: new AbortController(),
    pollRepeat: 0,
    createdAt: now,
    updatedAt: now,
  };
}

/** Project the internal record down to the LLM-facing snapshot. */
export function toSnapshot(sub: SubSession): SubSessionSnapshot {
  return {
    subSessionId: sub.subSessionId,
    parentSessionId: sub.parentSessionId,
    intent: sub.intent,
    status: sub.status,
    result: sub.result,
    error: sub.error,
    iterations: sub.iterations,
    dispatches: sub.dispatches,
    createdAt: sub.createdAt,
    updatedAt: sub.updatedAt,
  };
}

import type { ChatMessage } from "../providers/provider.js";
import { AgentRuntimeQueryable } from "../runtime/types.js";

/**
 * Summarizer.
 *
 * Compresses an old prefix of the orchestrator conversation into a single
 * "conversation-so-far" note. The orchestrator splices the result back in
 * as one `role: "system"` message, preserving the last K messages
 * verbatim so recent tool results remain precise.
 *
 * The summarizer never sees the live system prompts and never invokes
 * tools — it is a pure text-in, text-out role.
 */

const DEFAULT_TEMPERATURE = 0.2;
const ROLE_NAME = "summarizer";

export interface SummarizeOptions {
  signal?: AbortSignal;
  temperature?: number;
}

export class Summarizer {
 constructor(private readonly runtime: AgentRuntimeQueryable) {}
  public async summarize(
    prefix: readonly ChatMessage[],
    options: SummarizeOptions = {}
  ): Promise<string> {
    const modelsRegistry = this.runtime.getModelsRegistry();
    const provider = this.runtime.getProvidersRegistry().getProvider(modelsRegistry.getProviderForRole("summarizer"));
    const contextLoader = this.runtime.getContextLoader();
    const session = this.runtime.getSession();
    const transcript = prefix.map(formatMessageForSummary).join("\n\n");
    const hash = session.contextHashes![ROLE_NAME];
    const content = await contextLoader.getContextSnapshot(hash)
    let response;
    try {
      response = await provider.chat(
        [
          { role: "system", content: content?.systemPrompt || '' },
          { role: "user", content: transcript },
        ],
        {
          tools: [],
          temperature: options.temperature ?? DEFAULT_TEMPERATURE,
          signal: options.signal,
        }
      );
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      throw new Error(
        `Summarizer (${provider.providerName}:${provider.modelId}) failed: ${errorMsg}`
      );
    }

    return response.message.content.trim();
  }
}

/**
 * Sentinel that marks a spliced "conversation-so-far" system message. Kept as a
 * stable, machine-detectable prefix so other components (e.g. session reset) can
 * recognise the summary without re-parsing prose. Do not localise or reword it.
 */
export const SUMMARY_TAG = "[CONVERSATION SUMMARY]";

/**
 * Build the single `system` message the orchestrator splices in place of the
 * compressed prefix. Beyond the summary text, it tells the reader two things:
 * the summary is ground-truth context, and — crucially for resuming after a
 * reset — the work it describes ALREADY happened and must not be re-executed.
 */
export function buildSummaryMessage(summaryText: string, summarizedCount: number): ChatMessage {
  return {
    role: "system",
    content:
      `${SUMMARY_TAG}\n` +
      `This is a condensed summary of ${summarizedCount} earlier message(s), ` +
      `produced by the summarizer model. Treat it as ground-truth context for ` +
      `everything that happened before the messages below.\n` +
      `The actions it describes have ALREADY been performed — continue from here; ` +
      `do not re-execute work the summary reports as done.\n\n` +
      summaryText,
  };
}

/**
 * True when `message` is a spliced summary checkpoint. Used by session reset to
 * preserve the latest summary (so a reset session can continue from it) instead
 * of re-running the summarizer.
 */
export function isSummaryMessage(message: ChatMessage): boolean {
  return message.role === "system" && message.content.startsWith(SUMMARY_TAG);
}

function formatMessageForSummary(message: ChatMessage): string {
  switch (message.role) {
    case "user":
      return `USER: ${message.content}`;
    case "system":
      return `SYSTEM: ${message.content}`;
    case "assistant": {
      const calls = message.toolCalls?.length
        ? "\n  tool-calls: " +
          message.toolCalls
            .map((c) => `${c.name}(${stringifyArgsCompact(c.arguments)})`)
            .join("; ")
        : "";
      return `ASSISTANT: ${message.content}${calls}`;
    }
    case "tool":
      return `TOOL[${message.toolName ?? ""}]: ${message.content}`;
  }
}

function stringifyArgsCompact(args: Record<string, unknown>): string {
  try {
    const json = JSON.stringify(args);
    return json.length > 200 ? json.slice(0, 200) + "..." : json;
  } catch {
    return "{}";
  }
}

export interface Round {
  readonly roundId: string;
  readonly source: TurnSource;
  /** The input handed to the dispatch function (becomes the user message). */
  readonly content: string;
  status: RoundStatus;
  readonly createdAt: number;
  startedAt?: number;
  endedAt?: number;
  /** Dispatch outcome tag (e.g. "satisfied" / "capped") when status is done. */
  outcome?: string;
  /** Failure detail when status is "error". */
  error?: string;
}

export interface Turn {
  readonly turnId: string;
  /** Source of the submission that CREATED the turn (appended rounds keep their own). */
  readonly source: TurnSource;
  /** Pending turns sharing this key absorb later submissions as extra rounds. */
  readonly coalesceKey?: string;
  status: TurnStatus;
  /** FIFO of rounds; appended to while pending OR running, never reordered. */
  readonly rounds: Round[];
  readonly createdAt: number;
  startedAt?: number;
  endedAt?: number;
}

/** Serializable projection of a round — the future persistence unit. */
export interface RoundSnapshot {
  roundId: string;
  source: TurnSource;
  content: string;
  status: RoundStatus;
  createdAt: number;
  startedAt?: number;
  endedAt?: number;
  outcome?: string;
  error?: string;
}

/** Serializable projection of a turn — the future persistence unit. */
export interface TurnSnapshot {
  turnId: string;
  source: TurnSource;
  coalesceKey?: string;
  status: TurnStatus;
  createdAt: number;
  startedAt?: number;
  endedAt?: number;
  rounds: RoundSnapshot[];
}

/** Full scheduler state — what a future store would capture to resume. */
export interface TurnRunnerSnapshot {
  current: TurnSnapshot | null;
  pending: TurnSnapshot[];
}

export interface SubmitParams {
  content: string;
  source: TurnSource;
  /**
   * Set for input meant to steer or extend work already in flight (user
   * follow-ups, sub-session reports): it joins the RUNNING turn as a round so
   * it acts in that engagement's context instead of waiting behind it. Leave
   * off for work that must not run inside another engagement. Falls back to a
   * new turn when nothing is running.
   */
  preferMidTurn?: boolean;
  /**
   * Collapse onto an already-pending turn with the same key (as an extra
   * round) instead of creating another queue entry. Omit for no coalescing.
   */
  coalesceKey?: string;
}

/**
 * Receipt for a submission. `turnId`/`roundId` locate where it landed (which
 * may be an existing turn when it was appended or coalesced); `settled`
 * resolves with the owning turn's final snapshot and NEVER rejects — errors
 * are reported in the snapshot, mirroring how sub-session `settled` behaves.
 */
export interface SubmitReceipt {
  turnId: string;
  roundId: string;
  /** How the submission landed — useful for hosts and tests. */
  placement: "new-turn" | "mid-turn-round" | "coalesced-round";
  settled: Promise<TurnSnapshot>;
}

/**
 * The single operation the pump drives: run one round's content through the
 * session (the runtime binds this to `dispatchAsync`). The signal aborts the
 * round when its turn is cancelled.
 */
export type RoundDispatch = (
  content: string,
  signal: AbortSignal
) => Promise<{ outcome: string; summary?: string }>;

// ---------------------------------------------------------------------------
// Observability events
// ---------------------------------------------------------------------------

export type TurnRunnerEvent =
  | { type: "turn-queued"; turnId: string; source: TurnSource; queueDepth: number }
  | { type: "turn-start"; turnId: string; source: TurnSource; rounds: number }
  | { type: "round-start"; turnId: string; roundId: string; source: TurnSource; round: number }
  | { type: "round-done"; turnId: string; roundId: string; status: RoundStatus; error?: string }
  | { type: "turn-done"; turnId: string; source: TurnSource; status: TurnStatus; rounds: number };

export type TurnRunnerListener = (event: TurnRunnerEvent) => void;

export interface TurnRunnerOptions {
  /**
   * Ceiling on rounds a single turn may accumulate. An append past the cap
   * spills into a NEW queued turn instead — this bounds the "child settles →
   * round reacts → spawns child → settles → …" feedback loop so one turn
   * cannot run forever. Spilled submissions still coalesce among themselves.
   */
  maxRoundsPerTurn?: number;
  /** Lifecycle listener for rendering / telemetry. Errors are swallowed. */
  onEvent?: TurnRunnerListener;
}

export class TurnRunner {
  private readonly pendingTurns: Turn[] = [];
  private currentTurn: Turn | null = null;

  /** One resolver + abort controller per unsettled turn, keyed by turnId. */
  private readonly settleResolvers = new Map<string, (snapshot: TurnSnapshot) => void>();
  private readonly settledPromises = new Map<string, Promise<TurnSnapshot>>();
  private readonly abortControllers = new Map<string, AbortController>();

  private readonly maxRoundsPerTurn: number;
  private readonly listener?: TurnRunnerListener;

  private started = false;
  private stopping = false;
  private pumpDone: Promise<void> | null = null;
  /** Resolver that un-parks the pump when the queue was empty. */
  private wakePump: (() => void) | null = null;
  /** Resolvers parked on awaitIdle(), flushed when the last turn settles. */
  private readonly idleWaiters: Array<() => void> = [];

  constructor(private readonly dispatch: RoundDispatch, options: TurnRunnerOptions = {}) {
    this.maxRoundsPerTurn = options.maxRoundsPerTurn ?? DEFAULT_MAX_ROUNDS_PER_TURN;
    this.listener = options.onEvent;
  }

  // ------------------------------------------------------------------------
  // Producer API
  // ------------------------------------------------------------------------

  /**
   * Enqueue work. Placement is resolved synchronously, in priority order:
   *
   *   1. mid-turn round  — `preferMidTurn` and a turn is RUNNING with capacity
   *   2. coalesced round — `coalesceKey` matches a PENDING turn with capacity
   *   3. new turn        — everything else (also the spill path past the cap)
   *
   * Safe to call from any producer at any time, including while the pump is
   * stopped (the submission waits in the queue — the future resume path).
   */
  public submit(params: SubmitParams): SubmitReceipt {
    const round = makeRound(params);

    // 1. Same-engagement feedback lands on the live turn.
    if (
      params.preferMidTurn &&
      this.currentTurn &&
      this.currentTurn.status === "running" &&
      this.currentTurn.rounds.length < this.maxRoundsPerTurn
    ) {
      this.currentTurn.rounds.push(round);
      return this.receiptFor(this.currentTurn, round, "mid-turn-round");
    }

    // 2. Collapse onto a pending turn with the same coalesce key.
    if (params.coalesceKey) {
      const target = this.pendingTurns.find(
        (turn) =>
          turn.coalesceKey === params.coalesceKey &&
          turn.status === "pending" &&
          turn.rounds.length < this.maxRoundsPerTurn
      );
      if (target) {
        target.rounds.push(round);
        return this.receiptFor(target, round, "coalesced-round");
      }
    }

    // 3. New engagement.
    const turn = makeTurn(params, round);
    this.registerTurn(turn);
    this.pendingTurns.push(turn);
    this.emit({
      type: "turn-queued",
      turnId: turn.turnId,
      source: turn.source,
      queueDepth: this.pendingTurns.length,
    });
    this.kickPump();
    return this.receiptFor(turn, round, "new-turn");
  }

  /**
   * Cancel a turn. Pending: removed from the queue and settled as cancelled
   * without ever dispatching. Running: its abort signal fires and the active
   * round is allowed to unwind. Unknown/settled ids return false.
   */
  public cancel(turnId: string): boolean {
    const pendingIndex = this.pendingTurns.findIndex((turn) => turn.turnId === turnId);
    if (pendingIndex !== -1) {
      const [turn] = this.pendingTurns.splice(pendingIndex, 1);
      turn.status = "cancelled";
      turn.endedAt = Date.now();
      for (const round of turn.rounds) round.status = "skipped";
      this.settleTurn(turn);
      return true;
    }
    if (this.currentTurn?.turnId === turnId) {
      this.abortControllers.get(turnId)?.abort();
      return true;
    }
    return false;
  }

  /**
   * Abort whatever turn is in flight — the host's "stop" affordance, saving
   * callers from fishing the live turnId out of a snapshot. Best-effort by
   * nature: the active round unwinds as soon as the dispatch honours its
   * signal (worst case, at the round boundary); remaining rounds are skipped.
   */
  public cancelCurrent(): boolean {
    return this.currentTurn ? this.cancel(this.currentTurn.turnId) : false;
  }

  /**
   * Complete stoppage: flush PENDING turns first — so the pump cannot promote
   * one while the in-flight turn unwinds — then abort the current turn.
   * Returns how many turns were cancelled.
   */
  public cancelAll(): number {
    let cancelled = 0;
    while (this.pendingTurns.length > 0) {
      const tail = this.pendingTurns[this.pendingTurns.length - 1];
      if (this.cancel(tail.turnId)) cancelled += 1;
    }
    if (this.cancelCurrent()) cancelled += 1;
    return cancelled;
  }

  // ------------------------------------------------------------------------
  // Lifecycle
  // ------------------------------------------------------------------------

  /** Start the pump. Idempotent. */
  public start(): void {
    if (this.started) return;
    this.started = true;
    this.stopping = false;
    this.pumpDone = this.pump();
  }

  /**
   * Graceful stop: the in-flight turn (all its rounds) finishes; PENDING turns
   * stay queued so a snapshot taken afterwards captures them — the resume
   * contract. Resolves once the pump has fully exited.
   */
  public async stop(): Promise<void> {
    if (!this.started) return;
    this.stopping = true;
    this.kickPump();
    await this.pumpDone;
    this.started = false;
    this.pumpDone = null;
  }

  // ------------------------------------------------------------------------
  // Queries
  // ------------------------------------------------------------------------

  /** True when a turn is in flight OR waiting — "the session has work". */
  public get isBusy(): boolean {
    return this.currentTurn !== null || this.pendingTurns.length > 0;
  }

  /**
   * Resolves once nothing is in flight and nothing is queued. The bridge
   * between a synchronous cancel and operations that need true quiescence
   * (reset/compact): cancelAll() fires the aborts, but the in-flight turn
   * unwinds asynchronously — mutating state before it settles would let the
   * dying turn write into the fresh state.
   */
  public awaitIdle(): Promise<void> {
    if (!this.isBusy) return Promise.resolve();
    return new Promise<void>((resolve) => {
      this.idleWaiters.push(resolve);
    });
  }

  public get pendingCount(): number {
    return this.pendingTurns.length;
  }

  /** JSON-friendly projection of the whole scheduler — the persistence seam. */
  public snapshot(): TurnRunnerSnapshot {
    return {
      current: this.currentTurn ? toTurnSnapshot(this.currentTurn) : null,
      pending: this.pendingTurns.map(toTurnSnapshot),
    };
  }

  // ------------------------------------------------------------------------
  // The pump — the ONLY caller of `dispatch`
  // ------------------------------------------------------------------------

  private async pump(): Promise<void> {
    while (!this.stopping) {
      const turn = this.pendingTurns.shift();
      if (!turn) {
        await this.parkPump();
        continue;
      }
      await this.runTurn(turn);
    }
  }

  /**
   * Run one turn to completion: dispatch rounds in order, RE-CHECKING the
   * round list after each await so rounds appended mid-turn are picked up in
   * the same engagement. All status transitions between awaits are synchronous,
   * so a submit() can never observe a half-updated turn.
   */
  private async runTurn(turn: Turn): Promise<void> {
    this.currentTurn = turn;
    turn.status = "running";
    turn.startedAt = Date.now();
    this.emit({ type: "turn-start", turnId: turn.turnId, source: turn.source, rounds: turn.rounds.length });

    const controller = this.abortControllers.get(turn.turnId)!;
    let failed = false;

    for (;;) {
      const round = turn.rounds.find((candidate) => candidate.status === "pending");
      if (!round) break;

      if (controller.signal.aborted) {
        round.status = "skipped";
        continue;
      }

      round.status = "running";
      round.startedAt = Date.now();
      this.emit({
        type: "round-start",
        turnId: turn.turnId,
        roundId: round.roundId,
        source: round.source,
        round: turn.rounds.indexOf(round) + 1,
      });

      try {
        const result = await this.dispatch(round.content, controller.signal);
        round.status = "done";
        round.outcome = result.outcome;
      } catch (err) {
        // Distinguish a user stop from a genuine failure so a cancelled turn
        // never renders (or persists) as a broken one.
        if (controller.signal.aborted) {
          round.status = "cancelled";
        } else {
          round.status = "error";
          round.error = err instanceof Error ? (err.stack ?? err.message) : String(err);
          failed = true;
        }
      }
      round.endedAt = Date.now();
      this.emit({
        type: "round-done",
        turnId: turn.turnId,
        roundId: round.roundId,
        status: round.status,
        error: round.error,
      });

      // One failed round fails the engagement; later rounds would run against
      // a context the failure may have corrupted, so they are skipped, not run.
      if (failed) {
        for (const remaining of turn.rounds) {
          if (remaining.status === "pending") remaining.status = "skipped";
        }
        break;
      }
    }

    turn.status = controller.signal.aborted ? "cancelled" : failed ? "error" : "done";
    turn.endedAt = Date.now();
    this.currentTurn = null;
    this.emit({
      type: "turn-done",
      turnId: turn.turnId,
      source: turn.source,
      status: turn.status,
      rounds: turn.rounds.length,
    });
    this.settleTurn(turn);
  }

  // ------------------------------------------------------------------------
  // Internals
  // ------------------------------------------------------------------------

  private registerTurn(turn: Turn): void {
    this.abortControllers.set(turn.turnId, new AbortController());
    this.settledPromises.set(
      turn.turnId,
      new Promise<TurnSnapshot>((resolve) => {
        this.settleResolvers.set(turn.turnId, resolve);
      })
    );
  }

  private receiptFor(turn: Turn, round: Round, placement: SubmitReceipt["placement"]): SubmitReceipt {
  return {
      turnId: turn.turnId,
      roundId: round.roundId,
      placement,
      settled: this.settledPromises.get(turn.turnId)!,
    };
  }

  private settleTurn(turn: Turn): void {
    const resolve = this.settleResolvers.get(turn.turnId);
    this.settleResolvers.delete(turn.turnId);
    this.settledPromises.delete(turn.turnId);
    this.abortControllers.delete(turn.turnId);
    resolve?.(toTurnSnapshot(turn));

    if (!this.isBusy) {
      const waiters = this.idleWaiters.splice(0);
      for (const wake of waiters) wake();
    }
  }

  /** Block the pump until submit()/stop() kicks it. */
  private parkPump(): Promise<void> {
    return new Promise<void>((resolve) => {
      this.wakePump = resolve;
    });
  }

  private kickPump(): void {
    const wake = this.wakePump;
    this.wakePump = null;
    wake?.();
  }

  private emit(event: TurnRunnerEvent): void {
    try {
      this.listener?.(event);
    } catch {
      /* a throwing listener must not break the pump */
    }
  }
}

function makeRound(params: SubmitParams): Round {
  return {
    roundId: randomUUID(),
    source: params.source,
    content: params.content,
    status: "pending",
    createdAt: Date.now(),
  };
}

function makeTurn(params: SubmitParams, firstRound: Round): Turn {
  return {
    turnId: randomUUID(),
    source: params.source,
    coalesceKey: params.coalesceKey,
    status: "pending",
    rounds: [firstRound],
    createdAt: Date.now(),
  };
}

function toRoundSnapshot(round: Round): RoundSnapshot {
  return {
    roundId: round.roundId,
    source: round.source,
    content: round.content,
    status: round.status,
    createdAt: round.createdAt,
    startedAt: round.startedAt,
    endedAt: round.endedAt,
    outcome: round.outcome,
    error: round.error,
  };
}

function toTurnSnapshot(turn: Turn): TurnSnapshot {
  return {
    turnId: turn.turnId,
    source: turn.source,
    coalesceKey: turn.coalesceKey,
    status: turn.status,
    createdAt: turn.createdAt,
    startedAt: turn.startedAt,
    endedAt: turn.endedAt,
    rounds: turn.rounds.map(toRoundSnapshot),
  };
}

import type { ToolExecutionResult, } from "../mcp/mcp-client.js";
import type {
  ChatMessage,
  ChatResponse,
  LLMProvider,
  ToolCall,
  ToolDescriptor,
} from "../providers/provider.js";
import {
  buildPromptedToolInstructions,
  extractPromptedToolCalls,
} from "../tool-adapter.js";
import type { AgentRuntimeQueryable } from "../runtime/types.js";
import { ScopedToolClient } from "../scoped-tool-client.js";
import { ExecutorEventTypes, type ExecutorEvent, type RunnerListener } from "./runner-events.js";

export type { ExecutorEvent };

/**
 * Executor sub-agent.
 *
 * The orchestrator hands a single ask (tool + args + intent) to `run()`.
 * Inside, a short bounded LLM conversation drives the executor through
 * its mandatory four-step shape:
 *
 *   1. ACK <tool>
 *   2. call the requested tool
 *   3. independently re-read or check exit code to validate
 *   4. RESULT OK | FAIL  + evidence
 *
 * After the LLM finishes, a deterministic post-step verifies reality on
 * disk (or by tool-result inspection for exec-style tools). If the
 * deterministic check disagrees with the LLM's verdict, the deterministic
 * verdict wins — the orchestrator is told so explicitly.
 */

export interface ExecutorAsk {
  tool: string;
  args: Record<string, unknown>;
  intent: string;
}

export interface ExecutorFeedback {
  ok: boolean;
  ack: string | null;
  llmReport: string | null;
  evidence: string;
  deterministicVerdict: "ok" | "mismatch" | "unverified";
  /** Full sub-conversation, useful for debugging and surfacing in the REPL. */
  transcript: ChatMessage[];
  /** Iteration count actually consumed inside the executor's loop. */
  iterations: number;
}

export interface ExecutorRunOptions {
  signal?: AbortSignal;
  onEvent?: RunnerListener;
  /** Hard cap on executor LLM iterations. Defaults to 6. */
  maxIterations?: number;
  /** Sampling temperature for the executor LLM. Defaults to 0.1. */
  temperature?: number;
}

export class Executor {
  private provider?: LLMProvider;
  private tools?: ScopedToolClient;
  private availableTools?: ToolDescriptor[];
  constructor(
    private readonly runtime: AgentRuntimeQueryable
  ) {}

  public async run(ask: ExecutorAsk, options: ExecutorRunOptions = {}): Promise<ExecutorFeedback> {
    const emit = options.onEvent ?? (() => {});
    const maxIterations = options.maxIterations ?? DEFAULT_MAX_ITERATIONS;
    const temperature = options.temperature ?? DEFAULT_TEMPERATURE;
    const registry = this.runtime.getModelsRegistry();
    const providersRegistry = this.runtime.getProvidersRegistry();
    const mcpRegistry = this.runtime.getMcpClientRegistry();
    // Resolve the executor's tool servers (role → model → models.json `mcp` list),
    // skipping any not currently mounted, and front them with one scoped client.
    const clients = registry.getValidMcpForModel("executor").flatMap((serverName) => {
      const mounted = mcpRegistry.getClient(serverName);
      return mounted ? [mounted] : [];
    });

    this.provider = providersRegistry.getProvider(registry.getProviderForRole("executor"));
    this.tools = new ScopedToolClient(clients, emit);
    this.availableTools = this.tools.listTools();

    emit({
      type: ExecutorEventTypes.START,
      data: {
        model: this.provider.modelId,
        provider: this.provider.providerName,
        tool: ask.tool,
        intent: ask.intent,
      },
    });

    // Sanity-check the ask up front. If the requested tool isn't in the
    // executor's allowed set, there's no point spinning up the LLM.
    const allowedNames = new Set(this.availableTools.map((t) => t.name));
    if (!allowedNames.has(ask.tool)) {
      const evidence = `requested tool "${ask.tool}" is not in the executor's tool list`;
      emit({ type: ExecutorEventTypes.WARNING, data: { reason: evidence } });
      return {
        ok: false,
        ack: null,
        llmReport: null,
        evidence,
        deterministicVerdict: "mismatch",
        transcript: [],
        iterations: 0,
      };
    }

    const systemMessages = this.buildSystemMessages();
    const askMessage: ChatMessage = {
      role: "user",
      content: this.formatAskAsUserMessage(ask),
    };

    const workingMessages: ChatMessage[] = [...systemMessages, askMessage];

    let ack: string | null = null;
    let llmReport: string | null = null;
    let mainToolResult: ToolExecutionResult | null = null;
    let iterations = 0;

    for (let i = 1; i <= maxIterations; i += 1) {
      iterations = i;

      // Cooperative stop checkpoint — same contract as the orchestrator loop:
      // never start another model call once the turn's signal has fired.
      if (options.signal?.aborted) {
        throw new Error("executor aborted: user requested stop");
      }

      let response;
      try {
        response = await this.provider.chat(workingMessages, {
          tools: this.provider.supportsNativeTools ? this.availableTools : [],
          temperature,
          signal: options.signal,
        });
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        throw new Error(
          `Executor (${this.provider.providerName}:${this.provider.modelId}) failed at iteration ${i}/${maxIterations}: ${errorMsg}`
        );
      }
      const { assistantMessage, toolCalls } = this.normaliseAssistantTurn(response);
      workingMessages.push(assistantMessage);

      // Capture the ACK line the first time it appears.
      if (ack === null) {
        const parsedAck = parseAckLine(assistantMessage.content);
        if (parsedAck) {
          ack = parsedAck;
          emit({ type: ExecutorEventTypes.ACK, data: { ack: parsedAck } });
        }
      }

      // Dispatch any tool calls in this message FIRST, so `mainToolResult`
      // is populated before we consider a RESULT line. This handles models
      // that emit the tool call and the RESULT in a single turn, and lets
      // us catch a RESULT that claims success without ever running the tool.
      for (const call of toolCalls) {
        const isMainAsk = call.name === ask.tool && argsRoughlyMatch(call.arguments, ask.args);

        emit({
          type: isMainAsk ? ExecutorEventTypes.TOOL_CALL : ExecutorEventTypes.VALIDATE,
          data: { id: call.id, name: call.name, arguments: call.arguments },
        });

        const execution = await this.tools.callTool(call.name, call.arguments);

        emit({
          type: ExecutorEventTypes.TOOL_RESULT,
          data: {
            id: call.id,
            name: call.name,
            isError: execution.isError,
            contentPreview: execution.content.slice(0, 300),
          },
        });

        if (isMainAsk && mainToolResult === null) {
          mainToolResult = execution;
        }

        workingMessages.push({
          role: "tool",
          content: execution.isError ? `[tool-error] ${execution.content}` : execution.content,
          toolCallId: call.id,
          toolName: call.name,
        });
      }

      // Now consider a RESULT line. We only honour it once the main tool has
      // actually run — a `RESULT OK` with no execution behind it is a
      // hallucinated success, and we bounce it back rather than accept it.
      const parsedReport = parseResultLine(assistantMessage.content);
      if (parsedReport) {
        const claimedOkWithoutRun = parsedReport.verdict === "OK" && mainToolResult === null;
        if (claimedOkWithoutRun) {
          workingMessages.push({
            role: "user",
            content:
              `EXECUTOR protocol violation: you reported RESULT OK but never called ` +
              `\`${ask.tool}\`. Call \`${ask.tool}\` with the given args now, then ` +
              `independently validate the result, then emit your RESULT line. A ` +
              `RESULT OK is only valid after the tool has actually run.`,
          });
          emit({
            type: ExecutorEventTypes.WARNING,
            data: { reason: `RESULT OK before "${ask.tool}" ran — forcing a real call`, iteration: i },
          });
          continue;
        }

        // Legitimate report: either OK backed by a real run, or an early FAIL
        // (e.g. the model judged the args malformed and declined to execute).
        llmReport = assistantMessage.content;
        emit({
          type: ExecutorEventTypes.REPORT,
          data: { verdict: parsedReport.verdict, message: parsedReport.message },
        });
        break;
      }

      // No RESULT this turn. If there were also no tool calls, that's protocol
      // drift — steer the model back on track and let it retry.
      if (toolCalls.length === 0) {
        workingMessages.push({
          role: "user",
          content:
            "EXECUTOR protocol reminder: emit either a tool call or a final " +
            "`EXECUTOR: RESULT OK ...` / `EXECUTOR: RESULT FAIL ...` line.",
        });
        emit({
          type: ExecutorEventTypes.WARNING,
          data: { reason: "no tool call and no RESULT line", iteration: i },
        });
        continue;
      }
    }

    // Deterministic post-step. This is what makes the protocol enforceable.
    const verification = await this.verify(ask, mainToolResult);

    emit({
      type: ExecutorEventTypes.DETERMINISTIC_VERDICT,
      data: { verdict: verification.verdict, evidence: verification.evidence },
    });

    const llmSaysOk = llmReport ? parseResultLine(llmReport)?.verdict === "OK" : false;
    const ok = verification.verdict === "mismatch" ? false : llmSaysOk;

    return {
      ok,
      ack,
      llmReport,
      evidence: verification.evidence,
      deterministicVerdict: verification.verdict,
      transcript: workingMessages,
      iterations,
    };
  }

  // --------------------------------------------------------------------------

  private buildSystemMessages(): ChatMessage[] {
    const basePrompt = this.runtime?.getModelsRegistry().getPromptTemplate("executor");
    const messages: ChatMessage[] = [{ role: "system", content: basePrompt }];

    if (!this.provider?.supportsNativeTools) {
      messages.push({
        role: "system",
        content: buildPromptedToolInstructions(this.availableTools!),
      });
    }

    return messages;
  }

  private formatAskAsUserMessage(ask: ExecutorAsk): string {
    return [
      "ORCHESTRATOR: dispatch",
      `  tool:   ${ask.tool}`,
      `  intent: ${ask.intent}`,
      "  args:",
      indent(JSON.stringify(ask.args, null, 2), "    "),
      "",
      "Follow the EXECUTOR protocol: ACK, execute, validate, RESULT.",
    ].join("\n");
  }

  private normaliseAssistantTurn(response: ChatResponse): {
    assistantMessage: ChatMessage;
    toolCalls: ToolCall[];
  } {
    if (this.provider?.supportsNativeTools) {
      const native = response.message.toolCalls ?? [];
      if (native.length > 0) {
        return { assistantMessage: response.message, toolCalls: native };
      }
      const { toolCalls, cleanedContent } = extractPromptedToolCalls(response.message);
      if (toolCalls.length > 0) {
        return {
          assistantMessage: { role: "assistant", content: cleanedContent, toolCalls },
          toolCalls,
        };
      }
      return { assistantMessage: response.message, toolCalls: [] };
    }

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(response.message);
    return {
      assistantMessage: {
        role: "assistant",
        content: cleanedContent,
        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
      },
      toolCalls,
    };
  }

  /**
   * Deterministic post-step. We verify reality on disk where we can, and
   * fall back to "unverified" when we can't (e.g. a free-form shell command
   * with no specific assertion). "unverified" is not a failure — it means
   * we defer to the LLM's RESULT line. "mismatch" overrides the LLM.
   */
  private async verify(
    ask: ExecutorAsk,
    mainToolResult: ToolExecutionResult | null
  ): Promise<{ verdict: "ok" | "mismatch" | "unverified"; evidence: string }> {
    if (mainToolResult === null) {
      return {
        verdict: "mismatch",
        evidence: `executor never called the requested tool "${ask.tool}"`,
      };
    }

    if (mainToolResult.isError) {
      return {
        verdict: "mismatch",
        evidence: `requested tool "${ask.tool}" returned an error: ${mainToolResult.content.slice(0, 200)}`,
      };
    }

    const kind = classifyTool(ask.tool);

    if (kind === "write_file") {
      const path = typeof ask.args.path === "string" ? ask.args.path : null;
      const expected = typeof ask.args.content === "string" ? ask.args.content : null;
      if (!path || expected === null) {
        return { verdict: "unverified", evidence: "write_file ask missing path or content" };
      }
      const readBack = await this.readFileForVerification(path);
      if (readBack === null) {
        return { verdict: "mismatch", evidence: `post-write read of "${path}" failed` };
      }
      if (normaliseEol(readBack) !== normaliseEol(expected)) {
        return {
          verdict: "mismatch",
          evidence: `post-write read of "${path}" does not match requested content`,
        };
      }
      return { verdict: "ok", evidence: `wrote ${expected.length} chars to "${path}"` };
    }

    if (kind === "edit_file") {
      const path = typeof ask.args.path === "string" ? ask.args.path : null;
      const expectedSubstring = pickExpectedSubstring(ask.args);
      if (!path) {
        return { verdict: "unverified", evidence: "edit_file ask missing path" };
      }
      const readBack = await this.readFileForVerification(path);
      if (readBack === null) {
        return { verdict: "mismatch", evidence: `post-edit read of "${path}" failed` };
      }
      if (expectedSubstring && !normaliseEol(readBack).includes(normaliseEol(expectedSubstring))) {
        return {
          verdict: "mismatch",
          evidence: `post-edit read of "${path}" does not contain expected replacement`,
        };
      }
      return {
        verdict: "ok",
        evidence: expectedSubstring
          ? `edit landed in "${path}" (replacement substring present)`
          : `edit completed on "${path}" (no substring assertion possible)`,
      };
    }

    if (kind === "exec") {
      return {
        verdict: "ok",
        evidence: `shell tool returned without isError; output ${mainToolResult.content.length} chars`,
      };
    }

    return {
      verdict: "unverified",
      evidence: `tool "${ask.tool}" has no deterministic verifier; trusting LLM RESULT`,
    };
  }

  private async readFileForVerification(path: string): Promise<string | null> {
    const readToolName = this.availableTools!
      .map((t) => t.name)
      .find((name) => name.endsWith("__read_file"));
    if (!readToolName) return null;

    const result = await this.tools?.callTool(readToolName, { path });
    if (result!.isError) return null;
    return extractFileContent(result!.content);
  }
}

function parseAckLine(content: string): string | null {
  for (const raw of content.split("\n")) {
    const line = raw.trim();
    const match = line.match(/^EXECUTOR:\s*ACK\s+(.+)$/);
    if (match) return match[1].trim();
  }
  return null;
}

function parseResultLine(content: string): { verdict: "OK" | "FAIL"; message: string } | null {
  for (const raw of content.split("\n")) {
    const line = raw.trim();
    const match = line.match(/^EXECUTOR:\s*RESULT\s+(OK|FAIL)\b\s*(.*)$/);
    if (match) {
      return { verdict: match[1] as "OK" | "FAIL", message: match[2].trim() };
    }
  }
  return null;
}

/**
 * Pull the real file content out of a `read_file` tool result.
 *
 * fsmcp returns a JSON envelope ({ path, total_lines, returned_range,
 * content }) rather than raw bytes, so verification has to read the
 * `.content` field. Falls back to the raw text when the output isn't the
 * expected JSON shape, so the verifier still works against other MCP
 * servers that return plain content.
 */
function extractFileContent(toolOutput: string): string {
  try {
    const parsed = JSON.parse(toolOutput) as unknown;
    if (
      parsed &&
      typeof parsed === "object" &&
      "content" in parsed &&
      typeof (parsed as { content: unknown }).content === "string"
    ) {
      return (parsed as { content: string }).content;
    }
  } catch {
    // Not JSON — assume the server already returned raw content.
  }
  return toolOutput;
}

/**
 * Normalise CRLF to LF before comparison. fsmcp's read_file reconstructs
 * content with `split(/\r?\n/).join("\n")`, so a file written with CRLF
 * reads back as LF; comparing raw would yield a spurious mismatch.
 */
function normaliseEol(text: string): string {
  return text.replace(/\r\n/g, "\n");
}

function classifyTool(name: string): "write_file" | "edit_file" | "exec" | "other" {
  const tail = name.split("__").pop() ?? name;
  if (tail === "write_file") return "write_file";
  if (tail === "edit_file") return "edit_file";
  if (tail === "exec" || tail === "shell" || tail === "powershell" || tail === "run_command") {
    return "exec";
  }
  return "other";
}

function pickExpectedSubstring(args: Record<string, unknown>): string | null {
  // edit_file shapes vary across MCP servers. Try common field names in order.
  for (const key of ["newText", "replacement", "new_string", "content"]) {
    const value = args[key];
    if (typeof value === "string" && value.length > 0) return value;
  }
  return null;
}

function argsRoughlyMatch(a: Record<string, unknown>, b: Record<string, unknown>): boolean {
  // We don't require deep equality — the executor may add or reorder fields.
  // For the "main ask" identification we only need the primary identifier
  // (usually `path`, falling back to command/cwd) to agree.
  for (const key of ["path", "command", "cwd"]) {
    if (key in b) {
      if (a[key] !== b[key]) return false;
    }
  }
  return true;
}

function indent(text: string, prefix: string): string {
  return text
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}

import { randomUUID } from "node:crypto";

import type { Conversation } from "../conversation/conversation.js";
import { InputInbox } from "../runners/input-inbox.js";
import { Orchestrator, type RunOptions, type RunResult } from "../runners/orchestrator.js";
import type { ContextLoader } from "../context/context-loader.js";
import type { ChatMessage } from "../providers/provider.js";
import type { Session } from "../session/session.js";
import { SessionManager } from "../session/session-manager.js";
import { SessionStore, type SessionSummary } from "../session/session-store.js";
import { Summarizer, buildSummaryMessage, isSummaryMessage } from "../runners/summarizer.js";
import type { SubSessionNotification, SubSessionNotificationListener } from "../runners/subsession.js";
import { TurnRunner, type TurnRunnerListener } from "../runners/turn-runner.js";
import type { RunnerListener } from "../runners/runner-events.js";
import type { Workspace } from "../registries/workspace-registry.js";
import { WorkspaceRegistry } from "../registries/workspace-registry.js";
import type { AgentRuntimeDeps, AgentRuntimeQueryable, IMiddleware, RuntimeContext } from "./types.js";
import type { ModelRegistry } from "../registries/model-registry.js";
import type { McpClientRegistry } from "../registries/mcp-registry.js";
import type { Logger } from "../../common/logger.js";
import { ConfigurationRegistry } from "../registries/configuration-registry.js";
import { ProvidersRegistry } from "../registries/providers-registry.js";

export interface ResetResult {
  projectContext: string | null;
  contextChanged: boolean;
}

export interface CompactResult {
  summarizedCount: number;
  skipped: boolean;
  summary: string | null;
}

/**
 * AgentRuntime — the stateful owner of a single session.
 *
 * Replaces the old Initializer with a fluent middleware pipeline that runs
 * once during build() to set up the session, then exposes a clean set of
 * per-session operations.
 *
 * Construction (via the fluent builder):
 *
 *   const runtime = await new AgentRuntime({ registry, tools, sessionsDir, workspaceRoot })
 *     .add(new StoreMiddleware())
 *     .add(new WorkspaceRegistryMiddleware())
 *     .add(new SessionMiddleware({ sessionId }))
 *     .add(new OrchestratorMiddleware({ includeSubSessions: true }))
 *     .add(new InputInboxMiddleware())
 *     .add(new SessionManagerMiddleware())
 *     .build();
 *
 * Per-turn operations:
 *   await runtime.dispatchAsync(input, { onEvent });
 *   runtime.injectInput(content);
 *   await runtime.finalize();     // explicit persist (called automatically by dispatchAsync)
 *   await runtime.reset();
 *   await runtime.compact();
 *
 * Ownership tree (mirrors the old Initializer tree, now per-session):
 *   AgentRuntime   (stateful session owner)
 *   ├─ Session                 run state (status, counters, links)
 *   ├─ Conversation            the live transcript (rolling JSONL file)
 *   ├─ Workspace               resolved project context
 *   ├─ Orchestrator            ONE stateless instance drives this session
 *   ├─ InputInbox              external input injection seam
 *   ├─ SessionStore            persistence
 *   ├─ WorkspaceRegistry       workspace → root/context map
 *   └─ SessionManager          owns sub-sessions spawned within this session
 */
export class AgentRuntime implements AgentRuntimeQueryable {
  private readonly middlewares: IMiddleware[] = [];

  // Populated by build() — all required after construction
  private logger!: Logger;
  private session!: Session;
  private conversation!: Conversation;
  private workspace!: Workspace;
  private modelsRegistry!: ModelRegistry;
  private configurationRegistry!: ConfigurationRegistry;
  private providersRegistry!: ProvidersRegistry;
  private mcpClientRegistry!: McpClientRegistry;
  private contextLoader!: ContextLoader;
  private orchestrator!: Orchestrator;
  private inbox!: InputInbox;
  private sessionManager!: SessionManager;
  private store!: SessionStore;
  private workspaces!: WorkspaceRegistry;

  // Turn loop (optional — hosts opt in via startTurnLoop; headless single runs
  // keep calling dispatchAsync directly and never construct these).
  private turnRunner: TurnRunner | null = null;
  private unsubscribeTurnWake: (() => void) | null = null;

  constructor(private readonly deps: AgentRuntimeDeps) {}

  // --------------------------------------------------------------------------
  // Fluent builder
  // --------------------------------------------------------------------------

  add(middleware: IMiddleware): this {
    this.middlewares.push(middleware);
    return this;
  }

  /**
   * Seed the context with the raw deps, run the initialize pipeline, then claim
   * ownership of every subsystem the pipeline built. build() constructs nothing
   * itself — each subsystem is produced by a middleware step (see RuntimeContext
   * for the pipeline convention). Must be called (and awaited) before any other
   * method.
   */
  async build(): Promise<this> {
    const ctx: RuntimeContext = {
      configPath: this.deps.configPath,
      sessionsDir: this.deps.sessionsDir,
      workspaceRoot: this.deps.workspaceRoot,
      sandboxRoot: this.deps.sandboxRoot,
      mcpConfigPath: this.deps.mcpConfigPath,
      credentials: this.deps.credentials ?? {},
      configurationRegistry: undefined,
      modelsRegistry: undefined,
      mcpRegistry: undefined,
      contextLoader: undefined,
      providerRegistry: undefined,
      logger: undefined,
      store: undefined,
      workspaces: undefined,
      user: undefined,
      session: undefined,
      conversation: undefined,
      workspace: undefined,
      orchestrator: undefined,
      inbox: undefined,
      sessionManager: undefined,
    };

    await this.runPipeline(ctx, 0);

    // Every owned field must have been set by a pipeline step. Report all gaps
    // at once so a misordered/incomplete pipeline is easy to fix.
    const missing = [
      !ctx.logger && "logger (LoggerMiddleware)",
      !ctx.store && "store (StoreMiddleware)",
      !ctx.workspaces && "workspaces (WorkspaceRegistryMiddleware)",
      !ctx.session && "session (SessionMiddleware)",
      !ctx.conversation && "conversation (ConversationMiddleware)",
      !ctx.workspace && "workspace (SessionMiddleware)",
      !ctx.orchestrator && "orchestrator (OrchestratorMiddleware)",
      !ctx.inbox && "inbox (InputInboxMiddleware)",
      !ctx.sessionManager && "sessionManager (SessionManagerMiddleware)",
    ].filter(Boolean);
    if (missing.length > 0) {
      throw new Error(
        `AgentRuntime.build(): pipeline left these unset: ${missing.join(", ")}. ` +
          "Add the listed step(s) to the pipeline."
      );
    }

    this.configurationRegistry = ctx.configurationRegistry!;
    this.logger = ctx.logger!;
    this.modelsRegistry = ctx.modelsRegistry!;
    this.mcpClientRegistry = ctx.mcpRegistry!;
    this.contextLoader = ctx.contextLoader!;
    this.providersRegistry = ctx.providerRegistry!;
    this.store = ctx.store!;
    this.workspaces = ctx.workspaces!;
    this.session = ctx.session!;
    this.conversation = ctx.conversation!;
    this.workspace = ctx.workspace!;
    this.orchestrator = ctx.orchestrator!;
    this.inbox = ctx.inbox!;
    this.sessionManager = ctx.sessionManager!;

    // Wire the runtime into the orchestrator so it can query for dependencies
    this.orchestrator.setRuntime(this);

    // reset() re-runs build(), which constructs a NEW SessionManager — an
    // active turn loop's wake subscription would silently point at the dead
    // manager, so re-bind it to the one that will actually fire.
    this.rewireTurnWake();

    return this;
  }

  // --------------------------------------------------------------------------
  // Per-turn operations
  // --------------------------------------------------------------------------

  /**
   * Run one user turn. Manages the running-guard, status transitions, the turn
   * counter, and calls finalize() in the finally block so every exit path
   * (clean, capped, thrown) persists the session.
   */
  async dispatchAsync(input: string, options: RunOptions = {}): Promise<RunResult> {
    if (this.session.status === "running") {
      throw new Error(`Session "${this.session.sessionId}" is already running a turn.`);
    }

    this.session.status = "running";

    const runOptions: RunOptions = {
      ...options,
      coordinator: this.sessionManager,
      pullInjectedPrompts: () => this.inbox.drain(this.session.sessionId),
    };

    try {
      const result = await this.orchestrator.run(input, runOptions);
      this.session.status = result.outcome === "satisfied" ? "awaiting-input" : "error";
      this.session.counters.turns += 1;
      return result;
    } catch (err) {
      // A user stop is an abandonment, not a failure — the session must come
      // back ready for input, not flagged broken.
      this.session.status = options.signal?.aborted ? "awaiting-input" : "error";
      throw err;
    } finally {
      await this.finalize();
    }
  }

  /**
   * Inject a prompt from outside the orchestrator loop. The prompt is queued
   * and drained at the start of the next orchestrator iteration — safe to call
   * whether or not a turn is currently in flight.
   */
  injectInput(content: string, source?: string): void {
    this.inbox.push(this.session.sessionId, content, source);
  }

  // --------------------------------------------------------------------------
  // Turn loop — multi-producer scheduling over dispatchAsync
  // --------------------------------------------------------------------------

  /**
   * Start the session's turn loop and return its TurnRunner. From here on the
   * runner's pump is the sole caller of dispatchAsync: hosts SUBMIT turns
   * (user input, API calls) instead of dispatching, and settling sub-sessions
   * auto-wake the session — their report is appended as a mid-turn ROUND when
   * a turn is in flight, or queued as a coalesced wake TURN when idle. Either
   * way the report enters the conversation, so the orchestrator actually
   * reasons over the child's result instead of it dying in a log line.
   *
   * Idempotent; `onEvent` is bound on first call. Headless single runs simply
   * never call this and keep the direct dispatchAsync path.
   */
  startTurnLoop(options: { onEvent?: RunnerListener; onTurnEvent?: TurnRunnerListener } = {}): TurnRunner {
    if (this.turnRunner) return this.turnRunner;

    this.turnRunner = new TurnRunner(
      async (content, signal) => {
        const result = await this.dispatchAsync(content, { onEvent: options.onEvent, signal });
        return { outcome: result.outcome, summary: result.finalMessage.content };
      },
      { onEvent: options.onTurnEvent }
    );

    this.rewireTurnWake();
    this.turnRunner.start();
    return this.turnRunner;
  }

  /**
   * Complete stoppage — the user's "stop": abort the in-flight turn, flush
   * every queued turn, and cancel every running sub-session of this session.
   * Children are swept FIRST and through finalize(), whose settle guard
   * suppresses their report-back notifications — otherwise a dying child
   * could enqueue a wake turn into the queue being flushed.
   */
  stopAllWork(): { cancelledTurns: number; cancelledSubSessions: number } {
    const cancelledSubSessions = this.sessionManager.cancelActive(this.session.sessionId);
    const cancelledTurns = this.turnRunner?.cancelAll() ?? 0;
    return { cancelledTurns, cancelledSubSessions };
  }

  /**
   * Stop the turn loop: unhook the wake subscription and let the in-flight
   * turn finish. Pending turns stay in the runner's queue (snapshot-able by a
   * future resume path); they are simply no longer pumped.
   */
  async stopTurnLoop(): Promise<void> {
    this.unsubscribeTurnWake?.();
    this.unsubscribeTurnWake = null;
    if (this.turnRunner) {
      await this.turnRunner.stop();
      this.turnRunner = null;
    }
  }

  /**
   * (Re-)subscribe the turn loop's auto-wake to the CURRENT session manager.
   * Called from startTurnLoop and from build() so a reset() (which rebuilds
   * the manager) cannot leave the wake bound to a stale instance.
   */
  private rewireTurnWake(): void {
    this.unsubscribeTurnWake?.();
    this.unsubscribeTurnWake = null;
    if (!this.turnRunner || !this.sessionManager) return;

    this.unsubscribeTurnWake = this.sessionManager.onNotification((notification) => {
      this.turnRunner?.submit({
        content: formatSubSessionReport(notification),
        source: "subsession",
        preferMidTurn: true,
        coalesceKey: "subsession-report",
      });
    });
  }

  /**
   * Persist the current session state. Called automatically by dispatchAsync,
   * reset, and compact — expose as public so callers can flush ad-hoc changes.
   */
  async finalize(): Promise<void> {
    this.session.updatedAt = Date.now();
    // Backstop flush: rounds flush as they complete, but a turn that threw
    // between rounds may still hold an unpersisted tail.
    await this.conversation.flush();
    await this.store.save(this.session);
  }

  /**
   * Clear the conversation transcript and re-read the workspace context from
   * disk, picking up any edits to agentcontext.md since last load.
   *
   * Reset means ABANDON: in-flight work is stopped (current turn, queued
   * turns, sub-sessions) and awaited down to quiescence first — clearing
   * while a turn unwinds would let the dying turn write into the fresh
   * conversation.
   */
  async reset(): Promise<boolean> {
    this.stopAllWork();
    await this.turnRunner?.awaitIdle();
    if (this.session.status === "running") {
      // Backstop for hosts that dispatch directly (no turn loop): we hold no
      // abort handle for such a turn, so refusing is the only safe option.
      throw new Error(`Session "${this.session.sessionId}" is running a turn; cannot reset now.`);
    }

    // Reset is a SOFT delete: the transcript is flushed, marked deleted
    // (deletedAt stamped, file kept as <id>.deleted.json for audit), and the
    // session relinks to a fresh conversation — the old file is never
    // appended to again. build() below opens the new transcript.
    await this.conversation.flush();
    await this.conversation.markDeleted();
    this.session.conversationId = randomUUID();
    this.session.status = "idle";
    this.session.counters.turns = 0;
    this.workspace = await this.workspaces.reload(this.session.workspaceId);
    this.session.updatedAt = Date.now();
    await this.store.save(this.session);
    await this.build();

    return true;
  }

  /**
   * Fold the entire conversation into a single summary checkpoint. Unlike the
   * orchestrator's automatic threshold-gated summarization, this collapses the
   * whole transcript — no verbatim tail is kept.
   *
   * Like reset, compacting implies stopping: the transcript must be quiescent
   * while the summarizer reads it, so in-flight work is cancelled and awaited
   * down rather than raced or refused.
   */
  async compact(options: { signal?: AbortSignal } = {}): Promise<CompactResult> {
    this.stopAllWork();
    await this.turnRunner?.awaitIdle();
    if (this.session.status === "running") {
      // Backstop for direct-dispatch hosts — no abort handle, so refuse.
      throw new Error(`Session "${this.session.sessionId}" is running a turn; cannot compact now.`);
    }

    const messages = this.conversation.getMessages();
    if (messages.length === 0 || (messages.length === 1 && isSummaryMessage(messages[0]))) {
      return { summarizedCount: 0, skipped: true, summary: null };
    }

    const summarizer = new Summarizer(this);
    const summaryText = await summarizer.summarize([...messages], { signal: options.signal });
    const summarizedCount = messages.length;

    await this.conversation.replaceAll([buildSummaryMessage(summaryText, summarizedCount)]);
    await this.finalize();

    return { summarizedCount, skipped: false, summary: summaryText };
  }

  // --------------------------------------------------------------------------
  // Sub-session coordination
  // --------------------------------------------------------------------------

  /**
   * Subscribe to sub-session completions. Returns an unsubscribe function.
   * The REPL listens here so finished background tasks surface out-of-band.
   */
  onSubSessionEvent(listener: SubSessionNotificationListener): () => void {
    return this.sessionManager.onNotification(listener);
  }

  /**
   * Block until every sub-session spawned by THIS session has settled. Used
   * by the headless single-run path to drain background tasks before exit.
   */
  awaitSubSessions(): Promise<void> {
    return this.sessionManager.awaitActive(this.session.sessionId);
  }

  /**
   * Block until every sub-session across the internal session manager has
   * settled. Called on normal process exit so no detached task is abandoned.
   */
  awaitAllSubSessions(): Promise<void> {
    return this.sessionManager.awaitAllActive();
  }

  // --------------------------------------------------------------------------
  // Queries
  // --------------------------------------------------------------------------

  getSession(): Session {
    return this.session;
  }

  getConversation(): Conversation {
    return this.conversation;
  }

  getWorkspace(): Workspace {
    return this.workspace;
  }

  history(): readonly ChatMessage[] {
    return this.conversation.getMessages();
  }

  getContextLoader(): ContextLoader {
    return this.contextLoader;
  }

  getModelsRegistry(): ModelRegistry {
    return this.modelsRegistry;
  }

  getConfigurationRegistry(): ConfigurationRegistry {
    return this.configurationRegistry;
  }

  getProvidersRegistry(): ProvidersRegistry {
    return this.providersRegistry;
  }

  getMcpClientRegistry(): McpClientRegistry {
    return this.mcpClientRegistry;
  }

  getOrchestrator(): Orchestrator {
    return this.orchestrator;
  }

  getLogger(): Logger {
    return this.logger;
  }

  // --------------------------------------------------------------------------
  // Static utilities (pre-session)
  // --------------------------------------------------------------------------

  /**
   * List persisted top-level sessions for a session picker. Static so it can
   * be called before a runtime instance is built — the picker runs before the
   * user has chosen which session to open or resume.
   */
  static listSavedSessions(sessionsDir: string): Promise<SessionSummary[]> {
    return SessionStore.create(sessionsDir).summaries();
  }

  // --------------------------------------------------------------------------
  // Internal pipeline runner
  // --------------------------------------------------------------------------

  private runPipeline(ctx: RuntimeContext, index: number): Promise<void> {
    if (index >= this.middlewares.length) return Promise.resolve();
    const middleware = this.middlewares[index];
    return middleware.initialize(ctx, () => this.runPipeline(ctx, index + 1));
  }
}

/**
 * Shape a settled child's notification into the round content the parent's
 * orchestrator receives. Self-describing: the orchestrator's system prompt
 * knows nothing about sub-session reports, so the message itself carries the
 * facts AND what to do with them.
 */
function formatSubSessionReport(notification: SubSessionNotification): string {
  const header =
    notification.status === "done"
      ? `[sub-session report] Sub-session ${notification.subSessionId} COMPLETED.`
      : `[sub-session report] Sub-session ${notification.subSessionId} FAILED.`;

  const body =
    notification.status === "done"
      ? `Result:\n${notification.result ?? "(no result text)"}`
      : `Error:\n${notification.error ?? "(no error detail)"}`;

  return [
    header,
    `Intent: ${notification.intent}`,
    body,
    "",
    "This report arrived asynchronously from a sub-session you previously spawned. " +
      "Reconcile it with the original request it served: if follow-up work is needed, do it now; " +
      "otherwise reply with a brief confirmation of the outcome for the user.",
  ].join("\n");
}

