import path from "node:path";
import { ContextLoader } from "../../context/context-loader.js";
import { fillToolsList } from "../../context/system-prompt.js";
import type { IMiddleware, RuntimeContext } from "../types.js";

export interface ContextMiddlewareParams {
  /**
   * Role for which to build context ("orchestrator", "executor", etc).
   */
  roleName: string;
  /**
   * Directory for content-addressed context snapshots. Defaults to a `contexts`
   * folder beside the sessions dir (so `…/sessions` and `…/contexts` sit together).
   */
  contextsDir?: string;
  /**
   * Whether the snapshot's tool block includes the sub-session tools. Matches
   * what the orchestrator actually advertises: a top-level run gets them (true,
   * the default); a sub-session runs without a coordinator and never sees them
   * (false), so its snapshot — and therefore its contextHash — is faithfully
   * reduced.
   */
  includeSubSessions?: boolean;
}

/**
 * ContextMiddleware — captures the non-conversation context (system prompt,
 * project direction, tool block) the orchestrator will send, stores it once per
 * unique fingerprint under the contexts dir, and stamps the resulting hash onto
 * the session.
 *
 * This is observability/documentation, not behaviour: it lets you answer "what
 * context did session X run on" without bloating every session file with the
 * large, repeating prefix. The snapshot is content-addressed, so N sessions
 * sharing the same context cost a single file.
 *
 * Requires ctx.session + ctx.workspace (from SessionMiddleware) and ctx.store
 * (from StoreMiddleware); reads ctx.registry/ctx.tools (always seeded). Place it
 * after SessionMiddleware in the pipeline.
 */
export class ContextMiddleware implements IMiddleware {
  constructor(private readonly params: ContextMiddlewareParams) {}

  async initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void> {
    if (!ctx.session || !ctx.workspace || !ctx.store) {
      throw new Error(
        "ContextMiddleware: requires ctx.session, ctx.workspace and ctx.store. " +
          "Add StoreMiddleware and SessionMiddleware earlier in the pipeline."
      );
    }
    // Default the snapshot store to a `contexts` folder beside the sessions dir
    // (…/sessions and …/contexts sit together) when no explicit dir is given.
    const contextsDir = this.params.contextsDir ?? path.join(path.dirname(ctx.sessionsDir), "contexts");
    ctx.contextLoader ??= new ContextLoader(contextsDir);
    const role = this.params.roleName;

    // Resolve the role's tools by combining every MCP server the role's model is
    // allowed to use (role → model → models.json `mcp` list). Servers that are
    // declared but not yet connected (e.g. codemcp, subsessions) resolve to
    // undefined and are skipped, so the snapshot reflects what is actually mounted.
    const serverNames = ctx.modelsRegistry!
      .getValidMcpForModel(role)
      // A coordinator-less run never advertises the sub-session tools, so its
      // snapshot must not record them either — the hash stays faithful.
      .filter((serverName) => this.params.includeSubSessions !== false || serverName !== "subsessions");
    const tools = serverNames.flatMap((serverName) => ctx.mcpRegistry!.getClient(serverName)?.listTools() ?? []);

    const projectTemplate = ctx.modelsRegistry?.getPromptTemplate("project");
    const agentTemplate = ctx.modelsRegistry!.getPromptTemplate(role);
    const systemPrompt = fillToolsList(agentTemplate, tools);
    const provider = ctx.providerRegistry!.getProvider(ctx.modelsRegistry!.getProviderForRole(role));
    const context = ctx.contextLoader.buildContext(
      role,
      systemPrompt,
      projectTemplate || '',
      tools,
      provider.supportsNativeTools
    );
    const hash = await ctx.contextLoader.saveContextSnapshot(context);

    // Stamp the pointer by role and persist now so the hash is durable from init, even
    // if the first turn never reaches finalize().
    ctx.session.contextHashes ??= {};
    ctx.session.contextHashes[role] = hash;
    await ctx.store.save(ctx.session);
    await next();
  }

}

import { randomUUID } from "node:crypto";

import { Conversation } from "../../conversation/conversation.js";
import { ConversationStore } from "../../conversation/conversation-store.js";
import type { IMiddleware, RuntimeContext } from "../types.js";

export interface ConversationMiddlewareParams {
  /**
   * Optional standing context seeded as the first system message of a FRESH
   * conversation — the sub-runtime's parent-fed briefing. Ignored when the
   * conversation already has messages (a resume must not re-seed).
   */
  standingContext?: string;
}

/**
 * ConversationMiddleware — opens the session's conversation.
 *
 * Runs after the session step (SessionMiddleware or ChildSessionMiddleware):
 * it follows `session.conversationId` to the rolling JSONL file and loads it,
 * or starts empty for a fresh session. Sessions persisted before the
 * conversation split carry no conversationId — those get a fresh id stamped
 * here (their embedded transcript is NOT migrated, by decision).
 *
 * Also heals a crash-interrupted transcript on resume by trimming a dangling
 * tool_use tail — this lived in SessionMiddleware when the transcript lived on
 * the session. Sets ctx.conversation before calling next().
 */
export class ConversationMiddleware implements IMiddleware {
  constructor(private readonly params: ConversationMiddlewareParams = {}) {}

  async initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void> {
    if (!ctx.session || !ctx.store) {
      throw new Error(
        "ConversationMiddleware: requires ctx.session and ctx.store. Add a session step " +
          "(SessionMiddleware / ChildSessionMiddleware) earlier in the pipeline."
      );
    }

    const store = ConversationStore.create(ctx.sessionsDir);

    // Pre-split session files have no conversationId; mint and persist the
    // link so the next resume finds the same (new, empty) conversation.
    // A link pointing at a soft-deleted conversation gets the same treatment:
    // reusing the id would resurrect (append to) the audit copy.
    if (!ctx.session.conversationId || (await store.isDeleted(ctx.session.conversationId))) {
      ctx.session.conversationId = randomUUID();
      await ctx.store.save(ctx.session);
    }
    const conversation = await Conversation.open(store, ctx.session.conversationId);

    await conversation.trimDanglingToolCalls();

    const standing = this.params.standingContext?.trim();
    if (standing && standing.length > 0 && conversation.length === 0) {
      conversation.append({
        role: "system",
        content: `Sub-session standing context:\n\n${standing}`,
      });
      await conversation.flush();
    }

    ctx.conversation = conversation;
    await next();
  }
}

/**
 * IdentityMiddleware — reads credentials from ctx and attempts to resolve a
 * Principal. Sets ctx.user when successful; leaves it undefined otherwise so
 * AnonymousMiddleware (or any downstream fallback) can take over.
 *
 * This implementation is a MOCK: it decodes the JWT payload without verifying
 * the signature. Replace the `resolve` method body with a real authority call
 * (e.g. JWKS fetch + signature verification) when real auth is needed.
 */
export class IdentityMiddleware implements IMiddleware {
  async initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void> {
    const principal = this.resolve(ctx.credentials.token);
    if (principal) {
      ctx.user = principal;
    }
    await next();
  }

  /**
   * Attempt to decode a JWT and produce a Principal.
   *
   * Mock behaviour: base64url-decodes the payload segment without any
   * signature check. Extracts standard OIDC claims (`sub`, `iss`, `name`,
   * `email`, `roles`, `scope`). Returns null when the token is absent, not
   * three-part, or the payload is not valid JSON.
   *
   * Replace this with signature verification + authority validation in prod.
   */
  private resolve(token: string | undefined): Principal | null {
    if (!token) return null;

    const parts = token.split(".");
    if (parts.length !== 3) return null;

    let payload: Record<string, unknown>;
    try {
      const json = Buffer.from(parts[1], "base64url").toString("utf8");
      payload = JSON.parse(json) as Record<string, unknown>;
    } catch {
      return null;
    }

    const sub = typeof payload.sub === "string" ? payload.sub : null;
    if (!sub) return null;

    const roles = Array.isArray(payload.roles)
      ? (payload.roles as unknown[]).filter((r): r is string => typeof r === "string")
      : typeof payload.role === "string"
      ? [payload.role]
      : [];

    const scopes =
      typeof payload.scope === "string"
        ? payload.scope.split(" ").filter(Boolean)
        : [];

    const claims: Record<string, string | string[]> = { sub };
    if (typeof payload.iss === "string") claims.iss = payload.iss;
    if (typeof payload.name === "string") claims.name = payload.name;
    if (typeof payload.email === "string") claims.email = payload.email;
    if (roles.length > 0) claims.roles = roles;

    return {
      sub,
      iss: typeof payload.iss === "string" ? payload.iss : undefined,
      isAuthenticated: true,
      claims,
      scopes,
    };
  }
}

/**
 * InheritedUserMiddleware — the sub-runtime's replacement for the Identity +
 * Anonymous steps. A sub-session does not authenticate; it adopts its parent's
 * resolved identity wholesale, so the child's persisted record carries the same
 * principal the parent ran under. Sets ctx.user before calling next().
 *
 * The value is whatever the parent resolved to (an authenticated principal, or
 * the anonymous fallback the top-level pipeline always lands on) — undefined is
 * tolerated but should not occur, since the top-level chain guarantees a user.
 */
export class InheritedUserMiddleware implements IMiddleware {
  constructor(private readonly user: Principal | undefined) {}

  async initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void> {
    ctx.user = this.user;
    await next();
  }
}

/**
 * InputInboxMiddleware — creates the external input injection seam the
 * orchestrator drains at the start of each iteration.
 *
 * Has no dependencies of its own; SessionManagerMiddleware reads ctx.inbox, so
 * this must run earlier. Sets ctx.inbox before calling next().
 */
export class InputInboxMiddleware implements IMiddleware {
  async initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void> {
    ctx.inbox = new InputInbox();
    await next();
  }
}

