/**
 * A single step in the initialize pipeline.
 *
 * Each handler receives the context accumulated so far and a `next` function
 * that advances the chain. To short-circuit (e.g. on a fatal auth failure),
 * return without calling next. To enrich and continue, mutate ctx then call
 * next.
 *
 * Order matters: earlier middleware runs first and sees an empty context;
 * later middleware (e.g. preferences enrichment) can build on what earlier
 * ones set.
 */
export interface IMiddleware {
  initialize(ctx: RuntimeContext, next: () => Promise<void>): Promise<void>;
}

import type { RunnerListener } from "./runners/runner-events.js";
import { OrchestratorEventTypes } from "./runners/runner-events.js";
import type { Mcp, ToolExecutionResult, ToolInvoker } from "./mcp/mcp.js";
import type { ToolDescriptor } from "./providers/provider.js";

/**
 * Routes `<server>__<tool>` calls to the correct in-process MCP server and
 * emits TOOL_CALL / TOOL_RESULT events for the REPL renderer.
 *
 * Path confinement is NOT the responsibility of this class. Each synthetic fs
 * server is constructed with its workspace segment as root (sandboxRoot +
 * workspaceId), so the Workspace guard inside the server enforces confinement
 * deterministically — before any disk access, without client-side rewriting.
 *
 * Tolerant routing: small models routinely drop the `<server>__` namespace
 * prefix. When the name is bare (no `__`), we search all mounted servers for
 * a unique tail match and route it. Ambiguous or missing names return a
 * corrective error that names the real candidates.
 */
export class ScopedToolClient implements ToolInvoker {
  private readonly clientsByServer: Map<string, Mcp>;

  constructor(clients: Mcp[], private readonly emit?: RunnerListener) {
    this.clientsByServer = new Map(clients.map((c) => [c.name, c]));
  }

  public listTools(): ToolDescriptor[] {
    const tools: ToolDescriptor[] = [];
    for (const client of this.clientsByServer.values()) {
      tools.push(...client.listTools());
    }
    return tools;
  }

  public async callTool(
    name: string,
    args: Record<string, unknown>
  ): Promise<ToolExecutionResult> {
    const resolved = this.resolve(name);
    if ("error" in resolved) {
      return { isError: true, content: resolved.error };
    }

    const { client, toolTail } = resolved;

    this.emit?.({ type: OrchestratorEventTypes.TOOL_CALL, data: { id: "", name, arguments: args } });
    const result = await client.callTool(toolTail, args);
    this.emit?.({
      type: OrchestratorEventTypes.TOOL_RESULT,
      data: { id: "", name, isError: result.isError, contentPreview: result.content.slice(0, 400) },
    });
    return result;
  }

  // ---------------------------------------------------------------------------

  private resolve(name: string): { client: Mcp; toolTail: string } | { error: string } {
    const sep = name.indexOf("__");

    if (sep !== -1) {
      const serverName = name.slice(0, sep);
      const toolTail = name.slice(sep + 2);
      const client = this.clientsByServer.get(serverName);
      if (!client) {
        const mounted = [...this.clientsByServer.keys()].join(", ");
        return {
          error:
            `Unknown server "${serverName}" in tool call "${name}". ` +
            `Mounted servers: ${mounted}. Use namespaced as <server>__<tool>.`,
        };
      }
      return { client, toolTail };
    }

    // Bare name: find every server that advertises a tool whose tail matches.
    const owners: Array<{ client: Mcp; toolTail: string }> = [];
    for (const client of this.clientsByServer.values()) {
      for (const tool of client.listTools()) {
        const tail = tool.name.slice(tool.name.indexOf("__") + 2);
        if (tail === name) {
          owners.push({ client, toolTail: name });
          break; // one match per server is enough
        }
      }
    }

    if (owners.length === 1) {
      return owners[0];
    }

    if (owners.length > 1) {
      const candidates = owners
        .map((o) => `${o.client.name}__${name}`)
        .join(", ");
      return {
        error:
          `Ambiguous bare tool name "${name}": multiple servers expose it. ` +
          `Use a namespaced name: ${candidates}`,
      };
    }

    const mounted = [...this.clientsByServer.keys()].join(", ");
    return {
      error:
        `Unknown tool "${name}": not found on any mounted server (${mounted}). ` +
        `Use namespaced as <server>__<tool>.`,
    };
  }
}

import { randomUUID } from "node:crypto";

import { foldDelegatedUsage, type Session } from "./session.js";
import {
  makeSubSession,
  toSnapshot,
  type CreateSubSessionParams,
  type CreateSubSessionResult,
  type StatusResult,
  type SubRuntimeFactory,
  type SubSession,
  type SubSessionCoordinator,
  type SubSessionNotification,
  type SubSessionNotificationListener,
  type SubSessionSnapshot,
  type SubSessionStatus,
} from "../runners/subsession.js";

/** Default ceiling on concurrently-active children per parent. Configurable via
 *  the constructor; intentionally small while sub-sessions are new. */
const DEFAULT_MAX_ACTIVE_PER_PARENT = 2;

/** Poll backoff: delay applied the 2nd time the same status comes back, doubling
 *  each further repeat, capped. Throttles a tight get_status loop in wall-clock
 *  time so it stops burning iterations and API budget. */
const POLL_BACKOFF_BASE_MS = 1000;
const POLL_BACKOFF_MAX_MS = 15000;

/**
 * SessionManager — Service layer. Owns the orchestrator's sub-sessions.
 *
 * Sits as a sibling of the top-level session map under the Initializer, NOT
 * above it: the Initializer owns top-level sessions directly and owns this
 * manager separately. See the ownership tree on the `Initializer` class.
 *
 * The in-memory two-level map (parentSessionId → subSessionId → SubSession) is
 * the live tracking state; the child's transcript is persisted by its own
 * runtime, so the manager itself holds no durable state.
 *
 * `create` builds the child its OWN runtime through the injected
 * `subRuntimeFactory` (the sub-pipeline, with parent-fed steps), then DETACHES a
 * single dispatch of the intent — the headless lifecycle — and returns
 * immediately with a `running` snapshot. The parent polls via `getStatus` and
 * ends a child with `finalize`. The child's own coordinator is capped at 0, so a
 * sub-session cannot itself spawn sub-sessions — the one-level-deep guard.
 */
export class SessionManager implements SubSessionCoordinator {
  /** Active children, keyed parent → sub. */
  private readonly active = new Map<string, Map<string, SubSession>>();
  /** Finalized children, kept so getStatus can still answer after archival. */
  private readonly archived = new Map<string, Map<string, SubSession>>();
  /** Report-back subscribers, notified when a child settles (done/error). */
  private readonly notificationListeners = new Set<SubSessionNotificationListener>();

  constructor(
    /** Builds a fresh child runtime per spawn — the sub-pipeline composed with
     *  parent-fed steps. Undefined on a leaf coordinator (cap 0), which never
     *  spawns and so never calls it. */
    private readonly subRuntimeFactory: SubRuntimeFactory | undefined,
    private readonly maxActivePerParent: number = DEFAULT_MAX_ACTIVE_PER_PARENT,
    /** The owning runtime's live session. Settled children fold their token
     *  tally into these counters in memory; the parent's next persist writes
     *  the summed figure. Optional so leaf coordinators (and tests) can omit it. */
    private readonly parentSession?: Session
  ) {}

  /**
   * Subscribe to child completions. The returned function unsubscribes. This is
   * the push seam the UI (and, later, an external transport) listens on so a
   * finished child reports itself instead of being polled. In-memory only —
   * subscriptions do not survive a restart.
   */
  public onNotification(listener: SubSessionNotificationListener): () => void {
    this.notificationListeners.add(listener);
    return () => this.notificationListeners.delete(listener);
  }

  public createSubSession(params: CreateSubSessionParams): CreateSubSessionResult {
    const siblings = this.active.get(params.parentSessionId);

    // Dedupe: an identical outstanding intent is reused if still running, never
    // duplicated. This also stops a runaway "spawn the same child again" loop from
    // burning the cap or piling on redundant API load. Completed sub-sessions with
    // the same intent are auto-finalized to free the slot.
    const wanted = normalizeIntent(params.intent);
    let reusableRunning: SubSession | undefined;
    const toFinalize: SubSession[] = [];

    if (siblings) {
      for (const sib of siblings.values()) {
        if (normalizeIntent(sib.intent) === wanted) {
          if (sib.status === "running") {
            reusableRunning = sib;
          } else if (sib.status !== "archived") {
            toFinalize.push(sib);
          }
        }
      }
    }

    // If running, reuse it immediately. Otherwise clean up completed ones and continue.
    if (reusableRunning) {
      return {
        outcome: "reused",
        snapshot: toSnapshot(reusableRunning),
        reason: `an active sub-session with this intent already exists (${reusableRunning.subSessionId}, status=${reusableRunning.status})`,
      };
    }

    // Auto-finalize completed sub-sessions (done/error) to free slots. Safe to do
    // outside iteration since we've collected them first.
    for (const sub of toFinalize) {
      this.finalize(params.parentSessionId, sub.subSessionId);
    }

    // Cap: refuse to fan out beyond the per-parent ceiling. The orchestrator
    // surfaces this so the model waits on / finalizes existing children first.
    const activeCount = siblings?.size ?? 0;
    if (activeCount >= this.maxActivePerParent) {
      return {
        outcome: "rejected",
        snapshot: null,
        reason: `sub-session cap of ${this.maxActivePerParent} active children reached; finalize one before spawning another`,
      };
    }

    const subSessionId = randomUUID();

    // The record is created synchronously (so the tool reply carries a running
    // snapshot immediately), but the child's Session is owned by its runtime and
    // attached once launch() builds it. The child's sessionId IS the
    // subSessionId, so the inbox key and the run's session identity coincide.
    const sub = makeSubSession({
      subSessionId,
      parentSessionId: params.parentSessionId,
      intent: params.intent,
    });

    this.track(sub);
    this.launch(sub, params);

    return { outcome: "created", snapshot: toSnapshot(sub) };
  }

  public async getStatus(
    parentSessionId: string,
    subSessionId: string,
    signal?: AbortSignal
  ): Promise<StatusResult | null> {
    const sub =
      this.active.get(parentSessionId)?.get(subSessionId) ??
      this.archived.get(parentSessionId)?.get(subSessionId);
    if (!sub) return null;

    // Track consecutive identical statuses across polls.
    if (sub.lastPolledStatus === sub.status) {
      sub.pollRepeat += 1;
    } else {
      sub.lastPolledStatus = sub.status;
      sub.pollRepeat = 1;
    }

    // From the 2nd identical status on, back off exponentially before answering
    // (1s, 2s, 4s, … capped). The delay is abortable so finalize / Ctrl-C never
    // hangs on a sleeping poll.
    let backoffMs = 0;
    if (sub.pollRepeat >= 2) {
      const steps = sub.pollRepeat - 1;
      backoffMs = Math.min(POLL_BACKOFF_BASE_MS * 2 ** (steps - 1), POLL_BACKOFF_MAX_MS);
      await sleep(backoffMs, signal);
    }

    return { snapshot: toSnapshot(sub), backoffMs };
  }

  public finalize(
    parentSessionId: string,
    subSessionId: string,
    finalStatus?: "done" | "error"
  ): SubSessionSnapshot | null {
    const map = this.active.get(parentSessionId);
    const sub = map?.get(subSessionId);
    if (!sub || !map) {
      // Already finalized? Hand back the archived snapshot so finalize is
      // idempotent rather than erroring on a double-call.
      const prior = this.archived.get(parentSessionId)?.get(subSessionId);
      return prior ? toSnapshot(prior) : null;
    }

    // Cancel an in-flight run before archiving. The detached promise's
    // settle() guard sees status !== "running" afterward and won't clobber.
    if (sub.status === "running") {
      sub.abort.abort();
      if (finalStatus === "error" && sub.error === undefined) {
        sub.error = "finalized as error before the run completed";
      } else if (finalStatus === "done" && sub.result === undefined) {
        sub.result = "(finalized before the run completed)";
      }
    }

    sub.status = "archived";
    sub.updatedAt = Date.now();

    map.delete(subSessionId);
    if (map.size === 0) this.active.delete(parentSessionId);
    this.stash(this.archived, sub);

    return toSnapshot(sub);
  }

  /**
   * Abort and archive every active child of a parent in one sweep — the
   * "stop everything" path. Goes through finalize() rather than bare abort so
   * the settle guard suppresses each child's report-back notification: a stop
   * must not refill the turn queue it is clearing.
   */
  public cancelActive(parentSessionId: string): number {
    const snapshots = this.list(parentSessionId);
    for (const snapshot of snapshots) {
      this.finalize(parentSessionId, snapshot.subSessionId, "error");
    }
    return snapshots.length;
  }

  /** Snapshots of every active (non-archived) child of a parent — powers the
   *  list_subsessions diagnostic tool. */
  public list(parentSessionId: string): SubSessionSnapshot[] {
    const map = this.active.get(parentSessionId);
    if (!map) return [];
    return [...map.values()].map(toSnapshot);
  }

  // --------------------------------------------------------------------------

  private track(sub: SubSession): void {
    this.stash(this.active, sub);
  }

  private stash(into: Map<string, Map<string, SubSession>>, sub: SubSession): void {
    const map = into.get(sub.parentSessionId);
    if (map) {
      map.set(sub.subSessionId, sub);
    } else {
      into.set(sub.parentSessionId, new Map([[sub.subSessionId, sub]]));
    }
  }

  /**
   * Fire-and-forget the child's own one-shot runtime. Each sub-session is built
   * through the sub-pipeline (giving it a UNIQUE orchestrator/runner, inherited
   * user, and its own contextHash), then driven by a single dispatch of the
   * intent — the headless lifecycle. The build + run are folded into the
   * detached promise so createSubSession stays synchronous for the tool reply.
   *
   * The child runtime owns its inbox; future parent-driven steering injects into
   * `sub.runtime` rather than through a shared inbox.
   */
  private launch(sub: SubSession, params: CreateSubSessionParams): void {
    // Retain the settle promise on the record so a caller can block on this
    // child's completion (the headless single run drains all children before
    // exiting). Both arms resolve, so it never rejects — awaiting it is safe.
    sub.settled = this.run(sub, params)
      .then((result) => {
        return this.settle(sub, () => {
          // A capped run gave up without a satisfied verdict — record it as an
          // error so "didn't finish" means the same thing here as it does for a
          // top-level run, rather than masquerading as a clean "done".
          if (result.outcome === "capped") {
            sub.status = "error";
            sub.error = "sub-session hit the orchestrator iteration cap without completing";
          } else {
            sub.status = "done";
            sub.result = result.finalMessage.content;
          }
          sub.iterations = result.iterations;
          sub.dispatches = result.dispatches;
        });
      })
      .catch((err: unknown) => {
        return this.settle(sub, () => {
          sub.status = "error";
          sub.error = err instanceof Error ? err.message : String(err);
        });
      });
  }

  /**
   * Build the child runtime from the injected factory and run its single turn.
   * Attaches the live runtime + session to the record (for status reads and
   * future steering) before dispatching.
   */
  private async run(sub: SubSession, params: CreateSubSessionParams) {
    if (!this.subRuntimeFactory) {
      throw new Error("SessionManager: no subRuntimeFactory configured; cannot launch a sub-session.");
    }

    const runtime = await this.subRuntimeFactory({
      sessionId: sub.subSessionId,
      parentSessionId: params.parentSessionId,
      workspaceId: params.workspace.workspaceId,
      user: params.user,
      standingContext: params.context,
    }).build();

    sub.runtime = runtime;
    sub.session = runtime.getSession();

    return runtime.dispatchAsync(sub.intent, { signal: sub.abort.signal });
  }

  /**
   * Block until every active child of `parentSessionId` has settled. The
   * interactive path never calls this — children there report back through the
   * notification channel after the parent's turn ends. A headless single run
   * does: it must leave no detached sub-task in flight when the process exits.
   *
   * One pass is complete because sub-sessions are one level deep (a child
   * runtime's coordinator is capped at 0, so it cannot spawn grandchildren) and
   * the parent's own run has already returned by the time this is called, so no
   * new children will appear. settle() leaves a finished child in the active set
   * with a terminal status, so awaiting each child's `settled` promise suffices.
   */
  public async awaitActive(parentSessionId: string): Promise<void> {
    const map = this.active.get(parentSessionId);
    if (!map) return;
    const pending = [...map.values()].map((sub) => sub.settled ?? Promise.resolve());
    await Promise.all(pending);
  }

  /**
   * Block until every active child across ALL parents has settled. The shared
   * process teardown calls this on a normal exit so no detached sub-task is
   * abandoned: the REPL fires children and forgets them across turns, but on the
   * way out we join them. One pass suffices for the same reason awaitActive's
   * does — by teardown the REPL loop has stopped and any headless run has
   * returned, so no new children can appear, and settle() leaves a finished
   * child in the active set with a terminal status (its `settled` already
   * resolved).
   */
  public async awaitAllActive(): Promise<void> {
    const pending: Promise<void>[] = [];
    for (const map of this.active.values()) {
      for (const sub of map.values()) {
        pending.push(sub.settled ?? Promise.resolve());
      }
    }
    await Promise.all(pending);
  }

  /**
   * Apply a terminal mutation only if the sub-session is still running. Guards
   * against a finalize() that already aborted-and-archived the child: the
   * resulting run rejection must not flip "archived" back to "error".
   *
   * On a genuine settle it also mirrors the outcome onto the persisted child
   * session, writes it, and fires the report-back notification — the two
   * effects that make a finished child both durable and visible without a poll.
   */
  private async settle(sub: SubSession, mutate: () => void): Promise<void> {
    if (sub.status !== "running") return;
    mutate();
    sub.updatedAt = Date.now();

    // Mirror the sub-session outcome onto the underlying Session so the
    // persisted file records a terminal status alongside the full transcript
    // the orchestrator mutated in place. The cast re-widens `status`: the guard
    // above narrowed it to "running", and TS can't see that the opaque mutate()
    // just moved it to a terminal state.
    const settledStatus = sub.status as SubSessionStatus;
    if (settledStatus === "done" || settledStatus === "error") {
      // Fold the child's whole-run token tally into the parent's in-memory
      // *Tallied counters (dependency spend, kept apart from the parent's own
      // chat usage); the parent's next finalize() persists the summed figure.
      // Done here (not on a tool result) because a detached child settles
      // after the parent's turn has already returned.
      if (this.parentSession && sub.session) {
        foldDelegatedUsage(this.parentSession.counters, sub.session.counters);
      }
      // The child's runtime owns persistence; stamp the terminal sub-session
      // status onto its session and let it write. A run that errored before the
      // runtime came up has neither — there is nothing to persist, but we still
      // notify so the parent learns the spawn failed.
      if (sub.runtime && sub.session) {
        sub.session.status = settledStatus;
        sub.session.counters.turns = Math.max(sub.session.counters.turns, 1);
        sub.session.updatedAt = sub.updatedAt;
        await sub.runtime.finalize().catch(() => {
          /* best-effort: a child that fails to persist still notifies */
        });
      }
      this.emitNotification(sub);
    }
  }

  /** Notify every subscriber that a child reached a terminal state. Listener
   *  errors are isolated so one bad subscriber can't starve the others. */
  private emitNotification(sub: SubSession): void {
    if (sub.status !== "done" && sub.status !== "error") return;
    const notification: SubSessionNotification = {
      subSessionId: sub.subSessionId,
      parentSessionId: sub.parentSessionId,
      intent: sub.intent,
      status: sub.status,
      result: sub.result,
      error: sub.error,
    };
    for (const listener of this.notificationListeners) {
      try {
        listener(notification);
      } catch {
        /* a throwing subscriber must not break the settle path */
      }
    }
  }
}

/** Canonical form for intent-equality: trimmed, lower-cased, whitespace
 *  collapsed. Cheap and tolerant enough to catch the model re-asking for the
 *  same thing with cosmetic differences. */
function normalizeIntent(intent: string): string {
  return intent.trim().toLowerCase().replace(/\s+/g, " ");
}

/** Resolve after `ms`, or immediately when `signal` aborts. */
function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  if (ms <= 0 || signal?.aborted) return Promise.resolve();
  return new Promise((resolve) => {
    const timer = setTimeout(finish, ms);

function finish(): void {
  clearTimeout(timer);
  signal?.removeEventListener("abort", finish);
  resolve();
}

    signal?.addEventListener("abort", finish, { once: true });
  });
}

import fs from "node:fs/promises";
import path from "node:path";

import { ConversationStore } from "../conversation/conversation-store.js";
import type { ChatMessage } from "../providers/provider.js";
import type { Session } from "./session.js";

/**
 * Lightweight description of a persisted session, enough for a picker to show
 * a useful row without the caller having to load and parse every file itself.
 */
export interface SessionSummary {
  sessionId: string;
  /** Epoch millis of the last persist; drives most-recent-first ordering. */
  updatedAt: number;
  /** Completed user turns. */
  turns: number;
  /** Truncated first user message, or null when the transcript has none yet. */
  preview: string | null;
}

/**
 * SessionStore — Repository layer.
 *
 * Persists one JSON file per session under a single directory. Chosen for
 * zero new dependencies and trivial inspectability; it mirrors the
 * file-repository pattern already used in codeindex.
 *
 * Durability is turn-boundary: the Initializer calls `save` after each
 * completed turn. Writes go through a temp file + rename so a crash
 * mid-write can never corrupt an existing session file.
 */
export class SessionStore {
  /** Sibling store for transcript previews — sessions only carry the
   *  conversationId link, so summaries() must follow it. */
  private readonly conversations: ConversationStore;

  private constructor(private readonly directory: string) {
    this.conversations = ConversationStore.create(directory);
  }

  public static create(directory: string): SessionStore {
    return new SessionStore(path.resolve(directory));
  }

  public async save(session: Session): Promise<void> {
    await fs.mkdir(this.directory, { recursive: true });
    const target = this.fileFor(session.sessionId);
    const tmp = `${target}.tmp`;
    await fs.writeFile(tmp, JSON.stringify(session, null, 2), "utf8");
    await fs.rename(tmp, target);
  }

  public async load(sessionId: string): Promise<Session | null> {
    try {
      const raw = await fs.readFile(this.fileFor(sessionId), "utf8");
      return JSON.parse(raw) as Session;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  public async list(): Promise<string[]> {
    try {
      const entries = await fs.readdir(this.directory);
      return entries
        .filter((entry) => entry.endsWith(".json"))
        .map((entry) => entry.slice(0, -".json".length));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw err;
    }
  }

  /**
   * Summaries of every persisted top-level session, most-recently-updated
   * first. Loads each file once and projects it to the small shape a picker
   * needs; files that fail to parse (partial/corrupt) are skipped rather than
   * aborting the whole listing.
   *
   * Sub-sessions (any session carrying a `parentSessionId`) are deliberately
   * omitted: they are persisted for durability/inspection but are not
   * resumable as standalone sessions, so the startup picker must never offer
   * them.
   */
  public async summaries(): Promise<SessionSummary[]> {
    const ids = await this.list();
    const summaries: SessionSummary[] = [];
    for (const id of ids) {
      const session = await this.load(id).catch(() => null);
      if (!session) continue;
      if (session.parentSessionId) continue;
      const messages = session.conversationId
        ? await this.conversations.load(session.conversationId).catch(() => null)
        : null;
      summaries.push({
        sessionId: session.sessionId,
        updatedAt: session.updatedAt,
        turns: session.counters.turns,
        preview: firstUserPreview(messages ?? []),
      });
    }
    return summaries.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  /**
   * Map a sessionId to its file. The id is sanitised so a hostile or
   * malformed value can't escape the store directory via path traversal.
   */
  private fileFor(sessionId: string): string {
    const safe = sessionId.replace(/[^a-zA-Z0-9_.-]/g, "_");
    return path.join(this.directory, `${safe}.json`);
  }
}

/**
 * First user message of a transcript, whitespace-collapsed and truncated, to
 * hint at what the session was about. Returns null when no user turn exists yet.
 */
function firstUserPreview(messages: readonly ChatMessage[]): string | null {
  const firstUser = messages.find((message) => message.role === "user");
  if (!firstUser) return null;
  const flat = firstUser.content.replace(/\s+/g, " ").trim();
  if (flat.length === 0) return null;
  return flat.length > PREVIEW_MAX_LENGTH ? `${flat.slice(0, PREVIEW_MAX_LENGTH - 1)}…` : flat;
}

export interface SessionCounters {
  /** Completed user turns. */
  turns: number;

  /**
   * Cumulative model token usage for THIS session's own chat calls only —
   * delegated work (executor dispatches, sub-sessions) is kept apart in the
   * `*Tallied` fields below so the two figures can't be confused. A running
   * tally for cost/cache visibility — not a per-turn figure. Fields may be
   * absent on sessions persisted before this was added; read them through
   * `?? 0`.
   */
  inputTokens: number;
  outputTokens: number;
  cacheReadInputTokens: number;
  cacheCreationInputTokens: number;

  /**
   * Cumulative token usage of dependencies — child runs whose cost this
   * session caused but did not spend itself: executor dispatches (reported on
   * the tool result) and settled sub-sessions (folded by the SessionManager).
   * Each fold adds the child's TOTAL (its own usage plus its own tallied
   * dependencies), so a parent's tallied figure covers the whole tree below
   * it. Session total cost = own fields + these.
   */
  inputTokensTallied: number;
  outputTokensTallied: number;
  cacheReadInputTokensTallied: number;
  cacheCreationInputTokensTallied: number;
}

/**
 * A token-usage tally as exposed by a producer (a chat response, a tool
 * result carrying a child run's cost). All fields optional so providers and
 * tools that can't report a figure simply omit it. The `*Tallied` fields are
 * present when the producer is itself a session that had dependencies.
 */
export interface TokenUsage {
  inputTokens?: number;
  outputTokens?: number;
  cacheReadInputTokens?: number;
  cacheCreationInputTokens?: number;
  inputTokensTallied?: number;
  outputTokensTallied?: number;
  cacheReadInputTokensTallied?: number;
  cacheCreationInputTokensTallied?: number;
}

/**
 * Fold a chat response's usage into the session's OWN counters. Only for
 * tokens this session's loop spent directly — delegated cost goes through
 * `foldDelegatedUsage` instead.
 */
export function foldCounters(into: SessionCounters, usage: TokenUsage | undefined): void {
  if (!usage) return;
  into.inputTokens = (into.inputTokens ?? 0) + (usage.inputTokens ?? 0);
  into.outputTokens = (into.outputTokens ?? 0) + (usage.outputTokens ?? 0);
  into.cacheReadInputTokens =
    (into.cacheReadInputTokens ?? 0) + (usage.cacheReadInputTokens ?? 0);
  into.cacheCreationInputTokens =
    (into.cacheCreationInputTokens ?? 0) + (usage.cacheCreationInputTokens ?? 0);
}

/**
 * Fold a dependency's usage into the session's `*Tallied` counters. Adds the
 * dependency's own usage AND its tallied dependencies, so the receiving
 * session's tallied figure is the full cost of the tree it delegated.
 */
export function foldDelegatedUsage(into: SessionCounters, usage: TokenUsage | undefined): void {
  if (!usage) return;
  into.inputTokensTallied =
    (into.inputTokensTallied ?? 0) + (usage.inputTokens ?? 0) + (usage.inputTokensTallied ?? 0);
  into.outputTokensTallied =
    (into.outputTokensTallied ?? 0) + (usage.outputTokens ?? 0) + (usage.outputTokensTallied ?? 0);
  into.cacheReadInputTokensTallied =
    (into.cacheReadInputTokensTallied ?? 0) +
    (usage.cacheReadInputTokens ?? 0) +
    (usage.cacheReadInputTokensTallied ?? 0);
  into.cacheCreationInputTokensTallied =
    (into.cacheCreationInputTokensTallied ?? 0) +
    (usage.cacheCreationInputTokens ?? 0) +
    (usage.cacheCreationInputTokensTallied ?? 0);
}

export interface Session {
  sessionId: string;
  workspaceId: string;
  /** Reserved for sub-sessions; unused until the background-agent work lands. */
  parentSessionId?: string;
  /**
   * Link to this session's transcript (a rolling JSONL file owned by the
   * ConversationStore). Stamped at creation; sessions persisted before the
   * conversation split lack it and get a fresh one minted on resume.
   */
  conversationId: string;
  status: SessionStatus;
  counters: SessionCounters;
  /** Epoch millis. */
  createdAt: number;
  /** Epoch millis; bumped on every persist. */
  updatedAt: number;
  /**
   * Identity of the caller that opened this session. Always set on in-memory
   * sessions (anonymous when no credentials were presented). May be absent on
   * sessions persisted before identity was added — treat as anonymous.
   */
  user?: Principal;
  /**
   * Content-addressed context snapshots by role name (e.g., "orchestrator", "executor").
   * Each maps to a hash pointing to `<contextsDir>/<hash>.json` recording the
   * system prompt + project direction + tool block that role ran on.
   * Stamped by ContextMiddleware at init for each role. Absent on sessions
   * persisted before context snapshots were added.
   */
  contextHashes?: Record<string, string>;
}

export interface CreateSessionParams {
  sessionId: string;
  workspaceId: string;
  conversationId: string;
  parentSessionId?: string;
}

/**
 * Build a fresh session in the `idle` state. Pure: persistence and id
 * minting are the Initializer's job, so this never touches disk or randomness.
 */
export function createSession(params: CreateSessionParams): Session {
  const now = Date.now();
  return {
    sessionId: params.sessionId,
    workspaceId: params.workspaceId,
    conversationId: params.conversationId,
    parentSessionId: params.parentSessionId,
    status: "idle",
    counters: {
      turns: 0,
      inputTokens: 0,
      outputTokens: 0,
      cacheReadInputTokens: 0,
      cacheCreationInputTokens: 0,
      inputTokensTallied: 0,
      outputTokensTallied: 0,
      cacheReadInputTokensTallied: 0,
      cacheCreationInputTokensTallied: 0,
    },
    createdAt: now,
    updatedAt: now,
  };
}

/**
 * Shape of a single dispatch ask — tool name, args, and one-line intent.
 * Defined here (not imported from zzz_executor) so the tracker has no runner dependency.
 */
export interface DispatchAsk {
  tool: string;
  args: Record<string, unknown>;
  intent: string;
}

/**
 * DispatchTracker — per-turn accounting for executor dispatches.
 *
 * Pulls together the three pieces of state the orchestrator loop used to keep
 * loose: the dispatch cap, the duplicate-mutation guard, and the
 * every-N-dispatches periodic-validator gate. One instance is created per
 * `Orchestrator.run` turn and shared with the dispatch tool through the
 * synthetic-tool context; the orchestrator only queries `dueForPeriodicCheck`.
 */
export class DispatchTracker {
  private dispatches = 0;
  private dispatchesSinceCheck = 0;
  /**
   * Signatures (tool + stable-stringified args) of dispatches that already
   * SUCCEEDED this turn. A re-dispatch of an identical, already-succeeded
   * mutation is a no-progress loop and is refused by the dispatch tool.
   */
  private readonly succeededSignatures = new Set<string>();

  constructor(
    private readonly maxDispatches: number,
    private readonly checkInterval: number
  ) {}

  /** Dispatch slots reserved this turn (only counts those under the cap). */
  public get count(): number {
    return this.dispatches;
  }

  /**
   * Reserve a dispatch slot. Counts against the cap whether or not the dispatch
   * ultimately succeeds — a hard loop therefore still burns down toward the cap
   * as a backstop. Returns the reason string when the cap is already reached.
   */
  public reserve(): { ok: true } | { ok: false; reason: string } {
    if (this.dispatches >= this.maxDispatches) {
      return { ok: false, reason: `dispatch cap of ${this.maxDispatches} per turn reached` };
    }
    this.dispatches += 1;
    return { ok: true };
  }

  /** Has this exact mutation already landed successfully this turn? */
  public isDuplicate(signature: string): boolean {
    return this.succeededSignatures.has(signature);
  }

  /**
   * Record a genuinely-successful mutation: remember its signature (so a later
   * identical re-dispatch is caught) and advance the periodic-check counter.
   */
  public recordSuccess(signature: string): void {
    this.succeededSignatures.add(signature);
    this.dispatchesSinceCheck += 1;
  }

  /**
   * True when enough successful dispatches have accrued to warrant a mid-flight
   * validator check. Consumes the counter (resets to zero) on a true result so
   * the gate fires at most once per interval.
   */
  public dueForPeriodicCheck(): boolean {
    if (this.checkInterval <= 0) return false;
    if (this.dispatchesSinceCheck < this.checkInterval) return false;
    this.dispatchesSinceCheck = 0;
    return true;
  }
}

/**
 * Stable identity for a dispatch: its tool name plus a canonical stringify of
 * its args (object keys sorted recursively). Order-independence matters because
 * weak models re-emit args via the prompted-JSON fallback, where key order can
 * drift between otherwise-identical calls — a naive JSON.stringify would miss
 * the duplicate.
 */
export function dispatchSignature(ask: DispatchAsk): string {
  return `${ask.tool}::${stableStringify(ask.args)}`;
}

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value) ?? "null";
  }
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(",")}]`;
  }
  const entries = Object.entries(value as Record<string, unknown>).sort(([a], [b]) =>
    a < b ? -1 : a > b ? 1 : 0
  );
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(",")}}`;
}

/**
 * In-process Excel MCP server.
 *
 * Unlike fsmcp (which needs only a static workspace root), Excel tools need
 * per-turn context: the session's workspace ID, the abort signal, etc. So this
 * returns a `LocalMcp` whose tool handlers have that turn's `ToolContext` baked
 * in.
 *
 * Like fsmcp, the tools are exposed directly as a `LocalMcp` — a tool call is a
 * plain in-process function call, not a JSON-RPC round-trip over an in-memory
 * transport. To every consumer it is indistinguishable from a spawned stdio
 * server. Tool names namespace as `excel__*` (e.g. `excel__read_sheet`).
 *
 * Architecture role: Repository / External layer. No orchestrator logic here —
 * just tool handlers behind a thin in-process adapter.
 */

import { LocalMcp, type LocalTool } from "../mcp/local-mcp.js";
import {
  createExcelTools,
  GET_EXCEL_COLUMNS_TOOL,
  LIST_EXCEL_SHEETS_TOOL,
  QUERY_EXCEL_ROWS_TOOL,
  READ_EXCEL_SHEET_TOOL,
} from "./excel-tools/excel-tools.js";
import type { SyntheticMcp, ToolContext } from "./types.js";

/** The MCP server name this module mounts under (tools namespace as `excel__*`). */
export const EXCEL_SERVER_NAME = "excel";

/** The read-only Excel mount (tools namespace as `excelreadonly__*`). */
export const EXCEL_READONLY_SERVER_NAME = "excelreadonly";

/**
 * ALLOWLIST, not a denylist: a mutating tool added to `createExcelTools`
 * later stays out of the read-only mount unless deliberately listed here.
 */
const READ_ONLY_EXCEL_TOOL_NAMES = new Set([
  LIST_EXCEL_SHEETS_TOOL,
  GET_EXCEL_COLUMNS_TOOL,
  READ_EXCEL_SHEET_TOOL,
  QUERY_EXCEL_ROWS_TOOL,
]);

/**
 * Build an Excel `LocalMcp` for a specific turn's context.
 *
 * Each Excel tool is already a `{ descriptor, callTool(args, ctx) }`; we bind
 * the turn's `ToolContext` into a `LocalTool.invoke(args)` so the server matches
 * the `Mcp` contract. Excel handlers return a string `content` already, so the
 * result passes through unchanged (its optional post-call `event` is dropped —
 * the orchestrator no longer routes Excel through the synthetic event path).
 */
export function createExcelLocalMcp(toolCtx: ToolContext): LocalMcp {
  return new LocalMcp(EXCEL_SERVER_NAME, bindToolContext(createExcelTools(), toolCtx));
}

/**
 * Inspection-only Excel mount for coordinator roles — same enforcement story
 * as `createFsReadonlyLocalMcp`: the orchestrator's read-only contract holds
 * because append/insert/delete are not mounted, not because the prompt asks
 * nicely.
 */
export function createExcelReadonlyLocalMcp(toolCtx: ToolContext): LocalMcp {
  const readOnlyTools = createExcelTools().filter((tool) => READ_ONLY_EXCEL_TOOL_NAMES.has(tool.name));
  return new LocalMcp(EXCEL_READONLY_SERVER_NAME, bindToolContext(readOnlyTools, toolCtx));
}

function bindToolContext(tools: SyntheticMcp[], toolCtx: ToolContext): LocalTool[] {
  return tools.map((tool) => ({
    descriptor: tool.descriptor,
    invoke: async (args) => {
      const result = await tool.callTool(args ?? {}, toolCtx);
      return { isError: result.isError, content: result.content };
    },
  }));
}

import { promises as fs } from "node:fs";
import path from "node:path";

import * as XLSX from "xlsx";

import type { ToolDescriptor } from "../../providers/provider.js";
import { toolError, toolOk, type RichToolResult, type SyntheticMcp, type ToolContext } from "../types.js";

export const READ_EXCEL_SHEET_TOOL = "read_excel_sheet";
export const GET_EXCEL_COLUMNS_TOOL = "get_excel_columns";
export const QUERY_EXCEL_ROWS_TOOL = "query_excel_rows";
export const LIST_EXCEL_SHEETS_TOOL = "list_sheets";
export const APPEND_EXCEL_ROWS_TOOL = "append_excel_rows";
export const APPEND_AFTER_EXCEL_ROWS_TOOL = "append_after_excel_rows";
export const DELETE_EXCEL_ROWS_TOOL = "delete_excel_rows";

/**
 * Excel synthetic tools — SheetJS-backed read/query/append over .xlsx files.
 *
 * Like the other synthetic tools these LOOK like real MCP tools to the LLM, but
 * the orchestrator intercepts them and runs them in-process. Unlike
 * executor__dispatch (which routes every mutation through the executor), these
 * are self-contained DATA operations: a spreadsheet read/append is a single,
 * well-bounded effect, so routing it through a free-form sub-agent would add
 * cost and non-determinism without buying safety.
 *
 * Every file_path is workspace-relative and resolved under
 * `{sandboxRoot}/{workspaceId}/` (see `resolveWorkspacePath`), the same segment
 * fsmcp and the executor write to — absolute paths and `..` escapes are refused
 * deterministically in agent code, never trusting the model to behave.
 */

/**
 * Build Excel tool descriptors for advertisement (without creating handlers).
 * Used to include Excel tools in the visible tools list at turn setup.
 */
export function getExcelToolDescriptors(): ToolDescriptor[] {
  return createExcelTools().map((tool) => ({
    name: tool.name,
    description: tool.descriptor.description,
    inputSchema: tool.descriptor.inputSchema,
  }));
}

export function createExcelTools(): SyntheticMcp[] {
  return [
    { name: LIST_EXCEL_SHEETS_TOOL, descriptor: listSheetsDescriptor(), callTool: handleListSheets },
    { name: GET_EXCEL_COLUMNS_TOOL, descriptor: getColumnsDescriptor(), callTool: handleGetColumns },
    { name: READ_EXCEL_SHEET_TOOL, descriptor: readSheetDescriptor(), callTool: handleReadSheet },
    { name: QUERY_EXCEL_ROWS_TOOL, descriptor: queryRowsDescriptor(), callTool: handleQueryRows },
    { name: APPEND_EXCEL_ROWS_TOOL, descriptor: appendRowsDescriptor(), callTool: handleAppendRows },
    {
      name: APPEND_AFTER_EXCEL_ROWS_TOOL,
      descriptor: appendAfterRowsDescriptor(),
      callTool: handleAppendAfterRows,
    },
    {
      name: DELETE_EXCEL_ROWS_TOOL,
      descriptor: deleteRowsDescriptor(),
      callTool: handleDeleteRows,
    },
  ];
}

// ---------------------------------------------------------------------------
// Row model
// ---------------------------------------------------------------------------

/** A spreadsheet row as a header-keyed object — the shape used in and out. */
type Row = Record<string, unknown>;

/** A single AND-ed filter clause for query_excel_rows. */
type FilterOp = "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "contains";

interface FilterCondition {
  column: string;
  op: FilterOp;
  value: unknown;
}

async function handleListSheets(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return toolError(`[excel-error] ${filePath.reason}`);

  const loaded = await loadWorkbook(ctx, filePath.value);
  if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);

  return toolOk(JSON.stringify({ file_path: filePath.value, sheets: loaded.value.SheetNames }, null, 2));
}

async function handleGetColumns(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return toolError(`[excel-error] ${filePath.reason}`);

  const loaded = await loadWorkbook(ctx, filePath.value);
  if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);

  // sheet_name is optional here — default to the first sheet.
  const sheet = resolveSheet(loaded.value, optionalString(args.sheet_name));
  if (!sheet.ok) return toolError(`[excel-error] ${sheet.reason}`);

  const { headers } = sheetToTable(sheet.value.worksheet);
  return toolOk(
    JSON.stringify({ file_path: filePath.value, sheet_name: sheet.value.name, columns: headers }, null, 2)
  );
}

async function handleReadSheet(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return toolError(`[excel-error] ${filePath.reason}`);
  const sheetName = requireString(args.sheet_name, "sheet_name");
  if (!sheetName.ok) return toolError(`[excel-error] ${sheetName.reason}`);

  const loaded = await loadWorkbook(ctx, filePath.value);
  if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);

  const sheet = resolveSheet(loaded.value, sheetName.value);
  if (!sheet.ok) return toolError(`[excel-error] ${sheet.reason}`);

  const { headers, rows } = sheetToTable(sheet.value.worksheet);
  return toolOk(
    JSON.stringify(
      { file_path: filePath.value, sheet_name: sheet.value.name, columns: headers, row_count: rows.length, rows },
      null,
      2
    )
  );
}

async function handleQueryRows(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return toolError(`[excel-error] ${filePath.reason}`);

  const conditions = parseFilterConditions(args.filter_conditions);
  if (!conditions.ok) return toolError(`[excel-error] ${conditions.reason}`);

  const loaded = await loadWorkbook(ctx, filePath.value);
  if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);

  const sheet = resolveSheet(loaded.value, optionalString(args.sheet_name));
  if (!sheet.ok) return toolError(`[excel-error] ${sheet.reason}`);

  const { headers, rows } = sheetToTable(sheet.value.worksheet);
  const matched = rows.filter((row) => conditions.value.every((c) => matchesCondition(row, c)));

  return toolOk(
    JSON.stringify(
      {
        file_path: filePath.value,
        sheet_name: sheet.value.name,
        columns: headers,
        matched_count: matched.length,
        total_count: rows.length,
        rows: matched,
      },
      null,
      2
    )
  );
}

async function handleAppendRows(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const parsed = parseAppendArgs(args);
  if (!parsed.ok) return toolError(`[excel-error] ${parsed.reason}`);

  // null insertAt => append at the very end (see writeRows).
  return writeRows(ctx, parsed.value.filePath, parsed.value.sheetName, parsed.value.rows, null);
}

async function handleAppendAfterRows(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const parsed = parseAppendArgs(args);
  if (!parsed.ok) return toolError(`[excel-error] ${parsed.reason}`);

  const afterRow = args.after_row;
  if (typeof afterRow !== "number" || !Number.isInteger(afterRow) || afterRow < 0) {
    return toolError(
      `[excel-error] ${APPEND_AFTER_EXCEL_ROWS_TOOL}.after_row must be a non-negative integer ` +
        `(0 = insert right after the header, N = insert after the Nth data row)`
    );
  }

  return writeRows(ctx, parsed.value.filePath, parsed.value.sheetName, parsed.value.rows, afterRow);
}

async function handleDeleteRows(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return toolError(`[excel-error] ${filePath.reason}`);
  const sheetName = requireString(args.sheet_name, "sheet_name");
  if (!sheetName.ok) return toolError(`[excel-error] ${sheetName.reason}`);

  const rowIndices = args.row_indices;
  if (!Array.isArray(rowIndices) || !rowIndices.every((i) => Number.isInteger(i) && i >= 0)) {
    return toolError(
      `[excel-error] ${DELETE_EXCEL_ROWS_TOOL}.row_indices must be an array of non-negative integers ` +
        `(0-based data row indices to delete)`
    );
  }

  return deleteRows(ctx, filePath.value, sheetName.value, rowIndices as number[]);
}

/**
 * Insert `newRows` into a sheet and persist the workbook. `insertAt` is the
 * 0-based data-row index to splice in front of; `null` means append at the end.
 * Creates the file/sheet when missing, and widens the header union so rows that
 * introduce a new column don't silently lose data.
 */
async function writeRows(
  ctx: ToolContext,
  filePath: string,
  sheetName: string,
  newRows: Row[],
  insertAt: number | null
): Promise<RichToolResult> {
  const resolved = resolveWorkspacePath(ctx, filePath);
  if (!resolved.ok) return toolError(`[excel-error] ${resolved.reason}`);

  // Load the existing workbook if present; otherwise start a fresh one. A read
  // error other than "file missing" is fatal — we must not clobber a file we
  // failed to parse.
  let workbook: XLSX.WorkBook;
  let existingRows: Row[] = [];
  let existingHeaders: string[] = [];
  const fileExists = await pathExists(resolved.absolutePath);
  if (fileExists) {
    const loaded = await loadWorkbook(ctx, filePath);
    if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);
    workbook = loaded.value;
    const sheet = workbook.Sheets[sheetName];
    if (sheet) {
      const table = sheetToTable(sheet);
      existingRows = table.rows;
      existingHeaders = table.headers;
    }
  } else {
    workbook = XLSX.utils.book_new();
  }

  if (insertAt !== null && insertAt > existingRows.length) {
    return toolError(
      `[excel-error] after_row ${insertAt} is past the last data row (${existingRows.length}) of ` +
        `sheet "${sheetName}"`
    );
  }

  // Combine, preserving column order: existing headers first, then any new keys
  // the appended rows introduce.
  const headers = unionHeaders(existingHeaders, newRows);
  const combined =
    insertAt === null
      ? [...existingRows, ...newRows]
      : [...existingRows.slice(0, insertAt), ...newRows, ...existingRows.slice(insertAt)];

  const worksheet = XLSX.utils.json_to_sheet(combined, { header: headers });
  if (workbook.Sheets[sheetName]) {
    workbook.Sheets[sheetName] = worksheet;
  } else {
    XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
  }

  const buffer = XLSX.write(workbook, { type: "buffer", bookType: "xlsx" }) as Buffer;
  await fs.mkdir(path.dirname(resolved.absolutePath), { recursive: true });
  await fs.writeFile(resolved.absolutePath, buffer);

  const resultData = {
    file_path: filePath,
    sheet_name: sheetName,
    created: !fileExists,
    appended_count: newRows.length,
    total_count: combined.length,
    columns: headers,
  };

  return {
    isError: false,
    content: JSON.stringify(resultData, null, 2),
    event: {
      type: "tool-result",
      data: {
        tool: insertAt === null ? APPEND_EXCEL_ROWS_TOOL : APPEND_AFTER_EXCEL_ROWS_TOOL,
        file_path: filePath,
        sheet_name: sheetName,
        appended: newRows.length,
      },
    },
  };
}

/**
 * Delete rows from a sheet by 0-based data row indices and persist the workbook.
 * Row indices are sorted descending before removal to avoid index shifts.
 */
async function deleteRows(
  ctx: ToolContext,
  filePath: string,
  sheetName: string,
  rowIndicesToDelete: number[]
): Promise<RichToolResult> {
  const resolved = resolveWorkspacePath(ctx, filePath);
  if (!resolved.ok) return toolError(`[excel-error] ${resolved.reason}`);

  const loaded = await loadWorkbook(ctx, filePath);
  if (!loaded.ok) return toolError(`[excel-error] ${loaded.reason}`);

  const sheet = resolveSheet(loaded.value, sheetName);
  if (!sheet.ok) return toolError(`[excel-error] ${sheet.reason}`);

  const { headers, rows } = sheetToTable(sheet.value.worksheet);

  // Validate indices
  const validIndices = rowIndicesToDelete.filter((i) => i >= 0 && i < rows.length);
  if (validIndices.length === 0) {
    return toolError(`[excel-error] no valid row indices to delete (valid range: 0-${rows.length - 1})`);
  }

  // Remove rows by index, sorting descending to avoid index shifts
  const indicesToRemove = new Set(validIndices);
  const remaining = rows.filter((_, idx) => !indicesToRemove.has(idx));

  const worksheet = XLSX.utils.json_to_sheet(remaining, { header: headers });
  loaded.value.Sheets[sheetName] = worksheet;

  const buffer = XLSX.write(loaded.value, { type: "buffer", bookType: "xlsx" }) as Buffer;
  await fs.mkdir(path.dirname(resolved.absolutePath), { recursive: true });
  await fs.writeFile(resolved.absolutePath, buffer);

  const resultData = {
    file_path: filePath,
    sheet_name: sheetName,
    deleted_count: validIndices.length,
    total_count: remaining.length,
    columns: headers,
  };

  return {
    isError: false,
    content: JSON.stringify(resultData, null, 2),
    event: {
      type: "tool-result",
      data: {
        tool: DELETE_EXCEL_ROWS_TOOL,
        file_path: filePath,
        sheet_name: sheetName,
        deleted: validIndices.length,
      },
    },
  };
}

/**
 * Read and parse a workbook from a workspace-relative path. Read uses a buffer
 * (XLSX.read) rather than XLSX.readFile so the path clamp stays in our code and
 * we never hand a raw path to SheetJS.
 */
async function loadWorkbook(
  ctx: ToolContext,
  filePath: string
): Promise<{ ok: true; value: XLSX.WorkBook } | { ok: false; reason: string }> {
  const resolved = resolveWorkspacePath(ctx, filePath);
  if (!resolved.ok) return resolved;

  let buffer: Buffer;
  try {
    buffer = await fs.readFile(resolved.absolutePath);
  } catch (err) {
    if (isNotFound(err)) return { ok: false, reason: `file "${filePath}" not found in workspace` };
    return { ok: false, reason: `could not read "${filePath}": ${errorMessage(err)}` };
  }

  try {
    return { ok: true, value: XLSX.read(buffer, { type: "buffer" }) };
  } catch (err) {
    return { ok: false, reason: `could not parse "${filePath}" as a spreadsheet: ${errorMessage(err)}` };
  }
}

/** Resolve a sheet by name, or the first sheet when name is omitted. */
function resolveSheet(
  workbook: XLSX.WorkBook,
  sheetName: string | undefined
): { ok: true; value: { name: string; worksheet: XLSX.WorkSheet } } | { ok: false; reason: string } {
  if (workbook.SheetNames.length === 0) {
    return { ok: false, reason: "workbook contains no sheets" };
  }
  const name = sheetName ?? workbook.SheetNames[0];
  const worksheet = workbook.Sheets[name];
  if (!worksheet) {
    return {
      ok: false,
      reason: `sheet "${name}" not found; available sheets: ${workbook.SheetNames.join(", ")}`,
    };
  }
  return { ok: true, value: { name, worksheet } };
}

/**
 * Project a worksheet into a header list plus header-keyed rows. Reads the AoA
 * first so the header ORDER reflects the file's columns (sheet_to_json's object
 * keys alone would not preserve a stable order across rows).
 */
function sheetToTable(worksheet: XLSX.WorkSheet): { headers: string[]; rows: Row[] } {
  const matrix = XLSX.utils.sheet_to_json<unknown[]>(worksheet, { header: 1, blankrows: false });
  const headerRow = matrix.length > 0 ? matrix[0] : [];
  const headers = headerRow.map((h) => String(h ?? ""));

  const rows: Row[] = [];
  for (let i = 1; i < matrix.length; i += 1) {
    const cells = matrix[i];
    const row: Row = {};
    headers.forEach((header, col) => {
      row[header] = col < cells.length ? cells[col] ?? null : null;
    });
    rows.push(row);
  }
  return { headers, rows };
}

/** Existing headers in order, plus any new keys the appended rows introduce. */
function unionHeaders(existingHeaders: string[], newRows: Row[]): string[] {
  const headers = existingHeaders.filter((h) => h.length > 0);
  const seen = new Set(headers);
  for (const row of newRows) {
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        headers.push(key);
      }
    }
  }
  return headers;
}

/** Evaluate one AND-ed clause against a row. */
function matchesCondition(row: Row, condition: FilterCondition): boolean {
  const cell = row[condition.column];
  const target = condition.value;

  switch (condition.op) {
    case "eq":
      return looseEquals(cell, target);
    case "ne":
      return !looseEquals(cell, target);
    case "contains":
      return String(cell ?? "").includes(String(target ?? ""));
    case "gt":
    case "gte":
    case "lt":
    case "lte": {
      // Ordering only makes sense numerically; a non-numeric cell or target
      // never matches rather than producing a surprising string comparison.
      const a = Number(cell);
      const b = Number(target);
      if (Number.isNaN(a) || Number.isNaN(b)) return false;
      if (condition.op === "gt") return a > b;
      if (condition.op === "gte") return a >= b;
      if (condition.op === "lt") return a < b;
      return a <= b;
    }
    default:
      return false;
  }
}

/** Equality that bridges number/string cells (3 == "3"), else strict-ish. */
function looseEquals(cell: unknown, target: unknown): boolean {
  if (cell === target) return true;
  return String(cell ?? "") === String(target ?? "");
}

function parseFilterConditions(
  raw: unknown
): { ok: true; value: FilterCondition[] } | { ok: false; reason: string } {
  if (raw === undefined || raw === null) return { ok: true, value: [] };
  if (!Array.isArray(raw)) {
    return { ok: false, reason: "filter_conditions must be an array of {column, op, value}" };
  }

  const conditions: FilterCondition[] = [];
  for (const [index, entry] of raw.entries()) {
    if (entry === null || typeof entry !== "object" || Array.isArray(entry)) {
      return { ok: false, reason: `filter_conditions[${index}] must be an object` };
    }
    const { column, op, value } = entry as Record<string, unknown>;
    if (typeof column !== "string" || column.length === 0) {
      return { ok: false, reason: `filter_conditions[${index}].column must be a non-empty string` };
    }
    if (typeof op !== "string" || !FILTER_OPS.includes(op as FilterOp)) {
      return {
        ok: false,
        reason: `filter_conditions[${index}].op must be one of: ${FILTER_OPS.join(", ")}`,
      };
    }
    conditions.push({ column, op: op as FilterOp, value });
  }
  return { ok: true, value: conditions };
}

function parseAppendArgs(
  args: Record<string, unknown>
): { ok: true; value: { filePath: string; sheetName: string; rows: Row[] } } | { ok: false; reason: string } {
  const filePath = requireString(args.file_path, "file_path");
  if (!filePath.ok) return { ok: false, reason: filePath.reason };
  const sheetName = requireString(args.sheet_name, "sheet_name");
  if (!sheetName.ok) return { ok: false, reason: sheetName.reason };

  if (!Array.isArray(args.rows)) {
    return { ok: false, reason: "rows must be an array of objects (each keyed by column name)" };
  }
  const rows: Row[] = [];
  for (const [index, entry] of args.rows.entries()) {
    if (entry === null || typeof entry !== "object" || Array.isArray(entry)) {
      return { ok: false, reason: `rows[${index}] must be an object keyed by column name` };
    }
    rows.push(entry as Row);
  }
  if (rows.length === 0) {
    return { ok: false, reason: "rows must contain at least one row to append" };
  }

  return { ok: true, value: { filePath: filePath.value, sheetName: sheetName.value, rows } };
}

function requireString(
  value: unknown,
  field: string
): { ok: true; value: string } | { ok: false; reason: string } {
  if (typeof value !== "string" || value.trim().length === 0) {
    return { ok: false, reason: `${field} must be a non-empty string` };
  }
  return { ok: true, value };
}

function optionalString(value: unknown): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function resolveWorkspacePath(
  ctx: ToolContext,
  filePath: string
): { ok: true; absolutePath: string } | { ok: false; reason: string } {
  if (isAbsoluteLike(filePath)) {
    return { ok: false, reason: `path "${filePath}" must be workspace-relative (absolute paths are refused)` };
  }

  const segmentRoot = path.resolve(ctx.sandboxRoot, ctx.workspace.workspaceId);
  const resolved = path.resolve(segmentRoot, filePath);

  // Confirm the resolved path is still inside the workspace segment; a `..` that
  // climbs out lands elsewhere and is refused here.
  const relative = path.relative(segmentRoot, resolved);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    return { ok: false, reason: `path "${filePath}" escapes the workspace segment` };
  }
  return { ok: true, absolutePath: resolved };
}

/** Drive-letter, UNC, and rooted paths are treated as absolute and refused. */
function isAbsoluteLike(value: string): boolean {
  return /^[a-zA-Z]:[\\/]/.test(value) || /^[\\/]/.test(value);
}

async function pathExists(absolutePath: string): Promise<boolean> {
  try {
    await fs.access(absolutePath);
    return true;
  } catch {
    return false;
  }
}

function isNotFound(err: unknown): boolean {
  return Boolean(err) && typeof err === "object" && (err as NodeJS.ErrnoException).code === "ENOENT";
}

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function listSheetsDescriptor(): ToolDescriptor {
  return {
    name: LIST_EXCEL_SHEETS_TOOL,
    description: [
      "List the sheet (tab) names in an Excel workbook (.xlsx), in workbook",
      "order. Use this first to discover which sheets exist before reading or",
      "querying one. file_path is workspace-relative.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
      },
    },
  };
}

function getColumnsDescriptor(): ToolDescriptor {
  return {
    name: GET_EXCEL_COLUMNS_TOOL,
    description: [
      "Return the column headers (first row) of a sheet, in order. If sheet_name",
      "is omitted, the first sheet is used. Use this to learn the column names",
      "before querying or appending rows.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Sheet to inspect; defaults to the first sheet." },
      },
    },
  };
}

function readSheetDescriptor(): ToolDescriptor {
  return {
    name: READ_EXCEL_SHEET_TOOL,
    description: [
      "Read an entire sheet as rows. Returns the column headers and every data",
      "row as an object keyed by column name (the header row itself is not",
      "included as a data row). For large sheets prefer query_excel_rows to",
      "filter server-side instead of reading everything.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path", "sheet_name"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Name of the sheet to read." },
      },
    },
  };
}

function queryRowsDescriptor(): ToolDescriptor {
  return {
    name: QUERY_EXCEL_ROWS_TOOL,
    description: [
      "Return only the rows of a sheet that satisfy ALL of the given filter",
      "conditions (logical AND). Each condition is {column, op, value} where op",
      "is one of: eq, ne, gt, gte, lt, lte, contains. Ordering ops (gt/gte/lt/lte)",
      "compare numerically and skip non-numeric cells; eq/ne match by value",
      "(3 and \"3\" are equal); contains is a substring match. If sheet_name is",
      "omitted the first sheet is used. An empty/omitted filter returns all rows.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path", "filter_conditions"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Sheet to query; defaults to the first sheet." },
        filter_conditions: {
          type: "array",
          description: "Conditions AND-ed together. Empty array matches every row.",
          items: {
            type: "object",
            required: ["column", "op", "value"],
            properties: {
              column: { type: "string", description: "Column header to test." },
              op: {
                type: "string",
                enum: [...FILTER_OPS],
                description: "Comparison operator.",
              },
              value: { description: "Value to compare the cell against." },
            },
          },
        },
      },
    },
  };
}

function appendRowsDescriptor(): ToolDescriptor {
  return {
    name: APPEND_EXCEL_ROWS_TOOL,
    description: [
      "Append rows to the END of a sheet. Each row is an object keyed by column",
      "name; keys are matched to existing headers, and any new key adds a new",
      "column. If the file or the named sheet does not exist yet it is created.",
      "file_path is workspace-relative.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path", "sheet_name", "rows"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Sheet to append to (created if missing)." },
        rows: {
          type: "array",
          description: "Rows to append, each an object keyed by column name.",
          items: { type: "object" },
        },
      },
    },
  };
}

function appendAfterRowsDescriptor(): ToolDescriptor {
  return {
    name: APPEND_AFTER_EXCEL_ROWS_TOOL,
    description: [
      "Insert rows immediately AFTER a specific data row. after_row is 0-based on",
      "data rows (the header is not counted): 0 inserts right after the header",
      "(before the first data row), 1 inserts after the first data row, and so on.",
      "after_row must not exceed the current number of data rows. Otherwise behaves",
      "like append_excel_rows (header matching, new columns, file/sheet creation).",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path", "sheet_name", "after_row", "rows"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Sheet to insert into (created if missing)." },
        after_row: {
          type: "integer",
          minimum: 0,
          description: "0-based data-row index to insert after (0 = right after the header).",
        },
        rows: {
          type: "array",
          description: "Rows to insert, each an object keyed by column name.",
          items: { type: "object" },
        },
      },
    },
  };
}

function deleteRowsDescriptor(): ToolDescriptor {
  return {
    name: DELETE_EXCEL_ROWS_TOOL,
    description: [
      "Delete specific rows from a sheet by their 0-based data row indices.",
      "row_indices is a list of 0-based indices (0 = first data row, 1 = second,",
      "etc.; the header is never counted). Invalid indices are ignored; if all",
      "indices are out of range the operation fails.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["file_path", "sheet_name", "row_indices"],
      properties: {
        file_path: { type: "string", description: "Workspace-relative path to the .xlsx file." },
        sheet_name: { type: "string", description: "Sheet to delete rows from." },
        row_indices: {
          type: "array",
          description: "0-based data-row indices to delete (0 = first data row).",
          items: { type: "integer", minimum: 0 },
        },
      },
    },
  };
}

import { randomUUID } from "node:crypto";

import type { Mcp, ToolExecutionResult } from "../mcp/mcp.js";
import type { ToolDescriptor } from "../providers/provider.js";
import type { RuntimeContext } from "../runtime/types.js";
import type { OrchestratorListener } from "../runners/runner-events.js";
import { OrchestratorEventTypes } from "../runners/runner-events.js";
import { DispatchTracker, dispatchSignature, type DispatchAsk } from "./dispatch-tracker.js";
import type { TurnBindable } from "./types.js";
import { buildSubRuntime } from "../runtime/build-sub-runtime.js";

/**
 * A tool hosted on the executor server. Same shape as LocalMcp's LocalTool,
 * except the descriptor is produced by a function: the dispatch descriptor
 * embeds the executor's LIVE tool enum, so it cannot be a static object.
 */
interface ExecutorTool {
  /** Bare name — `callTool` receives it with the server prefix stripped. */
  name: string;
  describe(): ToolDescriptor;
  invoke(args: Record<string, unknown>): Promise<ToolExecutionResult>;
}

/**
 * ExecutorLocalMcp — in-process MCP server for executor coordination:
 * `executor__dispatch` (run one mutation) and `executor__list_tools`
 * (introspect what dispatch can target). Each dispatch builds a BRAND-NEW
 * child runtime from scratch with role "executor" — its own session
 * (parent-linked), context snapshot, registries, and persistence. Nothing is
 * shared with the parent runtime besides the workspace, so dispatches cannot
 * pollute each other or the parent; an executor child is ephemeral, sized to
 * one tool-call-shaped ask, and its persisted session is the future resume
 * point for the sub-task.
 *
 * Constructed ONCE at middleware startup with a `RuntimeContext` reference.
 * All context fields are resolved lazily at call time (the ctx object is fully
 * populated by the time any tool call arrives). Per-turn state (signal, emit,
 * tracker) is injected by the orchestrator via `bindTurn` before each turn.
 *
 * Only one executor dispatch can run at a time: a promise-chain mutex ensures
 * sequential execution without blocking the caller's microtask queue.
 */
export class ExecutorLocalMcp implements Mcp, TurnBindable {
  public readonly name = "executor";

  private readonly toolsByName: Map<string, ExecutorTool>;

  // Promise-chain mutex: each dispatch chains after the previous one settles.
  private runLock: Promise<void> = Promise.resolve();

  // Per-turn context — set by the orchestrator before each user turn.
  private turnSignal: AbortSignal | undefined = undefined;
  private turnEmit: OrchestratorListener = () => {};
  private turnTracker: DispatchTracker | undefined = undefined;

  constructor(private readonly ctx: RuntimeContext) {
    const tools: ExecutorTool[] = [
      {
        name: "dispatch",
        describe: () =>
          buildDispatchDescriptor(this.resolveExecutorTools().map((tool) => tool.name)),
        invoke: (args) => this.dispatch(args),
      },
      {
        // Read-only introspection — answered in-process, never spawns an executor.
        name: "list_tools",
        describe: () => LIST_TOOLS_DESCRIPTOR,
        invoke: async () => ({
          isError: false,
          content: JSON.stringify(this.resolveExecutorTools(), null, 2),
        }),
      },
    ];
    this.toolsByName = new Map(tools.map((tool) => [tool.name, tool]));
  }

  /**
   * Called by the orchestrator at the start of every turn that may dispatch.
   * Binds the current abort signal, event emitter, and dispatch tracker so
   * the executor sub-run shares them without needing them in the tool args.
   */
  public bindTurn(
    signal: AbortSignal | undefined,
    emit: OrchestratorListener,
    tracker: DispatchTracker
  ): void {
    this.turnSignal = signal;
    this.turnEmit = emit;
    this.turnTracker = tracker;
  }

  public listTools(): ToolDescriptor[] {
    return [...this.toolsByName.values()].map((tool) => tool.describe());
  }

  /**
   * Full descriptors of the tools the executor role may run, resolved fresh on
   * every advertisement (role → model → models.json `mcp` list) so they track
   * live server mounts: declared-but-unmounted servers drop out, exactly like
   * the orchestrator's own server resolution.
   */
  private resolveExecutorTools(): ToolDescriptor[] {
    const modelsRegistry = this.ctx.modelsRegistry;
    const mcpRegistry = this.ctx.mcpRegistry;
    if (!modelsRegistry || !mcpRegistry) return [];
    return modelsRegistry
      .getValidMcpForModel(EXECUTOR_ROLE)
      // A dispatch must never target dispatch itself.
      .filter((serverName) => serverName !== this.name)
      .flatMap((serverName) => mcpRegistry.getClient(serverName)?.listTools() ?? []);
  }

  public async callTool(
    toolName: string,
    args: Record<string, unknown>
  ): Promise<ToolExecutionResult> {
    const executorTool = this.toolsByName.get(toolName);
    if (!executorTool) {
      return { isError: true, content: `Unknown tool "${toolName}" on executor server.` };
    }
    return executorTool.invoke(args);
  }

  private async dispatch(args: Record<string, unknown>): Promise<ToolExecutionResult> {
    const tool = String(args.tool ?? "");
    const toolArgs = (typeof args.args === "object" && args.args !== null && !Array.isArray(args.args)
      ? args.args
      : {}) as Record<string, unknown>;
    const intent = String(args.intent ?? "");

    if (!tool) return { isError: true, content: "[dispatch-error] tool is required" };
    if (!intent) return { isError: true, content: "[dispatch-error] intent is required" };

    // Cap and duplicate guard run BEFORE entering the mutex so we fail fast
    // without queuing behind a running dispatch.
    const tracker = this.turnTracker;
    if (tracker) {
      const reservation = tracker.reserve();
      if (!reservation.ok) {
        this.turnEmit({ type: "warning", data: { message: reservation.reason } });
        return { isError: true, content: `[dispatch-blocked] ${reservation.reason}` };
      }

      const ask: DispatchAsk = { tool, args: toolArgs, intent };
      if (tracker.isDuplicate(dispatchSignature(ask))) {
        return {
          isError: true,
          content:
            "EVALUATOR: STOP — duplicate dispatch. You already ran this exact mutation " +
            "successfully this turn; repeating it changes nothing. Re-read the request " +
            "and workspace state, then take a DIFFERENT next action — or produce a final " +
            "answer with NO tool calls.",
        };
      }
    }

    // Mutex: chain this dispatch after any currently-running one.
    const prev = this.runLock;
    let resolve!: () => void;
    this.runLock = new Promise((r) => (resolve = r));
    try {
      await prev;
      return await this.runDispatch(tool, toolArgs, intent, tracker);
    } finally {
      resolve();
    }
  }

  public async shutdown(): Promise<void> {}

  // ---------------------------------------------------------------------------

  private async runDispatch(
    tool: string,
    toolArgs: Record<string, unknown>,
    intent: string,
    tracker: DispatchTracker | undefined
  ): Promise<ToolExecutionResult> {
    // Construct the canonical ask message the executor Orchestrator will receive.
    const askMessage =
      `Tool: ${tool}\n` +
      `Args: ${JSON.stringify(toolArgs, null, 2)}\n` +
      `Intent: ${intent}`;

    this.turnEmit({
      type: OrchestratorEventTypes.DISPATCH_START,
      data: { tool, intent, args: toolArgs },
    });

    // Brand-new child runtime per dispatch: own session (parent-linked, fresh
    // id), own registries and context snapshot, persisted by its own store.
    // Deliberately built from scratch — no parent state leaks in, no dispatch
    // sees another's transcript; a failed ask is simply dispatched again.
    const parentSession = this.ctx.session!;
    const childRuntime = buildSubRuntime(
      {
        configPath: this.ctx.configPath,
        orchestratorRole: EXECUTOR_ROLE,
        sessionsDir: this.ctx.sessionsDir,
        workspaceRoot: this.ctx.workspaceRoot,
        sandboxRoot: this.ctx.sandboxRoot,
        mcpConfigPath: this.ctx.mcpConfigPath,
        credentials: this.ctx.credentials,
      },
      {
        sessionId: randomUUID(),
        parentSessionId: parentSession.sessionId,
        workspaceId: parentSession.workspaceId,
        user: parentSession.user,
      }
    );

    const emit = this.turnEmit;
    let content: string;
    let ok: boolean;
    let iterations = 0;
    let usage: ToolExecutionResult["usage"];
    let runtime: Awaited<ReturnType<typeof childRuntime.build>> | undefined;

    try {
      runtime = await childRuntime.build();
      const result = await runtime.dispatchAsync(askMessage, {
        signal: this.turnSignal,
        // Forward executor sub-run events so the REPL can render them.
        onEvent: (event) =>
          emit({ type: "executor-event", data: { ...event.data, kind: event.type } }),
      });
      content = result.finalMessage.content;
      ok = result.outcome === "satisfied";
      iterations = result.iterations;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      content = `[executor-error] ${msg}`;
      ok = false;
    }

    // The child accumulated its own model usage while running; expose it on
    // the tool result so the parent folds the delegated cost into its tally.
    // A failed dispatch still burned tokens, so this sits outside the try.
    if (runtime) usage = { ...runtime.getSession().counters };

    if (tracker && ok) {
      tracker.recordSuccess(dispatchSignature({ tool, args: toolArgs, intent }));
    }

    emit({
      type: OrchestratorEventTypes.DISPATCH_FEEDBACK,
      data: {
        ok,
        ack: extractFirstLine(content, "EXECUTOR: ACK"),
        evidence: extractFirstLine(content, "EXECUTOR: RESULT"),
        deterministicVerdict: "unverified",
        iterations,
      },
    });

    return { isError: !ok, content, usage };
  }
}

// ---------------------------------------------------------------------------
// Dispatch descriptor builder. The "tool" property carries a strict enum of
// the executor-side tool names AND repeats them in the description: the enum
// rejects invented names at the schema level, the prose list keeps the names
// visible to models that ignore enums (prompted-JSON fallbacks). Built per
// listTools() call so it tracks live server mounts.
// ---------------------------------------------------------------------------

const EXECUTOR_ROLE = "executor" as const;

// Read-only safety net beside the dispatch enum: when the orchestrator is
// unsure of a target tool's exact name or argument shape, it can fetch the
// full descriptors (name, description, inputSchema) instead of guessing.
const LIST_TOOLS_DESCRIPTOR: ToolDescriptor = {
  name: "executor__list_tools",
  description:
    "List the tools the EXECUTOR can run via executor__dispatch, as full JSON " +
    "descriptors (name, description, inputSchema). Read-only and instant — call " +
    "it whenever you are unsure of a dispatch target's exact name or argument " +
    "shape instead of guessing.",
  inputSchema: {
    type: "object",
    properties: {},
  },
};

function buildDispatchDescriptor(executorToolNames: string[]): ToolDescriptor {
  const toolListBlock =
    executorToolNames.length > 0
      ? 'Valid "tool" values (the ONLY accepted names):\n' +
        executorToolNames.map((name) => `  - ${name}`).join("\n")
      : "No executor-side tools are currently mounted; any dispatch will fail.";

  return {
    name: "executor__dispatch",
    description: [
      "Spawn the EXECUTOR sub-agent to perform exactly one mutation.",
      "This is the ONLY way the orchestrator can change state — write_file,",
      "edit_file, and shell tools are NOT directly callable by the orchestrator.",
      "",
      'Provide "tool" as the fully-namespaced executor-side tool name.',
      '"args" is the exact argument object for that tool. "intent" is a',
      "one-line plain-English description of what this dispatch accomplishes;",
      "the executor uses it to interpret the action.",
      "",
      toolListBlock,
      "",
      "The executor will ACK the ask, run the tool, independently re-read or",
      "check the result, and return a RESULT line with evidence.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["tool", "args", "intent"],
      properties: {
        tool: {
          type: "string",
          // Omit an empty enum rather than emit an unsatisfiable schema.
          ...(executorToolNames.length > 0 ? { enum: executorToolNames } : {}),
          description:
            "Fully-namespaced executor-side tool name. Must be one of the names " +
            "enumerated in this tool's description.",
        },
        args: {
          type: "object",
          description: "Exact argument object for the named tool.",
        },
        intent: {
          type: "string",
          description: "One-line plain-English description of what this dispatch accomplishes.",
        },
      },
    },
  };
}

// ---------------------------------------------------------------------------
// Parse helpers — the executor emits structured lines; we pull the key bits
// for the dispatch-feedback event without requiring a full regex suite.
// ---------------------------------------------------------------------------

function extractFirstLine(content: string, prefix: string): string {
  const line = content.split("\n").find((l) => l.startsWith(prefix));
  return line ?? "";
}

/**
 * In-process filesystem/search MCP server.
 *
 * This is the former spawned `fsmcp` stdio server, lifted into the agent
 * process. It owns the same seven filesystem/search tools, but it is no longer
 * fronted by an SDK `Server` reached over an in-memory transport: the tools are
 * exposed directly as a `LocalMcp`, so a tool call is a plain in-process
 * function call — no JSON-RPC round-trip.
 *
 * From the registry's perspective a `LocalMcp` is indistinguishable from a
 * spawned stdio server (`McpClient`): both satisfy the `Mcp` interface.
 *
 * The workspace root is injected (rather than read from AGENT_WORKSPACE) so the
 * tools resolve files to the SAME sandbox root the agent is configured with.
 *
 * Architecture role: Repository / External layer. No agent logic here — pure
 * tool handlers behind a thin in-process adapter.
 */

import type { ZodTypeAny } from "zod";

import type { ToolDescriptor } from "../providers/provider.js";
import { LocalMcp, type LocalTool } from "../mcp/local-mcp.js";
import type { ToolExecutionResult } from "../mcp/mcp.js";

import { zodToJsonSchema } from "./fs-tools/schema-helpers.js";
import { createWorkspace, WorkspaceViolationError, type Workspace } from "./fs-tools/workspace.js";

import { readFile, readFileSchema } from "./fs-tools/read-file.js";
import { writeFile, writeFileSchema } from "./fs-tools/write-file.js";
import { editFile, editFileSchema, EditFileError } from "./fs-tools/edit-file.js";
import { deleteFile, deleteFileSchema, DeleteFileError } from "./fs-tools/delete-file.js";
import { listDir, listDirSchema } from "./fs-tools/list-dir.js";
import { glob, globSchema } from "./fs-tools/glob.js";
import { grep, grepSchema } from "./fs-tools/grep.js";

/** The MCP server name this module mounts under (tools namespace as `fsmcp__*`). */
export const FS_SERVER_NAME = "fsmcp";

/**
 * A registered tool, paired with its typed schema.
 *
 * `defineTool` accepts a typed schema + typed handler and packs them into a
 * uniform shape: the runtime handler takes `unknown` arguments and does the Zod
 * parse itself, keeping the tools array a single concrete type.
 */
interface RegisteredTool {
  name: string;
  description: string;
  inputSchema: ZodTypeAny;
  invoke: (rawArguments: unknown, workspace: Workspace) => Promise<unknown>;
}

function defineTool<Schema extends ZodTypeAny>(definition: {
  name: string;
  description: string;
  schema: Schema;
  handler: (input: ReturnType<Schema["parse"]>, workspace: Workspace) => Promise<unknown>;
}): RegisteredTool {
  return {
    name: definition.name,
    description: definition.description,
    inputSchema: definition.schema,
    invoke: async (rawArguments, workspace) => {
      const parsedInput = definition.schema.parse(rawArguments ?? {});
      return definition.handler(parsedInput, workspace);
    },
  };
}

/** Build the filesystem/search tools. Order matches the former fsmcp listing. */
function createFsTools(): RegisteredTool[] {
  return [
    defineTool({
      name: "read_file",
      description:
        "Read a UTF-8 text file from the workspace. Supports optional line ranges. " +
        "Returns total_lines, the returned_range, and the file content.",
      schema: readFileSchema,
      handler: (input, ws) => readFile(input, ws),
    }),
    defineTool({
      name: "write_file",
      description:
        "Create or overwrite a UTF-8 text file in the workspace. Parent directories are " +
        "created automatically unless create_directories is set to false.",
      schema: writeFileSchema,
      handler: (input, ws) => writeFile(input, ws),
    }),
    defineTool({
      name: "edit_file",
      description:
        "Replace an exact substring within an existing file. The match must be unique " +
        "unless replace_all is true. Fails if old_string is not found verbatim.",
      schema: editFileSchema,
      handler: (input, ws) => editFile(input, ws),
    }),
    defineTool({
      name: "delete_file",
      description:
        "Delete a file or directory in the workspace. Files are removed directly; " +
        "deleting a directory requires recursive: true and removes all of its contents. " +
        "Refuses to delete the workspace root and fails if the path does not exist.",
      schema: deleteFileSchema,
      handler: (input, ws) => deleteFile(input, ws),
    }),
    defineTool({
      name: "list_dir",
      description:
        "List the contents of a directory inside the workspace. Directories are returned " +
        "first, then files, alphabetically.",
      schema: listDirSchema,
      handler: (input, ws) => listDir(input, ws),
    }),
    defineTool({
      name: "glob",
      description:
        'Find files in the workspace by glob pattern (e.g. "src/**/*.ts"). Returns paths ' +
        "relative to the workspace root.",
      schema: globSchema,
      handler: (input, ws) => glob(input, ws),
    }),
    defineTool({
      name: "grep",
      description:
        "Search file contents in the workspace using a JavaScript regular expression. " +
        "Skips binary files, node_modules, .git, and dist by default.",
      schema: grepSchema,
      handler: (input, ws) => grep(input, ws),
    }),
  ];
}

/**
 * Render a tool error the same way the former fsmcp server did, so result
 * strings the agent already parses stay byte-for-byte compatible.
 */
function formatToolError(err: unknown): string {
  if (err instanceof WorkspaceViolationError) {
    return `Workspace violation: ${err.message}`;
  }
  if (err instanceof EditFileError) {
    return `Edit failed: ${err.message}`;
  }
  if (err instanceof DeleteFileError) {
    return `Delete failed: ${err.message}`;
  }
  if (err instanceof Error) {
    return `${err.name}: ${err.message}`;
  }
  return `Unknown error: ${String(err)}`;
}

/**
 * Adapt a `RegisteredTool` (Zod schema + workspace-bound handler) into a
 * `LocalTool`: a JSON-schema descriptor plus a direct invocation that does the
 * Zod parse, serializes the result, and shapes errors exactly as the former
 * stdio server's `CallTool` handler did.
 */
function toLocalTool(tool: RegisteredTool, workspace: Workspace): LocalTool {
  const descriptor: ToolDescriptor = {
    name: tool.name,
    description: tool.description,
    inputSchema: zodToJsonSchema(tool.inputSchema) as Record<string, unknown>,
  };

  return {
    descriptor,
    invoke: async (args): Promise<ToolExecutionResult> => {
      try {
        const result = await tool.invoke(args, workspace);
        return { isError: false, content: JSON.stringify(result, null, 2) };
      } catch (err) {
        return { isError: true, content: formatToolError(err) };
      }
    },
  };
}

/**
 * Build the in-process fsmcp server as a `LocalMcp` bound to `workspaceRoot`.
 *
 * The returned server can be registered directly with the MCP registry and is
 * indistinguishable from a spawned stdio server to every consumer.
 */
export function createFsLocalMcp(workspaceRoot: string): LocalMcp {
  const workspace = createWorkspace(workspaceRoot);
  const tools = createFsTools().map((tool) => toLocalTool(tool, workspace));
  return new LocalMcp(FS_SERVER_NAME, tools);
}

/** The read-only filesystem mount (tools namespace as `fsreadonly__*`). */
export const FS_READONLY_SERVER_NAME = "fsreadonly";

/**
 * ALLOWLIST, not a denylist: a mutating tool added to `createFsTools` later
 * stays out of the read-only mount unless deliberately listed here — the safe
 * failure mode for an enforcement boundary.
 */
const READ_ONLY_FS_TOOL_NAMES = new Set(["read_file", "list_dir", "glob", "grep"]);

/**
 * The read-only filesystem mount for coordinator roles. The orchestrator's
 * "read-only" contract was previously prompt-level only — its models.json
 * whitelist granted the whole fsmcp server, mutations included. Mounting an
 * inspection-only subset under its own server name turns that contract into
 * an enforced boundary: write/edit/delete are not advertised AND not callable,
 * regardless of what the model decides to try.
 */
export function createFsReadonlyLocalMcp(workspaceRoot: string): LocalMcp {
  const workspace = createWorkspace(workspaceRoot);
  const tools = createFsTools()
    .filter((tool) => READ_ONLY_FS_TOOL_NAMES.has(tool.name))
    .map((tool) => toLocalTool(tool, workspace));
  return new LocalMcp(FS_READONLY_SERVER_NAME, tools);
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "./workspace.js";

export const deleteFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file or directory to delete."),
  recursive: z
    .boolean()
    .optional()
    .default(false)
    .describe(
      "Required true to delete a directory and everything inside it. Ignored for files. " +
        "Deleting a directory without recursive:true is refused as a safety guard."
    ),
});

export type DeleteFileInput = z.infer<typeof deleteFileSchema>;

export interface DeleteFileResult {
  path: string;
  deleted: boolean;
  kind: "file" | "directory";
}

export class DeleteFileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DeleteFileError";
  }
}

export async function deleteFile(
  input: DeleteFileInput,
  workspace: Workspace
): Promise<DeleteFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);

  // Never let a delete remove the workspace root itself — that would wipe the
  // entire sandbox and is almost certainly a mistake, not an intent.
  if (path.resolve(absolutePath) === path.resolve(workspace.root)) {
    throw new DeleteFileError(
      "Refusing to delete the workspace root. Target a specific file or subdirectory instead."
    );
  }

  // Stat without following symlinks so a link is removed as a link, and so a
  // missing path fails loudly rather than silently succeeding.
  let stats;
  try {
    stats = await fs.lstat(absolutePath);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      throw new DeleteFileError(
        `No such file or directory: ${workspace.relativize(absolutePath)}`
      );
    }
    throw err;
  }

  if (stats.isDirectory()) {
    if (!input.recursive) {
      throw new DeleteFileError(
        `${workspace.relativize(absolutePath)} is a directory. ` +
          `Pass recursive: true to delete it and all of its contents.`
      );
    }
    await fs.rm(absolutePath, { recursive: true, force: false });
    return { path: workspace.relativize(absolutePath), deleted: true, kind: "directory" };
  }

  // Regular file or symlink: remove the entry itself.
  await fs.rm(absolutePath, { force: false });
  return { path: workspace.relativize(absolutePath), deleted: true, kind: "file" };
}

import fs from "node:fs/promises";
import { z } from "zod";

import type { Workspace } from "./workspace.js";

export const editFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to edit."),
  old_string: z
    .string()
    .min(1)
    .describe(
      "Exact text to replace. Must match the file's current content byte-for-byte and " +
        "must be unique within the file unless replace_all is true."
    ),
  new_string: z
    .string()
    .describe("Replacement text. May be empty to delete the matched region."),
  replace_all: z
    .boolean()
    .optional()
    .default(false)
    .describe("If true, replace every occurrence of old_string instead of requiring uniqueness."),
});

export type EditFileInput = z.infer<typeof editFileSchema>;

export interface EditFileResult {
  path: string;
  replacements: number;
}

export class EditFileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EditFileError";
  }
}

export async function editFile(
  input: EditFileInput,
  workspace: Workspace
): Promise<EditFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const original = await fs.readFile(absolutePath, "utf8");

  // Disallow editing if the target text never appears in the file.
  // The model must read the file first; otherwise we fail loudly so it can adjust.
  if (!original.includes(input.old_string)) {
    throw new EditFileError(
      `old_string was not found in ${workspace.relativize(absolutePath)}. ` +
        `Read the file first and copy the text exactly, including whitespace.`
    );
  }

  let updated: string;
  let replacements: number;

  if (input.replace_all) {
    const parts = original.split(input.old_string);
    replacements = parts.length - 1;
    updated = parts.join(input.new_string);
  } else {
    const occurrences = countOccurrences(original, input.old_string);

    if (occurrences > 1) {
      throw new EditFileError(
        `old_string appears ${occurrences} times in ${workspace.relativize(
          absolutePath
        )}. Provide more surrounding context to make it unique, or set replace_all: true.`
      );
    }

    updated = original.replace(input.old_string, input.new_string);
    replacements = 1;
  }

  await fs.writeFile(absolutePath, updated, "utf8");

  return {
    path: workspace.relativize(absolutePath),
    replacements,
  };
}

function countOccurrences(haystack: string, needle: string): number {
  if (needle.length === 0) return 0;
  let count = 0;
  let index = 0;
  while ((index = haystack.indexOf(needle, index)) !== -1) {
    count += 1;
    index += needle.length;
  }
  return count;
}

export interface GlobResult {
  pattern: string;
  cwd: string;
  matches: string[];
  truncated: boolean;
}

export async function glob(input: GlobInput, workspace: Workspace): Promise<GlobResult> {
  const cwdAbsolute = workspace.resolveSafe(input.cwd ?? ".");
  const limit = input.max_results ?? 500;

  // fast-glob gives us paths relative to `cwd` when `absolute: false`.
  // We then turn them into workspace-relative paths so the model always
  // sees the same coordinate system.
  const rawMatches = await fastGlob(input.pattern, {
    cwd: cwdAbsolute,
    dot: input.include_hidden,
    onlyFiles: false,
    followSymbolicLinks: false,
    absolute: true,
    suppressErrors: true,
  });

  const matches: string[] = [];
  for (const absolute of rawMatches) {
    // Defence in depth: confirm every match is still inside the workspace.
    // fast-glob shouldn't escape, but symlinks and "../" patterns are worth guarding against.
    try {
      const safeAbsolute = workspace.resolveSafe(absolute);
      matches.push(workspace.relativize(safeAbsolute));
    } catch {
      continue;
    }

    if (matches.length >= limit) break;
  }

  return {
    pattern: input.pattern,
    cwd: workspace.relativize(cwdAbsolute),
    matches,
    truncated: rawMatches.length > matches.length,
  };
}

export interface GrepMatch {
  path: string;
  line_number: number;
  line: string;
}

export interface GrepResult {
  pattern: string;
  path_glob: string;
  matches: GrepMatch[];
  truncated: boolean;
  files_scanned: number;
}

// Cheap binary-file heuristic: if the first 4 KB contains a null byte we treat
// it as binary and skip it. Misses obscure formats but is fast and safe.
const BINARY_PROBE_BYTES = 4096;

export async function grep(input: GrepInput, workspace: Workspace): Promise<GrepResult> {
  const root = workspace.root;
  const limit = input.max_results ?? 200;

  const flags = input.case_insensitive ? "i" : "";
  let regex: RegExp;
  try {
    regex = new RegExp(input.pattern, flags);
  } catch (err) {
    throw new Error(
      `Invalid regular expression "${input.pattern}": ${(err as Error).message}`
    );
  }

  const candidatePaths = await fastGlob(input.path_glob ?? "**/*", {
    cwd: root,
    dot: false,
    onlyFiles: true,
    followSymbolicLinks: false,
    absolute: true,
    suppressErrors: true,
    ignore: ["**/node_modules/**", "**/.git/**", "**/dist/**"],
  });

  const matches: GrepMatch[] = [];
  let filesScanned = 0;
  let truncated = false;

  for (const absolutePath of candidatePaths) {
    let safeAbsolute: string;
    try {
      safeAbsolute = workspace.resolveSafe(absolutePath);
    } catch {
      continue;
    }

    if (await looksBinary(safeAbsolute)) continue;

    let content: string;
    try {
      content = await fs.readFile(safeAbsolute, "utf8");
    } catch {
      continue;
    }
    filesScanned += 1;

    const relativePath = workspace.relativize(safeAbsolute);
    const lines = content.split(/\r?\n/);

    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i];
      if (regex.test(line)) {
        matches.push({ path: relativePath, line_number: i + 1, line });
        if (matches.length >= limit) {
          truncated = true;
          break;
        }
      }
    }

    if (truncated) break;
  }

  return {
    pattern: input.pattern,
    path_glob: input.path_glob ?? "**/*",
    matches,
    truncated,
    files_scanned: filesScanned,
  };
}

async function looksBinary(absolutePath: string): Promise<boolean> {
  try {
    const handle = await fs.open(absolutePath, "r");
    try {
      const buffer = Buffer.alloc(BINARY_PROBE_BYTES);
      const { bytesRead } = await handle.read(buffer, 0, BINARY_PROBE_BYTES, 0);
      for (let i = 0; i < bytesRead; i += 1) {
        if (buffer[i] === 0) return true;
      }
      return false;
    } finally {
      await handle.close();
    }
  } catch {
    return true;
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "./workspace.js";

export const listDirSchema = z.object({
  path: z
    .string()
    .min(1)
    .default(".")
    .describe("Workspace-relative or absolute directory path. Defaults to the workspace root."),
  include_hidden: z
    .boolean()
    .optional()
    .default(false)
    .describe("If true, include entries that start with a dot (e.g. .git, .env)."),
  max_entries: z
    .number()
    .int()
    .positive()
    .optional()
    .default(500)
    .describe("Cap on the number of entries returned. Defaults to 500."),
});

export type ListDirInput = z.infer<typeof listDirSchema>;

export interface DirEntry {
  name: string;
  type: "file" | "directory" | "symlink" | "other";
  size_bytes?: number;
}

export interface ListDirResult {
  path: string;
  total_entries: number;
  truncated: boolean;
  entries: DirEntry[];
}

export async function listDir(
  input: ListDirInput,
  workspace: Workspace
): Promise<ListDirResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const raw = await fs.readdir(absolutePath, { withFileTypes: true });

  const filtered = input.include_hidden
    ? raw
    : raw.filter((entry) => !entry.name.startsWith("."));

  // Sort directories first, then files, then alphabetically — easier for the model to scan.
  filtered.sort((a, b) => {
    const aIsDir = a.isDirectory();
    const bIsDir = b.isDirectory();
    if (aIsDir !== bIsDir) return aIsDir ? -1 : 1;
    return a.name.localeCompare(b.name);
  });

  const limit = input.max_entries ?? 500;
  const truncated = filtered.length > limit;
  const visibleEntries = filtered.slice(0, limit);

  const entries: DirEntry[] = await Promise.all(
    visibleEntries.map(async (entry) => {
      const entryPath = path.join(absolutePath, entry.name);
      const type = classifyEntry(entry);

      // Only stat files — directory sizes aren't meaningful here and we'd pay extra IO.
      let sizeBytes: number | undefined;
      if (type === "file") {
        try {
          const stat = await fs.stat(entryPath);
          sizeBytes = stat.size;
        } catch {
          sizeBytes = undefined;
        }
      }

      return { name: entry.name, type, size_bytes: sizeBytes };
    })
  );

  return {
    path: workspace.relativize(absolutePath),
    total_entries: filtered.length,
    truncated,
    entries,
  };
}

function classifyEntry(entry: import("node:fs").Dirent): DirEntry["type"] {
  if (entry.isDirectory()) return "directory";
  if (entry.isFile()) return "file";
  if (entry.isSymbolicLink()) return "symlink";
  return "other";
}

import fs from "node:fs/promises";
import { z } from "zod";

import type { Workspace } from "./workspace.js";

export const readFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to read."),
  start_line: z
    .number()
    .int()
    .positive()
    .optional()
    .describe("1-indexed first line to return. Omit to start at line 1."),
  end_line: z
    .number()
    .int()
    .positive()
    .optional()
    .describe("1-indexed last line to return (inclusive). Omit to read to EOF."),
});

export type ReadFileInput = z.infer<typeof readFileSchema>;

export interface ReadFileResult {
  path: string;
  total_lines: number;
  returned_range: { start: number; end: number };
  content: string;
}

export async function readFile(
  input: ReadFileInput,
  workspace: Workspace
): Promise<ReadFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const raw = await fs.readFile(absolutePath, "utf8");

  const lines = raw.split(/\r?\n/);
  const totalLines = lines.length;

  const startLine = input.start_line ?? 1;
  const endLine = Math.min(input.end_line ?? totalLines, totalLines);

  if (startLine > totalLines) {
    return {
      path: workspace.relativize(absolutePath),
      total_lines: totalLines,
      returned_range: { start: startLine, end: startLine - 1 },
      content: "",
    };
  }

  const slice = lines.slice(startLine - 1, endLine).join("\n");

  return {
    path: workspace.relativize(absolutePath),
    total_lines: totalLines,
    returned_range: { start: startLine, end: endLine },
    content: slice,
  };
}

interface JsonSchemaNode {
  type?: string;
  description?: string;
  enum?: string[];
  default?: unknown;
  minimum?: number;
  exclusiveMinimum?: number;
  properties?: Record<string, JsonSchemaNode>;
  required?: string[];
  additionalProperties?: boolean;
}

export function zodToJsonSchema(schema: ZodTypeAny): JsonSchemaNode {
  return convertNode(schema);
}

function convertNode(node: ZodTypeAny): JsonSchemaNode {
  const description = node.description;

  if (node instanceof z.ZodObject) {
    return convertObject(node, description);
  }
  if (node instanceof z.ZodString) {
    return withDescription({ type: "string" }, description);
  }
  if (node instanceof z.ZodNumber) {
    return convertNumber(node, description);
  }
  if (node instanceof z.ZodBoolean) {
    return withDescription({ type: "boolean" }, description);
  }
  if (node instanceof z.ZodEnum) {
    return withDescription({ type: "string", enum: [...node.options] }, description);
  }
  if (node instanceof z.ZodOptional) {
    return convertNode(node.unwrap());
  }
  if (node instanceof z.ZodDefault) {
    const inner = convertNode(node.removeDefault());
    inner.default = node._def.defaultValue();
    return withDescription(inner, description ?? inner.description);
  }

  // Unknown node type — return an empty schema so callers don't blow up.
  return withDescription({}, description);
}

function convertObject(node: z.ZodObject<z.ZodRawShape>, description?: string): JsonSchemaNode {
  const shape = node.shape;
  const properties: Record<string, JsonSchemaNode> = {};
  const required: string[] = [];

  for (const [key, child] of Object.entries(shape)) {
    properties[key] = convertNode(child as ZodTypeAny);

    // A property is "required" only if it has neither .optional() nor .default().
    if (!isOptionalOrDefaulted(child as ZodTypeAny)) {
      required.push(key);
    }
  }

  const result: JsonSchemaNode = {
    type: "object",
    properties,
    additionalProperties: false,
  };

  if (required.length > 0) result.required = required;
  return withDescription(result, description);
}

function convertNumber(node: z.ZodNumber, description?: string): JsonSchemaNode {
  const checks = node._def.checks ?? [];
  const isInt = checks.some((check) => check.kind === "int");

  const schema: JsonSchemaNode = { type: isInt ? "integer" : "number" };

  for (const check of checks) {
    if (check.kind === "min") {
      if (check.inclusive) schema.minimum = check.value;
      else schema.exclusiveMinimum = check.value;
    }
  }

  return withDescription(schema, description);
}

function isOptionalOrDefaulted(node: ZodTypeAny): boolean {
  return node instanceof z.ZodOptional || node instanceof z.ZodDefault;
}

function withDescription(schema: JsonSchemaNode, description: string | undefined): JsonSchemaNode {
  if (description) schema.description = description;
  return schema;
}

export class WorkspaceViolationError extends Error {
  constructor(requestedPath: string, workspaceRoot: string) {
    super(
      `Path "${requestedPath}" resolves outside the workspace root "${workspaceRoot}". ` +
        `Refusing the operation.`
    );
    this.name = "WorkspaceViolationError";
  }
}

export interface Workspace {
  readonly root: string;
  resolveSafe(userPath: string): string;
  relativize(absolutePath: string): string;
}

function resolveSafe(userPath: string): string {
  // Reject parent-traversal segments before any OS-level resolution. The
  // containment check below would catch escapes too, but an early explicit
  // reject makes hostile input fail fast and surfaces the offending path
  // directly rather than a resolved-absolute one.
  if (/(^|[/\\])\.\.($|[/\\])/.test(userPath)) {
    throw new WorkspaceViolationError(userPath, root);
  }

  // Treat a bare "." or "" as "the workspace root itself".
  const candidate = userPath === "" || userPath === "." ? root : userPath;

  // If the caller passed a relative path, anchor it at the workspace root.
  const absolute = path.isAbsolute(candidate)
    ? path.resolve(candidate)
    : path.resolve(root, candidate);

  // Normalise both sides so "C:\\Foo" and "c:\\foo\\" compare correctly on Windows.
  const normalisedRoot = path.resolve(root) + path.sep;
  const normalisedAbsolute = absolute + path.sep;

  const isInside =
    normalisedAbsolute === normalisedRoot ||
    normalisedAbsolute.startsWith(normalisedRoot);

  if (!isInside) {
    throw new WorkspaceViolationError(userPath, root);
  }

  return absolute;
}

function relativize(absolutePath: string): string {
  const rel = path.relative(root, absolutePath);
  return rel === "" ? "." : rel;
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "./workspace.js";

export const writeFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to create or overwrite."),
  content: z
    .string()
    .describe("Full file content. The file is written verbatim, no extra newline appended."),
  create_directories: z
    .boolean()
    .optional()
    .default(true)
    .describe("If true (default), create any missing parent directories."),
});

export type WriteFileInput = z.infer<typeof writeFileSchema>;

export interface WriteFileResult {
  path: string;
  bytes_written: number;
  created: boolean;
}

export async function writeFile(
  input: WriteFileInput,
  workspace: Workspace
): Promise<WriteFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);

  // Track whether the file existed beforehand so we can report create vs overwrite.
  const existedBefore = await fileExists(absolutePath);

  if (input.create_directories !== false) {
    await fs.mkdir(path.dirname(absolutePath), { recursive: true });
  }

  await fs.writeFile(absolutePath, input.content, "utf8");

  const stat = await fs.stat(absolutePath);

  return {
    path: workspace.relativize(absolutePath),
    bytes_written: stat.size,
    created: !existedBefore,
  };
}

async function fileExists(absolutePath: string): Promise<boolean> {
  try {
    await fs.access(absolutePath);
    return true;
  } catch {
    return false;
  }
}

export { DispatchTracker, dispatchSignature, type DispatchAsk } from "./dispatch-tracker.js";
export {
  createExcelTools,
  getExcelToolDescriptors,
} from "./excel-tools/excel-tools.js";
export { createSubSessionTools } from "./subsessions-tools/subsessions.js";
export type { RichToolResult, SyntheticMcp, TurnBindable, ToolContext } from "./types.js";

/**
 * In-process subsessions MCP server.
 *
 * Like the Excel server, subsessions tools need per-turn context: the session's
 * coordinator, workspace, etc. The orchestrator re-registers this LocalMcp each
 * turn with that turn's `ToolContext` baked into the tool handlers; calls route
 * to the SessionManager (the SubSessionCoordinator) — never through a transport.
 * Tool names are namespaced as `subsessions__*` (e.g. `subsessions__create_subsession`).
 *
 * Architecture role: Repository / External layer. No orchestrator logic here —
 * just tool handlers behind the `Mcp` contract.
 */

import { LocalMcp, type LocalTool } from "../mcp/local-mcp.js";
import { createSubSessionTools } from "./subsessions-tools/subsessions.js";
import type { ToolContext } from "./types.js";

/** The MCP server name this module mounts under (tools namespace as `subsessions__*`). */
export const SUBSESSIONS_SERVER_NAME = "subsessions";

/**
 * Build a subsessions `LocalMcp` for a specific turn's context.
 *
 * Mirrors `createExcelLocalMcp`: each subsession tool is already a
 * `{ descriptor, callTool(args, ctx) }`, so we bind the turn's `ToolContext`
 * into a `LocalTool.invoke(args)` to satisfy the `Mcp` contract. Tool calls are
 * plain in-process function calls — no SDK `Server` or in-memory transport.
 *
 * The handlers' optional post-call `event` is dropped here (the `LocalMcp` path
 * carries only `{ isError, content }`), matching how Excel is mounted. When the
 * turn's `ToolContext.coordinator` is absent the tools still advertise, but each
 * call returns the handlers' own "sub-sessions are not available" error.
 */
export function createSubsessionsLocalMcp(toolCtx: ToolContext): LocalMcp {
  const tools: LocalTool[] = createSubSessionTools().map((tool) => ({
    descriptor: tool.descriptor,
    invoke: async (args) => {
      const result = await tool.callTool(args ?? {}, toolCtx);
      return { isError: result.isError, content: result.content };
    },
  }));

  return new LocalMcp(SUBSESSIONS_SERVER_NAME, tools);
}

import type { ToolDescriptor } from "../../providers/provider.js";
import type { SubSessionCoordinator, SubSessionSnapshot } from "../../runners/subsession.js";
import { toolError, toolOk, type RichToolResult, type SyntheticMcp, type ToolContext } from "../types.js";

export const CREATE_SUBSESSION_TOOL = "create_subsession";
export const SUBSESSION_STATUS_TOOL = "get_subsession_status";
export const LIST_SUBSESSIONS_TOOL = "list_subsessions";
export const FINALIZE_SUBSESSION_TOOL = "finalize_subsession";

/**
 * Sub-session synthetic tools.
 *
 * Each is intercepted before MCP and routed to the SubSessionCoordinator.
 * `parentSessionId` is always taken from the context's session — the LLM never
 * supplies it, so it can't be spoofed or get out of sync, and it never appears
 * in any schema. These tools are only built (and therefore only advertised) when
 * a coordinator is wired in, which enforces the one-level-deep guard at source.
 */

export function createSubSessionTools(): SyntheticMcp[] {
  return [
    {
      name: CREATE_SUBSESSION_TOOL,
      descriptor: createDescriptor(),
      callTool: handleCreate,
    },
    {
      name: SUBSESSION_STATUS_TOOL,
      descriptor: statusDescriptor(),
      callTool: handleStatus,
    },
    {
      name: LIST_SUBSESSIONS_TOOL,
      descriptor: listDescriptor(),
      callTool: handleList,
    },
    {
      name: FINALIZE_SUBSESSION_TOOL,
      descriptor: finalizeDescriptor(),
      callTool: handleFinalize,
    },
  ];
}

async function handleCreate(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const coordinator = requireCoordinator(ctx);
  if (!coordinator) return toolError("[subsession-error] sub-sessions are not available in this run");

  const intent = args.intent;
  if (typeof intent !== "string" || intent.trim().length === 0) {
    return toolError("[subsession-error] create_subsession.intent must be a non-empty string");
  }
  const context = typeof args.context === "string" ? args.context : undefined;

  const result = coordinator.createSubSession({
    parentSessionId: ctx.session.sessionId,
    workspace: ctx.workspace,
    intent,
    context,
    // Inherit the parent's identity so the child runs (and persists) under the
    // same principal rather than as a fresh anonymous session.
    user: ctx.session.user,
  });

  // Rejected by the per-parent cap — surface as an error so the model waits on
  // or finalizes an existing child instead of retrying blindly.
  if (result.outcome === "rejected" || !result.snapshot) {
    return {
      isError: true,
      content: `[subsession-error] ${result.reason ?? "sub-session creation rejected"}`,
      event: { type: "subsession-start", data: { intent, outcome: "rejected", reason: result.reason } },
    };
  }

  // created or reused — both return the live child's snapshot. The reused note
  // tells the model it already has this work in flight.
  const prefix = result.outcome === "reused" ? `[subsession-reused] ${result.reason}\n` : "";
  return {
    isError: false,
    content: prefix + snapshotJson(result.snapshot),
    event: {
      type: "subsession-start",
      data: { subSessionId: result.snapshot.subSessionId, intent, outcome: result.outcome },
    },
  };
}

async function handleStatus(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const coordinator = requireCoordinator(ctx);
  if (!coordinator) return toolError("[subsession-error] sub-sessions are not available in this run");

  const subSessionId = requireSubSessionId(args, SUBSESSION_STATUS_TOOL);
  if (!subSessionId.ok) return toolError(subSessionId.reason);

  const result = await coordinator.getStatus(ctx.session.sessionId, subSessionId.value, ctx.signal);
  if (!result) {
    return toolError(`[subsession-error] unknown subSessionId "${subSessionId.value}" for this session`);
  }

  // When a backoff was applied the status hasn't changed since last poll — tell
  // the model to stop hammering and do other work before re-checking.
  const note =
    result.backoffMs > 0
      ? `[backoff ${result.backoffMs}ms — status unchanged ("${result.snapshot.status}") since your last check; ` +
        `do other useful work or finalize it instead of polling again immediately]\n`
      : "";

  return {
    isError: false,
    content: note + snapshotJson(result.snapshot),
    event: {
      type: "subsession-status",
      data: { subSessionId: subSessionId.value, status: result.snapshot.status, backoffMs: result.backoffMs },
    },
  };
}

async function handleList(
  _args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const coordinator = requireCoordinator(ctx);
  if (!coordinator) return toolError("[subsession-error] sub-sessions are not available in this run");

  const snapshots = coordinator.list(ctx.session.sessionId);
  const resultContent = JSON.stringify({ count: snapshots.length, subSessions: snapshots }, null, 2);
  return {
    isError: false,
    content: resultContent,
    event: { type: "subsession-status", data: { count: snapshots.length } },
  };
}

async function handleFinalize(
  args: Record<string, unknown>,
  ctx: ToolContext
): Promise<RichToolResult> {
  const coordinator = requireCoordinator(ctx);
  if (!coordinator) return toolError("[subsession-error] sub-sessions are not available in this run");

  const subSessionId = requireSubSessionId(args, FINALIZE_SUBSESSION_TOOL);
  if (!subSessionId.ok) return toolError(subSessionId.reason);

  const finalStatus =
    args.finalStatus === "done" || args.finalStatus === "error" ? args.finalStatus : undefined;
  const snapshot = coordinator.finalize(ctx.session.sessionId, subSessionId.value, finalStatus);
  if (!snapshot) {
    return toolError(`[subsession-error] unknown subSessionId "${subSessionId.value}" for this session`);
  }
  return {
    isError: false,
    content: snapshotJson(snapshot),
    event: { type: "subsession-finalize", data: { subSessionId: subSessionId.value, status: snapshot.status } },
  };
}

function requireCoordinator(ctx: ToolContext): SubSessionCoordinator | undefined {
  return ctx.coordinator;
}

function requireSubSessionId(
  args: Record<string, unknown>,
  toolName: string
): { ok: true; value: string } | { ok: false; reason: string } {
  const subSessionId = args.subSessionId;
  if (typeof subSessionId !== "string" || subSessionId.length === 0) {
    return { ok: false, reason: `[subsession-error] ${toolName}.subSessionId must be a non-empty string` };
  }
  return { ok: true, value: subSessionId };
}

function snapshotJson(snapshot: SubSessionSnapshot): string {
  return JSON.stringify(snapshot, null, 2);
}

function createDescriptor(): ToolDescriptor {
  return {
    name: CREATE_SUBSESSION_TOOL,
    description: [
      "Spawn an autonomous SUB-SESSION to pursue an independent sub-goal.",
      "The child runs the orchestrator loop on its own, driving toward the",
      "given intent until the evaluator is satisfied — it does NOT wait for a",
      "user prompt. Use this to delegate a self-contained chunk of work so you",
      "can continue in parallel.",
      "",
      'Returns IMMEDIATELY with a snapshot whose status is usually "running".',
      "Poll its progress with get_subsession_status, and end it (cancelling it",
      "if still running) with finalize_subsession. The child shares this",
      "session's workspace sandbox.",
      "",
      "GUARDED: a request whose intent matches an active child reuses that",
      "child instead of duplicating it, and there is a small cap on how many",
      "children may run at once — call list_subsessions first to see what is",
      "already in flight, and finalize_subsession to free a slot.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["intent"],
      properties: {
        intent: {
          type: "string",
          description: "The goal the sub-session must resolve, phrased as you would a user request.",
        },
        context: {
          type: "string",
          description:
            "Optional standing context seeded for the child before the intent (background, constraints).",
        },
      },
    },
  };
}

function statusDescriptor(): ToolDescriptor {
  return {
    name: SUBSESSION_STATUS_TOOL,
    description: [
      "Get a snapshot of a sub-session you spawned: its status",
      "(running/done/error/archived), and — once finished — its result or",
      "error. If you poll and the status has not changed since your last check,",
      "this call deliberately backs off (waits, with growing delay) before",
      "returning — so do other useful work between checks rather than polling",
      "in a tight loop.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["subSessionId"],
      properties: {
        subSessionId: {
          type: "string",
          description: "The id returned by create_subsession.",
        },
      },
    },
  };
}

function listDescriptor(): ToolDescriptor {
  return {
    name: LIST_SUBSESSIONS_TOOL,
    description: [
      "List the sub-sessions currently active for this session — each with its",
      "id, intent, and status. Use this to see how many you have running and",
      "whether the work you are about to delegate is already in flight, before",
      "calling create_subsession. Takes no arguments.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      properties: {},
    },
  };
}

function finalizeDescriptor(): ToolDescriptor {
  return {
    name: FINALIZE_SUBSESSION_TOOL,
    description: [
      "Finalize a sub-session: cancel it if still running, record a final",
      "status, and archive it (dereferencing it from this session). Idempotent.",
    ].join("\n"),
    inputSchema: {
      type: "object",
      required: ["subSessionId"],
      properties: {
        subSessionId: {
          type: "string",
          description: "The id returned by create_subsession.",
        },
        finalStatus: {
          type: "string",
          enum: ["done", "error"],
          description:
            "Optional outcome to record when finalizing a child that has not finished on its own.",
        },
      },
    },
  };
}

import type { OrchestratorEvent, OrchestratorListener } from "../runners/runner-events.js";
import type { ToolExecutionResult } from "../mcp/mcp-client.js";
import type { ToolDescriptor } from "../providers/provider.js";
import type { Session } from "../session/session.js";
import type { SubSessionCoordinator } from "../runners/subsession.js";
import type { Workspace } from "../registries/workspace-registry.js";
import type { DispatchTracker } from "./dispatch-tracker.js";

/**
 * Slim context for MCP server tool handlers — only the fields tools actually need.
 * No executor, tracker, or emit: tools are pure functions that return results,
 * and the server layer handles post-call side effects.
 */
export interface ToolContext {
  readonly session: Session;
  readonly workspace: Workspace;
  readonly sandboxRoot: string;
  readonly coordinator?: SubSessionCoordinator;
  readonly signal?: AbortSignal;
}

/**
 * Tool result with optional post-call event. The tool returns this instead of
 * calling emit directly. The server layer checks for the event and fires it
 * after the MCP response is sent.
 */
export interface RichToolResult extends ToolExecutionResult {
  readonly event?: OrchestratorEvent;
}

/**
 * A single synthetic MCP server. `descriptor` is what the LLM sees; `callTool` is the
 * intercepted invocation. The shape deliberately mirrors a real MCP tool so the
 * two can be dispatched and wrapped identically.
 */
export interface SyntheticMcp {
  readonly name: string;
  readonly descriptor: ToolDescriptor;
  callTool(args: Record<string, unknown>, context: ToolContext): Promise<RichToolResult>;
}

/**
 * Per-turn binding surface for MCP servers that need turn-scoped context
 * (abort signal, event emitter, dispatch tracker). Implemented by ExecutorLocalMcp;
 * the orchestrator casts to this interface after looking up the "executor" client
 * so there is no import cycle between orchestrator and executor-server.
 */
export interface TurnBindable {
  bindTurn(
    signal: AbortSignal | undefined,
    emit: OrchestratorListener,
    tracker: DispatchTracker
  ): void;
}

/** Shape a non-success synthetic result the same way MCP errors are shaped. */
export function toolError(content: string): RichToolResult {
  return { isError: true, content };
}

/** Shape a successful synthetic result. */
export function toolOk(content: string): RichToolResult {
  return { isError: false, content };
}

/**
 * Build the addendum to inject into the system prompt when the active
 * model does not support native function calling. The orchestrator
 * appends this to the existing system message at agent-loop startup.
 */
export function buildPromptedToolInstructions(tools: ToolDescriptor[]): string {
  if (tools.length === 0) return "";

  const toolDescriptions = tools
    .map((tool) => {
      const schema = JSON.stringify(tool.inputSchema, null, 2);
      return `• ${tool.name} — ${tool.description}\n  arguments schema:\n${indent(schema, "  ")}`;
    })
    .join("\n\n");

  return [
    "",
    "## Available tools",
    "",
    toolDescriptions,
    "",
    "## How to invoke a tool",
    "",
    TOOL_INSTRUCTION_HEADER,
    "",
    TOOL_INSTRUCTION_EXAMPLE,
    "",
    TOOL_INSTRUCTION_RULES,
  ].join("\n");
}

/**
 * Inspect an assistant message and pull out any prompted-JSON tool calls.
 * Returns the calls and a `cleanedContent` string with the JSON blocks
 * removed so it doesn't pollute the visible chat transcript.
 */
export function extractPromptedToolCalls(message: ChatMessage): {
  toolCalls: ToolCall[];
  cleanedContent: string;
} {
  const calls: ToolCall[] = [];
  let cleaned = message.content;

  const blockPattern = /```json\s*([\s\S]*?)```/g;
  let match: RegExpExecArray | null;
  let counter = 0;

  while ((match = blockPattern.exec(message.content)) !== null) {
    const jsonText = match[1].trim();
    let parsed: unknown;
    try {
      parsed = JSON.parse(jsonText);
    } catch {
      // Not a valid JSON block. Leave it in the visible content so the model
      // can see its own mistake on the next turn, and skip extraction.
      continue;
    }

    const toolCall = parseToolCallShape(parsed);
    if (toolCall) {
      calls.push({
        id: `prompted_${Date.now()}_${counter}`,
        name: toolCall.name,
        arguments: toolCall.arguments,
      });
      counter += 1;

      // Strip the recognised JSON block from the visible content.
      cleaned = cleaned.replace(match[0], "").trim();
    }
  }

  // Fallback: some models (including native-tool ones that misfire) emit the
  // call as bare, unfenced JSON in prose. If the fenced pass found nothing,
  // scan for balanced top-level { … } spans and recover any that clearly look
  // like a tool call (name + arguments object). We require `arguments` here to
  // avoid misreading a model legitimately answering with JSON.
  if (calls.length === 0) {
    for (const candidate of extractBalancedJsonObjects(cleaned)) {
      let parsed: unknown;
      try {
        parsed = JSON.parse(candidate);
      } catch {
        continue;
      }

      const toolCall = parseToolCallShape(parsed, { requireArguments: true });
      if (toolCall) {
        calls.push({
          id: `prompted_${Date.now()}_${counter}`,
          name: toolCall.name,
          arguments: toolCall.arguments,
        });
        counter += 1;
        cleaned = cleaned.replace(candidate, "").trim();
      }
    }
  }

  return { toolCalls: calls, cleanedContent: cleaned };
}

/**
 * Scan text for top-level, balanced `{ … }` substrings, returning each as a
 * candidate JSON string. Brace counting ignores braces inside string literals
 * and honours backslash escapes, so JSON containing `{`/`}` or quotes inside
 * values is captured whole. Nested objects are returned as part of their
 * outermost parent, not separately.
 */
function extractBalancedJsonObjects(text: string): string[] {
  const objects: string[] = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === "\\") {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
    } else if (ch === "{") {
      if (depth === 0) start = i;
      depth += 1;
    } else if (ch === "}") {
      if (depth > 0) {
        depth -= 1;
        if (depth === 0 && start >= 0) {
          objects.push(text.slice(start, i + 1));
          start = -1;
        }
      }
    }
  }

  return objects;
}

function parseToolCallShape(
  parsed: unknown,
  options: { requireArguments?: boolean } = {}

): { name: string; arguments: Record<string, unknown> } | null {
  if (!parsed || typeof parsed !== "object") return null;
  const root = parsed as Record<string, unknown>;
  const candidate = (root.tool_call ?? root) as Record<string, unknown>;

  if (typeof candidate.name !== "string" || candidate.name.length === 0) return null;
  const args = candidate.arguments;
  const argsIsObject = typeof args === "object" && args !== null && !Array.isArray(args);

  if (args !== undefined && !argsIsObject) {
    return null;
  }
  // For bare-JSON recovery we insist on a real arguments object so we don't
  // misread arbitrary JSON prose as a call.
  if (options.requireArguments && !argsIsObject) {
    return null;
  }

  return {
    name: candidate.name,
    arguments: (args ?? {}) as Record<string, unknown>,
  };
}

function indent(text: string, prefix: string): string {
  return text
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}

/** Parsed CLI invocation. `run` present ⇒ headless single run; absent ⇒ REPL. */
export interface CliArgs {
  /** The single-run input. When set, the process runs headless and exits. */
  run?: string;
  /** Optional session to resume; a fresh one is opened when omitted. */
  sessionId?: string;
}

/**
 * Minimal argv parser for the two recognised flags:
 *   --run <input>      run headless against this input, then exit
 *   --session <id>     resume this session (otherwise a fresh one is opened)
 * `--flag=value` and `--flag value` forms are both accepted. Anything else is
 * ignored so the interactive path stays the no-flag default.
 */
export function parseArgs(argv: string[]): CliArgs {
  const args: CliArgs = {};
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    const eq = token.indexOf("=");
    const flag = eq >= 0 ? token.slice(0, eq) : token;
    const inlineValue = eq >= 0 ? token.slice(eq + 1) : undefined;
    const takeValue = (): string | undefined => {
      if (inlineValue !== undefined) return inlineValue;
      const next = argv[i + 1];
      if (next === undefined || next.startsWith("--")) return undefined;
      i += 1;
      return next;
    };

    if (flag === "--run") {
      args.run = takeValue() ?? "";
    } else if (flag === "--session") {
      const value = takeValue();
      if (value !== undefined) args.sessionId = value;
    }
  }
  return args;
}

#!/usr/bin/env node
/**
 * CLI entry point — the composition root.
 *
 * Boots the shared infrastructure in order:
 *   1. Environment + workspace settings.
 *   2. The MCP tool client (spawns the tools server child process).
 *   3. The model registry (instantiates every provider declared in models.json).
 *
 * Session setup is deferred to each run mode via AgentRuntime's middleware
 * pipeline. Both modes share the same infrastructure but build their own
 * runtime after resolving the session:
 *
 *   Interactive: session picker → AgentRuntime.build() → REPL
 *   Headless:    args.sessionId → AgentRuntime.build() → single dispatch → exit
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import url from "node:url";

import chalk from "chalk";
import dotenv from "dotenv";

import { AgentRuntime } from "../agent/runtime/agent-runtime.js";

import type { AgentRuntimeDeps } from "../agent/runtime/types.js";
import { buildRuntime as buildRuntimeRef } from "../agent/runtime/build-runtime.js";
import { parseArgs } from "./args.js";
import { runRepl } from "./repl.js";
import { renderEvent, renderSubSessionNotification } from "./render.js";
import { pickSession } from "./session-picker.js";

/** Exit codes for the headless single-run path. */
const EXIT_SATISFIED = 0;
const EXIT_ERROR = 1;
const EXIT_CAPPED = 2;

/** Shared infrastructure produced by bootstrap(). Session setup is NOT here —
 *  each run mode builds its own AgentRuntime after choosing a session. */
interface Bootstrap {
  projectRoot: string;
  sandboxRoot: string;
  sessionsDir: string;
  configPath: string;
  mcpConfigPath: string;
  shutdown: () => Promise<void>;
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  const boot = await bootstrap();

  if (args.run !== undefined) {
    const code = await runHeadless(boot, args.run, args.sessionId);
    await boot.shutdown();
    process.exit(code);
  }

  try {
    await runInteractive(boot);
  } finally {
    await boot.shutdown();
  }
}

/**
 * Bring up the shared infrastructure (tools + model registry) and return it
 * with a teardown callback. Session creation happens per run-mode via
 * AgentRuntime so the session picker and headless session-id argument both
 * land in the same place — the pipeline.
 */
async function bootstrap(): Promise<Bootstrap> {
  dotenv.config();

  const projectRoot = findProjectRoot();

  const sandboxRoot = path.resolve(
    process.env.AGENT_WORKSPACE ?? path.join(projectRoot, "src", "agent", "workspace")
  );
  fs.mkdirSync(sandboxRoot, { recursive: true });

  const sessionsDir = path.resolve(
    process.env.AGENT_SESSIONS_DIR ?? path.join(projectRoot, "src", "agent", "sessions")
  );

  const mcpConfigPath = path.join(projectRoot, "mcp.json");
  const configPath = path.join(projectRoot, "models.json");

  const shutdown = async (): Promise<void> => {
    //bye
  };

  process.on("SIGINT", () => {
    void shutdown().finally(() => process.exit(EXIT_ERROR));
  });
  process.on("SIGTERM", () => {
    void shutdown().finally(() => process.exit(EXIT_ERROR));
  });

  return { projectRoot, sandboxRoot, sessionsDir, mcpConfigPath, configPath, shutdown };
}

/**
 * Build an AgentRuntime with the standard pipeline. Every subsystem the runtime
 * owns is produced by a step here — build() constructs nothing itself:
 **/
function buildRuntime(
  boot: Bootstrap,
  sessionId?: string
): AgentRuntime {
  const { projectRoot, sandboxRoot, sessionsDir, mcpConfigPath, configPath } = boot;
  const token = process.env.AGENT_API_TOKEN;
  const deps: AgentRuntimeDeps = {
    mcpConfigPath,
    configPath,
    sessionsDir,
    workspaceRoot: projectRoot,
    sandboxRoot,
    credentials: token ? { token } : {},
    orchestratorRole: "orchestrator"
  };
  return buildRuntimeRef(deps, sessionId);
}

/**
 * Interactive mode. Lists saved sessions so the user can resume or start
 * fresh, then builds the runtime through the pipeline and hands off to
 * the REPL.
 */
async function runInteractive(boot: Bootstrap): Promise<void> {
  const { projectRoot, sandboxRoot, sessionsDir, configPath } = boot;

  const saved = await AgentRuntime.listSavedSessions(sessionsDir);
  const choice = await pickSession(saved);

  const runtime = await buildRuntime(boot, choice.kind === "resume" ? choice.sessionId : undefined).build();

  // Drain any sub-sessions that outlive a turn before the REPL exits.
  const unsubscribe = runtime.onSubSessionEvent(renderSubSessionNotification);
  try {
    await runRepl({
      workspaceRoot: projectRoot,
      sandboxRoot,
      configPath,
      runtime,
      resumed: choice.kind === "resume",
    });
  } finally {
    unsubscribe();
    await runtime.awaitAllSubSessions();
  }
}

/**
 * Headless single run: build a runtime for the given (or fresh) session,
 * dispatch ONE turn, drain sub-tasks, persist, print the answer, and return
 * the process exit code.
 *
 * Progress goes to stderr so stdout carries only the final answer.
 */
async function runHeadless(
  boot: Bootstrap,
  input: string,
  sessionId?: string
): Promise<number> {
  try {
    const runtime = await buildRuntime(boot, sessionId).build();

    const unsubscribe = runtime.onSubSessionEvent(renderSubSessionNotification);

    process.stderr.write(chalk.gray(`[session ${runtime.getSession().sessionId}]\n`));

    try {
      const result = await runtime.dispatchAsync(input, { onEvent: renderEvent });
      await runtime.awaitSubSessions();
      process.stdout.write(result.finalMessage.content + "\n");
      return result.outcome === "satisfied" ? EXIT_SATISFIED : EXIT_CAPPED;
    } finally {
      unsubscribe();
    }
  } catch (err) {
    process.stderr.write(chalk.red(`\n[error] runHeadless: ${(err as Error).message}\n`));
    return EXIT_ERROR;
  }
}

function findProjectRoot(): string {
  const here = url.fileURLToPath(new URL(".", import.meta.url));
  let cursor = path.resolve(here);
  while (true) {
    if (fs.existsSync(path.join(cursor, "mcp.json"))) return cursor;
    const parent = path.dirname(cursor);
    if (parent === cursor) {
      throw new Error(
        `Could not locate mcp.json walking up from ${here}. Make sure the agent is launched from inside the workspace.`
      );
    }
    cursor = parent;
  }
}

main().catch((err) => {
  process.stderr.write(chalk.red(`\n[fatal] ${(err as Error).stack ?? err}\n`));
  process.exit(EXIT_ERROR);
});

import chalk from "chalk";

import type { RunnerEvent } from "../agent/runners/runner-events.js";
import type { SubSessionNotification } from "../agent/runners/subsession.js";
import type { TurnRunnerEvent } from "../agent/runners/turn-runner.js";

/**
 * REPL renderer.
 *
 * The CLI layer keeps all colour/formatting decisions here so the
 * orchestrator stays UI-agnostic. The orchestrator emits structured
 * events; this module turns them into human-readable lines.
 *
 * Two role labels are used consistently:
 *   ORCHESTRATOR — cyan, coordinator messages and read-only tool calls.
 *   EXECUTOR     — magenta, ack/execute/validate/report inside one dispatch.
 */

export function renderEvent(event: RunnerEvent): void {
  switch (event.type) {
    case "orchestrator-start": {
      const orch = String(event.data.orchestratorModel ?? "");
      const reads = Number(event.data.readToolCount ?? 0);
      process.stdout.write(
        chalk.cyanBright(`\n[ORCHESTRATOR] ${orch} — ${reads} tools\n`)
      );
      break;
    }

    case "orchestrator-iteration": {
      const iteration = Number(event.data.iteration ?? 0);
      const max = Number(event.data.max ?? 0);
      process.stdout.write(chalk.gray(`  ── orchestrator turn ${iteration}/${max}\n`));
      break;
    }

    case "orchestrator-message": {
      const content = String(event.data.content ?? "").trim();
      if (content.length > 0) {
        process.stdout.write(chalk.cyan("[ORCHESTRATOR] ") + content + "\n");
      }
      break;
    }

    case "tool-call": {
      const name = String(event.data.name ?? "");
      const args = JSON.stringify(event.data.arguments ?? {}, null, 0);
      process.stdout.write(chalk.yellow(`  → tool: ${name} ${chalk.gray(args)}\n`));
      break;
    }

    case "tool-result": {
      const name = String(event.data.name ?? "");
      const isError = Boolean(event.data.isError);
      const preview = String(event.data.contentPreview ?? "");
      const colour = isError ? chalk.red : chalk.green;
      const label = isError ? "tool-error" : "tool-ok";
      process.stdout.write(colour(`  ← ${label}: ${name}\n`));
      if (preview.length > 0) {
        process.stdout.write(indent(preview, "    " + chalk.gray("│ ")) + "\n");
      }
      break;
    }

    case "dispatch-start": {
      const tool = String(event.data.tool ?? "");
      const intent = String(event.data.intent ?? "");
      process.stdout.write(
        chalk.magentaBright(`\n[DISPATCH] → ${tool}\n`) + chalk.gray(`           intent: ${intent}\n`)
      );
      break;
    }

    case "dispatch-feedback": {
      const ok = Boolean(event.data.ok);
      const ack = String(event.data.ack ?? "");
      const evidence = String(event.data.evidence ?? "");
      const det = String(event.data.deterministicVerdict ?? "");
      const iterations = Number(event.data.iterations ?? 0);
      const stamp = ok ? chalk.greenBright("OK") : chalk.redBright("FAIL");
      process.stdout.write(
        chalk.magentaBright(`[DISPATCH] ← ${stamp}`) +
          chalk.gray(
            ` (ack=${ack}, deterministic=${det}, executor turns=${iterations})\n`
          ) +
          chalk.gray(`           evidence: ${evidence}\n`)
      );
      break;
    }

    case "executor-event": {
      renderExecutorEvent(event.data);
      break;
    }

    case "final-message": {
      const content = String(event.data.content ?? "").trim();
      const iterations = Number(event.data.iterations ?? 0);
      process.stdout.write(chalk.greenBright(`\n[answer] (after ${iterations} orchestrator turn(s))\n`));
      process.stdout.write(content + "\n");
      break;
    }

    case "summarization": {
      const summarized = Number(event.data.summarizedCount ?? 0);
      const kept = Number(event.data.keptCount ?? 0);
      const chars = Number(event.data.summaryChars ?? 0);
      process.stdout.write(
        chalk.gray(
          `[summarizer] folded ${summarized} message(s) into ~${chars} chars; kept last ${kept}\n`
        )
      );
      break;
    }

    case "evaluation-start": {
      process.stdout.write(chalk.gray("  [EVALUATOR] checking whether the request is fulfilled…\n"));
      break;
    }

    case "evaluation-verdict": {
      const state = String(event.data.state ?? "");
      const reason = String(event.data.reason ?? "");
      const stamp =
        state === "satisfied"
          ? chalk.greenBright("SATISFIED")
          : state === "continue"
            ? chalk.cyanBright("CONTINUE")
            : state === "awaiting-input"
              ? chalk.blueBright("AWAITING-INPUT")
              : chalk.yellowBright(state.toUpperCase() || "UNSATISFIED");
      // Verdicts are turn-transient (events only, never persisted to the
      // conversation): gray label per the saved-keeps-color convention, but
      // the verdict word stays colored — it's the line being scanned for.
      process.stdout.write(chalk.gray("  [EVALUATOR] ") + stamp + chalk.gray(` — ${reason}\n`));
      break;
    }

    case "warning": {
      const message = String(event.data.message ?? "");
      process.stdout.write(chalk.yellowBright(`[warning] ${message}\n`));
      break;
    }
  }
}

/**
 * Render turn-loop scheduling events. Deliberately quiet for plain user turns
 * (the prompt/await flow already narrates those); only out-of-band activity —
 * auto-wake turns from settling sub-sessions, queued/coalesced work — gets a
 * line, so the user can see WHY the agent started talking unprompted.
 */
export function renderTurnEvent(event: TurnRunnerEvent): void {
  switch (event.type) {
    case "turn-queued":
      if (event.source !== "user") {
        process.stdout.write(
          chalk.gray(`\n(queued ${event.source} turn — ${event.queueDepth} waiting)\n`)
        );
      }
      break;
    case "turn-start":
      if (event.source !== "user") {
        process.stdout.write(chalk.gray(`\n(auto-wake: processing ${event.source} report)\n`));
      }
      break;
    case "round-start":
      // Rounds beyond the first mean mid-turn feedback was folded in.
      if (event.round > 1) {
        process.stdout.write(chalk.gray(`\n(round ${event.round}: ${event.source} feedback folded into this turn)\n`));
      }
      break;
    case "round-done":
      // The REPL no longer awaits a turn's settle (the prompt stays live for
      // mid-turn injection), so failures must surface here or nowhere.
      if (event.status === "error") {
        const errorDetail = event.error ?? "unknown error";
        process.stdout.write(chalk.red(`\n[error] turn round failed:\n${errorDetail}\n`));
      }
      break;
    case "turn-done":
      if (event.status === "cancelled") {
        process.stdout.write(chalk.yellowBright("\n(turn cancelled)\n"));
      }
      break;
  }
}

/**
 * Render a sub-session completion that arrived out-of-band (the child settled
 * after the parent's turn ended). Prefixed with a newline so it doesn't smear
 * the live `you>` prompt, and tagged so it's clearly an async report rather
 * than part of the current turn's output.
 */
export function renderSubSessionNotification(notification: SubSessionNotification): void {
  const shortId = notification.subSessionId.split("-")[0] ?? notification.subSessionId.slice(0, 8);
  const intent = notification.intent.replace(/\s+/g, " ").trim();

  if (notification.status === "done") {
    const result = (notification.result ?? "").replace(/\s+/g, " ").trim();
    const preview = result.length > 200 ? `${result.slice(0, 199)}…` : result;
    process.stdout.write(
      "\n" +
        chalk.greenBright(`✓ [sub-session ${shortId} done] `) +
        chalk.gray(intent) +
        (preview.length > 0 ? `\n  ${preview}` : "") +
        "\n"
    );
    return;
  }

  const reason = (notification.error ?? "unknown error").replace(/\s+/g, " ").trim();
  process.stdout.write(
    "\n" +
      chalk.redBright(`✗ [sub-session ${shortId} error] `) +
      chalk.gray(intent) +
      `\n  ${reason}\n`
  );
}

// Executor sub-run lines render gray: they persist in the CHILD session's
// transcript, not this conversation, so by the saved-keeps-color convention
// they are transient here. Errors stay red — failure must remain visible.
function renderExecutorEvent(data: Record<string, unknown>): void {
  const kind = String(data.kind ?? "");
  switch (kind) {
    // Orchestrator-style events forwarded from the executor sub-run.
    case "orchestrator-start": {
      const model = String(data.orchestratorModel ?? "");
      process.stdout.write(chalk.gray(`  [EXECUTOR] running (${model})\n`));
      return;
    }
    case "orchestrator-message": {
      const content = String(data.content ?? "").trim();
      if (content.length > 0) {
        process.stdout.write(chalk.gray(`  [EXECUTOR] ${content}\n`));
      }
      return;
    }
    case "tool-call": {
      const name = String(data.name ?? "");
      const args = JSON.stringify(data.arguments ?? {}, null, 0);
      process.stdout.write(chalk.gray(`  [EXECUTOR] → tool: ${name} ${args}\n`));
      return;
    }
    case "tool-result": {
      const name = String(data.name ?? "");
      const isError = Boolean(data.isError);
      const colour = isError ? chalk.red : chalk.gray;
      process.stdout.write(colour(`  [EXECUTOR] ← ${isError ? "tool-error" : "tool-ok"}: ${name}\n`));
      return;
    }
    case "warning": {
      const message = String(data.message ?? "");
      process.stdout.write(chalk.yellowBright(`  [EXECUTOR] warning: ${message}\n`));
      return;
    }
  }
}

/** Identity of the session this REPL drives, shown in the startup banner. */
export interface BannerSession {
  sessionId: string;
  /** Transcript link — the session's rolling conversation file. */
  conversationId: string;
  /** Workspace the session is bound to. */
  workspaceId: string;
  /** Content-addressed pointer to the captured context, when one was stamped. */
  contextHashes: Record<string, string>;
  /** True when resumed from disk, false for a freshly bootstrapped session. */
  resumed: boolean;
  /** Completed user turns (0 for a new session). */
  turns: number;
  /** Short description — the first user message, or null when none yet. */
  preview: string | null;
}

export function renderBanner(
  workspaceRoot: string,
  sandboxRoot: string,
  session: BannerSession,
  contextPath?: string | null
): void {
  const lines = [
    "",
    chalk.bold("Agent.Local") + chalk.gray(" — local coding agent (Ollama + MCP)"),
    chalk.gray(`session:   ${sessionLine(session)}`),
    chalk.gray(`project:   ${workspaceRoot}`),
    chalk.gray(`fs sandbox: ${sandboxRoot} (all file I/O confined here)`),
    chalk.gray("architecture: orchestrator (read-only) → executor__dispatch → executor (mutations)"),
  ];
  if (contextPath) {
    lines.push(chalk.gray(`project context: ${contextPath}`));
  }
  lines.push(chalk.gray("type /help for commands, /exit to quit"), "");
  process.stdout.write(lines.join("\n"));
}

/**
 * "id=b1557363 · conv=9c2e11d4 · ctx=3f8a1c2b · ws=ad2f457f · new" identity
 * line. On a resumed session the origin is followed by the turn count and a
 * description of the opening message. ctx falls back to "none" when no
 * snapshot was stamped.
 */
function sessionLine(session: BannerSession): string {
  const id = `id=${short(session.sessionId)}`;
  const conv = `conv=${short(session.conversationId)}`;
  const ctx = `ctx=${session.contextHashes["orchestrator"] ? short(session.contextHashes["orchestrator"]) : "none"}`;
  const ws = `ws=${short(session.workspaceId)}`;

  let origin: string = session.resumed ? "resumed" : "new";
  if (session.resumed) {
    const turns = `${session.turns} turn${session.turns === 1 ? "" : "s"}`;
    const desc = session.preview ? ` · ${session.preview}` : "";
    origin += ` — ${turns}${desc}`;
  }

  return `${id} · ${conv} · ${ctx} · ${ws} · ${origin}`;
}

/** First 8 chars — enough to eyeball/grep an id without wrapping the banner. */
function short(value: string): string {
  return value.slice(0, 8);
}

export function renderSession(session: BannerSession): void {
  process.stdout.write(chalk.gray(`session:   ${sessionLine(session)}\n`));
}

function indent(text: string, prefix: string): string {
  return text
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}

import readline from "node:readline/promises";
import chalk from "chalk";

import type { McpClientRegistry } from "../agent/registries/mcp-registry.js";
import type { ModelRegistry } from "../agent/registries/model-registry.js";
import type { TurnRunner } from "../agent/runners/turn-runner.js";
import type { AgentRuntime } from "../agent/runtime/agent-runtime.js";
import { renderBanner, renderEvent, renderHelp, renderSession, renderSubSessionNotification, renderTurnEvent } from "./render.js";

/**
 * Interactive REPL.
 *
 * Wraps a single session's AgentRuntime with a readline prompt and a small set
 * of slash commands. All model and tool logic lives in the runtime — the REPL
 * only routes input in and events out.
 */

export interface ReplOptions {
  workspaceRoot: string;
  sandboxRoot: string;
  configPath: string;
  runtime: AgentRuntime;
  resumed: boolean;
}

export async function runRepl(options: ReplOptions): Promise<void> {
  const { workspaceRoot, sandboxRoot, runtime, resumed } = options;

  const session = runtime.getSession();
  const firstUser = runtime.history().find((m) => m.role === "user");
  const preview = firstUser ? previewOf(firstUser.content) : null;

  renderBanner(
    workspaceRoot,
    sandboxRoot,
    {
      sessionId: session.sessionId,
      conversationId: session.conversationId,
      workspaceId: session.workspaceId,
      contextHashes: session.contextHashes || {} as Record<string, string>,
      resumed,
      turns: session.counters.turns,
      preview,
    },
    null
  );

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  // Activity indicator + prompt repaint are CLI concerns: they hang off the
  // runner's lifecycle events here, not inside the runtime. Every writer
  // interrupts the spinner first so log lines never land on a half-drawn
  // star line.
  const spinner = new TurnSpinner(() => rl.line.length > 0);

  // Sub-session completions fire out-of-band (after the parent turn that
  // spawned them has ended). Surface them as they arrive.
  const unsubscribe = runtime.onSubSessionEvent((notification) => {
    spinner.interrupt();
    renderSubSessionNotification(notification);
  });

  // All turns flow through the runner's single pump: the REPL SUBMITS user
  // input and awaits the turn's settle, and settling sub-sessions auto-wake
  // the session through the same queue — no producer ever races the
  // dispatchAsync running-guard.
  let runnerRef: TurnRunner | null = null;
  const turnRunner = runtime.startTurnLoop({
    onEvent: (event) => {
      spinner.interrupt();
      renderEvent(event);
    },
    onTurnEvent: (event) => {
      if (event.type === "turn-start") {
        spinner.start();
        renderTurnEvent(event);
        return;
      }
      if (event.type === "turn-done") {
        spinner.stop();
        renderTurnEvent(event);
        // The pending readline question is intact — only its visual line
        // scrolled away under the turn's output. Repaint it so the user sees
        // they have the floor again; skip when another turn is about to start.
        if ((runnerRef?.pendingCount ?? 0) === 0) {
          redrawPrompt(rl);
        }
        return;
      }
      spinner.interrupt();
      renderTurnEvent(event);
    },
  });
  runnerRef = turnRunner;

  while (true) {
    let input: string;
    try {
      input = (await rl.question(chalk.bold.cyan("you> "))).trim();
    } catch {
      break;
    }

    if (input === "") continue;

    // "stop" is an interrupt, not a prompt: with the input line always live,
    // it must never enter the queue (where it would be LLM-interpreted after
    // the very work it was meant to halt).
    if (input.toLowerCase() === "stop") {
      writeStopResult(runtime.stopAllWork());
      continue;
    }

    if (input.startsWith("/")) {
      const command = input.slice(1).trim();
      const exitRequested = await handleSlashCommand(command, {
        runtime,
        turnRunner,
        registry: runtime.getModelsRegistry(),
        mcpRegistry: runtime.getMcpClientRegistry(),
        resumed,
      });
      if (exitRequested) break;
      continue;
    }

    // Fire-and-forget so the prompt stays live: typing while a turn runs is
    // how the user steers it — the input folds into the running turn as a
    // round rather than waiting behind it. Completion and failures are
    // reported by the turn-event renderer, so nothing here needs to block.
    const receipt = turnRunner.submit({ content: input, source: "user", preferMidTurn: true });
    if (receipt.placement === "mid-turn-round") {
      process.stdout.write(chalk.gray("(added to the running turn)\n"));
    }
  }

  await runtime.stopTurnLoop();
  unsubscribe();
  rl.close();

  const finalSession = runtime.getSession();
  const finalFirstUser = runtime.history().find((m) => m.role === "user");
  renderSession({
    sessionId: finalSession.sessionId,
    conversationId: finalSession.conversationId,
    workspaceId: finalSession.workspaceId,
    contextHashes: finalSession.contextHashes ?? {},
    resumed,
    turns: finalSession.counters.turns,
    preview: finalFirstUser ? previewOf(finalFirstUser.content) : null,
  });
}

interface SlashContext {
  runtime: AgentRuntime;
  turnRunner: TurnRunner;
  registry: ModelRegistry;
  mcpRegistry: McpClientRegistry;
  resumed: boolean;
}

async function handleSlashCommand(command: string, ctx: SlashContext): Promise<boolean> {
  const [head, ...rest] = command.split(/\s+/);
  const args = rest.join(" ");

  switch (head) {
    case "exit":
    case "quit":
      return true;

    case "stop":
      writeStopResult(ctx.runtime.stopAllWork());
      return false;

    case "help":
      renderHelp();
      return false;

    case "session": {
      const s = ctx.runtime.getSession();
      const firstUser = ctx.runtime.history().find((m) => m.role === "user");
      renderSession({
        sessionId: s.sessionId,
        conversationId: s.conversationId,
        workspaceId: s.workspaceId,
        contextHashes: s.contextHashes ?? {},
        resumed: ctx.resumed,
        turns: s.counters.turns,
        preview: firstUser ? previewOf(firstUser.content) : null,
      });
      return false;
    }

    case "reset": {
      // The runtime stops and drains in-flight work itself; this pre-pass
      // exists only to tell the user WHAT got cancelled on their behalf.
      const stoppedForReset = ctx.runtime.stopAllWork();
      if (stoppedForReset.cancelledTurns + stoppedForReset.cancelledSubSessions > 0) {
        writeStopResult(stoppedForReset);
      }
      await ctx.runtime.reset();
      process.stdout.write(chalk.gray("(conversation cleared)\n"));
      return false;
    }

    case "compact": {
      const stoppedForCompact = ctx.runtime.stopAllWork();
      if (stoppedForCompact.cancelledTurns + stoppedForCompact.cancelledSubSessions > 0) {
        writeStopResult(stoppedForCompact);
      }
      process.stdout.write(chalk.gray("(summarizing…)\n"));
      try {
        const result = await ctx.runtime.compact();
        if (result.skipped) {
          process.stdout.write(chalk.gray("(nothing to compact)\n"));
        } else {
          process.stdout.write(`\n${chalk.bold.gray("[SUMMARY]")}\n${result.summary}\n`);
          process.stdout.write(
            chalk.gray(`\n(compacted ${result.summarizedCount} messages into a summary checkpoint)\n`)
          );
        }
      } catch (err) {
        process.stdout.write(chalk.red(`error: ${(err as Error).message}\n`));
      }
      return false;
    }

    case "think":
      process.stdout.write(
        chalk.gray(
          "(/think is gone — the orchestrator coordinates every turn and dispatches the executor as needed)\n"
        )
      );
      return false;

    case "models":
      await handleModelsCommand(ctx);
      return false;

    case "model":
      handleModelAssignmentCommand(args, ctx);
      return false;

    case "tools":
      handleToolsCommand(ctx);
      return false;

    case "history":
      handleHistoryCommand(ctx);
      return false;

    default:
      process.stdout.write(chalk.yellow(`unknown command: /${head} (try /help)\n`));
      return false;
  }
}

async function handleModelsCommand(ctx: SlashContext): Promise<void> {
  const config = ctx.runtime.getConfigurationRegistry();
  const modelsFile = await config.getModelsConfiguration();

  process.stdout.write(chalk.bold("\nConfigured models:\n"));
  for (const [modelId, definition] of Object.entries(modelsFile.models)) {
    const tools = definition.supportsTools ? "tools=native" : "tools=prompted";
    const reasoning = definition.reasoning ? ", reasoning" : "";
    process.stdout.write(
      `  ${chalk.cyan(modelId)} → ${definition.provider}:${definition.model} (${tools}${reasoning})\n`
    );
  }

  process.stdout.write(chalk.bold("\nRole assignments:\n"));
  for (const [role, modelId] of Object.entries(modelsFile.roles)) {
    const modelDef = modelsFile.models[modelId];
    process.stdout.write(`  ${chalk.magenta(role)} → ${modelId} (${modelDef.provider}:${modelDef.model})\n`);
  }
  process.stdout.write("\n");
}

function handleModelAssignmentCommand(args: string, ctx: SlashContext): void {
  const match = /^([a-zA-Z0-9_-]+)\s*=\s*([a-zA-Z0-9_:.-]+)$/.exec(args.trim());
  if (!match) {
    process.stdout.write(chalk.yellow("usage: /model <role>=<model-id>\n"));
    return;
  }

  const [, role, modelId] = match;
  try {
    ctx.runtime.getModelsRegistry().assignRole(role, modelId);
    process.stdout.write(chalk.gray(`(role "${role}" now uses "${modelId}")\n`));
  } catch (err) {
    process.stdout.write(chalk.red(`error: ${(err as Error).message}\n`));
  }
}

function handleToolsCommand(ctx: SlashContext): void {
  const tools = ctx.mcpRegistry.listTools();
  if (tools.length === 0) {
    process.stdout.write(chalk.yellow("(no tools connected)\n"));
    return;
  }
  process.stdout.write(chalk.bold(`\nConnected tools (${tools.length}):\n`));
  for (const tool of tools) {
    process.stdout.write(`  ${chalk.green(tool.name)} — ${tool.description}\n`);
  }
  process.stdout.write("\n");
}

function handleHistoryCommand(ctx: SlashContext): void {
  const history = ctx.runtime.history();
  if (history.length === 0) {
    process.stdout.write(chalk.gray("(empty)\n"));
    return;
  }
  process.stdout.write(chalk.bold("\nConversation so far:\n"));
  for (const message of history) {
    const label = message.role.padEnd(9);
    const colour = roleColour(message.role);
    process.stdout.write(`  ${colour(label)} ${message.content}\n`);
  }
  process.stdout.write("\n");
}

/**
 * In-place activity indicator: cycles "*" → "****" on the current line while
 * a turn is in flight, so silent stretches (model thinking, long tool calls)
 * read as "working" rather than hung. Ticks are suppressed while the user is
 * mid-keystroke — the spinner must never clobber a line someone is typing on.
 */
class TurnSpinner {
  private timer: NodeJS.Timeout | null = null;
  private step = 0;

  constructor(private readonly userIsTyping: () => boolean) {}

  start(): void {
    if (this.timer) return;
    this.step = 0;
    this.timer = setInterval(() => {
      if (this.userIsTyping()) return;
      this.step = (this.step % 4) + 1;
      process.stdout.write("\r" + chalk.gray("*".repeat(this.step).padEnd(5)));
    }, 300);
    this.timer.unref(); // never the reason the process stays alive
  }

  /** Wipe the spinner off the current line so real output starts clean. */
  interrupt(): void {
    if (!this.timer) return;
    process.stdout.write("\r     \r");
  }

  stop(): void {
    if (!this.timer) return;
    clearInterval(this.timer);
    this.timer = null;
    process.stdout.write("\r     \r");
  }
}

/**
 * Repaint the prompt after out-of-band output. The readline question asked at
 * the top of the REPL loop is still pending — only its visual line scrolled
 * away — so this redraws the prompt plus whatever the user had already typed
 * (readline keeps the in-progress buffer on `rl.line`).
 */
function redrawPrompt(rl: readline.Interface): void {
  process.stdout.write(chalk.bold.cyan("you> ") + rl.line);
}

function writeStopResult(result: { cancelledTurns: number; cancelledSubSessions: number }): void {
  const total = result.cancelledTurns + result.cancelledSubSessions;
  process.stdout.write(
    total > 0
      ? chalk.gray(
          `(stopping everything: ${result.cancelledTurns} turn(s), ${result.cancelledSubSessions} sub-session(s))\n`
        )
      : chalk.gray("(nothing is running)\n")
  );
}

function previewOf(content: string): string | null {
  const flat = content.replace(/\s+/g, " ").trim();
  if (flat.length === 0) return null;
  return flat.length > 60 ? `${flat.slice(0, 59)}…` : flat;
}

function roleColour(role: string): (s: string) => string {
  switch (role) {
    case "user":      return chalk.bold.white;
    case "assistant": return chalk.magenta;
    case "tool":      return chalk.green;
    case "system":    return chalk.gray;
    default:          return chalk.white;
  }
}

import readline from "node:readline";
import process from "node:process";
import chalk from "chalk";

import type { SessionSummary } from "../agent/session/session-store.js";

/**
 * Startup session picker (UI layer).
 *
 * A hand-rolled arrow-key selector so resuming a session needs no prompt
 * library — the store already commits to a zero-dependency ethos and this
 * keeps the CLI in step. It drives raw-mode keypress events directly and,
 * crucially, fully restores the terminal before returning so the REPL's own
 * readline interface (created afterward) starts from a clean slate.
 */

export type PickResult =
  | { kind: "new" }
  | { kind: "resume"; sessionId: string };

/** Sentinel index for the always-present "create new session" row. */
const CREATE_NEW = 0;

/**
 * Present the saved sessions and let the user choose one to resume or start a
 * new one. ↑/↓ (or k/j) move, Enter selects, Esc/Ctrl+C aborts to a new
 * session. Falls back to "new" without prompting when stdin is not a TTY
 * (piped input, CI), where an interactive menu can't work.
 */
export async function pickSession(summaries: SessionSummary[]): Promise<PickResult> {
  if (!process.stdin.isTTY) return { kind: "new" };

  // Row 0 is "create new"; the rest map 1:1 onto summaries.
  const rowCount = summaries.length + 1;
  let selected = CREATE_NEW;
  let rendered = 0; // lines emitted last paint, so we can rewind and redraw.

  const paint = (): void => {
    if (rendered > 0) {
      // Rewind to the top of the previous block and clear downward.
      process.stdout.write(`\x1b[${rendered}A\x1b[0J`);
    }

    const lines: string[] = [];
    lines.push(chalk.bold("Select a session  ") + chalk.gray("(↑/↓ to move, Enter to choose, Esc for new)"));

    lines.push(rowFor(selected === CREATE_NEW, chalk.green("＋ Create new session"), ""));
    summaries.forEach((summary, index) => {
      const isSelected = selected === index + 1;
      lines.push(rowFor(isSelected, chalk.cyan(shortId(summary.sessionId)), describe(summary)));
    });

    process.stdout.write(lines.join("\n") + "\n");
    rendered = lines.length;
  };

  paint();

  const wasRaw = process.stdin.isRaw ?? false;
  readline.emitKeypressEvents(process.stdin);
  process.stdin.setRawMode(true);
  process.stdin.resume();

  try {
    const choice = await new Promise<PickResult>((resolve) => {
      const onKeypress = (
        _str: string | undefined,
        key: { name?: string; ctrl?: boolean } | undefined
      ): void => {
        if (!key) return;

        // Abort paths resolve to a brand-new session.
        if (key.name === "escape" || (key.ctrl && key.name === "c")) {
          cleanup();
          resolve({ kind: "new" });
          return;
        }

        if (key.name === "up" || key.name === "k") {
          selected = (selected - 1 + rowCount) % rowCount;
          paint();
          return;
        }
        if (key.name === "down" || key.name === "j") {
          selected = (selected + 1) % rowCount;
          paint();
          return;
        }
        if (key.name === "return" || key.name === "enter") {
          cleanup();
          resolve(
            selected === CREATE_NEW
              ? { kind: "new" }
              : { kind: "resume", sessionId: summaries[selected - 1].sessionId }
          );
        }
      };

      const cleanup = (): void => {
        process.stdin.off("keypress", onKeypress);
      };

      process.stdin.on("keypress", onKeypress);
    });

    return choice;
  } finally {
    // Restore the terminal so the REPL's readline starts clean. Leave stdin
    // resumed — readline takes it over next.
    process.stdin.setRawMode(wasRaw);
  }
}

/** A menu row: highlighted (inverse) when selected, indented otherwise. */
function rowFor(selected: boolean, label: string, detail: string): string {
  const body = detail ? `${label}  ${chalk.gray(detail)}` : label;
  return selected ? chalk.inverse(`▶ ${body} `) : `  ${body}`;
}

/** First segment of a UUID — enough to recognise a session at a glance. */
function shortId(sessionId: string): string {
  return sessionId.split("-")[0] ?? sessionId.slice(0, 8);
}

/** "3 turns · 5m ago · <preview>" style detail for a saved session. */
function describe(summary: SessionSummary): string {
  const turns = `${summary.turns} turn${summary.turns === 1 ? "" : "s"}`;
  const when = relativeTime(summary.updatedAt);
  const preview = summary.preview ?? chalk.italic("(no messages yet)");
  return `${turns} · ${when} · ${preview}`;
}

/** Coarse "Nx ago" relative time; precise enough for an at-a-glance list. */
function relativeTime(epochMillis: number): string {
  const seconds = Math.max(0, Math.round((Date.now() - epochMillis) / 1000));
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.round(hours / 24);
  return `${days}d ago`;
}

export interface Logger {
  error(message: string, ...args: unknown[]): void;
  warn(message: string, ...args: unknown[]): void;
  info(message: string, ...args: unknown[]): void;
  debug(message: string, ...args: unknown[]): void;
}

export class ConsoleLogger implements Logger {
  constructor(private readonly prefix?: string) {}

  private format(message: string): string {
    return this.prefix ? `[${this.prefix}] ${message}` : message;
  }

  error(message: string, ...args: unknown[]): void {
    console.error(this.format(message), ...args);
  }

  warn(message: string, ...args: unknown[]): void {
    console.warn(this.format(message), ...args);
  }

  info(message: string, ...args: unknown[]): void {
    console.log(this.format(message), ...args);
  }

  debug(message: string, ...args: unknown[]): void {
    if (process.env.DEBUG) {
      console.debug(this.format(message), ...args);
    }
  }
}

import { describe, expect, test } from "@jest/globals";
import type Anthropic from "@anthropic-ai/sdk";

import { applyMessageBreakpoints } from "../src/agent/providers/anthropic-provider.js";

/**
 * Rolling conversation-cache breakpoint tests.
 *
 * The provider marks the last content block of the prompt (so the next,
 * longer prompt reads this one as a cache hit) and a second block ~15 blocks
 * earlier (so the current prompt can still find the previous entry when one
 * iteration appended more than the API's 20-block lookback window).
 */

function user(text: string): Anthropic.MessageParam {
  return { role: "user", content: text };
}

function assistant(text: string): Anthropic.MessageParam {
  return { role: "assistant", content: text };
}

function toolResults(count: number): Anthropic.MessageParam {
  return {
    role: "user",
    content: Array.from({ length: count }, (_, i) => ({
      type: "tool_result" as const,
      tool_use_id: `tu_${i}`,
      content: `result ${i}`,
    })),
  };
}

/** All blocks across all messages, flattened in order, post-normalisation. */
function flatBlocks(messages: Anthropic.MessageParam[]): Record<string, unknown>[] {
  return messages.flatMap((m) =>
    typeof m.content === "string"
      ? [{ type: "text", text: m.content }]
      : (m.content as Record<string, unknown>[])
  );
}

function markedIndexes(messages: Anthropic.MessageParam[]): number[] {
  return flatBlocks(messages)
    .map((b, i) => ("cache_control" in b ? i : -1))
    .filter((i) => i >= 0);
}

describe("applyMessageBreakpoints", () => {
  test("marks only the last block of a short conversation", () => {
    const messages = [user("hello"), assistant("hi"), user("do the thing")];

    applyMessageBreakpoints(messages);

    expect(markedIndexes(messages)).toEqual([2]); // last of 3 blocks
  });

  test("normalises string content to a text block only where it marks", () => {
    const messages = [user("hello"), user("latest")];

    applyMessageBreakpoints(messages);

    // Unmarked message keeps its plain-string content (no churn).
    expect(typeof messages[0].content).toBe("string");
    // Marked message was converted so the block can carry cache_control.
    expect(messages[1].content).toEqual([
      { type: "text", text: "latest", cache_control: { type: "ephemeral" } },
    ]);
  });

  test("counts content blocks, not messages, and places the lookback marker", () => {
    // 1 (user) + 18 (tool_results) + 1 (assistant) = 20 blocks total.
    const messages = [user("start"), toolResults(18), assistant("done")];

    applyMessageBreakpoints(messages);

    const marked = markedIndexes(messages);
    // Last block (index 19) and the block 15 positions back from it (19-15=4).
    expect(marked).toEqual([4, 19]);
  });

  test("places exactly two markers no matter how long the conversation is", () => {
    const messages = Array.from({ length: 60 }, (_, i) =>
      i % 2 === 0 ? user(`u${i}`) : assistant(`a${i}`)
    );

    applyMessageBreakpoints(messages);

    expect(markedIndexes(messages)).toHaveLength(2);
  });

  test("tolerates an empty message array", () => {
    const messages: Anthropic.MessageParam[] = [];
    expect(() => applyMessageBreakpoints(messages)).not.toThrow();
  });
});

import { describe, expect, test } from "@jest/globals";
import type Anthropic from "@anthropic-ai/sdk";

import { repairToolPairing } from "../src/agent/providers/anthropic-provider.js";

/**
 * repairToolPairing tests.
 *
 * The Messages API requires every assistant `tool_use` to be answered by a
 * `tool_result` in the immediately-following user turn. These cover the
 * poisoned-transcript shapes a real interruption leaves behind.
 */

const toolUse = (id: string): Anthropic.ContentBlockParam => ({
  type: "tool_use",
  id,
  name: "do_thing",
  input: {},
});

/** Pull the tool_result ids out of a user turn (or [] for anything else). */
function resultIds(message: Anthropic.MessageParam | undefined): string[] {
  if (!message || message.role !== "user" || !Array.isArray(message.content)) return [];
  return message.content
    .filter((b) => typeof b === "object" && b !== null && (b as { type?: string }).type === "tool_result")
    .map((b) => (b as Anthropic.ToolResultBlockParam).tool_use_id);
}

describe("repairToolPairing", () => {
  test("leaves a well-formed transcript untouched", () => {
    const messages: Anthropic.MessageParam[] = [
      { role: "user", content: "do it" },
      { role: "assistant", content: [toolUse("a")] },
      { role: "user", content: [{ type: "tool_result", tool_use_id: "a", content: "ok" }] },
    ];
    const out = repairToolPairing(messages);
    expect(out).toHaveLength(3);
    expect(resultIds(out[2])).toEqual(["a"]);
  });

  test("dangling tool_use followed by a user turn: synthesizes the missing result", () => {
    // The exact poison shape: [user, assistant(tool_use), user] with no result.
    const messages: Anthropic.MessageParam[] = [
      { role: "user", content: "do it" },
      { role: "assistant", content: [toolUse("a")] },
      { role: "user", content: "continue the work" },
    ];
    const out = repairToolPairing(messages);

    // Still three turns (the synthetic result folds INTO the next user turn,
    // never creating two consecutive user turns).
    expect(out).toHaveLength(3);
    expect(out[1].role).toBe("assistant");
    expect(out[2].role).toBe("user");

    // The next user turn now leads with the synthetic, error-flagged result for
    // "a", and still carries the original user text.
    const blocks = out[2].content as Anthropic.ContentBlockParam[];
    expect(blocks[0]).toMatchObject({ type: "tool_result", tool_use_id: "a", is_error: true });
    expect(blocks.some((b) => (b as { type?: string }).type === "text")).toBe(true);
  });

  test("dangling tool_use at the end of the transcript: appends a result turn", () => {
    const messages: Anthropic.MessageParam[] = [
      { role: "user", content: "do it" },
      { role: "assistant", content: [toolUse("a")] },
    ];
    const out = repairToolPairing(messages);
    expect(out).toHaveLength(3);
    expect(out[2].role).toBe("user");
    expect(resultIds(out[2])).toEqual(["a"]);
  });

  test("multiple tool_use blocks: only the unanswered id is synthesized", () => {
    const messages: Anthropic.MessageParam[] = [
      { role: "assistant", content: [toolUse("a"), toolUse("b")] },
      { role: "user", content: [{ type: "tool_result", tool_use_id: "a", content: "ok" }] },
    ];
    const out = repairToolPairing(messages);
    // "a" was already answered; "b" gets a synthetic result merged into the same
    // user turn, which stays a single turn.
    expect(out).toHaveLength(2);
    expect(resultIds(out[1]).sort()).toEqual(["a", "b"]);
  });
});

import { describe, expect, test } from "@jest/globals";

import { parseArgs } from "../src/cli/args.js";

/**
 * parseArgs tests.
 *
 * Pure input → output: assert the two recognised flags across the
 * `--flag value` and `--flag=value` forms, plus the no-flag (interactive)
 * default and the value-handling edge cases.
 */
describe("parseArgs", () => {
  test("no flags ⇒ interactive (run undefined)", () => {
    const args = parseArgs([]);
    expect(args.run).toBeUndefined();
    expect(args.sessionId).toBeUndefined();
  });

  test("--run with a space-separated value", () => {
    const args = parseArgs(["--run", "refactor foo.ts"]);
    expect(args.run).toBe("refactor foo.ts");
    expect(args.sessionId).toBeUndefined();
  });

  test("--run and --session together", () => {
    const args = parseArgs(["--run", "do X", "--session", "abc-123"]);
    expect(args.run).toBe("do X");
    expect(args.sessionId).toBe("abc-123");
  });

  test("--flag=value form is accepted", () => {
    const args = parseArgs(["--run=do Y", "--session=sess-9"]);
    expect(args.run).toBe("do Y");
    expect(args.sessionId).toBe("sess-9");
  });

  test("order is irrelevant", () => {
    const args = parseArgs(["--session", "s1", "--run", "task"]);
    expect(args.run).toBe("task");
    expect(args.sessionId).toBe("s1");
  });

  test("--run with no following value defaults to empty string (still headless)", () => {
    const args = parseArgs(["--run"]);
    expect(args.run).toBe("");
  });

  test("--run does not swallow a following flag as its value", () => {
    const args = parseArgs(["--run", "--session", "s2"]);
    // "--session" is a flag, not the run value, so run is empty and session set.
    expect(args.run).toBe("");
    expect(args.sessionId).toBe("s2");
  });

  test("unknown flags are ignored", () => {
    const args = parseArgs(["--verbose", "--run", "go"]);
    expect(args.run).toBe("go");
  });
});

import { describe, expect, test, beforeEach, afterEach } from "@jest/globals";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

import { ContextLoader } from "../../src/agent/context/context-loader.js";
import type { ToolDescriptor } from "../../src/agent/providers/provider.js";

/**
 * Context-snapshot store tests.
 *
 * The snapshot captures the non-conversation context (system prompt + project
 * direction + tool block) under a content-addressed hash. These cover the
 * invariants ContextMiddleware leans on: deterministic hashing keyed on the
 * captured inputs, write-once dedup, and a faithful round-trip read.
 */

const tool = (name: string): ToolDescriptor => ({
  name,
  description: `desc ${name}`,
  inputSchema: { type: "object" },
});

const ROLE = "orchestrator";
const SYSTEM_PROMPT = "You are the ORCHESTRATOR.";
const PROJECT_CONTEXT = "do the thing";
const TOOLS = [tool("read_file"), tool("list_dir")];

describe("ContextLoader.buildContext / hashContextSnapshot", () => {
  // The contexts dir is irrelevant for pure build/hash work — only save/get touch disk.
  const loader = new ContextLoader(os.tmpdir());

  test("captures the build inputs verbatim", () => {
    const snapshot = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);

    expect(snapshot.role).toBe(ROLE);
    expect(snapshot.systemPrompt).toBe(SYSTEM_PROMPT);
    expect(snapshot.projectContext).toBe(PROJECT_CONTEXT);
    expect(snapshot.tools.map((t) => t.name)).toEqual(["read_file", "list_dir"]);
  });

  test("the same inputs hash identically", () => {
    const a = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const b = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);

    expect(loader.hashContextSnapshot(a)).toBe(loader.hashContextSnapshot(b));
  });

  test("a changed system prompt yields a different hash", () => {
    const a = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const b = loader.buildContext(ROLE, "different", PROJECT_CONTEXT, TOOLS);

    expect(loader.hashContextSnapshot(a)).not.toBe(loader.hashContextSnapshot(b));
  });

  test("a changed tool set yields a different hash", () => {
    const a = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const b = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, [tool("read_file")]);

    expect(loader.hashContextSnapshot(a)).not.toBe(loader.hashContextSnapshot(b));

    const b = loader.buildContext(ROLE, "different", PROJECT_CONTEXT, TOOLS);

    expect(loader.hashContextSnapshot(a)).not.toBe(loader.hashContextSnapshot(b));
  });

  test("a changed tool set yields a different hash", () => {
    const a = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const b = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, [tool("read_file")]);

    expect(loader.hashContextSnapshot(a)).not.toBe(loader.hashContextSnapshot(b));
  });
});

describe("ContextLoader.saveContextSnapshot / getContextSnapshot", () => {
  let dir: string;
  let loader: ContextLoader;

  beforeEach(async () => {
    dir = await fs.mkdtemp(path.join(os.tmpdir(), "ctx-snap-"));
    loader = new ContextLoader(dir);
  });

  afterEach(async () => {
    await fs.rm(dir, { recursive: true, force: true });
  });

  test("saves under <hash>.json and round-trips the exact snapshot", async () => {
    const snapshot = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const hash = await loader.saveContextSnapshot(snapshot);

    expect(hash).toBe(loader.hashContextSnapshot(snapshot));
    await expect(fs.access(path.join(dir, `${hash}.json`))).resolves.toBeUndefined();
    expect(await loader.getContextSnapshot(hash)).toEqual(snapshot);
  });

  test("is write-once: re-saving the same context does not rewrite the file", async () => {
    const snapshot = loader.buildContext(ROLE, SYSTEM_PROMPT, PROJECT_CONTEXT, TOOLS);
    const hash = await loader.saveContextSnapshot(snapshot);

    const target = path.join(dir, `${hash}.json`);
    const firstMtime = (await fs.stat(target)).mtimeMs;

    const hashAgain = await loader.saveContextSnapshot(snapshot);
    const secondMtime = (await fs.stat(target)).mtimeMs;

    expect(hashAgain).toBe(hash);
    expect(secondMtime).toBe(firstMtime); // untouched
  });

  test("returns null for an unknown hash", async () => {
    expect(await loader.getContextSnapshot("deadbeefdeadbeef")).toBeNull();
  });
});

import { afterEach, beforeEach, describe, expect, jest, test } from "@jest/globals";

import { GeminiProvider, cacheExpiryMs } from "../src/agent/providers/gemini-provider.js";

/**
 * Gemini context-cache lifecycle tests.
 *
 * The provider memoizes one server-side cache entry (system + tools). Entries
 * are deleted server-side at expireTime; reusing a lapsed name fails the
 * request outright. These lock in that the memo is keyed on BOTH content and
 * freshness: a fresh entry is reused, an expired or content-changed one is
 * recreated, and a failed create falls back to inline (and retries later).
 */

const NOW = Date.parse("2026-06-10T12:00:00Z");

/** A system instruction + tool set big enough to be cache-worthy in spirit. */
const SYSTEM = "You are the orchestrator.";
const TOOLS = [{ functionDeclarations: [{ name: "read_file" }] }];

function providerWithStubbedCaches(create: jest.Mock) {
  const provider = new GeminiProvider({
    apiKey: "test-key",
    model: "gemini-2.5-flash-lite",
    supportsTools: true,
  } as never);
  // Replace the real SDK client with a stub; only caches.create is exercised.
  (provider as unknown as { client: unknown }).client = { caches: { create } };
  return provider;
}

function ensureCache(provider: GeminiProvider, system: string | undefined, tools: unknown) {
  return (
    provider as unknown as {
      ensureCache(s: string | undefined, t: unknown): Promise<string | undefined>;
    }
  ).ensureCache(system, tools);
}

describe("cacheExpiryMs", () => {
  test("prefers the server-reported expireTime", () => {
    const expireTime = "2026-06-10T12:05:00Z";
    expect(cacheExpiryMs(expireTime, NOW)).toBe(Date.parse(expireTime));
  });

  test("falls back to now + TTL when expireTime is absent", () => {
    expect(cacheExpiryMs(undefined, NOW)).toBe(NOW + 300_000);
  });

  test("falls back to now + TTL when expireTime is unparseable", () => {
    expect(cacheExpiryMs("not-a-date", NOW)).toBe(NOW + 300_000);
  });
});

describe("GeminiProvider cache lifecycle", () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(NOW);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test("reuses a fresh cache entry without re-creating", async () => {
    const create = jest.fn(async () => ({
      name: "cachedContents/fresh",
      expireTime: new Date(NOW + 300_000).toISOString(),
    })) as jest.Mock;
    const provider = providerWithStubbedCaches(create);

    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/fresh");
    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/fresh");
    expect(create).toHaveBeenCalledTimes(1);
  });

  test("recreates once the entry is within the expiry margin", async () => {
    let serial = 0;
    const create = jest.fn(async () => ({
      name: `cachedContents/v${++serial}`,
      expireTime: new Date(Date.now() + 300_000).toISOString(),
    })) as jest.Mock;
    const provider = providerWithStubbedCaches(create);

    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/v1");

    // 30s before expireTime is the margin boundary — past it, the memoized
    // name must NOT be reused (this was the bug: it was reused forever).
    jest.setSystemTime(NOW + 300_000 - 10_000);
    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/v2");
    expect(create).toHaveBeenCalledTimes(2);
  });

  test("recreates when the system+tools key changes", async () => {
    let serial = 0;
    const create = jest.fn(async () => ({
      name: `cachedContents/v${++serial}`,
      expireTime: new Date(Date.now() + 300_000).toISOString(),
    })) as jest.Mock;
    const provider = providerWithStubbedCaches(create);

    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/v1");
    expect(await ensureCache(provider, "Different system prompt.", TOOLS)).toBe(
      "cachedContents/v2"
    );
    expect(create).toHaveBeenCalledTimes(2);
  });

  test("falls back to inline on create failure and retries next call", async () => {
    const create = jest
      .fn(async () => {
        throw new Error("below minimum token count");
      })
      .mockImplementationOnce(async () => {
        throw new Error("below minimum token count");
      }) as jest.Mock;
    const provider = providerWithStubbedCaches(create);

    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBeUndefined();

    // State was cleared, so the next call tries again rather than staying
    // permanently inline on a stale memo.
    create.mockImplementationOnce(async () => ({
      name: "cachedContents/recovered",
      expireTime: new Date(Date.now() + 300_000).toISOString(),
    }));
    expect(await ensureCache(provider, SYSTEM, TOOLS)).toBe("cachedContents/recovered");
  });
});

import { describe, expect, test } from "@jest/globals";
import type { GenerateContentResponse } from "@google/genai";

import {
  fromGeminiResponse,
  toGeminiMessages,
} from "../src/agent/providers/gemini-provider.js";
import type { ChatMessage } from "../src/agent/providers/provider.js";

/**
 * Gemini thoughtSignature round-trip tests.
 *
 * Thinking models attach an opaque `thoughtSignature` to each functionCall
 * part and reject (HTTP 400) any later request that replays the call without
 * it. These lock in that the signature is captured off the response and echoed
 * back verbatim when the conversation is replayed.
 */

/** Minimal GenerateContentResponse stand-in carrying just the parts we read. */
function responseWithParts(
  parts: Array<Record<string, unknown>>
): GenerateContentResponse {
  return {
    candidates: [{ content: { parts } }],
  } as unknown as GenerateContentResponse;
}

describe("fromGeminiResponse", () => {
  test("captures thoughtSignature from a functionCall part onto the ToolCall", () => {
    const response = responseWithParts([
      { functionCall: { name: "do_thing", args: { a: 1 } }, thoughtSignature: "sig-xyz" },
    ]);

    const { toolCalls } = fromGeminiResponse(response);

    expect(toolCalls).toHaveLength(1);
    expect(toolCalls[0]).toMatchObject({ name: "do_thing", signature: "sig-xyz" });
  });

  test("concatenates text parts and skips thought parts when building content", () => {
    const response = responseWithParts([
      { text: "internal reasoning", thought: true },
      { text: "visible answer" },
    ]);

    const { content, toolCalls } = fromGeminiResponse(response);

    expect(content).toBe("visible answer");
    expect(toolCalls).toHaveLength(0);
  });

  test("leaves signature undefined when the part has none", () => {
    const response = responseWithParts([
      { functionCall: { name: "do_thing", args: {} } },
    ]);

    const { toolCalls } = fromGeminiResponse(response);

    expect(toolCalls[0].signature).toBeUndefined();
  });
});

describe("toGeminiMessages", () => {
  test("echoes the signature back onto the replayed functionCall part", () => {
    const messages: ChatMessage[] = [
      {
        role: "assistant",
        content: "",
        toolCalls: [{ id: "do_thing", name: "do_thing", arguments: {}, signature: "sig-xyz" }],
      },
    ];

    const { contents } = toGeminiMessages(messages);

    const modelTurn = contents[0];
    expect(modelTurn.role).toBe("model");
    expect(modelTurn.parts?.[0]).toMatchObject({
      functionCall: { name: "do_thing" },
      thoughtSignature: "sig-xyz",
    });
  });

  test("omits thoughtSignature when the ToolCall carries none", () => {
    const messages: ChatMessage[] = [
      {
        role: "assistant",
        content: "",
        toolCalls: [{ id: "do_thing", name: "do_thing", arguments: {} }],
      },
    ];

    const { contents } = toGeminiMessages(messages);

    expect(contents[0].parts?.[0]).not.toHaveProperty("thoughtSignature");
  });
});

describe("response → replay round-trip", () => {
  test("a captured signature survives back into the next request", () => {
    const { toolCalls } = fromGeminiResponse(
      responseWithParts([
        { functionCall: { name: "do_thing", args: { a: 1 } }, thoughtSignature: "sig-abc" },
      ])
    );

    const assistant: ChatMessage = { role: "assistant", content: "", toolCalls };
    const { contents } = toGeminiMessages([assistant]);

    expect(contents[0].parts?.[0]).toMatchObject({ thoughtSignature: "sig-abc" });
  });
});

