import { describe, expect, test } from "@jest/globals";

import { TurnRunner, type RoundDispatch } from "../../src/agent/runners/turn-runner.js";

/**
 * TurnRunner scheduling semantics.
 *
 * The runner is tested as a pure scheduler: `dispatch` is a fake that records
 * calls and can be gated on a deferred, so each test controls exactly when a
 * round is "in flight". No orchestrator, providers, or timers involved.
 */

interface Deferred<T> {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: unknown) => void;
}

function deferred<T = void>(): Deferred<T> {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

/** Dispatch that records contents and resolves immediately. */
function instantDispatch(calls: string[]): RoundDispatch {
  return async (content) => {
    calls.push(content);
    return { outcome: "satisfied" };
  };
}

describe("TurnRunner", () => {
  test("runs queued turns in FIFO order", async () => {
    const calls: string[] = [];
    const runner = new TurnRunner(instantDispatch(calls));
    runner.start();

    const first = runner.submit({ content: "one", source: "user" });
    const second = runner.submit({ content: "two", source: "user" });

    const [firstTurn, secondTurn] = await Promise.all([first.settled, second.settled]);
    expect(calls).toEqual(["one", "two"]);
    expect(firstTurn.status).toBe("done");
    expect(secondTurn.status).toBe("done");
    await runner.stop();
  });

  test("submissions queued before start run once started (resume contract)", async () => {
    const calls: string[] = [];
    const runner = new TurnRunner(instantDispatch(calls));

    const receipt = runner.submit({ content: "early", source: "user" });
    expect(calls).toEqual([]); // pump not running yet

    runner.start();
    const settled = await receipt.settled;
    expect(calls).toEqual(["early"]);
    expect(settled.status).toBe("done");
    await runner.stop();
  });

  test("preferMidTurn appends a round to the RUNNING turn and settles with it", async () => {
    const firstStarted = deferred();
    const releaseFirst = deferred();
    const calls: string[] = [];
    const runner = new TurnRunner(async (content) => {
      calls.push(content);
      if (content === "first") {
        firstStarted.resolve();
        await releaseFirst.promise;
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    const userReceipt = runner.submit({ content: "first", source: "user" });
    await firstStarted.promise;

    const feedbackReceipt = runner.submit({
      content: "feedback",
      source: "subsession",
      preferMidTurn: true,
    });

    expect(feedbackReceipt.placement).toBe("mid-turn-round");
    expect(feedbackReceipt.turnId).toBe(userReceipt.turnId);

    releaseFirst.resolve();
    const settled = await userReceipt.settled;
    expect(settled.status).toBe("done");
    expect(settled.rounds.map((round) => round.content)).toEqual(["first", "feedback"]);
    expect(calls).toEqual(["first", "feedback"]);
    await runner.stop();
  });

  test("preferMidTurn with no running turn falls back to a new queued turn", async () => {
    const calls: string[] = [];
    const runner = new TurnRunner(instantDispatch(calls));
    runner.start();

    const receipt = runner.submit({ content: "wake", source: "subsession", preferMidTurn: true });
    expect(receipt.placement).toBe("new-turn");
    const settled = await receipt.settled;
    expect(settled.status).toBe("done");
    expect(calls).toEqual(["wake"]);
    await runner.stop();
  });

  test("coalesceKey collapses onto a PENDING turn instead of growing the queue", async () => {
    const firstStarted = deferred();
    const releaseFirst = deferred();
    const calls: string[] = [];
    const runner = new TurnRunner(async (content) => {
      calls.push(content);
      if (content === "busy") {
        firstStarted.resolve();
        await releaseFirst.promise;
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    runner.submit({ content: "busy", source: "user" });
    await firstStarted.promise;

    // Two reports arrive while the user turn runs; preferMidTurn is OFF here
    // so they must queue — and the second coalesces into the first's turn.
    const reportA = runner.submit({ content: "report-a", source: "subsession", coalesceKey: "report" });
    const reportB = runner.submit({ content: "report-b", source: "subsession", coalesceKey: "report" });

    expect(reportA.placement).toBe("new-turn");
    expect(reportB.placement).toBe("coalesced-round");
    expect(reportB.turnId).toBe(reportA.turnId);
    expect(runner.pendingCount).toBe(1);

    releaseFirst.resolve();
    const settled = await reportA.settled;
    expect(settled.rounds.map((round) => round.content)).toEqual(["report-a", "report-b"]);
    expect(calls).toEqual(["busy", "report-a", "report-b"]);
    await runner.stop();
  });

  test("a failing round fails the turn, skips later rounds, and the pump continues", async () => {
    const calls: string[] = [];
    const runner = new TurnRunner(async (content) => {
      calls.push(content);
      if (content === "boom") throw new Error("dispatch exploded");
      return { outcome: "satisfied" };
    });

    // Build a 2-round turn via coalescing BEFORE the pump starts, plus a
    // follow-up turn that must still run after the failure.
    const failing = runner.submit({ content: "boom", source: "subsession", coalesceKey: "k" });
    runner.submit({ content: "never-runs", source: "subsession", coalesceKey: "k" });
    const followUp = runner.submit({ content: "after", source: "user" });

    runner.start();
    const [failedTurn, followUpTurn] = await Promise.all([failing.settled, followUp.settled]);

    expect(failedTurn.status).toBe("error");
    expect(failedTurn.rounds[0].status).toBe("error");
    expect(failedTurn.rounds[0].error).toContain("dispatch exploded");
    expect(failedTurn.rounds[1].status).toBe("skipped");
    expect(followUpTurn.status).toBe("done");
    expect(calls).toEqual(["boom", "after"]); // "never-runs" was never dispatched
    await runner.stop();
  });

  test("cancelling a pending turn settles it without dispatching", async () => {
    const firstStarted = deferred();
    const releaseFirst = deferred();
    const calls: string[] = [];
    const runner = new TurnRunner(async (content) => {
      calls.push(content);
      if (content === "busy") {
        firstStarted.resolve();
        await releaseFirst.promise;
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    runner.submit({ content: "busy", source: "user" });
    await firstStarted.promise;
    const doomed = runner.submit({ content: "doomed", source: "user" });

    expect(runner.cancel(doomed.turnId)).toBe(true);
    const settled = await doomed.settled;
    expect(settled.status).toBe("cancelled");
    expect(settled.rounds[0].status).toBe("skipped");

    releaseFirst.resolve();
    await runner.stop();
    expect(calls).toEqual(["busy"]);
  });

  test("cancelCurrent aborts the in-flight turn; the pump moves on to the next", async () => {
    const started = deferred();
    const calls: string[] = [];
    const runner = new TurnRunner(async (content, signal) => {
      calls.push(content);
      if (content === "long") {
        started.resolve();
        // Honour the abort signal the way a real provider call would.
        await new Promise<never>((_, reject) => {
          signal.addEventListener("abort", () => reject(new Error("aborted")), { once: true });
        });
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    expect(runner.cancelCurrent()).toBe(false); // nothing in flight yet

    const longReceipt = runner.submit({ content: "long", source: "user" });
    const nextReceipt = runner.submit({ content: "next", source: "user" });
    await started.promise;

    expect(runner.cancelCurrent()).toBe(true);
    const [cancelled, next] = await Promise.all([longReceipt.settled, nextReceipt.settled]);

    expect(cancelled.status).toBe("cancelled");
    expect(cancelled.rounds[0].status).toBe("cancelled"); // a stop, not an error
    expect(next.status).toBe("done");
    expect(calls).toEqual(["long", "next"]);
    await runner.stop();
  });

  test("cancelAll flushes pending turns and aborts the in-flight one", async () => {
    const started = deferred();
    const calls: string[] = [];
    const runner = new TurnRunner(async (content, signal) => {
      calls.push(content);
      if (content === "long") {
        started.resolve();
        await new Promise<never>((_, reject) => {
          signal.addEventListener("abort", () => reject(new Error("aborted")), { once: true });
        });
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    const inFlight = runner.submit({ content: "long", source: "user" });
    const queuedA = runner.submit({ content: "queued-a", source: "user" });
    const queuedB = runner.submit({ content: "queued-b", source: "subsession", coalesceKey: "report" });
    await started.promise;

    expect(runner.cancelAll()).toBe(3);
    const [current, a, b] = await Promise.all([inFlight.settled, queuedA.settled, queuedB.settled]);

    expect(current.status).toBe("cancelled");
    expect(a.status).toBe("cancelled");
    expect(b.status).toBe("cancelled");
    expect(calls).toEqual(["long"]); // queued turns never dispatched
    expect(runner.isBusy).toBe(false);
    await runner.stop();
  });

  test("awaitIdle resolves immediately when idle, and only after in-flight work settles otherwise", async () => {
    const started = deferred();
    const release = deferred();
    const runner = new TurnRunner(async () => {
      started.resolve();
      await release.promise;
      return { outcome: "satisfied" };
    });
    runner.start();

    await runner.awaitIdle(); // idle → must not hang

    const receipt = runner.submit({ content: "work", source: "user" });
    await started.promise;

    let idleResolved = false;
    const idle = runner.awaitIdle().then(() => {
      idleResolved = true;
    });
    expect(idleResolved).toBe(false); // still in flight

    release.resolve();
    await idle;
    expect(runner.isBusy).toBe(false);

    const settled = await receipt.settled;
    expect(settled.status).toBe("done");
    await runner.stop();
  });

  test("maxRoundsPerTurn spills appends into a new turn instead of growing forever", async () => {
    const firstStarted = deferred();
    const releaseFirst = deferred();
    const runner = new TurnRunner(
      async (content) => {
        if (content === "busy") {
          firstStarted.resolve();
          await releaseFirst.promise;
        }
        return { outcome: "satisfied" };
      },
      { maxRoundsPerTurn: 1 }
    );
    runner.start();

    const userReceipt = runner.submit({ content: "busy", source: "user" });
    await firstStarted.promise;

    // The running turn is at its 1-round cap — the append must spill.
    const spilled = runner.submit({ content: "fb", source: "subsession", preferMidTurn: true });
    expect(spilled.placement).toBe("new-turn");
    expect(spilled.turnId).not.toBe(userReceipt.turnId);

    releaseFirst.resolve();
    await Promise.all([userReceipt.settled, spilled.settled]);
    await runner.stop();
  });

  test("snapshot projects current + pending turns with their rounds", async () => {
    const firstStarted = deferred();
    const releaseFirst = deferred();
    const runner = new TurnRunner(async (content) => {
      if (content === "busy") {
        firstStarted.resolve();
        await releaseFirst.promise;
      }
      return { outcome: "satisfied" };
    });
    runner.start();

    const running = runner.submit({ content: "busy", source: "user" });
    await firstStarted.promise;
    const waiting = runner.submit({ content: "waiting", source: "subsession", coalesceKey: "report" });

    const snapshot = runner.snapshot();
    expect(snapshot.current?.turnId).toBe(running.turnId);
    expect(snapshot.current?.status).toBe("running");
    expect(snapshot.current?.rounds[0].status).toBe("running");
    expect(snapshot.pending).toHaveLength(1);
    expect(snapshot.pending[0].coalesceKey).toBe("report");
    expect(snapshot.pending[0].rounds[0].content).toBe("waiting");

    releaseFirst.resolve();
    // Await BOTH turns: a graceful stop() leaves still-pending turns queued
    // (the resume contract), so isBusy is only false once the queue drained.
    await Promise.all([running.settled, waiting.settled]);
    await runner.stop();
    expect(runner.isBusy).toBe(false);
  });
});

import { describe, expect, jest, test } from "@jest/globals";

import { ScopedToolClient } from "../src/agent/scoped-tool-client.js";
import type { Mcp } from "../src/agent/mcp/mcp.js";
import type { ToolDescriptor } from "../src/agent/providers/provider.js";

/**
 * ScopedToolClient routing.
 *
 * Path confinement lives in the server (Workspace guard), not here — these
 * tests cover the routing layer only: namespaced calls, tolerant bare-name
 * resolution, and corrective errors for ambiguous / unknown names.
 */

function fakeMcp(name: string, toolTails: string[]): { mcp: Mcp; callTool: jest.Mock } {
  const callTool = jest.fn(async () => ({ isError: false, content: "{}" }));
  const tools: ToolDescriptor[] = toolTails.map((tail) => ({
    name: `${name}__${tail}`,
    description: tail,
    inputSchema: { type: "object" },
  }));
  return {
    mcp: {
      name,
      listTools: () => tools,
      callTool: callTool as unknown as Mcp["callTool"],
      shutdown: async () => {},
    },
    callTool,
  };
}

describe("ScopedToolClient routing", () => {
  test("a namespaced call routes to the correct server with the bare tail", async () => {
    const excel = fakeMcp("excel", ["append_rows", "read_sheet"]);
    const fs = fakeMcp("fsmcp", ["read_file"]);
    const client = new ScopedToolClient([excel.mcp, fs.mcp]);

    const result = await client.callTool("excel__append_rows", { rows: [] });

    expect(result.isError).toBe(false);
    expect(excel.callTool).toHaveBeenCalledWith("append_rows", { rows: [] });
    expect(fs.callTool).not.toHaveBeenCalled();
  });

  test("a bare tool name with exactly one owner routes to that server", async () => {
    const excel = fakeMcp("excel", ["append_rows", "read_sheet"]);
    const client = new ScopedToolClient([excel.mcp]);

    const result = await client.callTool("append_rows", { rows: [] });

    expect(result.isError).toBe(false);
    expect(excel.callTool).toHaveBeenCalledWith("append_rows", { rows: [] });
  });

  test("an unknown bare name returns a corrective error naming mounted servers", async () => {
    const fs = fakeMcp("fsmcp", ["read_file"]);
    const client = new ScopedToolClient([fs.mcp]);

    const result = await client.callTool("run_shell", {});

    expect(result.isError).toBe(true);
    expect(result.content).toContain("namespaced as <server>__<tool>");
    expect(result.content).toContain("fsmcp");
    expect(fs.callTool).not.toHaveBeenCalled();
  });

  test("a bare name owned by multiple servers is rejected as ambiguous with candidates", async () => {
    const a = fakeMcp("alpha", ["list_items"]);
    const b = fakeMcp("beta", ["list_items"]);
    const client = new ScopedToolClient([a.mcp, b.mcp]);

    const result = await client.callTool("list_items", {});

    expect(result.isError).toBe(true);
    expect(result.content).toContain("alpha__list_items");
    expect(result.content).toContain("beta__list_items");
    expect(a.callTool).not.toHaveBeenCalled();
    expect(b.callTool).not.toHaveBeenCalled();
  });
});

import { describe, expect, test } from "@jest/globals";

import { ExecutorLocalMcp } from "../../src/agent/synthetic-mcp/executor-server.js";
import type { ModelRegistry } from "../../src/agent/registries/index.js";
import type { McpClientRegistry } from "../../src/agent/registries/mcp-registry.js";
import { makeContext } from "../middleware/context.js";

/**
 * ExecutorLocalMcp dispatch descriptor.
 *
 * The "tool" property must enumerate the executor role's live tool names —
 * resolved per listTools() call from the role's MCP servers — both as a strict
 * schema enum and in the prose description, so the orchestrator can only pick
 * names the executor can actually run.
 */
describe("ExecutorLocalMcp.listTools", () => {
  const makeRegistries = () => {
    const modelsRegistry = {
      getValidMcpForModel: (role: string) =>
        role === "executor" ? ["fsmcp", "codemcp", "executor"] : [],
    } as unknown as ModelRegistry;

    const clients: Record<string, { listTools: () => { name: string }[] } | undefined> = {
      fsmcp: {
        listTools: () => [
          { name: "fsmcp__write_file" },
          { name: "fsmcp__edit_file" },
        ],
      },
      // codemcp declared in models.json but not mounted — must drop out.
      codemcp: undefined,
    };
    const mcpRegistry = {
      getClient: (name: string) => clients[name],
    } as unknown as McpClientRegistry;

    return { modelsRegistry, mcpRegistry };
  };

  test("enumerates the executor role's mounted tools as enum and description", () => {
    const { modelsRegistry, mcpRegistry } = makeRegistries();
    const ctx = makeContext({ modelsRegistry, mcpRegistry });

    const [descriptor] = new ExecutorLocalMcp(ctx).listTools();

    expect(descriptor.name).toBe("executor__dispatch");
    const toolProperty = (descriptor.inputSchema as { properties: { tool: { enum?: string[] } } })
      .properties.tool;
    expect(toolProperty.enum).toEqual(["fsmcp__write_file", "fsmcp__edit_file"]);
    expect(descriptor.description).toContain("fsmcp__write_file");
    expect(descriptor.description).toContain("fsmcp__edit_file");
    // The executor server itself is never a dispatch target.
    expect(descriptor.description).not.toContain("executor__dispatch\n");
  });

  test("omits the enum when no executor tools are mounted", () => {
    const ctx = makeContext({
      modelsRegistry: {
        getValidMcpForModel: () => [],
      } as unknown as ModelRegistry,

    expect(descriptor.description).toContain("fsmcp__edit_file");
    // The executor server itself is never a dispatch target.
    expect(descriptor.description).not.toContain("executor__dispatch\n");
  });

  test("omits the enum when no executor tools are mounted", () => {
    const ctx = makeContext({
      modelsRegistry: {
        getValidMcpForModel: () => [],
      } as unknown as ModelRegistry,
    });

    const [descriptor] = new ExecutorLocalMcp(ctx).listTools();

    const toolProperty = (descriptor.inputSchema as { properties: { tool: { enum?: string[] } } })
      .properties.tool;
    expect(toolProperty.enum).toBeUndefined();
    expect(descriptor.description).toContain("No executor-side tools are currently mounted");
  });

  test("advertises executor__list_tools alongside dispatch", () => {
    const { modelsRegistry, mcpRegistry } = makeRegistries();
    const ctx = makeContext({ modelsRegistry, mcpRegistry });

    const tools = new ExecutorLocalMcp(ctx).listTools();

    expect(tools.map((tool) => tool.name)).toEqual(["executor__dispatch", "executor__list_tools"]);
  });
});

describe("ExecutorLocalMcp.callTool list_tools", () => {
  test("returns the executor's tool descriptors as JSON without dispatching", async () => {
    const modelsRegistry = {
      getValidMcpForModel: (role: string) => (role === "executor" ? ["fsmcp"] : []),
    } as unknown as ModelRegistry;
    const mcpRegistry = {
      getClient: () => ({
        listTools: () => [{ name: "fsmcp__write_file", description: "write", inputSchema: {} }],
      }),
    } as unknown as McpClientRegistry;
    const ctx = makeContext({ modelsRegistry, mcpRegistry });

    const result = await new ExecutorLocalMcp(ctx).callTool("list_tools", {});

    expect(result.isError).toBe(false);
    const parsed = JSON.parse(result.content) as { name: string }[];
    expect(parsed.map((tool) => tool.name)).toEqual(["fsmcp__write_file"]);
  });
});

import { afterEach, beforeEach, describe, expect, test } from "@jest/globals";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

import { createFsLocalMcp } from "../../src/agent/synthetic-mcp/fs-server.js";
import type { LocalMcp } from "../../src/agent/mcp/local-mcp.js";

/**
 * The in-process fsmcp server that replaced the spawned stdio server. It is now
 * a `LocalMcp`: tool calls are plain in-process function calls (no SDK Server,
 * no transport), so the tests drive it through the `Mcp` surface — listTools()
 * advertises namespaced descriptors, callTool() takes the bare tool name and
 * returns a `{ isError, content }` envelope whose content is the tool's JSON
 * payload. IO must stay confined to the injected sandbox root.
 */

describe("createFsLocalMcp", () => {
  let root: string;
  let server: LocalMcp;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), "fs-server-"));
    server = createFsLocalMcp(root);
  });

  afterEach(async () => {
    await server.shutdown();
    await fs.rm(root, { recursive: true, force: true });
  });

  test("advertises the seven fs tools namespaced under fsmcp", () => {
    const tools = server.listTools();
    expect(tools.map((t) => t.name).sort()).toEqual([
      "fsmcp__delete_file",
      "fsmcp__edit_file",
      "fsmcp__glob",
      "fsmcp__grep",
      "fsmcp__list_dir",
      "fsmcp__read_file",
      "fsmcp__write_file",
    ]);
    // inputSchema is real JSON Schema derived from the Zod schema.
    const readFile = tools.find((t) => t.name === "fsmcp__read_file");
    expect(readFile?.inputSchema).toMatchObject({ type: "object" });
  });

  test("write_file then read_file round-trips through a JSON envelope", async () => {
    const write = await server.callTool("write_file", { path: "notes/a.txt", content: "hello" });
    expect(write.isError).toBeFalsy();
    expect(JSON.parse(write.content)).toMatchObject({
      path: path.join("notes", "a.txt"),
      created: true,
    });

    // It actually hit disk under the sandbox root.
    const onDisk = await fs.readFile(path.join(root, "notes", "a.txt"), "utf8");
    expect(onDisk).toBe("hello");

    const read = await server.callTool("read_file", { path: "notes/a.txt" });

    expect(JSON.parse(write.content)).toMatchObject({
      path: path.join("notes", "a.txt"),
      created: true,
    });

    // It actually hit disk under the sandbox root.
    const onDisk = await fs.readFile(path.join(root, "notes", "a.txt"), "utf8");
    expect(onDisk).toBe("hello");

    const read = await server.callTool("read_file", { path: "notes/a.txt" });
    expect(read.isError).toBeFalsy();
    expect(JSON.parse(read.content).content).toBe("hello");
  });

  test("confines IO to the sandbox root (absolute escape is refused as a tool error)", async () => {
    const outside = path.join(os.tmpdir(), "escapee.txt");

    const result = await server.callTool("write_file", { path: outside, content: "nope" });

    expect(result.isError).toBe(true);
    expect(result.content).toContain("Workspace violation");
    await expect(fs.access(outside)).rejects.toThrow();
  });

  test("an unknown tool name returns an error result, not a throw", async () => {
    const result = await server.callTool("nonexistent", {});
    expect(result.isError).toBe(true);
    expect(result.content).toContain("Unknown tool");
  });
});

import { describe, expect, test } from "@jest/globals";

import { createFsReadonlyLocalMcp } from "../../src/agent/synthetic-mcp/fs-server.js";
import { createExcelReadonlyLocalMcp } from "../../src/agent/synthetic-mcp/excel-server.js";
import type { ToolContext } from "../../src/agent/synthetic-mcp/types.js";

/**
 * Read-only server mounts — the ENFORCED half of the orchestrator/executor
 * split. The contract under test is the boundary itself: mutating tools must
 * be absent from the advertisement AND uncallable, so a coordinator model
 * granted only these mounts cannot mutate no matter what it emits.
 */

const MUTATING_FS_TAILS = ["write_file", "edit_file", "delete_file"];
const MUTATING_EXCEL_TAILS = ["append_excel_rows", "append_after_excel_rows", "delete_excel_rows"];

/** Tool handlers are never invoked in these tests; only mounting is exercised. */
const fakeToolContext = {
  session: {},
  workspace: {},
  sandboxRoot: "/tmp/sandbox",
  coordinator: undefined,
  signal: undefined,
} as unknown as ToolContext;

describe("read-only server mounts", () => {
  test("fsreadonly advertises exactly the inspection tools, namespaced", () => {
    const server = createFsReadonlyLocalMcp("/tmp/sandbox");
    const names = server.listTools().map((tool) => tool.name).sort();

    expect(names).toEqual([
      "fsreadonly__glob",
      "fsreadonly__grep",
      "fsreadonly__list_dir",
      "fsreadonly__read_file",
    ]);
  });

  test("fsreadonly refuses mutating tool calls outright", async () => {
    const server = createFsReadonlyLocalMcp("/tmp/sandbox");

    for (const tail of MUTATING_FS_TAILS) {
      const result = await server.callTool(tail, { path: "x.txt", content: "x" });
      expect(result.isError).toBe(true);
      expect(result.content).toContain(`Unknown tool "${tail}"`);
    }
  });

  test("excelreadonly advertises exactly the inspection tools, namespaced", () => {
    const server = createExcelReadonlyLocalMcp(fakeToolContext);
    const names = server.listTools().map((tool) => tool.name).sort();

    expect(names).toEqual([
      "excelreadonly__get_excel_columns",
      "excelreadonly__list_sheets",
      "excelreadonly__query_excel_rows",
      "excelreadonly__read_excel_sheet",
    ]);
  });

    const names = server.listTools().map((tool) => tool.name).sort();

    expect(names).toEqual([
      "excelreadonly__get_excel_columns",
      "excelreadonly__list_sheets",
      "excelreadonly__query_excel_rows",
      "excelreadonly__read_excel_sheet",
    ]);
  });

  test("excelreadonly refuses mutating tool calls outright", async () => {
    const server = createExcelReadonlyLocalMcp(fakeToolContext);

    for (const tail of MUTATING_EXCEL_TAILS) {
      const result = await server.callTool(tail, { file_path: "x.xlsx", rows: [] });
      expect(result.isError).toBe(true);
      expect(result.content).toContain(`Unknown tool "${tail}"`);
    }
  });
});

import { describe, expect, test } from "@jest/globals";

import type { ChatMessage, ToolDescriptor } from "../src/agent/providers/provider.js";
import {
  buildPromptedToolInstructions,
  extractPromptedToolCalls,
} from "../src/agent/tool-adapter.js";

/**
 * tool-adapter tests.
 *
 * Both functions are pure (no I/O, no clock dependence beyond the generated
 * call id), so these are straightforward input → output assertions covering the
 * native-less "prompted JSON" strategy: building the instruction addendum and
 * recovering tool calls from assistant text.
 */

const SAMPLE_TOOL: ToolDescriptor = {
  name: "read_file",
  description: "Read a file from disk",
  inputSchema: { type: "object", properties: { path: { type: "string" } } },
};

/** Build the assistant message shape the extractor consumes. */
function assistant(content: string): ChatMessage {
  return { role: "assistant", content };
}

describe("buildPromptedToolInstructions", () => {
  test("returns an empty string when there are no tools", () => {
    expect(buildPromptedToolInstructions([])).toBe("");
  });

  test("lists each tool's name, description, and schema plus the invocation rules", () => {
    const result = buildPromptedToolInstructions([SAMPLE_TOOL]);

    expect(result).toContain("read_file");
    expect(result).toContain("Read a file from disk");
    // The JSON schema is rendered into the block.
    expect(result).toContain('"properties"');
    // The how-to-invoke scaffolding is present.
    expect(result).toContain("## Available tools");
    expect(result).toContain("single fenced JSON block");
    expect(result).toContain("Emit at most one tool_call block per turn.");
  });
});

describe("extractPromptedToolCalls", () => {
  test("extracts a fenced tool_call block and strips it from the visible content", () => {
    const message = assistant(
      ['Let me read that file.', '```json', '{ "tool_call": { "name": "read_file", "arguments": { "path": "a.txt" } } }', '```'].join(
        "\n"
      )
    );

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(1);
    expect(toolCalls[0].name).toBe("read_file");
    expect(toolCalls[0].arguments).toEqual({ path: "a.txt" });
    expect(toolCalls[0].id).toMatch(/^prompted_/);
    // The fenced block is removed; the surrounding prose remains.
    expect(cleanedContent).toBe("Let me read that file.");
  });

  test("accepts a bare {name, arguments} shape without the tool_call wrapper", () => {
    const message = assistant('```json\n{ "name": "read_file", "arguments": { "path": "b.txt" } }\n```');

    const { toolCalls } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(1);
    expect(toolCalls[0].name).toBe("read_file");
    expect(toolCalls[0].arguments).toEqual({ path: "b.txt" });
  });

  test("defaults arguments to an empty object when the fenced call omits them", () => {
    const message = assistant('```json\n{ "tool_call": { "name": "list_dir" } }\n```');

    const { toolCalls } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(1);
    expect(toolCalls[0].arguments).toEqual({});
  });

  test("extracts multiple fenced blocks in order", () => {
    const message = assistant(
      [
        '```json',
        '{ "tool_call": { "name": "read_file", "arguments": { "path": "a" } } }',
        '```',
        'and then',
        '```json',
        '{ "tool_call": { "name": "read_file", "arguments": { "path": "b" } } }',
        '```',
      ].join("\n")
    );

    const { toolCalls } = extractPromptedToolCalls(message);

    expect(toolCalls.map((c) => c.arguments)).toEqual([{ path: "a" }, { path: "b" }]);
  });

  test("leaves an invalid JSON block in place and reports no calls", () => {
    const content = '```json\n{ not valid json }\n```';
    const message = assistant(content);

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(0);
    // Untouched so the model can see its own malformed output next turn.
    expect(cleanedContent).toBe(content);
  });

  test("returns no calls for ordinary prose", () => {
    const message = assistant("Here is the answer: the file contains a greeting.");

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(0);
    expect(cleanedContent).toBe("Here is the answer: the file contains a greeting.");
  });

  test("recovers a bare, unfenced JSON tool call as a fallback", () => {
    const message = assistant(
      'Sure: { "tool_call": { "name": "read_file", "arguments": { "path": "c.txt" } } }'
    );

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(1);
    expect(toolCalls[0].name).toBe("read_file");
    expect(toolCalls[0].arguments).toEqual({ path: "c.txt" });
    expect(cleanedContent).toBe("Sure:");
  });

  test("does not treat bare JSON lacking an arguments object as a call", () => {
    // The bare-JSON fallback requires a real arguments object, so a model
    // legitimately answering with JSON is not misread as a tool call.
    const message = assistant('The result is { "name": "read_file" } as requested.');

    const { toolCalls, cleanedContent } = extractPromptedToolCalls(message);

    expect(toolCalls).toHaveLength(0);
    expect(cleanedContent).toBe('The result is { "name": "read_file" } as requested.');
  });
});

