#!/usr/bin/env node
import { Command, Option } from 'commander';
import { loadConfig, type Backend, type CliOverrides, type EmbedProvider } from './config.js';
import { MigrationRunner } from './publisher/migrate.js';
import { publish } from './publisher/publish.js';
import { createEmbedAdapter } from './embed/index.js';
import { wireWriter } from './wiring.js';

const program = new Command();

program
  .name('codeindex')
  .description(
    'Chunk, embed, and publish a repository to PostgreSQL/pgvector for codemcp. ' +
    'The directory being indexed is process.cwd() unless you pass --root <path> ' +
    '(path is resolved relative to cwd when relative).',
  )
  .option(
    '-r, --root <path>',
    'directory to index (default: cwd). Config file defaults to <root>/codeindex.config.json when --config is omitted.',
  )
  .option(
    '-c, --config <path>',
    'path to codeindex.config.json (resolved against cwd; default file is <root>/codeindex.config.json when omitted)',
  )
  .addOption(new Option('-b, --backend <backend>', 'storage backend').choices(['pg', 'file']).default('pg'))
  .option('--branch <branch>', 'branch name recorded on the commit row', 'main')
  .option('--repository <name>', 'override repository id stored on the commit row; when omitted, uses origin URL (owner/repo) if set, else the resolved absolute path of the index root')
  .addOption(new Option('--embed-provider <provider>', 'embedding model provider').choices(['local', 'voyage', 'openai']).default('local'))
  .option('--embed-dim <n>', 'embedding dimensionality (must match the chunks.embedding column for pg backend)', (v) => parseDim(v), 768);

function parseDim(input: string): number {
  const n = Number(input);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n <= 0) {
    throw new Error(`--embed-dim must be a positive integer (got: ${input})`);
  }
  return n;
}

function readOverrides(): CliOverrides {
  const opts = program.opts<{
    config?: string;
    root?: string;
    backend: Backend;
    branch: string;
    repository?: string;
    embedProvider: EmbedProvider;
    embedDim: number;
  }>();
  const overrides: CliOverrides = {
    backend: opts.backend,
    branch: opts.branch,
    embedProvider: opts.embedProvider,
    embedDim: opts.embedDim,
  };
  if (opts.config !== undefined) overrides.configPath = opts.config;
  if (opts.root !== undefined) overrides.rootDir = opts.root;
  if (opts.repository !== undefined) overrides.repository = opts.repository;
  return overrides;
}

function printContext(config: ReturnType<typeof loadConfig>): void {
  process.stdout.write(`root dir:       ${config.rootDir}\n`);
  process.stdout.write(`backend:        ${config.backend}\n`);
  process.stdout.write(`branch:         ${config.branch}\n`);
  process.stdout.write(`repository:     ${config.repository ?? '(auto-detect)'}\n`);
  process.stdout.write(`embed provider: ${config.embedProvider}\n`);
  process.stdout.write(`embed dim:      ${config.embedDim}\n`);
  if (config.backend === 'file') {
    process.stdout.write(`file dir:       ${config.fileDir}\n`);
  }
}

program
  .command('migrate')
  .description('Apply pending SQL migrations (file backend: seed schema_versions journal).')
  .option('--status', 'show applied / pending migrations without applying anything')
  .action(async (opts: { status?: boolean }) => {
    const config = loadConfig(readOverrides());
    const { factory, repo, supportsSql } = wireWriter(config);
    const runner = new MigrationRunner(factory, repo, { executeSql: supportsSql });
    try {
      printContext(config);
      if (opts.status) {
        const status = await runner.status();
        process.stdout.write(`applied:\n`);
        for (const a of status.applied) process.stdout.write(`  ${a.scriptName}\n`);
        process.stdout.write(`pending:\n`);
        for (const p of status.pending) process.stdout.write(`  ${p.name}\n`);
      } else {
        const { appliedNow } = await runner.run();
        if (appliedNow.length === 0) {
          process.stdout.write(`no pending migrations\n`);
        } else {
          process.stdout.write(`applied now:\n`);
          for (const n of appliedNow) process.stdout.write(`  ${n}\n`);
        }
      }
    } finally {
      await factory.end();
    }
  });

program
  .command('publish')
  .description('Run migrations, then chunk + embed + upsert the current commit.')
  .action(async () => {
    const config = loadConfig(readOverrides());
    const { factory, repo, supportsSql } = wireWriter(config);
    const runner = new MigrationRunner(factory, repo, { executeSql: supportsSql });
    try {
      printContext(config);
      await runner.run();
      const embedder = createEmbedAdapter(config.embedProvider, config.embedDim);
      const result = await publish({
        config,
        factory,
        repo,
        embedder,
        log: (m) => process.stdout.write(`[codeindex] ${m}\n`),
      });
      process.stdout.write(JSON.stringify(result, null, 2) + '\n');
    } finally {
      await factory.end();
    }
  });

program
  .command('pack-and-publish')
  .description('Alias for `publish` — both steps are bundled by default.')
  .action(async () => {
    await program.parseAsync([process.argv[0]!, process.argv[1]!, 'publish', ...passThroughGlobals()]);
  });

program
  .command('plan')
  .description('Show what would be indexed (walker output) without touching the backend.')
  .action(async () => {
    const config = loadConfig(readOverrides());
    const { walkRepository } = await import('./indexer/walker.js');
    const files = walkRepository({ rootDir: config.rootDir, excludeGlobs: config.excludeGlobs });
    printContext(config);
    process.stdout.write(`${files.length} files\n`);
    for (const f of files) process.stdout.write(`  ${f.relativePath}\n`);
  });

function passThroughGlobals(): string[] {
  // Used by the pack-and-publish alias so it inherits all top-level flags.
  const opts = program.opts<Record<string, unknown>>();
  const out: string[] = [];
  if (opts.config !== undefined) out.push('--config', String(opts.config));
  if (opts.root !== undefined) out.push('--root', String(opts.root));
  if (opts.backend !== undefined) out.push('--backend', String(opts.backend));
  if (opts.branch !== undefined) out.push('--branch', String(opts.branch));
  if (opts.repository !== undefined) out.push('--repository', String(opts.repository));
  if (opts.embedProvider !== undefined) out.push('--embed-provider', String(opts.embedProvider));
  if (opts.embedDim !== undefined) out.push('--embed-dim', String(opts.embedDim));
  return out;
}

program.parseAsync(process.argv).catch((err: unknown) => {
  const e = err as { message?: string; code?: string };
  const msg = e?.message || e?.code || (typeof err === 'string' ? err : '') || 'unknown error';
  process.stderr.write(`codeindex: ${msg}\n`);
  process.exit(1);
});

import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

export type EmbedProvider = 'local' | 'voyage' | 'openai';
export type Backend = 'pg' | 'file';

/**
 * Effective configuration used at runtime. Three sources, in a strict
 * precedence order — no env-var fallbacks, no implicit autodetection:
 *
 *   - CLI flags (with defaults)  → backend, branch, embedProvider, embedDim
 *   - Config file                → connectionString, excludeGlobs
 *   - `--root <path>` / process.cwd() → rootDir (what to index)
 *
 * File-backend data always lives at `<package-root>/data` — there is no
 * `--file-dir` flag. Keep the file backend simple: write to the folder next
 * to the binary, manually copy to codemcp's `data/` to consume.
 */
export interface CodeIndexConfig {
  backend: Backend;
  branch: string;
  embedProvider: EmbedProvider;
  embedDim: number;
  fileDir: string;
  rootDir: string;
  connectionString: string;
  excludeGlobs: string[];
  /**
   * Optional repository identifier override. When unset, the publisher
   * uses `owner/repo` from `git config --get remote.origin.url` when
   * available, otherwise the resolved absolute path of `rootDir`.
   */
  repository?: string;
}

/** Overrides supplied by the CLI. Anything undefined falls back to the default below. */
export interface CliOverrides {
  configPath?: string;
  /** Absolute path to the tree to index; when omitted, `process.cwd()` is used. */
  rootDir?: string;
  backend?: Backend;
  branch?: string;
  embedProvider?: EmbedProvider;
  embedDim?: number;
  repository?: string;
}

interface ConfigFileShape {
  connectionString?: string;
  excludeGlobs?: string[];
}

/**
 * Path to the package root (the directory that contains `dist/`, `migrations/`,
 * `package.json`). Used as the home for the default file-backend data folder.
 */
export function packageRoot(): string {
  // import.meta.url at runtime points at the compiled file under dist/. From
  // dist/config.js, the package root is one directory up.
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

export function defaultFileDir(): string {
  return resolve(packageRoot(), 'data');
}

export function loadConfig(overrides: CliOverrides = {}): CodeIndexConfig {
  const cwd = process.cwd();
  const rootDir =
    overrides.rootDir !== undefined ? resolve(cwd, overrides.rootDir) : cwd;

  const configFilePath = overrides.configPath
    ? resolve(cwd, overrides.configPath)
    : resolve(rootDir, 'codeindex.config.json');

  let fromFile: ConfigFileShape = {};
  if (existsSync(configFilePath)) {
    const raw = readFileSync(configFilePath, 'utf-8');
    fromFile = JSON.parse(raw) as ConfigFileShape;
  }

  const config: CodeIndexConfig = {
    backend: overrides.backend ?? DEFAULTS.backend,
    branch: overrides.branch ?? DEFAULTS.branch,
    embedProvider: overrides.embedProvider ?? DEFAULTS.embedProvider,
    embedDim: overrides.embedDim ?? DEFAULTS.embedDim,
    fileDir: defaultFileDir(),
    rootDir,
    connectionString: fromFile.connectionString ?? DEFAULTS.connectionString,
    excludeGlobs: fromFile.excludeGlobs ?? DEFAULTS.excludeGlobs,
  };
  if (overrides.repository !== undefined) {
    config.repository = overrides.repository;
  }
  return config;
}

import pg from 'pg';
import type { DbConnection, DbConnectionFactory, QueryResult } from './types.js';

const { Pool } = pg;

type TxState = 'none' | 'open' | 'committed' | 'rolledback';

class PgConnection implements DbConnection {
  private txState: TxState = 'none';
  private released = false;

  constructor(private readonly client: pg.PoolClient) {}

  async query<T = unknown>(sql: string, params?: unknown[]): Promise<QueryResult<T>> {
    if (this.released) throw new Error('DbConnection used after dispose');
    const result = await this.client.query(sql, params as unknown[] | undefined);
    return { rows: result.rows as T[], rowCount: result.rowCount ?? 0 };
  }

  async begin(): Promise<void> {
    if (this.txState === 'open') throw new Error('Transaction already open');
    await this.client.query('BEGIN');
    this.txState = 'open';
  }

  async commit(): Promise<void> {
    if (this.txState !== 'open') throw new Error('No transaction to commit');
    await this.client.query('COMMIT');
    this.txState = 'committed';
  }

  async rollback(): Promise<void> {
    if (this.txState !== 'open') return;
    await this.client.query('ROLLBACK');
    this.txState = 'rolledback';
  }

  async [Symbol.asyncDispose](): Promise<void> {
    if (this.released) return;
    try {
      if (this.txState === 'open') {
        // Fail-safe: an open transaction at dispose means the caller never committed.
        try { await this.client.query('ROLLBACK'); } catch { /* swallow */ }
        this.txState = 'rolledback';
      }
    } finally {
      this.released = true;
      this.client.release();
    }
  }
}

export class PgConnectionFactory implements DbConnectionFactory {
  private readonly pool: pg.Pool;

  constructor(connectionString: string) {
    this.pool = new Pool({ connectionString });
  }

  async getConnection(): Promise<DbConnection> {
    const client = await this.pool.connect();
    return new PgConnection(client);
  }

  async withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T> {
    await using conn = await this.getConnection();
    await conn.begin();
    try {
      const result = await fn(conn);
      await conn.commit();
      return result;
    } catch (err) {
      await conn.rollback();
      throw err;
    }
  }

  async end(): Promise<void> {
    await this.pool.end();
  }
}

import { mkdirSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import type { DbConnection, DbConnectionFactory, QueryResult } from '../types.js';

/**
 * File-backed connection used by the debug/file repository. Satisfies the
 * DbConnection contract so the same repository interfaces and call sites
 * (await using, withTransaction, etc.) work unchanged. SQL execution is
 * unsupported — repositories using this connection do their own file I/O
 * keyed off `connection.baseDir`.
 */
export class FileConnection implements DbConnection {
  private released = false;
  private txOpen = false;

  constructor(readonly baseDir: string) {}

  async query<T = unknown>(_sql: string, _params?: unknown[]): Promise<QueryResult<T>> {
    throw new Error(
      'FileConnection.query() is not supported. The file backend has no SQL ' +
      'engine; repositories must use their own file-based access.',
    );
  }

  async begin(): Promise<void> {
    // File backend is not transactional. begin/commit/rollback are no-ops so
    // higher-level code (withTransaction, migration runner script-per-tx) can
    // run unchanged. If a write fails partway through, the on-disk artifacts
    // may be partially written — for debug usage, re-run the publish.
    if (this.txOpen) throw new Error('Transaction already open');
    this.txOpen = true;
  }

  async commit(): Promise<void> {
    if (!this.txOpen) throw new Error('No transaction to commit');
    this.txOpen = false;
  }

  async rollback(): Promise<void> {
    this.txOpen = false;
  }

  async [Symbol.asyncDispose](): Promise<void> {
    this.released = true;
    this.txOpen = false;
  }

  ensureAlive(): void {
    if (this.released) throw new Error('FileConnection used after dispose');
  }
}

export class FileConnectionFactory implements DbConnectionFactory {
  readonly baseDir: string;

  constructor(baseDir: string) {
    this.baseDir = resolve(baseDir);
    if (!existsSync(this.baseDir)) {
      mkdirSync(this.baseDir, { recursive: true });
    }
  }

  async getConnection(): Promise<DbConnection> {
    return new FileConnection(this.baseDir);
  }

  async withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T> {
    await using conn = await this.getConnection();
    await conn.begin();
    try {
      const result = await fn(conn);
      await conn.commit();
      return result;
    } catch (err) {
      await conn.rollback();
      throw err;
    }
  }

  async end(): Promise<void> {
    // No pool to drain.
  }
}

// File-backed implementation of PgWriterRepository for debugging. Stores
// everything as human-readable JSON / JSONL under `baseDir`:
//
//   <baseDir>/
//     schema_versions.json     [{ scriptName, appliedAt, checksum }]
//     commits/
//       <commitSha>/
//         commit.json          { commitSha, branch, repository, indexedAt, embedModel, ... }
//         chunks.jsonl         one ChunkRow per line
//
// All operations are direct file I/O — no batching, no transactions. The
// connection arg is only used to recover the baseDir.

import {
  mkdirSync,
  readFileSync,
  writeFileSync,
  existsSync,
  rmSync,
  readdirSync,
  appendFileSync,
} from 'node:fs';
import { resolve, join } from 'node:path';

import type { DbConnection } from '../types.js';
import type { AppliedMigration, PgWriterRepository } from '../pgRepository.js';
import type { ChunkRow, CommitRow } from '../../types.js';
import { FileConnection } from './fileConnectionFactory.js';

interface SchemaVersionEntry {
  scriptName: string;
  appliedAt: string;
  checksum: string;
}

interface CommitJson {
  commitSha: string;
  branch: string;
  repository: string;
  indexedAt: string;
  embedModel: string;
  embedDim: number;
  fileCount: number;
  chunkCount: number;
}

export class FileWriterRepositoryImpl implements PgWriterRepository {
  async ensureSchemaVersionsTable(conn: DbConnection): Promise<void> {
    const base = baseOf(conn);
    const path = schemaVersionsPath(base);
    if (!existsSync(path)) {
      writeFileSync(path, '[]\n', 'utf-8');
    }
    ensureCommitsDir(base);
  }

  async getAppliedMigrations(conn: DbConnection): Promise<AppliedMigration[]> {
    const base = baseOf(conn);
    return readSchemaVersions(base).map(e => ({ scriptName: e.scriptName, checksum: e.checksum }));
  }

  async recordMigration(conn: DbConnection, scriptName: string, checksum: string): Promise<void> {
    const base = baseOf(conn);
    const entries = readSchemaVersions(base);
    if (entries.some(e => e.scriptName === scriptName)) return;
    entries.push({ scriptName, appliedAt: new Date().toISOString(), checksum });
    writeFileSync(schemaVersionsPath(base), JSON.stringify(entries, null, 2) + '\n', 'utf-8');
  }

  async acquireAdvisoryLock(_conn: DbConnection, _key: number): Promise<void> {
    // No-op — the file backend is single-process by design.
  }

  async releaseAdvisoryLock(_conn: DbConnection, _key: number): Promise<void> {
    // No-op.
  }

  async upsertCommit(conn: DbConnection, commit: CommitRow): Promise<void> {
    const base = baseOf(conn);
    const dir = commitDir(base, commit.commitSha);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const data: CommitJson = {
      commitSha: commit.commitSha,
      branch: commit.branch,
      repository: commit.repository,
      indexedAt: new Date().toISOString(),
      embedModel: commit.embedModel,
      embedDim: commit.embedDim,
      fileCount: commit.fileCount,
      chunkCount: commit.chunkCount,
    };
    writeFileSync(commitJsonPath(base, commit.commitSha), JSON.stringify(data, null, 2) + '\n', 'utf-8');
  }

  async deleteChunksForCommit(conn: DbConnection, commitSha: string): Promise<void> {
    const base = baseOf(conn);
    const path = chunksJsonlPath(base, commitSha);
    if (existsSync(path)) rmSync(path);
  }

  async insertChunks(conn: DbConnection, commitSha: string, chunks: ChunkRow[]): Promise<void> {
    const base = baseOf(conn);
    const dir = commitDir(base, commitSha);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const path = chunksJsonlPath(base, commitSha);
    // Write in chunks so we don't materialize a giant single string.
    const lines = chunks.map(c => JSON.stringify(c)).join('\n');
    if (lines.length > 0) {
      // Append a trailing newline so concat to existing file stays line-aligned.
      appendFileSync(path, lines + '\n', 'utf-8');
    }
  }

  async getEmbeddingDimension(_conn: DbConnection): Promise<number | null> {
    // No fixed schema in the file backend — accept any dim. publish() will
    // skip the dim-equality check when this returns null.
    return null;
  }
}

function baseOf(conn: DbConnection): string {
  if (!(conn instanceof FileConnection)) {
    throw new Error('FileWriterRepository requires a FileConnection');
  }
  conn.ensureAlive();
  return conn.baseDir;
}

function schemaVersionsPath(base: string): string {
  return resolve(base, 'schema_versions.json');
}

function ensureCommitsDir(base: string): void {
  const dir = resolve(base, 'commits');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
}

function commitDir(base: string, sha: string): string {
  return resolve(base, 'commits', sanitizeSha(sha));
}

function commitJsonPath(base: string, sha: string): string {
  return join(commitDir(base, sha), 'commit.json');
}

function chunksJsonlPath(base: string, sha: string): string {
  return join(commitDir(base, sha), 'chunks.jsonl');
}

function sanitizeSha(sha: string): string {
  // Allow alnum + dash + underscore. Anything else would be a path-traversal risk.
  if (!/^[A-Za-z0-9_\-]+$/.test(sha)) {
    throw new Error(`Invalid commit identifier: ${sha}`);
  }
  return sha;
}

function readSchemaVersions(base: string): SchemaVersionEntry[] {
  const path = schemaVersionsPath(base);
  if (!existsSync(path)) return [];
  const raw = readFileSync(path, 'utf-8');
  if (raw.trim().length === 0) return [];
  return JSON.parse(raw) as SchemaVersionEntry[];
}

export function listCommitShas(base: string): string[] {
  const dir = resolve(base, 'commits');
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .filter(e => e.isDirectory())
    .map(e => e.name);
}

// All SQL for the writer side lives in this file. No other module in
// tools/codeindex/src may contain SQL statements — the migration runner
// (publish/migrate.ts) is the only documented exception, and it streams
// .sql files from disk rather than embedding SQL in TypeScript.

import type { DbConnection } from './types.js';
import type { ChunkRow, CommitRow } from '../types.js';

export interface AppliedMigration {
  scriptName: string;
  checksum: string;
}

export interface PgWriterRepository {
  ensureSchemaVersionsTable(conn: DbConnection): Promise<void>;
  getAppliedMigrations(conn: DbConnection): Promise<AppliedMigration[]>;
  recordMigration(conn: DbConnection, scriptName: string, checksum: string): Promise<void>;

  acquireAdvisoryLock(conn: DbConnection, key: number): Promise<void>;
  releaseAdvisoryLock(conn: DbConnection, key: number): Promise<void>;

  upsertCommit(conn: DbConnection, commit: CommitRow): Promise<void>;
  deleteChunksForCommit(conn: DbConnection, commitSha: string): Promise<void>;
  insertChunks(conn: DbConnection, commitSha: string, chunks: ChunkRow[]): Promise<void>;

  getEmbeddingDimension(conn: DbConnection): Promise<number | null>;
}

export class PgWriterRepositoryImpl implements PgWriterRepository {
  async ensureSchemaVersionsTable(conn: DbConnection): Promise<void> {
    await conn.query(SQL.createSchemaVersions);
  }

  async getAppliedMigrations(conn: DbConnection): Promise<AppliedMigration[]> {
    const result = await conn.query<AppliedMigration>(SQL.selectAppliedMigrations);
    return result.rows;
  }

  async recordMigration(conn: DbConnection, scriptName: string, checksum: string): Promise<void> {
    await conn.query(SQL.insertAppliedMigration, [scriptName, checksum]);
  }

  async acquireAdvisoryLock(conn: DbConnection, key: number): Promise<void> {
    await conn.query(SQL.acquireAdvisoryLock, [key]);
  }

  async releaseAdvisoryLock(conn: DbConnection, key: number): Promise<void> {
    await conn.query(SQL.releaseAdvisoryLock, [key]);
  }

  async upsertCommit(conn: DbConnection, commit: CommitRow): Promise<void> {
    await conn.query(SQL.upsertCommit, [
      commit.commitSha,
      commit.branch,
      commit.repository,
      commit.embedModel,
      commit.embedDim,
      commit.fileCount,
      commit.chunkCount,
    ]);
  }

  async deleteChunksForCommit(conn: DbConnection, commitSha: string): Promise<void> {
    await conn.query(SQL.deleteChunksForCommit, [commitSha]);
  }

  async insertChunks(conn: DbConnection, commitSha: string, chunks: ChunkRow[]): Promise<void> {
    for (const chunk of chunks) {
      await conn.query(SQL.insertChunk, [
        commitSha,
        chunk.path,
        chunk.area,
        chunk.language,
        chunk.kind,
        chunk.symbol,
        chunk.parentSymbol,
        chunk.startLine,
        chunk.endLine,
        chunk.content,
        chunk.contentHash,
        chunk.imports,
        chunk.claudeMd,
        toVectorLiteral(chunk.embedding),
      ]);
    }
  }

  async getEmbeddingDimension(conn: DbConnection): Promise<number | null> {
    const result = await conn.query<{ dim: number }>(SQL.selectEmbeddingDim);
    if (result.rows.length === 0) return null;
    const first = result.rows[0];
    if (!first) return null;
    // pg_attribute.atttypmod stores the vector dimension directly for the
    // pgvector extension (no -4 offset, unlike varchar's typmod).
    return first.dim ?? null;
  }
}

function toVectorLiteral(values: number[]): string {
  return `[${values.join(',')}]`;
}

export interface QueryResult<T = unknown> {
  rows: T[];
  rowCount: number;
}

export interface DbConnection extends AsyncDisposable {
  query<T = unknown>(sql: string, params?: unknown[]): Promise<QueryResult<T>>;
  begin(): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface DbConnectionFactory {
  getConnection(): Promise<DbConnection>;
  withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T>;
  end(): Promise<void>;
}

import type { EmbedProvider } from '../config.js';
import { LocalEmbedAdapter } from './local.js';
import { VoyageEmbedAdapter } from './voyage.js';
import { OpenAIEmbedAdapter } from './openai.js';

export interface EmbedAdapter {
  /** Stable identifier stored on the commit row (e.g. "local:hash-768"). */
  readonly modelId: string;
  /** Output dimensionality — must match the vector(N) column. */
  readonly dim: number;
  embedBatch(texts: string[]): Promise<number[][]>;
}

export function createEmbedAdapter(provider: EmbedProvider, dim: number): EmbedAdapter {
  switch (provider) {
    case 'local':  return new LocalEmbedAdapter(dim);
    case 'voyage': return new VoyageEmbedAdapter(dim);
    case 'openai': return new OpenAIEmbedAdapter(dim);
    default:
      throw new Error(`Unknown embed provider: ${String(provider)}`);
  }
}

/**
 * Local, dependency-free embedding adapter. Uses a deterministic hashed
 * bag-of-tokens projection so the project builds and runs offline with zero
 * external dependencies or model downloads.
 *
 * This is intentionally a *placeholder-grade* embedding: it is reproducible,
 * stable, and dimensionally correct, but retrieval quality is much weaker
 * than a real embedding model. Swap to `voyage` or `openai` (or wire a real
 * local model such as @xenova/transformers' nomic-embed-text) when accuracy
 * matters. The modelId field changes when you change provider so the
 * codemcp server can refuse cross-model queries.
 */
export class LocalEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;

  constructor(dim: number) {
    this.dim = dim;
    this.modelId = `local:hashed-bag-${dim}`;
  }

  async embedBatch(texts: string[]): Promise<number[][]> {
    return texts.map(t => embedOne(t, this.dim));
  }
}

function embedOne(text: string, dim: number): number[] {
  const tokens = tokenize(text);
  const vec = new Array<number>(dim).fill(0);
  for (const tok of tokens) {
    const h1 = hashTo(tok, dim, 0);
    const h2 = hashTo(tok, dim, 1);
    vec[h1] = (vec[h1] ?? 0) + 1;
    vec[h2] = (vec[h2] ?? 0) - 1;
  }
  // L2 normalize for cosine-distance friendliness.
  let norm = 0;
  for (const v of vec) norm += v * v;
  norm = Math.sqrt(norm);
  if (norm === 0) return vec;
  for (let i = 0; i < vec.length; i++) vec[i] = (vec[i] ?? 0) / norm;
  return vec;
}

function tokenize(text: string): string[] {
  // Split on non-word characters; lowercase; drop empties; cap length.
  return text
    .toLowerCase()
    .split(/[^a-z0-9_]+/)
    .filter(t => t.length > 1 && t.length < 64);
}

function hashTo(token: string, dim: number, salt: number): number {
  const h = createHash('sha256').update(`${salt}:${token}`).digest();
  // Use first 4 bytes as an unsigned int.
  const n = (h.readUInt32BE(0) >>> 0) % dim;
  return n;
}

interface OpenAIResponse {
  data: { embedding: number[] }[];
}

export class OpenAIEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  private readonly apiKey: string;
  private readonly modelName: string;

  constructor(dim: number) {
    this.apiKey = process.env.OPENAI_API_KEY ?? '';
    this.modelName = process.env.OPENAI_EMBED_MODEL ?? DEFAULT_MODEL;
    this.dim = dim;
    this.modelId = `openai:${this.modelName}-${dim}`;
  }

  async embedBatch(texts: string[]): Promise<number[][]> {
    if (this.apiKey === '') {
      throw new Error('OPENAI_API_KEY is not set. Set it to use the openai embed provider.');
    }
    const res = await fetch('https://api.openai.com/v1/embeddings', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: this.modelName,
        input: texts,
        dimensions: this.dim,
      }),
    });
    if (!res.ok) {
      const body = await res.text();
      throw new Error(`OpenAI embeddings request failed: ${res.status} ${body}`);
    }
    const json = (await res.json()) as OpenAIResponse;
    return json.data.map(d => d.embedding);
  }
}

interface VoyageResponse {
  data: { embedding: number[] }[];
}

export class VoyageEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  private readonly apiKey: string;
  private readonly modelName: string;

  constructor(dim: number) {
    const apiKey = process.env.VOYAGE_API_KEY ?? '';
    if (apiKey === '') {
      // Don't throw at construction time — the user may only be building.
      // Throw on first call instead.
    }
    this.apiKey = apiKey;
    this.modelName = process.env.VOYAGE_MODEL ?? DEFAULT_MODEL;
    this.dim = dim;
    this.modelId = `voyage:${this.modelName}-${dim}`;
  }

  async embedBatch(texts: string[]): Promise<number[][]> {
    if (this.apiKey === '') {
      throw new Error('VOYAGE_API_KEY is not set. Set it to use the voyage embed provider.');
    }
    const res = await fetch('https://api.voyageai.com/v1/embeddings', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: this.modelName,
        input: texts,
        input_type: 'document',
        output_dimension: this.dim,
      }),
    });
    if (!res.ok) {
      const body = await res.text();
      throw new Error(`Voyage embeddings request failed: ${res.status} ${body}`);
    }
    const json = (await res.json()) as VoyageResponse;
    return json.data.map(d => d.embedding);
  }
}

// Shared helper for pulling leading doc comments into a chunk.
//
// A declaration's "doc" comment is the comment block immediately above it,
// with no blank line separating them. Including it in the chunk means:
//   - the embedder sees the intent ("what this function is for"), not just the body
//   - the assistant can quote the docs alongside the code with line citations
// The chunk's startLine is shifted up to the first comment line; endLine is unchanged.

export type CommentSyntax = 'cstyle' | 'sql';

interface SyntaxRules {
  /** Line-comment prefixes (any match counts). */
  lineStarts: string[];
  blockStart: string;
  blockEnd: string;
}

const C_STYLE: SyntaxRules = {
  lineStarts: ['//'],   // covers `//`, `///`, `////`, etc. — all start with `//`
  blockStart: '/*',     // covers `/*` and `/**`
  blockEnd: '*/',
};

const SQL_STYLE: SyntaxRules = {
  lineStarts: ['--'],
  blockStart: '/*',
  blockEnd: '*/',
};

/**
 * Walks backward from `declStartLine` (1-based) collecting contiguous comment
 * lines. Stops at the first blank line or non-comment line. Returns the new
 * (earlier-or-equal) 1-based start line.
 */
export function expandToLeadingComments(
  lines: string[],
  declStartLine: number,
  syntax: CommentSyntax,
): number {
  const rules = syntax === 'sql' ? SQL_STYLE : C_STYLE;
  let earliest = declStartLine;
  let i = declStartLine - 2; // 0-based index of the line just above the declaration

  while (i >= 0) {
    const trimmed = (lines[i] ?? '').trim();

    if (trimmed.length === 0) break;

    if (rules.lineStarts.some(prefix => trimmed.startsWith(prefix))) {
      earliest = i + 1;
      i--;
      continue;
    }

    if (trimmed.endsWith(rules.blockEnd)) {
      // Walk back further to find the matching block start. Allow it to be
      // on the same line (single-line block comment) or any earlier line.
      let j = i;
      let foundStart = false;
      while (j >= 0) {
        const candidate = lines[j] ?? '';
        if (candidate.includes(rules.blockStart)) {
          earliest = j + 1;
          i = j - 1;
          foundStart = true;
          break;
        }
        j--;
      }
      if (!foundStart) break;
      continue;
    }

    break;
  }

  return earliest;
}

/**
 * Strip leading comment lines from a statement body — used by the SQL
 * chunker so symbol-extraction regexes can match the underlying DDL/DML
 * keyword. The original chunk content is left untouched; only the text
 * passed to the symbol detector is stripped.
 */
export function stripLeadingComments(text: string, syntax: CommentSyntax): string {
  const rules = syntax === 'sql' ? SQL_STYLE : C_STYLE;
  const lines = text.split(/\r?\n/);
  let firstCode = 0;

  while (firstCode < lines.length) {
    const trimmed = (lines[firstCode] ?? '').trim();
    if (trimmed.length === 0) { firstCode++; continue; }
    if (rules.lineStarts.some(p => trimmed.startsWith(p))) { firstCode++; continue; }
    if (trimmed.startsWith(rules.blockStart)) {
      // Skip lines until we close the block.
      while (firstCode < lines.length) {
        const line = lines[firstCode] ?? '';
        firstCode++;
        if (line.includes(rules.blockEnd)) break;
      }
      continue;
    }
    break;
  }

  return lines.slice(firstCode).join('\n');
}

import type { Area, ChunkKind, RawChunk } from '../../types.js';
import { chunkFallback } from './fallback.js';
import { expandToLeadingComments } from './comments.js';
import { fillFileGaps } from './gaps.js';

export interface CSharpInput {
  path: string;
  area: Area;
  content: string;
}

// Heuristic C# chunker. Tree-sitter would be more accurate, but we want a
// dependency-light path that works on Windows without native bindings. The
// goal is to produce *useful* retrievable units, not a perfect parse.
//
// Detected forms:
//   - class / record / struct / interface declarations
//   - method / constructor declarations inside classes
//   - top-level methods (file-scoped)
//
// Anything we can't classify falls through to the windowed fallback so we
// never silently drop content.

interface Decl {
  kind: ChunkKind;
  symbol: string;
  startLine: number;  // 1-based
}

const TYPE_DECL_RE = /^\s*(?:public|private|internal|protected|static|abstract|sealed|partial|\s)*\s*(class|record|struct|interface)\s+([A-Za-z_][A-Za-z0-9_]*)/;
const METHOD_DECL_RE = /^\s*(?:public|private|internal|protected|static|virtual|override|async|sealed|abstract|new|extern|partial|\s)*\s*(?:[A-Za-z_<>?,\[\]\.\s]+?)\s+([A-Za-z_][A-Za-z0-9_]*)\s*\([^;]*\)\s*(?:where[^{;]+)?\s*[{=]/;
const USING_RE = /^\s*using\s+(?:static\s+)?([A-Za-z_][A-Za-z0-9_\.]*)\s*;\s*$/;

export function chunkCSharp(input: CSharpInput): RawChunk[] {
  const lines = input.content.split(/\r?\n/);

  const imports: string[] = [];
  for (const line of lines) {
    const m = USING_RE.exec(line);
    if (m && m[1]) imports.push(m[1]);
  }

  const blocks = extractBraceBlocks(lines);
  if (blocks.length === 0) {
    return chunkFallback({
      path: input.path,
      area: input.area,
      language: 'csharp',
      content: input.content,
    });
  }

  const out: RawChunk[] = [];
  for (const block of blocks) {
    const headerLine = lines[block.startLine - 1] ?? '';
    let decl: Decl | null = null;

    const typeMatch = TYPE_DECL_RE.exec(headerLine);
    if (typeMatch) {
      const kindWord = typeMatch[1]!;
      const symbol = typeMatch[2]!;
      const kind: ChunkKind =
        kindWord === 'class' ? 'class' :
        kindWord === 'record' ? 'record' :
        kindWord === 'interface' ? 'interface' :
        'class';
      decl = { kind, symbol, startLine: block.startLine };
    } else {
      const methodMatch = METHOD_DECL_RE.exec(headerLine);
      if (methodMatch && !/^\s*(?:if|for|foreach|while|switch|using|lock|fixed|try|catch|finally|do)\b/.test(headerLine)) {
        decl = { kind: 'method', symbol: methodMatch[1]!, startLine: block.startLine };
      }
    }

    if (!decl) continue;

    const parentSymbol = findEnclosingType(blocks, block, lines);
    const startLine = expandToLeadingComments(lines, block.startLine, 'cstyle');
    out.push({
      path: input.path,
      area: input.area,
      language: 'csharp',
      kind: decl.kind,
      symbol: decl.symbol,
      parentSymbol,
      startLine,
      endLine: block.endLine,
      content: lines.slice(startLine - 1, block.endLine).join('\n'),
      imports,
    });
  }

  if (out.length === 0) {
    return chunkFallback({
      path: input.path,
      area: input.area,
      language: 'csharp',
      content: input.content,
    });
  }
  return fillFileGaps(out, lines, {
    path: input.path,
    area: input.area,
    language: 'csharp',
    imports,
  });
}

interface BraceBlock {
  startLine: number;  // 1-based, the line containing the declaration header
  bodyStart: number;  // 1-based, line containing '{'
  endLine: number;    // 1-based, line containing the matching '}'
  depth: number;
}

function extractBraceBlocks(lines: string[]): BraceBlock[] {
  // Strip strings and comments cheaply so braces in them don't confuse us.
  const sanitized = lines.map(stripStringsAndComments);

  const blocks: BraceBlock[] = [];
  const open: { headerLine: number; bodyStart: number; depth: number }[] = [];
  let depth = 0;

  for (let i = 0; i < sanitized.length; i++) {
    const line = sanitized[i] ?? '';
    let pendingHeaderLine: number | null = null;

    // A declaration header is a non-blank line preceding the '{' that we
    // attribute the block to. Walk back to find it.
    for (let c = 0; c < line.length; c++) {
      const ch = line[c];
      if (ch === '{') {
        if (pendingHeaderLine === null) {
          pendingHeaderLine = findHeaderLine(sanitized, i);
        }
        open.push({ headerLine: pendingHeaderLine, bodyStart: i + 1, depth });
        depth++;
      } else if (ch === '}') {
        depth = Math.max(0, depth - 1);
        const top = open.pop();
        if (top) {
          blocks.push({
            startLine: top.headerLine,
            bodyStart: top.bodyStart,
            endLine: i + 1,
            depth: top.depth,
          });
        }
      }
    }
  }
  // Sort by start line for deterministic output.
  blocks.sort((a, b) => a.startLine - b.startLine);
  return blocks;
}

function findHeaderLine(sanitized: string[], braceLine: number): number {
  // The header is on this line if it has anything before '{', otherwise walk
  // backwards through blank lines to the first non-blank line.
  const line = sanitized[braceLine] ?? '';
  const idx = line.indexOf('{');
  if (idx > 0 && line.slice(0, idx).trim().length > 0) return braceLine + 1;
  for (let i = braceLine - 1; i >= 0; i--) {
    const candidate = sanitized[i] ?? '';
    if (candidate.trim().length > 0) return i + 1;
  }
  return braceLine + 1;
}

function findEnclosingType(blocks: BraceBlock[], inner: BraceBlock, lines: string[]): string | null {
  // The enclosing type is the smallest type-declaring block strictly containing `inner`.
  const candidates = blocks.filter(b =>
    b !== inner &&
    b.startLine < inner.startLine &&
    b.endLine > inner.endLine,
  );
  candidates.sort((a, b) => (b.startLine - a.startLine));
  for (const c of candidates) {
    const header = lines[c.startLine - 1] ?? '';
    const m = TYPE_DECL_RE.exec(header);
    if (m && m[2]) return m[2];
  }
  return null;
}

function stripStringsAndComments(line: string): string {
  let out = '';
  let i = 0;
  let inString: '"' | "'" | null = null;
  while (i < line.length) {
    const ch = line[i] ?? '';
    if (inString) {
      if (ch === '\\') { out += '  '; i += 2; continue; }
      if (ch === inString) { inString = null; out += ' '; i++; continue; }
      out += ' ';
      i++;
      continue;
    }
    if (ch === '/' && line[i + 1] === '/') {
      return out + ' '.repeat(line.length - i);
    }
    if (ch === '"' || ch === "'") {
      inString = ch;
      out += ' ';
      i++;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

import type { Area, RawChunk } from '../../types.js';

const WINDOW_LINES = 60;
const OVERLAP_LINES = 10;

export interface FallbackInput {
  path: string;
  area: Area;
  language: string;
  content: string;
}

export function chunkFallback(input: FallbackInput): RawChunk[] {
  const lines = input.content.split(/\r?\n/);
  if (lines.length === 0) return [];

  // For very small files, emit a single chunk.
  if (lines.length <= WINDOW_LINES) {
    return [{
      path: input.path,
      area: input.area,
      language: input.language,
      kind: 'file',
      symbol: null,
      parentSymbol: null,
      startLine: 1,
      endLine: lines.length,
      content: input.content,
      imports: [],
    }];
  }

  const chunks: RawChunk[] = [];
  let start = 0;
  while (start < lines.length) {
    const end = Math.min(start + WINDOW_LINES, lines.length);
    const slice = lines.slice(start, end).join('\n');
    chunks.push({
      path: input.path,
      area: input.area,
      language: input.language,
      kind: 'window',
      symbol: null,
      parentSymbol: null,
      startLine: start + 1,
      endLine: end,
      content: slice,
      imports: [],
    });
    if (end >= lines.length) break;
    start = end - OVERLAP_LINES;
  }
  return chunks;
}

// Gap-filler: ensures every line of a file is covered by some chunk.
//
// Symbol-based chunkers (csharp, typescript, proto) only emit chunks for
// declarations they recognize. That leaves file-level glue — imports, top-level
// constants, regex/literal tables, trailing setup code — invisible to the
// index. `get_file_context` then returns "all chunks for this file" but the
// chunks don't actually cover the whole file.
//
// fillFileGaps takes the symbol chunks, computes the line ranges they don't
// cover, and emits a synthetic `module` chunk for each gap whose content is
// not whitespace-only.

import type { Area, RawChunk } from '../../types.js';

export interface GapContext {
  path: string;
  area: Area;
  language: string;
  imports: string[];
}

export function fillFileGaps(
  symbolChunks: RawChunk[],
  lines: string[],
  ctx: GapContext,
): RawChunk[] {
  if (symbolChunks.length === 0) return symbolChunks;

  const sorted = [...symbolChunks].sort((a, b) => a.startLine - b.startLine || a.endLine - b.endLine);
  const out: RawChunk[] = [];
  let cursor = 1;

  for (const chunk of sorted) {
    if (chunk.startLine > cursor) {
      const gap = makeGapChunk(lines, cursor, chunk.startLine - 1, ctx, gapLabel(cursor));
      if (gap) out.push(gap);
    }
    out.push(chunk);
    cursor = Math.max(cursor, chunk.endLine + 1);
  }

  if (cursor <= lines.length) {
    const tail = makeGapChunk(lines, cursor, lines.length, ctx, '(tail)');
    if (tail) out.push(tail);
  }

  // Re-sort so module chunks appear in file order alongside symbol chunks.
  out.sort((a, b) => a.startLine - b.startLine);
  return out;
}

function gapLabel(cursorAtGapStart: number): string {
  return cursorAtGapStart === 1 ? '(preamble)' : '(gap)';
}

function makeGapChunk(
  lines: string[],
  startLine: number,
  endLine: number,
  ctx: GapContext,
  symbol: string,
): RawChunk | null {
  if (startLine > endLine) return null;
  const slice = lines.slice(startLine - 1, endLine);
  if (slice.join('').trim().length === 0) return null;
  return {
    path: ctx.path,
    area: ctx.area,
    language: ctx.language,
    kind: 'module',
    symbol,
    parentSymbol: null,
    startLine,
    endLine,
    content: slice.join('\n'),
    imports: ctx.imports,
  };
}

import { readFileSync } from 'node:fs';
import type { Area, RawChunk } from '../../types.js';
import { chunkMarkdown } from './markdown.js';
import { chunkCSharp } from './csharp.js';
import { chunkTypeScript } from './typescript.js';
import { chunkSql } from './sql.js';
import { chunkProto } from './proto.js';
import { chunkFallback } from './fallback.js';

export interface ChunkFileInput {
  absolutePath: string;
  relativePath: string;   // forward-slash, relative to repo root
  area: Area;
  language: string;
}

export function chunkFile(input: ChunkFileInput): RawChunk[] {
  const content = readFileSync(input.absolutePath, 'utf-8');
  switch (input.language) {
    case 'markdown':
      return chunkMarkdown({ path: input.relativePath, area: input.area, content });
    case 'csharp':
      return chunkCSharp({ path: input.relativePath, area: input.area, content });
    case 'typescript':
    case 'tsx':
    case 'javascript':
    case 'jsx':
      return chunkTypeScript({ path: input.relativePath, area: input.area, language: input.language, content });
    case 'sql':
      return chunkSql({ path: input.relativePath, area: input.area, content });
    case 'protobuf':
      return chunkProto({ path: input.relativePath, area: input.area, content });
    default:
      return chunkFallback({ path: input.relativePath, area: input.area, language: input.language, content });
  }
}

export interface MarkdownInput {
  path: string;
  area: Area;
  content: string;
}

interface HeaderRange {
  level: number;
  title: string;
  startLine: number;   // 1-based
  endLine: number;     // inclusive
}

export function chunkMarkdown(input: MarkdownInput): RawChunk[] {
  const lines = input.content.split(/\r?\n/);
  const headers: { level: number; title: string; line: number }[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? '';
    const m = HEADER_RE.exec(line);
    if (m) {
      headers.push({ level: m[1]!.length, title: m[2]!, line: i + 1 });
    }
  }

  if (headers.length === 0) {
    // No headers — treat the whole file as a single chunk.
    return [{
      path: input.path,
      area: input.area,
      language: 'markdown',
      kind: 'file',
      symbol: null,
      parentSymbol: null,
      startLine: 1,
      endLine: lines.length,
      content: input.content,
      imports: [],
    }];
  }

  const ranges: HeaderRange[] = headers.map((h, i) => {
    const next = headers[i + 1];
    return {
      level: h.level,
      title: h.title,
      startLine: h.line,
      endLine: next ? next.line - 1 : lines.length,
    };
  });

  // Optional preamble before the first header.
  const first = headers[0]!;
  const out: RawChunk[] = [];
  if (first.line > 1) {
    const preamble = lines.slice(0, first.line - 1).join('\n').trim();
    if (preamble.length > 0) {
      out.push({
        path: input.path,
        area: input.area,
        language: 'markdown',
        kind: 'section',
        symbol: '(preamble)',
        parentSymbol: null,
        startLine: 1,
        endLine: first.line - 1,
        content: lines.slice(0, first.line - 1).join('\n'),
        imports: [],
      });
    }
  }

  const titleStack: { level: number; title: string }[] = [];
  for (const range of ranges) {
    while (titleStack.length > 0 && (titleStack[titleStack.length - 1]?.level ?? 0) >= range.level) {
      titleStack.pop();
    }
    const parent = titleStack.length > 0 ? titleStack[titleStack.length - 1]?.title ?? null : null;
    titleStack.push({ level: range.level, title: range.title });

    out.push({
      path: input.path,
      area: input.area,
      language: 'markdown',
      kind: 'section',
      symbol: range.title,
      parentSymbol: parent,
      startLine: range.startLine,
      endLine: range.endLine,
      content: lines.slice(range.startLine - 1, range.endLine).join('\n'),
      imports: [],
    });
  }

  return out;
}

import type { Area, ChunkKind, RawChunk } from '../../types.js';
import { chunkFallback } from './fallback.js';
import { expandToLeadingComments } from './comments.js';
import { fillFileGaps } from './gaps.js';

export interface ProtoInput {
  path: string;
  area: Area;
  content: string;
}

export function chunkProto(input: ProtoInput): RawChunk[] {
  const lines = input.content.split(/\r?\n/);

  const imports: string[] = [];
  for (const line of lines) {
    const m = IMPORT_RE.exec(line);
    if (m && m[1]) imports.push(m[1]);
  }

  const decls: { kind: ChunkKind; symbol: string; startLine: number; endLine: number }[] = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i] ?? '';
    const m = HEADER_RE.exec(line);
    if (m) {
      const word = m[1]!;
      const symbol = m[2]!;
      const kind: ChunkKind =
        word === 'message' ? 'message' :
        word === 'service' ? 'service' :
        word === 'rpc' ? 'rpc' :
        'message';

      // Find matching closing brace.
      const startLine = i + 1;
      let endLine = startLine;
      const braceIdx = line.indexOf('{');
      if (braceIdx === -1) {
        // Single-line rpc declaration or similar.
        endLine = startLine;
      } else {
        let depth = 0;
        let opened = false;
        for (let j = i; j < lines.length; j++) {
          const lj = lines[j] ?? '';
          for (const ch of stripQuotes(lj)) {
            if (ch === '{') { depth++; opened = true; }
            else if (ch === '}') depth--;
          }
          if (opened && depth === 0) { endLine = j + 1; break; }
        }
        if (!opened) endLine = startLine;
      }
      decls.push({ kind, symbol, startLine, endLine });
      i = endLine;
      continue;
    }
    i++;
  }

  if (decls.length === 0) {
    return chunkFallback({
      path: input.path,
      area: input.area,
      language: 'protobuf',
      content: input.content,
    });
  }

  const symbolChunks: RawChunk[] = decls.map(d => {
    const startLine = expandToLeadingComments(lines, d.startLine, 'cstyle');
    return {
      path: input.path,
      area: input.area,
      language: 'protobuf' as const,
      kind: d.kind,
      symbol: d.symbol,
      parentSymbol: null,
      startLine,
      endLine: d.endLine,
      content: lines.slice(startLine - 1, d.endLine).join('\n'),
      imports,
    };
  });

  return fillFileGaps(symbolChunks, lines, {
    path: input.path,
    area: input.area,
    language: 'protobuf',
    imports,
  });
}

function stripQuotes(line: string): string {
  // Remove "..."-delimited strings so braces inside don't confuse depth counting.
  let out = '';
  let inStr = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i] ?? '';
    if (ch === '"') { inStr = !inStr; out += ' '; continue; }
    out += inStr ? ' ' : ch;
  }
  return out;
}

import type { Area, ChunkKind, RawChunk } from '../../types.js';
import { chunkFallback } from './fallback.js';
import { stripLeadingComments } from './comments.js';

export interface SqlInput {
  path: string;
  area: Area;
  content: string;
}

// Split on top-level semicolons (ignoring those inside strings and line
// comments) and pull out the object name from common DDL/DML headers.

const HEADER_RE = /^\s*(CREATE|ALTER|DROP|MERGE|WITH|INSERT|UPDATE|DELETE|SELECT)\b[\s\S]*?(?:(?:TABLE|VIEW|INDEX|FUNCTION|PROCEDURE|TRIGGER|SCHEMA|TYPE|EXTENSION|SEQUENCE)\s+(?:IF\s+NOT\s+EXISTS\s+)?([A-Za-z_][\w\.]*))?/i;

export function chunkSql(input: SqlInput): RawChunk[] {
  const statements = splitStatements(input.content);
  if (statements.length === 0) {
    return chunkFallback({
      path: input.path,
      area: input.area,
      language: 'sql',
      content: input.content,
    });
  }

  return statements.map(stmt => {
    // Leading comments are already part of stmt.text (the splitter accumulates
    // them naturally). Strip them only for symbol extraction so the verb /
    // object name detector matches the underlying DDL keyword.
    const headerMatch = HEADER_RE.exec(stripLeadingComments(stmt.text, 'sql'));
    const symbol = headerMatch?.[2] ?? null;
    const verb = headerMatch?.[1]?.toUpperCase() ?? null;
    const kind: ChunkKind = 'statement';
    return {
      path: input.path,
      area: input.area,
      language: 'sql',
      kind,
      symbol: symbol ?? (verb ? `(${verb})` : null),
      parentSymbol: null,
      startLine: stmt.startLine,
      endLine: stmt.endLine,
      content: stmt.text,
      imports: [],
    };
  });
}

function splitStatements(source: string): Statement[] {
  const out: Statement[] = [];
  const lines = source.split(/\r?\n/);

  let buffer: string[] = [];
  let bufferStartLine = 1;
  let inSingle = false;
  let inDoubleDollar = false;
  let inLineComment = false;
  let inBlockComment = false;

  for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
    const line = lines[lineIdx] ?? '';
    inLineComment = false;
    let i = 0;
    while (i < line.length) {
      const ch = line[i] ?? '';
      const next = line[i + 1] ?? '';
      if (inLineComment) break;
      if (inBlockComment) {
        if (ch === '*' && next === '/') { inBlockComment = false; i += 2; continue; }
        i++; continue;
      }
      if (inSingle) {
        if (ch === "'" && next === "'") { i += 2; continue; }
        if (ch === "'") { inSingle = false; i++; continue; }
        i++; continue;
      }
      if (inDoubleDollar) {
        if (ch === '$' && next === '$') { inDoubleDollar = false; i += 2; continue; }
        i++; continue;
      }
      if (ch === '-' && next === '-') { inLineComment = true; break; }
      if (ch === '/' && next === '*') { inBlockComment = true; i += 2; continue; }
      if (ch === "'") { inSingle = true; i++; continue; }
      if (ch === '$' && next === '$') { inDoubleDollar = true; i += 2; continue; }
      if (ch === ';') {
        buffer.push(line.slice(0, i + 1));
        flush();
        const remainder = line.slice(i + 1);
        if (remainder.length > 0) buffer.push(remainder);
        bufferStartLine = lineIdx + 1;
        i = line.length;
        continue;
      }
      i++;
    }

    // End of line: anything from this line not already pushed becomes buffer.
    if (buffer.length === 0 || buffer[buffer.length - 1] !== line) {
      buffer.push(line);
    }
  }
  if (buffer.join('\n').trim().length > 0) flush();

function flush(): void {
  const text = buffer.join('\n').trim();
  buffer = [];
  if (text.length === 0) return;
  out.push({
    text,
    startLine: bufferStartLine,
    endLine: Math.max(bufferStartLine, bufferStartLine + text.split('\n').length - 1),
  });
}

import type { Area, ChunkKind, RawChunk } from '../../types.js';
import { chunkFallback } from './fallback.js';
import { expandToLeadingComments } from './comments.js';
import { fillFileGaps } from './gaps.js';

export interface TypeScriptInput {
  path: string;
  area: Area;
  language: string;          // 'typescript' | 'tsx' | 'javascript' | 'jsx'
  content: string;
}

// Heuristic TS/JS chunker. Detects exported/top-level functions, classes,
// interfaces, type aliases, and React components. Falls back to the
// windowed chunker if nothing recognizable is found.

const IMPORT_RE = /^\s*import\s+(?:[^'"]+?\s+from\s+)?['"]([^'"]+)['"]\s*;?\s*$/;

interface TopDecl {
  kind: ChunkKind;
  symbol: string;
  startLine: number;
}

const PATTERNS: { re: RegExp; kind: ChunkKind; nameGroup: number }[] = [
  // export class Foo
  { re: /^\s*export\s+(?:default\s+)?(?:abstract\s+)?class\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'class', nameGroup: 1 },
  { re: /^\s*(?:abstract\s+)?class\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'class', nameGroup: 1 },
  // export interface Foo
  { re: /^\s*export\s+interface\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'interface', nameGroup: 1 },
  { re: /^\s*interface\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'interface', nameGroup: 1 },
  // export function foo
  { re: /^\s*export\s+(?:default\s+)?(?:async\s+)?function\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'function', nameGroup: 1 },
  { re: /^\s*(?:async\s+)?function\s+([A-Za-z_$][A-Za-z0-9_$]*)/, kind: 'function', nameGroup: 1 },
  // export const Foo = (...) => ... or = function ...
  { re: /^\s*export\s+(?:default\s+)?(?:const|let|var)\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*(?::[^=]+)?=\s*(?:async\s*)?(?:\([^)]*\)|<[^>]+>\s*\([^)]*\)|[A-Za-z_$][A-Za-z0-9_$]*)\s*=>/, kind: 'function', nameGroup: 1 },
  { re: /^\s*export\s+(?:default\s+)?(?:const|let|var)\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*(?::[^=]+)?=\s*function/, kind: 'function', nameGroup: 1 },
];

export function chunkTypeScript(input: TypeScriptInput): RawChunk[] {
  const lines = input.content.split(/\r?\n/);

  const imports: string[] = [];
  for (const line of lines) {
    const m = IMPORT_RE.exec(line);
    if (m && m[1]) imports.push(m[1]);
  }

  const decls: TopDecl[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? '';
    for (const pattern of PATTERNS) {
      const m = pattern.re.exec(line);
      if (m) {
        const symbol = m[pattern.nameGroup];
        if (symbol) {
          // Component heuristic: capitalized name in .tsx/.jsx = component.
          const isComponent =
            (input.language === 'tsx' || input.language === 'jsx') &&
            /^[A-Z]/.test(symbol) &&
            pattern.kind === 'function';
          decls.push({
            kind: isComponent ? 'component' : pattern.kind,
            symbol,
            startLine: i + 1,
          });
          break;
        }
      }
    }
  }

  if (decls.length === 0) {
    return chunkFallback({
      path: input.path,
      area: input.area,
      language: input.language,
      content: input.content,
    });
  }

  // Determine end lines by walking brace depth from each declaration onward.
  const out: RawChunk[] = [];
  for (let i = 0; i < decls.length; i++) {
    const decl = decls[i]!;
    const nextStart = decls[i + 1]?.startLine ?? lines.length + 1;
    const endLine = findEndLine(lines, decl.startLine, nextStart);
    const startLine = expandToLeadingComments(lines, decl.startLine, 'cstyle');
    out.push({
      path: input.path,
      area: input.area,
      language: input.language,
      kind: decl.kind,
      symbol: decl.symbol,
      parentSymbol: null,
      startLine,
      endLine,
      content: lines.slice(startLine - 1, endLine).join('\n'),
      imports,
    });
  }
  return fillFileGaps(out, lines, {
    path: input.path,
    area: input.area,
    language: input.language,
    imports,
  });
}

function findEndLine(lines: string[], startLine: number, nextStart: number): number {
  // Track brace depth from startLine until depth returns to 0 having been
  // positive at some point. The termination check must happen at end-of-line,
  // not after each closing brace — otherwise patterns like `= {}` (empty
  // default object) on the signature line falsely close the function before
  // the body brace is even seen.
  let depth = 0;
  let opened = false;
  const limit = Math.min(nextStart - 1, lines.length);
  for (let i = startLine - 1; i < limit; i++) {
    const sanitized = stripStringsAndComments(lines[i] ?? '');
    for (const ch of sanitized) {
      if (ch === '{') { depth++; opened = true; }
      else if (ch === '}') { depth = Math.max(0, depth - 1); }
    }
    if (opened && depth === 0) return i + 1;
    // If the declaration ends with a semicolon and we never opened a brace,
    // it's a one-liner (`const foo = () => bar();`) — end at this line.
    if (!opened && sanitized.trimEnd().endsWith(';')) {
      return i + 1;
    }
  }
  return limit;
}

function stripStringsAndComments(line: string): string {
  let out = '';
  let i = 0;
  let inString: '"' | "'" | '`' | null = null;
  while (i < line.length) {
    const ch = line[i] ?? '';
    if (inString) {
      if (ch === '\\') { out += '  '; i += 2; continue; }
      if (ch === inString) { inString = null; out += ' '; i++; continue; }
      out += ' ';
      i++;
      continue;
    }
    if (ch === '/' && line[i + 1] === '/') {
      return out + ' '.repeat(line.length - i);
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      inString = ch as '"' | "'" | '`';
      out += ' ';
      i++;
      continue;
    }
    out += ch;
    i++;
  }
  return out;
}

import { existsSync } from 'node:fs';
import { dirname, join, posix } from 'node:path';
import type { Area } from '../types.js';

export function areaForPath(relPath: string): Area {
  const parts = relPath.split(posix.sep);
  if (parts[0] === 'src') {
    const sub = parts[1];
    if (sub === 'api') return 'api';
    if (sub === 'backend') return 'backend';
    if (sub === 'frontend') return 'frontend';
    if (sub === 'db') return 'db';
    if (sub === 'test') return 'test';
    if (sub === 'codemcp') return 'tools';
    return 'root';
  }
  if (parts[0] === 'tools') return 'tools';
  if (parts[0] === 'pipeline') return 'pipeline';
  if (parts[0] === 'minikube') return 'minikube';
  if (relPath.endsWith('.md')) return 'docs';
  return 'root';
}

export function languageForPath(relPath: string): string {
  const dot = relPath.lastIndexOf('.');
  if (dot < 0) return 'plain';
  const ext = relPath.slice(dot + 1).toLowerCase();
  switch (ext) {
    case 'cs': return 'csharp';
    case 'ts': return 'typescript';
    case 'tsx': return 'tsx';
    case 'js': case 'mjs': case 'cjs': return 'javascript';
    case 'jsx': return 'jsx';
    case 'md': return 'markdown';
    case 'sql': return 'sql';
    case 'proto': return 'protobuf';
    case 'json': return 'json';
    case 'yml': case 'yaml': return 'yaml';
    default: return ext;
  }
}

/**
 * Walk upward from the file's directory collecting every CLAUDE.md and
 * CLAUDE.BASE.md until rootDir. The closest file is most specific; the
 * root-level one is the base contract. The returned list is ordered from
 * most-specific to least-specific.
 */
export function claudeMdLineageForFile(rootDir: string, relPath: string): string[] {
  const out: string[] = [];
  let current = dirname(join(rootDir, relPath));
  const root = rootDir.replace(/[\\/]+$/, '');

  while (current.length >= root.length) {
    for (const name of ['CLAUDE.md', 'CLAUDE.BASE.md']) {
      const candidate = join(current, name);
      if (existsSync(candidate)) {
        const rel = candidate.substring(root.length + 1).split(/[\\/]/).join('/');
        out.push(rel);
      }
    }
    if (current === root) break;
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return out;
}

import { readdirSync, readFileSync, statSync, existsSync } from 'node:fs';
import { resolve, relative, join, sep, posix } from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
// `ignore` is a CommonJS factory; importing it via createRequire avoids the
// NodeNext/ESM interop headaches around `module.exports = factory`.
const ignoreFactory: () => IgnoreLike = require('ignore');

interface IgnoreLike {
  add(patterns: string | string[]): IgnoreLike;
  ignores(path: string): boolean;
}

export interface WalkOptions {
  rootDir: string;
  excludeGlobs?: string[];
}

export interface DiscoveredFile {
  absolutePath: string;
  relativePath: string;   // forward-slash, relative to rootDir
  sizeBytes: number;
}

export function walkRepository(options: WalkOptions): DiscoveredFile[] {
  const rootDir = resolve(options.rootDir);
  const ig = ignoreFactory();

  const gitignorePath = join(rootDir, '.gitignore');
  if (existsSync(gitignorePath)) {
    ig.add(readFileSync(gitignorePath, 'utf-8'));
  }
  if (options.excludeGlobs && options.excludeGlobs.length > 0) {
    ig.add(options.excludeGlobs);
  }
  // Always exclude these regardless of .gitignore presence.
  ig.add(['.git/', 'node_modules/', 'dist/', 'bin/', 'obj/', 'publish/']);

  const out: DiscoveredFile[] = [];
  walk(rootDir, rootDir, ig, out);
  return out;
}

function walk(rootDir: string, current: string, ig: IgnoreLike, out: DiscoveredFile[]): void {
  let entries;
  try {
    entries = readdirSync(current, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const absolute = join(current, entry.name);
    const rel = toPosix(relative(rootDir, absolute));
    const relForMatch = entry.isDirectory() ? `${rel}/` : rel;
    if (ig.ignores(relForMatch)) continue;

    if (entry.isDirectory()) {
      walk(rootDir, absolute, ig, out);
      continue;
    }
    if (!entry.isFile()) continue;

    const ext = extOf(entry.name);
    if (!INDEXABLE_EXTENSIONS.has(ext)) continue;

    let size = 0;
    try { size = statSync(absolute).size; } catch { continue; }
    if (size > MAX_FILE_BYTES) continue;
    if (size === 0) continue;

    out.push({ absolutePath: absolute, relativePath: rel, sizeBytes: size });
  }
}

function toPosix(p: string): string {
  return p.split(sep).join(posix.sep);
}

function extOf(name: string): string {
  const dot = name.lastIndexOf('.');
  if (dot < 0) return '';
  return name.slice(dot).toLowerCase();
}

import { realpathSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { resolve } from 'node:path';

export interface GitContext {
  commitSha: string;
  branch: string;
  isDirty: boolean;
  /**
   * Repository identifier: parsed from `remote.origin.url` when available
   * (`owner/repo`), else a stable id from the resolved filesystem path of
   * `rootDir` (forward slashes). Never blank.
   */
  repository: string;
}

export function readGitContext(rootDir: string, fallbackBranch: string, override?: string): GitContext {
  if (override && override.trim().length > 0) {
    const base = readGitContextNoRepo(rootDir, fallbackBranch);
    return { ...base, repository: override.trim() };
  }
  const base = readGitContextNoRepo(rootDir, fallbackBranch);
  const repository = detectRepositoryName(rootDir) ?? repositoryIdFromResolvedPath(rootDir);
  return { ...base, repository };
}

function readGitContextNoRepo(rootDir: string, fallbackBranch: string): Omit<GitContext, 'repository'> {
  try {
    const commitSha = run('git rev-parse HEAD', rootDir);
    let branch = run('git rev-parse --abbrev-ref HEAD', rootDir);
    if (branch === 'HEAD' || branch === '') branch = fallbackBranch;
    const status = run('git status --porcelain', rootDir);
    const isDirty = status.length > 0;
    return { commitSha, branch, isDirty };
  } catch {
    const synthetic = `nogit-${Date.now().toString(16)}`;
    return { commitSha: synthetic, branch: fallbackBranch, isDirty: false };
  }
}

/**
 * Stable repository key when git `origin` is missing: resolved absolute path
 * with symlinks collapsed, `/` separators (Windows-safe for matching).
 */
export function repositoryIdFromResolvedPath(rootDir: string): string {
  const absolute = resolve(rootDir);
  let canonical: string;
  try {
    canonical = realpathSync(absolute);
  } catch {
    canonical = absolute;
  }
  return canonical.replace(/\\/g, '/');
}

/**
 * Reads `git config --get remote.origin.url` and parses it to `owner/repo`
 * form. Returns null when the repo has no origin remote or git is unavailable;
 * the caller is expected to fall back to {@link repositoryIdFromResolvedPath}.
 */
export function detectRepositoryName(rootDir: string): string | null {
  let url: string;
  try {
    url = run('git config --get remote.origin.url', rootDir);
  } catch {
    return null;
  }
  if (!url) return null;
  return parseRepositoryFromOriginUrl(url);
}

/**
 * Pulls the "owner/repo" tail out of an origin URL. Handles the common Git
 * hosting URL shapes. Exported for unit testing.
 */
export function parseRepositoryFromOriginUrl(url: string): string | null {
  const stripped = url.trim().replace(/\.git$/i, '');
  if (!stripped) return null;

  let pathPart: string;
  if (stripped.includes('://')) {
    const afterScheme = stripped.split('://')[1] ?? '';
    const slashIdx = afterScheme.indexOf('/');
    pathPart = slashIdx >= 0 ? afterScheme.slice(slashIdx + 1) : '';
  } else if (/^[^/]+@[^/]+:/.test(stripped)) {
    pathPart = stripped.split(':').slice(1).join(':');
  } else {
    pathPart = stripped;
  }

  const segments = pathPart.split('/').filter(s => s.length > 0 && s !== '_git');
  if (segments.length === 0) return null;
  if (segments.length === 1) return segments[0] ?? null;
  return segments.slice(-2).join('/');
}

function run(cmd: string, cwd: string): string {
  return execSync(cmd, { cwd, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
}

import { readdirSync, readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

import type { DbConnectionFactory } from '../db/types.js';
import type { AppliedMigration, PgWriterRepository } from '../db/pgRepository.js';

const MIGRATION_LOCK_KEY = 7148291035;

interface Script {
  name: string;
  body: string;
  checksum: string;
}

export interface MigrationStatus {
  applied: AppliedMigration[];
  pending: { name: string; checksum: string }[];
}

export interface MigrationRunnerOptions {
  /** Path to the migrations directory. Defaults to ../../migrations relative to this file. */
  migrationsDir?: string;
  /**
   * When false, the runner records migrations as applied without executing
   * their SQL body. Set to false for non-SQL backends (e.g. the debug file
   * backend) so the schema_versions journal stays in lockstep with what
   * Postgres would have.
   */
  executeSql?: boolean;
}

export class MigrationRunner {
  private readonly migrationsDir: string;
  private readonly executeSql: boolean;

  constructor(
    private readonly factory: DbConnectionFactory,
    private readonly repo: PgWriterRepository,
    options: MigrationRunnerOptions = {},
  ) {
    const thisDir = dirname(fileURLToPath(import.meta.url));
    this.migrationsDir = options.migrationsDir ?? resolve(thisDir, '..', '..', 'migrations');
    this.executeSql = options.executeSql ?? true;
  }

  async status(): Promise<MigrationStatus> {
    await using conn = await this.factory.getConnection();
    await this.repo.ensureSchemaVersionsTable(conn);
    const applied = await this.repo.getAppliedMigrations(conn);
    const appliedSet = new Set(applied.map(a => a.scriptName));
    const scripts = this.loadScripts();
    this.verifyAppliedChecksums(applied, scripts);
    const pending = scripts
      .filter(s => !appliedSet.has(s.name))
      .map(s => ({ name: s.name, checksum: s.checksum }));
    return { applied, pending };
  }

  async run(): Promise<{ appliedNow: string[] }> {
    const scripts = this.loadScripts();

    await using lockConn = await this.factory.getConnection();
    await this.repo.ensureSchemaVersionsTable(lockConn);
    await this.repo.acquireAdvisoryLock(lockConn, MIGRATION_LOCK_KEY);

    const appliedNow: string[] = [];
    try {
      const applied = await this.repo.getAppliedMigrations(lockConn);
      this.verifyAppliedChecksums(applied, scripts);
      const appliedSet = new Set(applied.map(a => a.scriptName));

      for (const script of scripts) {
        if (appliedSet.has(script.name)) continue;
        await this.applyScript(script);
        appliedNow.push(script.name);
      }
    } finally {
      await this.repo.releaseAdvisoryLock(lockConn, MIGRATION_LOCK_KEY);
    }

    return { appliedNow };
  }

  private async applyScript(script: Script): Promise<void> {
    await using conn = await this.factory.getConnection();
    await conn.begin();
    try {
      if (this.executeSql) {
        // The migration runner is the documented exception to the "no SQL in
        // code" rule — by design, it streams arbitrary SQL loaded from .sql
        // files. The journal-table insert is delegated back to the repository.
        await conn.query(script.body);
      }
      await this.repo.recordMigration(conn, script.name, script.checksum);
      await conn.commit();
    } catch (err) {
      await conn.rollback();
      throw new Error(`Migration ${script.name} failed: ${(err as Error).message}`, { cause: err });
    }
  }

  private loadScripts(): Script[] {
    const entries = readdirSync(this.migrationsDir, { withFileTypes: true });
    const sqlFiles = entries
      .filter(e => e.isFile() && e.name.endsWith('.sql'))
      .map(e => e.name)
      .sort((a, b) => a.localeCompare(b));

    return sqlFiles.map(name => {
      const body = readFileSync(resolve(this.migrationsDir, name), 'utf-8');
      const checksum = createHash('sha256').update(body).digest('hex');
      return { name, body, checksum };
    });
  }

  private verifyAppliedChecksums(applied: AppliedMigration[], scripts: Script[]): void {
    const byName = new Map(scripts.map(s => [s.name, s]));
    for (const row of applied) {
      const current = byName.get(row.scriptName);
      if (!current) {
        throw new Error(
          `Migration ${row.scriptName} was applied previously but is no longer present on disk. ` +
          `Forward-only migrations must not be deleted; restore the file or roll forward with a new migration.`,
        );
      }
      if (current.checksum !== row.checksum) {
        throw new Error(
          `Migration ${row.scriptName} has been modified after being applied ` +
          `(checksum mismatch: db=${row.checksum} disk=${current.checksum}). ` +
          `Forward-only migrations are immutable; create a new migration with the changes.`,
        );
      }
    }
  }
}

import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import type { CodeIndexConfig } from '../config.js';
import type { DbConnectionFactory } from '../db/types.js';
import type { PgWriterRepository } from '../db/pgRepository.js';
import type { EmbedAdapter } from '../embed/index.js';
import type { ChunkRow, CommitRow, RawChunk } from '../types.js';
import { walkRepository } from '../indexer/walker.js';
import { chunkFile } from '../indexer/chunkers/index.js';
import { areaForPath, claudeMdLineageForFile, languageForPath } from '../indexer/metadata.js';
import { readGitContext } from './git.js';

const EMBED_BATCH_SIZE = 32;

export interface PublishResult {
  commitSha: string;
  branch: string;
  repository: string;
  fileCount: number;
  chunkCount: number;
  modelId: string;
}

export interface PublishDeps {
  config: CodeIndexConfig;
  factory: DbConnectionFactory;
  repo: PgWriterRepository;
  embedder: EmbedAdapter;
  log?: (msg: string) => void;
}

export async function publish(deps: PublishDeps): Promise<PublishResult> {
  const { config, factory, repo, embedder } = deps;
  const log = deps.log ?? (() => undefined);

  const rootDir = resolve(config.rootDir);
  const git = readGitContext(rootDir, config.branch, config.repository);
  log(`indexing commit ${git.commitSha} (branch ${git.branch}, repository ${git.repository})${git.isDirty ? ' [dirty]' : ''}`);

  const files = walkRepository({ rootDir, excludeGlobs: config.excludeGlobs });
  log(`walked ${files.length} indexable files`);

  // Verify the on-disk schema matches the configured dimension before doing
  // any work.
  await using probeConn = await factory.getConnection();
  const onDiskDim = await repo.getEmbeddingDimension(probeConn);
  if (onDiskDim !== null && onDiskDim !== embedder.dim) {
    throw new Error(
      `Configured embed dim (${embedder.dim}) does not match the chunks.embedding column dim (${onDiskDim}). ` +
      `Either change CODEINDEX_EMBED_DIM or add a forward migration that ALTERs the column.`,
    );
  }

  const rawChunks: RawChunk[] = [];
  for (const file of files) {
    const language = languageForPath(file.relativePath);
    const area = areaForPath(file.relativePath);
    try {
      const fileChunks = chunkFile({
        absolutePath: file.absolutePath,
        relativePath: file.relativePath,
        area,
        language,
      });
      rawChunks.push(...fileChunks);
    } catch (err) {
      log(`WARN  failed to chunk ${file.relativePath}: ${(err as Error).message}`);
    }
  }
  log(`produced ${rawChunks.length} raw chunks`);

  const chunkRows: ChunkRow[] = [];
  for (let i = 0; i < rawChunks.length; i += EMBED_BATCH_SIZE) {
    const batch = rawChunks.slice(i, i + EMBED_BATCH_SIZE);
    const texts = batch.map(b => embedInputFor(b));
    const vectors = await embedder.embedBatch(texts);
    if (vectors.length !== batch.length) {
      throw new Error(`Embed adapter returned ${vectors.length} vectors for ${batch.length} inputs`);
    }
    for (let j = 0; j < batch.length; j++) {
      const raw = batch[j]!;
      const embedding = vectors[j]!;
      if (embedding.length !== embedder.dim) {
        throw new Error(`Embedding has dim ${embedding.length}, expected ${embedder.dim}`);
      }
      chunkRows.push({
        path: raw.path,
        area: raw.area,
        language: raw.language,
        kind: raw.kind,
        symbol: raw.symbol,
        parentSymbol: raw.parentSymbol,
        startLine: raw.startLine,
        endLine: raw.endLine,
        content: raw.content,
        contentHash: sha256(raw.content),
        imports: raw.imports,
        claudeMd: claudeMdLineageForFile(rootDir, raw.path),
        embedding,
      });
    }
    log(`embedded ${Math.min(i + EMBED_BATCH_SIZE, rawChunks.length)}/${rawChunks.length}`);
  }

  const commit: CommitRow = {
    commitSha: git.commitSha,
    branch: git.branch,
    repository: git.repository,
    embedModel: embedder.modelId,
    embedDim: embedder.dim,
    fileCount: files.length,
    chunkCount: chunkRows.length,
  };

  await factory.withTransaction(async (conn) => {
    await repo.deleteChunksForCommit(conn, commit.commitSha);
    await repo.upsertCommit(conn, commit);
    await repo.insertChunks(conn, commit.commitSha, chunkRows);
  });

  log(`published ${chunkRows.length} chunks for ${commit.commitSha} (${commit.repository}) using ${embedder.modelId}`);
  return {
    commitSha: commit.commitSha,
    branch: commit.branch,
    repository: commit.repository,
    fileCount: commit.fileCount,
    chunkCount: commit.chunkCount,
    modelId: embedder.modelId,
  };
}

function embedInputFor(raw: RawChunk): string {
  // Prefix structural context so the embedder gets some semantic anchoring
  // (file path, symbol) along with the raw text.
  const header = [
    `path: ${raw.path}`,
    `lang: ${raw.language}`,
    `kind: ${raw.kind}`,
    raw.symbol ? `symbol: ${raw.symbol}` : null,
    raw.parentSymbol ? `parent: ${raw.parentSymbol}` : null,
  ].filter(Boolean).join('\n');
  return `${header}\n---\n${raw.content}`;
}

function sha256(input: string): string {
  return createHash('sha256').update(input).digest('hex');
}

export interface ChunkRow {
  path: string;
  area: Area;
  language: string;
  kind: ChunkKind;
  symbol: string | null;
  parentSymbol: string | null;
  startLine: number;
  endLine: number;
  content: string;
  contentHash: string;
  imports: string[];
  claudeMd: string[];
  embedding: number[];
}

export interface CommitRow {
  commitSha: string;
  branch: string;
  repository: string;
  indexedAt?: Date;
  embedModel: string;
  embedDim: number;
  fileCount: number;
  chunkCount: number;
}

export interface ChunkResult extends Omit<ChunkRow, 'embedding'> {
  commitSha: string;
  score?: number;
}

export interface SearchFilters {
  area?: Area;
  kind?: ChunkKind;
  language?: string;
}

export interface RawChunk {
  path: string;
  area: Area;
  language: string;
  kind: ChunkKind;
  symbol: string | null;
  parentSymbol: string | null;
  startLine: number;
  endLine: number;
  content: string;
  imports: string[];
}

import type { CodeIndexConfig } from './config.js';
import type { DbConnectionFactory } from './db/types.js';
import type { PgWriterRepository } from './db/pgRepository.js';
import { PgConnectionFactory } from './db/connectionFactory.js';
import { PgWriterRepositoryImpl } from './db/pgRepository.js';
import { FileConnectionFactory } from './db/file/fileConnectionFactory.js';
import { FileWriterRepositoryImpl } from './db/file/fileRepository.js';

export interface WiredWriter {
  factory: DbConnectionFactory;
  repo: PgWriterRepository;
  /**
   * True when the backend supports executing raw SQL (i.e. Postgres). The
   * migration runner uses this to decide whether to apply .sql files or just
   * seed the schema_versions journal.
   */
  supportsSql: boolean;
}

export function wireWriter(config: CodeIndexConfig): WiredWriter {
  if (config.backend === 'file') {
    return {
      factory: new FileConnectionFactory(config.fileDir),
      repo: new FileWriterRepositoryImpl(),
      supportsSql: false,
    };
  }
  return {
    factory: new PgConnectionFactory(config.connectionString),
    repo: new PgWriterRepositoryImpl(),
    supportsSql: true,
  };
}

