import { queuePipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const abandonChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  force: z
    .boolean()
    .optional()
    .default(false)
    .describe(
      'Skip the safety guard that prevents abandoning when a PR already exists. Default: false.',
    ),
  reason: z
    .string()
    .optional()
    .describe('Optional reason for the audit log.'),
};

export interface AbandonChangesInput {
  repository: string;
  force?: boolean;
  reason?: string;
}

export async function abandonChanges(
  input: AbandonChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    return 'No active feature to abandon. State is already clear.';
  }

  const { branchName, branchSlug, featureName, prUrl, envDeployed } = state;
  const slug  = branchSlug ?? slugify(featureName);
  const force = input.force ?? false;
  const repo  = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  if (input.reason) lines.push(`reason:  ${input.reason}`);
  lines.push('');

  // ── Safety guard ──────────────────────────────────────────────────────────
  if (prUrl && !force) {
    lines.push(
      `SAFETY: an open PR exists at ${prUrl}.\n` +
      `Pass force=true to abandon anyway. The PR will remain open in Azure DevOps — abandon it there manually.`,
    );
    return lines.join('\n');
  }

  // ── Tear down deploy environment ──────────────────────────────────────────
  const deletePipelineId = config.azureDevOps.pipelines.deletePipelineId;

  if (envDeployed && deletePipelineId) {
    lines.push(`[pipeline] queue delete-env pipeline #${deletePipelineId}`);
    try {
      const delRun = await queuePipelineRun(
        adoConfig, adoToken, deletePipelineId,
        { branchName, branchSlug: slug, featureName },
      );
      lines.push(`[pipeline] teardown queued: ${delRun.webUrl}`);
    } catch (err) {
      lines.push(`[warn] teardown pipeline failed to queue: ${(err as Error).message}. Continuing cleanup.`);
    }
  } else if (envDeployed && !deletePipelineId) {
    lines.push('[env] no deletePipelineId configured — skipping environment teardown.');
  } else {
    lines.push('[env] environment was not deployed — nothing to tear down.');
  }

  // ── Return to main branch ─────────────────────────────────────────────────
  lines.push(`[git] checkout ${config.mainBranch}`);
  const checkoutResult = await run(`git -C "${repo}" checkout ${config.mainBranch}`);
  if (checkoutResult.exitCode !== 0) {
    lines.push(`[warn] checkout failed: ${checkoutResult.stderr}`);
  }

  // ── Delete local branch ───────────────────────────────────────────────────
  lines.push(`[git] branch -D ${branchName}`);
  const localDelete = await run(`git -C "${repo}" branch -D ${branchName}`);
  if (localDelete.exitCode !== 0) {
    lines.push(`[warn] local delete: ${localDelete.stderr || localDelete.stdout}`);
  }

  // ── Delete remote branch (best-effort; ADO also auto-deletes on PR close) ─
  lines.push(`[git] push origin --delete ${branchName}`);
  const remoteDelete = await run(`git -C "${repo}" push origin --delete ${branchName}`);
  if (remoteDelete.exitCode !== 0) {
    lines.push(
      `[warn] remote branch delete exited ${remoteDelete.exitCode}: ` +
      `${remoteDelete.stderr || remoteDelete.stdout}`,
    );
  }

  // ── Clear state ───────────────────────────────────────────────────────────
  clearState(dataDir(serverDir));

  lines.push('');
  lines.push(`✓ Feature "${featureName}" abandoned. Branch and environment cleaned up.`);
  lines.push('  Call start_feature to begin a new feature.');

  return lines.join('\n');
}

import { z } from 'zod';
import { run } from '../runner.js';
import { readState, patchState, dataDir } from '../state.js';
import { resolveRepository, slugify } from '../config.js';
import {
  createPullRequest,
  queuePipelineRun,
  waitForPipelineRun,
} from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const acceptChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  title: z
    .string()
    .optional()
    .describe('PR title. Defaults to "feat: {branchSlug}" when omitted.'),
  description: z
    .string()
    .optional()
    .describe('PR description. Defaults to a brief generated summary.'),
};

export interface AcceptChangesInput {
  repository: string;
  title?: string;
  description?: string;
}

export async function acceptChanges(
  input: AcceptChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    throw new Error('No active feature. Call start_feature first.');
  }

  const { branchName, branchSlug, featureName } = state;
  const slug = branchSlug ?? slugify(featureName);
  const repo = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName} → ${config.mainBranch}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Ensure latest is pushed ───────────────────────────────────────────────
  lines.push(`[git] push -u origin ${branchName}`);
  const pushResult = await run(`git -C "${repo}" push -u origin ${branchName}`);
  if (pushResult.exitCode !== 0 && !pushResult.stderr.includes('Everything up-to-date')) {
    lines.push(`[warn] push: ${pushResult.stderr || pushResult.stdout}`);
  }

  // ── Tear down deploy environment (fire-and-forget) ────────────────────────
  const deletePipelineId = config.azureDevOps.pipelines.deletePipelineId;
  if (deletePipelineId && state.envDeployed) {
    lines.push(`[pipeline] queue delete-env pipeline #${deletePipelineId}`);
    try {
      const delRun = await queuePipelineRun(
        adoConfig, adoToken, deletePipelineId,
        { branchName, branchSlug: slug, featureName },
      );
      lines.push(`[pipeline] teardown queued: ${delRun.webUrl}`);
      patchState(dataDir(serverDir), { envDeployed: false });
    } catch (err) {
      lines.push(`[warn] teardown pipeline failed to queue: ${(err as Error).message}`);
    }
  }

  // ── Create Pull Request ───────────────────────────────────────────────────
  lines.push('');
  const prTitle = input.title ?? `feat: ${slug}`;
  const prDescription =
    input.description ??
    `Automated PR for feature **${featureName}**.\n\nBranch: \`${branchName}\``;

  try {
    const pr = await createPullRequest(
      adoConfig,
      adoToken,
      {
        title: prTitle,
        description: prDescription,
        sourceBranch: branchName,
        targetBranch: config.mainBranch,
      },
    );

    patchState(dataDir(serverDir), { prId: pr.prId, prUrl: pr.url });

    lines.push(
      pr.alreadyExists
        ? `[pr] existing PR #${pr.prId}: ${pr.url}`
        : `[pr] created PR #${pr.prId}: ${pr.url}`,
    );
  } catch (err) {
    lines.push(`[pr] WARN: could not create PR — ${(err as Error).message}`);
  }

  // ── Queue CI pipeline and wait ────────────────────────────────────────────
  lines.push('');
  const ciPipelineId = config.azureDevOps.pipelines.ciPipelineId;
  const timeoutMs    = (config.azureDevOps.pipelines.ciTimeoutMinutes ?? 15) * 60 * 1_000;

  lines.push(`[pipeline] queue CI pipeline #${ciPipelineId}`);
  const ciRun = await queuePipelineRun(
    adoConfig, adoToken, ciPipelineId,
    { branchName, branchSlug: slug, featureName },
  );
  lines.push(`[pipeline] CI run #${ciRun.id} started — ${ciRun.webUrl}`);
  patchState(dataDir(serverDir), { lastCiRunId: ciRun.id });

  lines.push(`[pipeline] waiting for CI (timeout: ${config.azureDevOps.pipelines.ciTimeoutMinutes ?? 15} min)…`);
  const finalRun = await waitForPipelineRun(
    adoConfig, adoToken, ciPipelineId, ciRun.id,
    15_000,
    timeoutMs,
  );

  // ── Evaluate CI result ────────────────────────────────────────────────────
  lines.push('');

  if (finalRun.state !== 'completed') {
    lines.push(`CI pipeline still running after timeout: ${finalRun.webUrl}`);
    lines.push('Call get_status to check current pipeline state, or open the URL above.');
    return lines.join('\n');
  }

  if (finalRun.result !== 'succeeded') {
    lines.push(`CI FAILED (result: ${finalRun.result})`);
    lines.push(`Pipeline run: ${finalRun.webUrl}`);
    lines.push('');
    lines.push(
      'Action required: open the pipeline URL above to read the failure details. ' +
      'Fix the failing tests or build errors, then call push_changes and accept_changes again.',
    );
    return lines.join('\n');
  }

  // ── All green ─────────────────────────────────────────────────────────────
  lines.push('✓ CI pipeline succeeded.');

  const latestState = readState(dataDir(serverDir));
  if (latestState?.prUrl) {
    lines.push(`✓ PR ready for review: ${latestState.prUrl}`);
  }

  lines.push(
    '  Next: the PR is now ready for the downstream security review gate. ' +
    'Call abandon_changes only if the feature is being scrapped.',
  );

  return lines.join('\n');
}

import { z } from 'zod';
import { run } from '../runner.js';
import { readState, dataDir } from '../state.js';
import { resolveRepository } from '../config.js';
import { getPipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const getStatusShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
};

export interface GetStatusInput {
  repository: string;
}

export async function getStatus(
  input: GetStatusInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  const repo      = config.repositoryPath;
  const lines: string[] = [];

  // ── Workflow state ────────────────────────────────────────────────────────
  if (state) {
    lines.push(`feature:     ${state.featureName}`);
    lines.push(`branch:      ${state.branchName}`);
    lines.push(`slug:        ${state.branchSlug}`);
    lines.push(`env:         ${state.envDeployed ? 'deployed' : 'not deployed'}`);
    if (state.prUrl) lines.push(`pr:          ${state.prUrl}`);
  } else {
    lines.push('workflow:    no active feature');
  }

  lines.push(`target:      ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Git working tree ──────────────────────────────────────────────────────
  const currentBranch = await run(`git -C "${repo}" branch --show-current`);
  lines.push(`git branch:  ${currentBranch.stdout || '(detached HEAD)'}`);

  const gitStatus = await run(`git -C "${repo}" status --short`);
  if (gitStatus.stdout) {
    lines.push(`git status:\n${gitStatus.stdout}`);
  } else {
    lines.push('git status:  clean');
  }

  const lastCommit = await run(
    `git -C "${repo}" log -1 --pretty=format:"%h %s (%cr)" HEAD`,
  );
  if (lastCommit.stdout) {
    lines.push(`last commit: ${lastCommit.stdout}`);
  }

  if (!state) return lines.join('\n');

  // ── Pipeline run status ───────────────────────────────────────────────────
  lines.push('');

  if (state.lastDeployRunId) {
    lines.push(`[deploy pipeline]`);
    try {
      const deployRun = await getPipelineRun(
        adoConfig, adoToken,
        config.azureDevOps.pipelines.deployPipelineId,
        state.lastDeployRunId,
      );
      lines.push(`  run #${deployRun.id}  state: ${deployRun.state}  result: ${deployRun.result}`);
      lines.push(`  ${deployRun.webUrl}`);
    } catch (err) {
      lines.push(`  could not query deploy run: ${(err as Error).message}`);
    }
  }

  if (state.lastCiRunId) {
    lines.push(`[CI pipeline]`);
    try {
      const ciRun = await getPipelineRun(
        adoConfig, adoToken,
        config.azureDevOps.pipelines.ciPipelineId,
        state.lastCiRunId,
      );
      lines.push(`  run #${ciRun.id}  state: ${ciRun.state}  result: ${ciRun.result}`);
      lines.push(`  ${ciRun.webUrl}`);
    } catch (err) {
      lines.push(`  could not query CI run: ${(err as Error).message}`);
    }
  }

  return lines.join('\n');
}

import { z } from 'zod';
import { run, mustRun } from '../runner.js';
import { readState, patchState, dataDir } from '../state.js';
import { resolveRepository, slugify } from '../config.js';
import { queuePipelineRun } from '../azuredevops.js';
import type { ToolDeps } from './registry.js';

export const pushChangesShape = {
  repository: z
    .string()
    .min(1)
    .describe(
      'Repository path key, e.g. "org/Project/_git/RepoName". ' +
      'Looked up in the configured repositories map to resolve the Azure DevOps target.',
    ),
  message: z
    .string()
    .optional()
    .describe('Commit message. Defaults to "wip: {branchSlug}" when omitted.'),
  stageAll: z
    .boolean()
    .optional()
    .default(true)
    .describe('Stage all changes (git add -A) before committing. Default: true.'),
};

export interface PushChangesInput {
  repository: string;
  message?: string;
  stageAll?: boolean;
}

export async function pushChanges(
  input: PushChangesInput,
  deps: ToolDeps,
): Promise<string> {
  const { config, serverDir, adoToken } = deps;
  const adoConfig = resolveRepository(input.repository);
  const state     = readState(dataDir(serverDir));
  if (!state) {
    throw new Error('No active feature. Call start_feature first.');
  }

  const { branchName, branchSlug, featureName } = state;
  const repo  = config.repositoryPath;
  const lines: string[] = [];

  lines.push(`feature: ${featureName}`);
  lines.push(`branch:  ${branchName}`);
  lines.push(`target:  ${adoConfig.organization}/${adoConfig.project}/${adoConfig.repository}`);
  lines.push('');

  // ── Ensure we are on the right branch ────────────────────────────────────
  const currentBranch = await run(`git -C "${repo}" branch --show-current`);
  if (currentBranch.stdout !== branchName) {
    lines.push(`[warn] current branch "${currentBranch.stdout}" ≠ "${branchName}". Switching.`);
    await mustRun(`git -C "${repo}" checkout ${branchName}`);
  }

  // ── Stage ─────────────────────────────────────────────────────────────────
  const stageAll = input.stageAll ?? true;
  if (stageAll) {
    lines.push('[git] add -A');
    await mustRun(`git -C "${repo}" add -A`);
  }

  // ── Commit if there is anything staged ───────────────────────────────────
  const statusResult  = await run(`git -C "${repo}" status --porcelain`);
  const hasChanges    = statusResult.stdout.length > 0;

  if (hasChanges) {
    const message = input.message ?? `wip: ${branchSlug}`;
    lines.push(`[git] commit -m "${message}"`);
    await mustRun(`git -C "${repo}" commit -m "${message.replace(/"/g, '\\"')}"`);
  } else {
    lines.push('[git] nothing to commit — skipping commit step');
  }

  // ── Push ──────────────────────────────────────────────────────────────────
  lines.push(`[git] push -u origin ${branchName}`);
  const pushResult = await mustRun(`git -C "${repo}" push -u origin ${branchName}`);
  if (pushResult.stderr) lines.push(pushResult.stderr);

  // ── Trigger deploy pipeline ───────────────────────────────────────────────
  const pipelineId = config.azureDevOps.pipelines.deployPipelineId;
  lines.push(`[pipeline] queue deploy pipeline #${pipelineId}`);

  const run2 = await queuePipelineRun(
    adoConfig,
    adoToken,
    pipelineId,
    { branchName, branchSlug: branchSlug ?? slugify(featureName), featureName },
  );

  lines.push(`[pipeline] queued run #${run2.id} — ${run2.webUrl}`);

  patchState(dataDir(serverDir), { envDeployed: true, lastDeployRunId: run2.id });

  lines.push('');
  lines.push(
    hasChanges
      ? `✓ Changes committed and pushed to "${branchName}". Deploy pipeline queued.`
      : `✓ Pushed (no new commit). Deploy pipeline queued.`,
  );
  lines.push(`  Deploy: ${run2.webUrl}`);
  lines.push(`  Next: call accept_changes to open a PR and run CI, or push more changes.`);

  return lines.join('\n');
}

