import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { listIndexedRepositoryIds } from './db/file/fileRepository.js';

export type Backend = 'pg' | 'file';
export type EmbedProvider = 'local' | 'voyage' | 'openai';

/**
 * A single repository registered at startup via `--repository name` or `--repository name:localPath`.
 *
 * `name` — owner/repo identifier used in commit.json (e.g. "Platform/Rxo.Platform.Web.Sandbox").
 *
 * **Name-only** (no `:`): if `tools/codeindex/data/schema_versions.json` exists next to this
 * package (sibling `codeindex`), file data is read from **`../codeindex/data`** (shared with
 * `codeindex publish` — no copy step). Otherwise falls back to
 * `{packageRoot}/data/{...name.split('/')}`.
 *
 * **With `localPath`**: data at `{localPath}/.codemcp/data/{...name.split('/')}`.
 *
 * Pass multiple registrations by repeating `--repository`, or one flag with
 * values separated by `;` (see {@link parseRepositoryArgList}).
 */
export interface RepositoryEntry {
  name: string;
  /** When set, index files live under `{localPath}/.codemcp/data/...`. When omitted, under `{packageRoot}/data/...`. */
  localPath?: string;
}

/**
 * Computes the file-backend data directory for a repository entry.
 * Name-only: prefer sibling **`../codeindex/data`** when it already has migrations;
 * else `{packageRoot}/data/{segment0}/...`.
 * With localPath: `{localPath}/.codemcp/data/{segment0}/...`
 * Commit dirs live under `{fileDir}/commits/<sha>/` (nested) or `{fileDir}/<sha>/` (flat).
 */
export function repoFileDir(entry: RepositoryEntry): string {
  const segments = entry.name.split('/').filter(s => s.length > 0);
  const lp = entry.localPath?.trim();
  if (!lp) {
    const codeindexData = join(packageRoot(), '..', 'codeindex', 'data');
    if (existsSync(join(codeindexData, 'schema_versions.json'))) {
      return codeindexData;
    }
    return join(packageRoot(), 'data', ...segments);
  }
  return join(lp, '.codemcp', 'data', ...segments);
}

/**
 * Effective configuration used at runtime. Sources:
 *
 *   - CLI flags (with defaults)  → backend, branch, embedProvider, embedDim,
 *                                  expectedMigration, repositories
 *   - Config file                → connectionString (also overridable via --pg-dsn)
 *
 * Config file is resolved relative to process.cwd() (default
 * ./codemcp.config.json, or whatever --config <path> points at). No
 * environment-variable fallbacks.
 *
 * File-backend data: with `--repository owner/name` only, under `{packageRoot}/data/{name}/`;
 * with `name:localPath`, under `{localPath}/.codemcp/data/{name}/`.
 * Pass `--repository` once per repo (repeatable), or `name:path` entries separated by `;`.
 */
export interface CodeMcpConfig {
  backend: Backend;
  branch: string;
  embedProvider: EmbedProvider;
  embedDim: number;
  /** Legacy single-repo file dir (resolved from packageRoot when no --repository flags given). */
  fileDir: string;
  expectedMigration: string;
  connectionString: string;
  /** Repositories registered at startup (may be empty for backward-compat single-repo mode). */
  repositories: RepositoryEntry[];
}

/** Overrides supplied by the CLI. Anything undefined falls back to the default below. */
export interface CliOverrides {
  configPath?: string;
  backend?: Backend;
  branch?: string;
  embedProvider?: EmbedProvider;
  embedDim?: number;
  pgDsn?: string;
  expectedMigration?: string;
  repositories?: RepositoryEntry[];
}

interface ConfigFileShape {
  connectionString?: string;
}

const DEFAULTS = {
  backend: 'pg' as Backend,
  branch: 'main',
  embedProvider: 'local' as EmbedProvider,
  embedDim: 768,
  expectedMigration: '002_add_repository.sql',
  connectionString: 'postgres://codeindex_user:CHANGE_ME@localhost:5432/codeindex',
};

export function packageRoot(): string {
  return resolve(dirname(fileURLToPath(import.meta.url)), '..');
}

export function defaultFileDir(): string {
  return resolve(packageRoot(), 'data');
}

/**
 * Default on-disk index root for the file backend when no `--repository` flags
 * are given: sibling `tools/codeindex/data` if migrated there, else
 * {@link defaultFileDir}.
 */
export function resolveDefaultFileBackendBaseDir(): string {
  const codeindexData = join(packageRoot(), '..', 'codeindex', 'data');
  if (existsSync(join(codeindexData, 'schema_versions.json'))) {
    return codeindexData;
  }
  return defaultFileDir();
}

/**
 * When `--backend file` and no `--repository` entries were passed, scan the
 * default file index directory for distinct `repository` ids in published
 * commits and treat each as a registered name-only repo (same layout as
 * repeating `--repository` for each id). Explicit CLI registrations always win.
 */
export function discoverFileRepositoriesIfUnset(config: CodeMcpConfig): CodeMcpConfig {
  if (config.backend !== 'file') return config;
  if (config.repositories.length > 0) return config;

  const base = resolveDefaultFileBackendBaseDir();
  if (!existsSync(join(base, 'schema_versions.json'))) {
    return config;
  }

  const ids = listIndexedRepositoryIds(base);
  if (ids.length === 0) return config;

  return {
    ...config,
    repositories: ids.map((name) => ({ name })),
  };
}

/**
 * Parses a single `--repository` value: `owner/repo` (name-only) or `name:localPath`.
 * With a colon, the separator is the FIRST colon after a non-empty name so
 * `owner/name:C:\...` keeps the drive letter in `localPath`.
 */
export function parseRepositoryArg(raw: string): RepositoryEntry {
  const trimmed = raw.trim();
  if (!trimmed) {
    throw new Error('Invalid --repository value: empty string.');
  }
  const idx = trimmed.indexOf(':');
  if (idx === -1) {
    return { name: trimmed };
  }
  const name = trimmed.slice(0, idx).trim();
  const localPath = trimmed.slice(idx + 1).trim();
  if (!name || !localPath) {
    throw new Error(`Invalid --repository value "${raw}": name and localPath must both be non-empty.`);
  }
  const isBareWindowsPath =
    idx === 1 &&
    trimmed.length > 2 &&
    /[A-Za-z]/.test(trimmed.charAt(0)) &&
    (trimmed.charAt(2) === '\\' || trimmed.charAt(2) === '/');
  if (isBareWindowsPath) {
    throw new Error(
      `Invalid --repository value "${raw}". Use "owner/name:${trimmed}" so the path is not parsed as a bare drive letter.`,
    );
  }
  return { name, localPath };
}

/**
 * Parses one or more repository specs from a single `--repository`
 * argument. Multiple entries are separated by **`;`** (spaces cannot be used as
 * separators because `localPath` may contain spaces). Each entry is `owner/name`
 * or `owner/name:localPath`.
 */
export function parseRepositoryArgList(raw: string): RepositoryEntry[] {
  const segments = raw
    .split(';')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
  return segments.map((s) => parseRepositoryArg(s));
}

export function loadConfig(overrides: CliOverrides = {}): CodeMcpConfig {
  const cwd = process.cwd();

  const configFilePath = overrides.configPath
    ? resolve(cwd, overrides.configPath)
    : resolve(cwd, 'codemcp.config.json');

  let fromFile: ConfigFileShape = {};
  if (existsSync(configFilePath)) {
    const raw = readFileSync(configFilePath, 'utf-8');
    fromFile = JSON.parse(raw) as ConfigFileShape;
  }

  return {
    backend: overrides.backend ?? DEFAULTS.backend,
    branch: overrides.branch ?? DEFAULTS.branch,
    embedProvider: overrides.embedProvider ?? DEFAULTS.embedProvider,
    embedDim: overrides.embedDim ?? DEFAULTS.embedDim,
    fileDir: defaultFileDir(),
    expectedMigration: overrides.expectedMigration ?? DEFAULTS.expectedMigration,
    connectionString: overrides.pgDsn ?? fromFile.connectionString ?? DEFAULTS.connectionString,
    repositories: overrides.repositories ?? [],
  };
}

import pg from 'pg';
import type { DbConnection, DbConnectionFactory, QueryResult } from './types.js';

const { Pool } = pg;

type TxState = 'none' | 'open' | 'committed' | 'rolledback';

class PgConnection implements DbConnection {
  private txState: TxState = 'none';
  private released = false;

  constructor(private readonly client: pg.PoolClient) {}

  async query<T = unknown>(sql: string, params?: unknown[]): Promise<QueryResult<T>> {
    if (this.released) throw new Error('DbConnection used after dispose');
    const result = await this.client.query(sql, params as unknown[] | undefined);
    return { rows: result.rows as T[], rowCount: result.rowCount ?? 0 };
  }

  async begin(): Promise<void> {
    if (this.txState === 'open') throw new Error('Transaction already open');
    await this.client.query('BEGIN');
    this.txState = 'open';
  }

  async commit(): Promise<void> {
    if (this.txState !== 'open') throw new Error('No transaction to commit');
    await this.client.query('COMMIT');
    this.txState = 'committed';
  }

  async rollback(): Promise<void> {
    if (this.txState !== 'open') return;
    await this.client.query('ROLLBACK');
    this.txState = 'rolledback';
  }

  async [Symbol.asyncDispose](): Promise<void> {
    if (this.released) return;
    try {
      if (this.txState === 'open') {
        try { await this.client.query('ROLLBACK'); } catch { /* swallow */ }
        this.txState = 'rolledback';
      }
    } finally {
      this.released = true;
      this.client.release();
    }
  }
}

export class PgConnectionFactory implements DbConnectionFactory {
  private readonly pool: pg.Pool;

  constructor(connectionString: string) {
    this.pool = new Pool({ connectionString });
  }

  async getConnection(): Promise<DbConnection> {
    const client = await this.pool.connect();
    return new PgConnection(client);
  }

  async withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T> {
    await using conn = await this.getConnection();
    await conn.begin();
    try {
      const result = await fn(conn);
      await conn.commit();
      return result;
    } catch (err) {
      await conn.rollback();
      throw err;
    }
  }

  async end(): Promise<void> {
    await this.pool.end();
  }
}

/**
 * File-backed connection used by the debug/file reader repository. Mirrors
 * the codeindex writer-side FileConnection — repositories using this access
 * the disk via `connection.baseDir`. SQL execution is unsupported.
 */
export class FileConnection implements DbConnection {
  private released = false;
  private txOpen = false;

  constructor(readonly baseDir: string) {}

  async query<T = unknown>(_sql: string, _params?: unknown[]): Promise<QueryResult<T>> {
    throw new Error(
      'FileConnection.query() is not supported. The file backend has no SQL ' +
      'engine; the reader repository must use file-based access.',
    );
  }

  async begin(): Promise<void> {
    if (this.txOpen) throw new Error('Transaction already open');
    this.txOpen = true;
  }

  async commit(): Promise<void> {
    if (!this.txOpen) throw new Error('No transaction to commit');
    this.txOpen = false;
  }

  async rollback(): Promise<void> {
    this.txOpen = false;
  }

  async [Symbol.asyncDispose](): Promise<void> {
    this.released = true;
    this.txOpen = false;
  }

  ensureAlive(): void {
    if (this.released) throw new Error('FileConnection used after dispose');
  }
}

export class FileConnectionFactory implements DbConnectionFactory {
  readonly baseDir: string;

  constructor(baseDir: string) {
    this.baseDir = resolve(baseDir);
    // Read-only backend: do not mkdir — an empty directory looks like "no migrations"
    // and breaks startup; index data must come from codeindex publish or a manual copy.
  }

  async getConnection(): Promise<DbConnection> {
    return new FileConnection(this.baseDir);
  }

  async withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T> {
    await using conn = await this.getConnection();
    await conn.begin();
    try {
      const result = await fn(conn);
      await conn.commit();
      return result;
    } catch (err) {
      await conn.rollback();
      throw err;
    }
  }

  async end(): Promise<void> {
    // Nothing to clean up.
  }
}

// File-backed implementation of PgReaderRepository for debugging. Reads the
// JSON / JSONL layout written by tools/codeindex's FileWriterRepositoryImpl.
//
// Supported layouts (same schema_versions.json at base):
//
//   (A) Flat — legacy / hand-copied:
//       <baseDir>/<commitSha>/commit.json, chunks.jsonl
//
//   (B) Nested `commits/` — tools/codeindex file backend output:
//       <baseDir>/commits/<commitSha>/commit.json, chunks.jsonl
//
// baseDir is typically: {localPath}/.codemcp/data/{repoOwner}/{repoName}
// (computed by config.repoFileDir() from a RepositoryEntry)

import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';

import type { DbConnection } from '../types.js';
import type { ChunkRow, CommitRow, PgReaderRepository, SearchFilters } from '../pgRepository.js';
import { FileConnection } from './fileConnectionFactory.js';

interface SchemaVersionEntry {
  scriptName: string;
  appliedAt: string;
  checksum: string;
}

interface CommitJson {
  commitSha: string;
  branch: string;
  repository: string;
  indexedAt: string;
  embedModel: string;
  embedDim: number;
  fileCount: number;
  chunkCount: number;
}

interface StoredChunk {
  path: string;
  area: string;
  language: string;
  kind: string;
  symbol: string | null;
  parentSymbol: string | null;
  startLine: number;
  endLine: number;
  content: string;
  contentHash: string;
  imports: string[];
  claudeMd: string[];
  embedding: number[];
}

export class FileReaderRepositoryImpl implements PgReaderRepository {
  async getLatestAppliedMigration(conn: DbConnection): Promise<string | null> {
    const base = baseOf(conn);
    const entries = readSchemaVersions(base);
    if (entries.length === 0) return null;
    entries.sort((a, b) => a.scriptName.localeCompare(b.scriptName));
    return entries[entries.length - 1]!.scriptName;
  }

  async latestCommitFor(
    conn: DbConnection,
    branch: string,
    repository: string | null,
  ): Promise<CommitRow | null> {
    const base = baseOf(conn);
    const commits = readAllCommits(base).filter(c => {
      if (c.branch !== branch) return false;
      if (repository !== null && c.repository !== repository) return false;
      return true;
    });
    commits.sort((a, b) => b.indexedAt.getTime() - a.indexedAt.getTime());
    return commits[0] ?? null;
  }

  async listCommits(
    conn: DbConnection,
    branch: string | null,
    repository: string | null,
    limit: number,
  ): Promise<CommitRow[]> {
    const base = baseOf(conn);
    const filtered = readAllCommits(base).filter(c => {
      if (branch !== null && c.branch !== branch) return false;
      if (repository !== null && c.repository !== repository) return false;
      return true;
    });
    filtered.sort((a, b) => b.indexedAt.getTime() - a.indexedAt.getTime());
    return filtered.slice(0, limit);
  }

  async searchByEmbedding(
    conn: DbConnection,
    commitSha: string,
    embedding: number[],
    k: number,
    filters: SearchFilters,
  ): Promise<ChunkRow[]> {
    const base = baseOf(conn);
    const chunks = readChunksJsonl(base, commitSha);
    const filtered = chunks.filter(c => matchesFilters(c, filters));
    const scored = filtered.map(c => ({
      chunk: c,
      score: cosineDistance(embedding, c.embedding),
    }));
    scored.sort((a, b) => a.score - b.score);
    return scored.slice(0, k).map(s => toChunkRow(s.chunk, commitSha, s.score));
  }

  async findSymbol(conn: DbConnection, commitSha: string, name: string): Promise<ChunkRow[]> {
    const base = baseOf(conn);
    const chunks = readChunksJsonl(base, commitSha);
    return chunks
      .filter(c => c.symbol === name)
      .sort((a, b) => a.path.localeCompare(b.path) || a.startLine - b.startLine)
      .map(c => toChunkRow(c, commitSha));
  }

  async getFileChunks(conn: DbConnection, commitSha: string, path: string): Promise<ChunkRow[]> {
    const base = baseOf(conn);
    const chunks = readChunksJsonl(base, commitSha);
    return chunks
      .filter(c => c.path === path)
      .sort((a, b) => a.startLine - b.startLine)
      .map(c => toChunkRow(c, commitSha));
  }
}

function baseOf(conn: DbConnection): string {
  if (!(conn instanceof FileConnection)) {
    throw new Error('FileReaderRepository requires a FileConnection');
  }
  conn.ensureAlive();
  return conn.baseDir;
}

function readSchemaVersions(base: string): SchemaVersionEntry[] {
  const path = resolve(base, 'schema_versions.json');
  if (!existsSync(path)) return [];
  const raw = readFileSync(path, 'utf-8');
  if (raw.trim().length === 0) return [];
  return JSON.parse(raw) as SchemaVersionEntry[];
}

function commitShaDirsToScan(base: string): string[] {
  const roots: string[] = [base];
  const nested = join(base, 'commits');
  if (existsSync(nested)) roots.push(nested);
  return roots;
}

/**
 * Lists distinct non-empty `repository` values found under `baseDir` (flat or
 * nested `commits/` layout). Used when the file backend starts with no
 * `--repository` flags to auto-register every indexed logical repository.
 */
export function listIndexedRepositoryIds(baseDir: string): string[] {
  const seen = new Set<string>();
  for (const row of readAllCommits(baseDir)) {
    const id = row.repository?.trim();
    if (id && id.length > 0) seen.add(id);
  }
  return [...seen].sort((a, b) => a.localeCompare(b));
}

function readAllCommits(base: string): CommitRow[] {
  if (!existsSync(base)) return [];
  const out: CommitRow[] = [];
  const seen = new Set<string>();
  for (const root of commitShaDirsToScan(base)) {
    for (const entry of readdirSync(root, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (!SHA_DIR_RE.test(entry.name)) continue;
      if (seen.has(entry.name)) continue;
      const commitPath = join(root, entry.name, 'commit.json');
      if (!existsSync(commitPath)) continue;
      try {
        const stored = JSON.parse(readFileSync(commitPath, 'utf-8')) as CommitJson;
        seen.add(entry.name);
        out.push({
          commitSha: stored.commitSha,
          branch: stored.branch,
          repository: stored.repository ?? '',
          indexedAt: new Date(stored.indexedAt),
          embedModel: stored.embedModel,
          embedDim: stored.embedDim,
          fileCount: stored.fileCount,
          chunkCount: stored.chunkCount,
        });
      } catch {
        // Skip malformed commit files rather than blow up search.
      }
    }
  }
  return out;
}

function chunksJsonlPathForCommit(base: string, commitSha: string): string | null {
  if (!SHA_DIR_RE.test(commitSha)) return null;
  const flat = resolve(base, commitSha, 'chunks.jsonl');
  if (existsSync(flat)) return flat;
  const nested = resolve(base, 'commits', commitSha, 'chunks.jsonl');
  if (existsSync(nested)) return nested;
  return null;
}

function readChunksJsonl(base: string, commitSha: string): StoredChunk[] {
  const path = chunksJsonlPathForCommit(base, commitSha);
  if (path === null) return [];
  try { statSync(path); } catch { return []; }
  const raw = readFileSync(path, 'utf-8');
  const out: StoredChunk[] = [];
  for (const line of raw.split(/\r?\n/)) {
    if (line.trim().length === 0) continue;
    try {
      out.push(JSON.parse(line) as StoredChunk);
    } catch {
      // Skip malformed lines.
    }
  }
  return out;
}

function matchesFilters(chunk: StoredChunk, filters: SearchFilters): boolean {
  if (filters.area && chunk.area !== filters.area) return false;
  if (filters.kind && chunk.kind !== filters.kind) return false;
  if (filters.language && chunk.language !== filters.language) return false;
  return true;
}

function cosineDistance(a: number[], b: number[]): number {
  const len = Math.min(a.length, b.length);
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < len; i++) {
    const av = a[i] ?? 0;
    const bv = b[i] ?? 0;
    dot += av * bv;
    na += av * av;
    nb += bv * bv;
  }
  if (na === 0 || nb === 0) return 1;
  return 1 - dot / (Math.sqrt(na) * Math.sqrt(nb));
}

function toChunkRow(chunk: StoredChunk, commitSha: string, score?: number): ChunkRow {
  const row: ChunkRow = {
    commitSha,
    path: chunk.path,
    area: chunk.area,
    language: chunk.language,
    kind: chunk.kind,
    symbol: chunk.symbol,
    parentSymbol: chunk.parentSymbol,
    startLine: chunk.startLine,
    endLine: chunk.endLine,
    content: chunk.content,
    contentHash: chunk.contentHash,
    imports: chunk.imports,
    claudeMd: chunk.claudeMd,
  };
  if (score !== undefined) row.score = score;
  return row;
}

