import type { DbConnection } from './types.js';

export interface CommitRow {
  commitSha: string;
  branch: string;
  repository: string;
  indexedAt: Date;
  embedModel: string;
  embedDim: number;
  fileCount: number;
  chunkCount: number;
}

export interface ChunkRow {
  commitSha: string;
  path: string;
  area: string;
  language: string;
  kind: string;
  symbol: string | null;
  parentSymbol: string | null;
  startLine: number;
  endLine: number;
  content: string;
  contentHash: string;
  imports: string[];
  claudeMd: string[];
  score?: number;
}

export interface SearchFilters {
  area?: string;
  kind?: string;
  language?: string;
}

export interface PgReaderRepository {
  getLatestAppliedMigration(conn: DbConnection): Promise<string | null>;
  /**
   * Latest indexed commit on `branch`, optionally scoped to a repository.
   * `repository === null` means "any repository" — used when the server can't
   * detect a current repo and the caller didn't provide one.
   */
  latestCommitFor(
    conn: DbConnection,
    branch: string,
    repository: string | null,
  ): Promise<CommitRow | null>;
  listCommits(
    conn: DbConnection,
    branch: string | null,
    repository: string | null,
    limit: number,
  ): Promise<CommitRow[]>;
  searchByEmbedding(
    conn: DbConnection,
    commitSha: string,
    embedding: number[],
    k: number,
    filters: SearchFilters,
  ): Promise<ChunkRow[]>;
  findSymbol(conn: DbConnection, commitSha: string, name: string): Promise<ChunkRow[]>;
  getFileChunks(conn: DbConnection, commitSha: string, path: string): Promise<ChunkRow[]>;
}

export class PgReaderRepositoryImpl implements PgReaderRepository {
  async getLatestAppliedMigration(conn: DbConnection): Promise<string | null> {
    try {
      const result = await conn.query<{ script_name: string }>(SQL.latestMigration);
      const first = result.rows[0];
      return first?.script_name ?? null;
    } catch {
      // schema_versions table doesn't exist yet — interpret as "no migrations applied".
      return null;
    }
  }

  async latestCommitFor(
    conn: DbConnection,
    branch: string,
    repository: string | null,
  ): Promise<CommitRow | null> {
    const result = await conn.query<CommitRow>(SQL.latestCommitFor, [branch, repository]);
    return result.rows[0] ?? null;
  }

  async listCommits(
    conn: DbConnection,
    branch: string | null,
    repository: string | null,
    limit: number,
  ): Promise<CommitRow[]> {
    const result = await conn.query<CommitRow>(SQL.listCommits, [branch, repository, limit]);
    return result.rows;
  }

  async searchByEmbedding(
    conn: DbConnection,
    commitSha: string,
    embedding: number[],
    k: number,
    filters: SearchFilters,
  ): Promise<ChunkRow[]> {
    const result = await conn.query<ChunkRow>(SQL.searchByEmbedding, [
      commitSha,
      toVectorLiteral(embedding),
      filters.area ?? null,
      filters.kind ?? null,
      filters.language ?? null,
      k,
    ]);
    return result.rows;
  }

  async findSymbol(conn: DbConnection, commitSha: string, name: string): Promise<ChunkRow[]> {
    const result = await conn.query<ChunkRow>(SQL.findSymbol, [commitSha, name]);
    return result.rows;
  }

  async getFileChunks(conn: DbConnection, commitSha: string, path: string): Promise<ChunkRow[]> {
    const result = await conn.query<ChunkRow>(SQL.getFileChunks, [commitSha, path]);
    return result.rows;
  }
}

function toVectorLiteral(values: number[]): string {
  return `[${values.join(',')}]`;
}

export interface QueryResult<T = unknown> {
  rows: T[];
  rowCount: number;
}

export interface DbConnection extends AsyncDisposable {
  query<T = unknown>(sql: string, params?: unknown[]): Promise<QueryResult<T>>;
  begin(): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface DbConnectionFactory {
  getConnection(): Promise<DbConnection>;
  withTransaction<T>(fn: (conn: DbConnection) => Promise<T>): Promise<T>;
  end(): Promise<void>;
}

export interface EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  embedQuery(text: string): Promise<number[]>;
}

export function createQueryEmbedAdapter(provider: 'local' | 'voyage' | 'openai', dim: number): EmbedAdapter {
  switch (provider) {
    case 'local':  return new LocalQueryEmbedAdapter(dim);
    case 'voyage': return new VoyageQueryEmbedAdapter(dim);
    case 'openai': return new OpenAIQueryEmbedAdapter(dim);
    default:
      throw new Error(`Unknown embed provider: ${String(provider)}`);
  }
}

/**
 * Mirror of the local writer-side embed adapter. MUST stay in lockstep with
 * tools/codeindex/src/embed/local.ts — both produce the same vector for the
 * same text. If you change one, change the other.
 */
class LocalQueryEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  constructor(dim: number) {
    this.dim = dim;
    this.modelId = `local:hashed-bag-${dim}`;
  }
  async embedQuery(text: string): Promise<number[]> {
    return embedHashed(text, this.dim);
  }
}

class VoyageQueryEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  private readonly apiKey: string;
  private readonly modelName: string;
  constructor(dim: number) {
    this.apiKey = process.env.VOYAGE_API_KEY ?? '';
    this.modelName = process.env.VOYAGE_MODEL ?? 'voyage-code-3';
    this.dim = dim;
    this.modelId = `voyage:${this.modelName}-${dim}`;
  }
  async embedQuery(text: string): Promise<number[]> {
    if (this.apiKey === '') throw new Error('VOYAGE_API_KEY is not set');
    const res = await fetch('https://api.voyageai.com/v1/embeddings', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${this.apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: this.modelName,
        input: [text],
        input_type: 'query',
        output_dimension: this.dim,
      }),
    });
    if (!res.ok) throw new Error(`Voyage query failed: ${res.status} ${await res.text()}`);
    const json = (await res.json()) as { data: { embedding: number[] }[] };
    const first = json.data[0];
    if (!first) throw new Error('Voyage returned no embedding');
    return first.embedding;
  }
}

class OpenAIQueryEmbedAdapter implements EmbedAdapter {
  readonly modelId: string;
  readonly dim: number;
  private readonly apiKey: string;
  private readonly modelName: string;
  constructor(dim: number) {
    this.apiKey = process.env.OPENAI_API_KEY ?? '';
    this.modelName = process.env.OPENAI_EMBED_MODEL ?? 'text-embedding-3-small';
    this.dim = dim;
    this.modelId = `openai:${this.modelName}-${dim}`;
  }
  async embedQuery(text: string): Promise<number[]> {
    if (this.apiKey === '') throw new Error('OPENAI_API_KEY is not set');
    const res = await fetch('https://api.openai.com/v1/embeddings', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${this.apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: this.modelName, input: text, dimensions: this.dim }),
    });
    if (!res.ok) throw new Error(`OpenAI query failed: ${res.status} ${await res.text()}`);
    const json = (await res.json()) as { data: { embedding: number[] }[] };
    const first = json.data[0];
    if (!first) throw new Error('OpenAI returned no embedding');
    return first.embedding;
  }
}

function embedHashed(text: string, dim: number): number[] {
  const tokens = text.toLowerCase().split(/[^a-z0-9_]+/).filter(t => t.length > 1 && t.length < 64);
  const vec = new Array<number>(dim).fill(0);
  for (const tok of tokens) {
    const h1 = hashTo(tok, dim, 0);
    const h2 = hashTo(tok, dim, 1);
    vec[h1] = (vec[h1] ?? 0) + 1;
    vec[h2] = (vec[h2] ?? 0) - 1;
  }
  let norm = 0;
  for (const v of vec) norm += v * v;
  norm = Math.sqrt(norm);
  if (norm === 0) return vec;
  for (let i = 0; i < vec.length; i++) vec[i] = (vec[i] ?? 0) / norm;
  return vec;
}

function hashTo(token: string, dim: number, salt: number): number {
  const h = createHash('sha256').update(`${salt}:${token}`).digest();
  return (h.readUInt32BE(0) >>> 0) % dim;
}

// Git-context detection for the reader.
//
// Only the URL parser ({@link parseRepositoryFromOriginUrl}) is duplicated from
// tools/codeindex/src/publisher/git.ts — keep those two implementations in
// lock-step. The entry point here intentionally diverges from the publisher:
// the publisher MUST always come up with a repository name (it has nothing to
// write into commit.json otherwise), so it falls back to basename(rootDir).
// The reader, by contrast, is strict: if we cannot read it from git, we return
// null and force the caller (the agent) to either pass `repository` explicitly
// or ask the user. A wrong default here silently mis-targets every query.

import { execSync } from 'node:child_process';

/**
 * Resolves the repository identifier for `rootDir` in `owner/repo` form by
 * reading `remote.origin.url` and parsing it via
 * {@link parseRepositoryFromOriginUrl}.
 *
 * Returns `null` when git is unavailable, the directory is not a git
 * repository, or the repository has no `origin` remote. Callers MUST treat
 * `null` as "unknown" — never substitute a guess (e.g. `basename(cwd)`),
 * because in practice the launching tool's cwd is rarely the repo root.
 */
export function detectCurrentRepository(rootDir: string): string | null {
  return readOriginRepository(rootDir);
}

function readOriginRepository(rootDir: string): string | null {
  let url: string;
  try {
    url = execSync('git config --get remote.origin.url', {
      cwd: rootDir,
      stdio: ['ignore', 'pipe', 'ignore'],
    }).toString().trim();
  } catch {
    return null;
  }
  if (!url) return null;
  return parseRepositoryFromOriginUrl(url);
}

/**
 * Pulls the "owner/repo" tail out of an origin URL. Handles the common Git
 * hosting URL shapes (HTTPS, SSH, Azure DevOps). Exported for unit testing.
 */
export function parseRepositoryFromOriginUrl(url: string): string | null {
  const stripped = url.trim().replace(/\.git$/i, '');
  if (!stripped) return null;

  let pathPart: string;
  if (stripped.includes('://')) {
    const afterScheme = stripped.split('://')[1] ?? '';
    const slashIdx = afterScheme.indexOf('/');
    pathPart = slashIdx >= 0 ? afterScheme.slice(slashIdx + 1) : '';
  } else if (/^[^/]+@[^/]+:/.test(stripped)) {
    pathPart = stripped.split(':').slice(1).join(':');
  } else {
    pathPart = stripped;
  }

  const segments = pathPart.split('/').filter(s => s.length > 0 && s !== '_git');
  if (segments.length === 0) return null;
  if (segments.length === 1) return segments[0] ?? null;
  return segments.slice(-2).join('/');
}

#!/usr/bin/env node
import { Command, Option } from 'commander';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { CallToolRequestSchema, ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js';

import {
  loadConfig,
  parseRepositoryArgList,
  discoverFileRepositoriesIfUnset,
  resolveDefaultFileBackendBaseDir,
  type Backend,
  type CliOverrides,
  type CodeMcpConfig,
  type EmbedProvider,
  type RepositoryEntry,
} from './config.js';
import { wireReader, wireMultiRepoReaders } from './wiring.js';
import type { PgReaderRepository } from './db/pgRepository.js';
import { createQueryEmbedAdapter } from './embed.js';
import type { DbConnectionFactory } from './db/types.js';
import { TOOLS, findTool, type ToolDeps } from './tools/registry.js';
import { detectCurrentRepository } from './git.js';

async function buildDeps(config: CodeMcpConfig): Promise<{
  factory: DbConnectionFactory;
  repo: PgReaderRepository;
  deps: ToolDeps;
  currentRepository: string | null;
}> {
  const { factory, repo } = wireReader(config);
  const embedder = createQueryEmbedAdapter(config.embedProvider, config.embedDim);

  // Build per-repo readers for the file backend (multi-repo mode).
  const repoReaders = config.backend === 'file' && config.repositories.length > 0
    ? wireMultiRepoReaders(config)
    : new Map<string, { factory: DbConnectionFactory; repo: PgReaderRepository }>();

  // Verify schema for each configured repo (file backend) or the primary backend.
  if (config.backend === 'file' && repoReaders.size > 0) {
    for (const [repoName, reader] of repoReaders) {
      await verifySchema(reader.factory, reader.repo, config.expectedMigration, repoName);
    }
  } else {
    await verifySchema(factory, repo, config.expectedMigration, null);
  }

  // Default repo when a tool call omits `repository`: match cwd git origin to
  // a registered name when possible, else the first registration / discovery order.
  const currentRepository = ((): string | null => {
    if (config.repositories.length === 0) {
      return detectCurrentRepository(process.cwd());
    }
    const registered = new Set(config.repositories.map((r) => r.name));
    const fromGit = detectCurrentRepository(process.cwd());
    if (fromGit !== null && registered.has(fromGit)) return fromGit;
    return config.repositories[0]?.name ?? null;
  })();

  const deps: ToolDeps = {
    factory,
    repo,
    embedder,
    defaultBranch: config.branch,
    currentRepository,
    repoReaders,
  };
  return { factory, repo, deps, currentRepository };
}

async function verifySchema(
  factory: DbConnectionFactory,
  repo: PgReaderRepository,
  expected: string,
  repoLabel: string | null,
): Promise<void> {
  const label = repoLabel ? ` (${repoLabel})` : '';
  await using conn = await factory.getConnection();
  const latest = await repo.getLatestAppliedMigration(conn);
  if (latest === null) {
    const base = 'baseDir' in factory && typeof (factory as { baseDir?: string }).baseDir === 'string'
      ? (factory as { baseDir: string }).baseDir
      : '(unknown)';
    throw new Error(
      `codemcp refuses to start${label}: no migrations have been applied (missing or empty ` +
      `schema_versions.json under ${base}). ` +
      `From the monorepo: \`cd tools/codeindex && npm run migrate:file && npm run publish:file\` ` +
      `(writes tools/codeindex/data/). Name-only \`--repository\` reads that folder automatically when present.`,
    );
  }
  if (latest < expected) {
    throw new Error(
      `codemcp expected migration >= ${expected}, found ${latest}${label}. ` +
      `Run \`codeindex migrate\` to bring the backend up to date.`,
    );
  }
}

async function serve(overrides: CliOverrides): Promise<void> {
  const rawConfig = loadConfig(overrides);
  const config = discoverFileRepositoriesIfUnset(rawConfig);
  if (
    config.backend === 'file' &&
    rawConfig.repositories.length === 0 &&
    config.repositories.length > 0
  ) {
    const names = config.repositories.map((r) => r.name).join(', ');
    process.stderr.write(
      `codemcp: auto-discovered ${config.repositories.length} repository id(s) from the file index ` +
      `(${resolveDefaultFileBackendBaseDir()}): ${names}. ` +
      `Omit \`--repository\` in MCP args when all live in this data tree.\n`,
    );
  }
  const { factory, deps, currentRepository } = await buildDeps(config);

  const repoList = config.repositories.length > 0
    ? config.repositories
      .map((r) => `${r.name}@${r.localPath?.trim() ? r.localPath : '<tools/codemcp/data>'}`)
      .join(', ')
    : '(auto-detect)';

  process.stderr.write(
    `codemcp: serving stdio MCP — backend=${config.backend} ` +
    `branch=${config.branch} repository=${currentRepository ?? '(none detected)'} ` +
    `repositories=${repoList} ` +
    `cwd=${process.cwd()} ` +
    `embed=${config.embedProvider}-${config.embedDim}\n`,
  );
  if (currentRepository === null && config.repositories.length === 0) {
    process.stderr.write(
      `codemcp: WARN no repository auto-detected from cwd — every tool call must pass ` +
      `\`repository\` explicitly. Pass \`--repository owner/name\` or \`--repository name:localPath\` at startup, ` +
      `set \`cwd\` in the MCP launcher config to the repo root, ` +
      `or expect the agent to resolve the repo from chat context per call.\n`,
    );
  }
  if (config.backend === 'file' && config.repositories.length > 1) {
    const names = config.repositories.map((r) => r.name).join(', ');
    process.stderr.write(
      `codemcp: ${config.repositories.length} file-backend repos registered (${names}). ` +
      `Each is searchable: pass tool argument repository="<name>" (see names above). ` +
      `If omitted, search_code / find_symbol / get_file_context use git origin when it matches a name, ` +
      `else the first: "${currentRepository ?? ''}". ` +
      `list_commits with no repository filter aggregates all.\n`,
    );
  }

  const server = new Server(
    { name: 'codemcp', version: '0.1.0' },
    { capabilities: { tools: {} } },
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: TOOLS.map(t => ({
      name: t.name,
      description: t.description,
      inputSchema: t.inputSchema,
    })),
  }));

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const tool = findTool(request.params.name);
    if (!tool) {
      return {
        content: [{ type: 'text' as const, text: `unknown tool: ${request.params.name}` }],
        isError: true,
      };
    }
    try {
      const text = await tool.handler(request.params.arguments ?? {}, deps);
      return { content: [{ type: 'text' as const, text }] };
    } catch (err) {
      return {
        content: [{ type: 'text' as const, text: `${tool.name} failed: ${(err as Error).message}` }],
        isError: true,
      };
    }
  });

  const transport = new StdioServerTransport();
  await server.connect(transport);

  const shutdown = async (): Promise<void> => {
    try { await factory.end(); } catch { /* ignore */ }
    for (const reader of deps.repoReaders.values()) {
      try { await reader.factory.end(); } catch { /* ignore */ }
    }
    process.exit(0);
  };
  process.on('SIGINT', () => { void shutdown(); });
  process.on('SIGTERM', () => { void shutdown(); });
}

async function probe(overrides: CliOverrides, toolName: string, argsJson: string | undefined): Promise<void> {
  const config = discoverFileRepositoriesIfUnset(loadConfig(overrides));
  const tool = findTool(toolName);
  if (!tool) {
    process.stderr.write(`unknown tool: ${toolName}\n`);
    process.stderr.write(`available tools: ${TOOLS.map(t => t.name).join(', ')}\n`);
    process.exit(2);
  }
  let parsedArgs: unknown = {};
  if (argsJson !== undefined && argsJson.length > 0) {
    try {
      parsedArgs = JSON.parse(argsJson);
    } catch (err) {
      throw new Error(`Invalid JSON for tool args: ${(err as Error).message}`);
    }
  }
  const { factory, deps } = await buildDeps(config);
  try {
    const text = await tool.handler(parsedArgs, deps);
    process.stdout.write(text + '\n');
  } finally {
    await factory.end();
    for (const reader of deps.repoReaders.values()) {
      try { await reader.factory.end(); } catch { /* ignore */ }
    }
  }
}

async function listToolsCommand(): Promise<void> {
  for (const t of TOOLS) {
    process.stdout.write(`${t.name}\n  ${t.description}\n`);
    const props = (t.inputSchema as { properties?: Record<string, { type?: string; description?: string }>; required?: string[] });
    const required = new Set(props.required ?? []);
    if (props.properties) {
      for (const [name, schema] of Object.entries(props.properties)) {
        const req = required.has(name) ? ' (required)' : '';
        process.stdout.write(`  - ${name}: ${schema.type ?? 'any'}${req}${schema.description ? ` — ${schema.description}` : ''}\n`);
      }
    }
    process.stdout.write('\n');
  }
}

function parseDim(input: string): number {
  const n = Number(input);
  if (!Number.isFinite(n) || !Number.isInteger(n) || n <= 0) {
    throw new Error(`--embed-dim must be a positive integer (got: ${input})`);
  }
  return n;
}

interface RawOpts {
  config?: string;
  backend: Backend;
  branch: string;
  embedProvider: EmbedProvider;
  embedDim: number;
  pgDsn?: string;
  expectedMigration: string;
  repository: RepositoryEntry[];
}

function readOverrides(): CliOverrides {
  const opts = program.opts<RawOpts>();
  const overrides: CliOverrides = {
    backend: opts.backend,
    branch: opts.branch,
    embedProvider: opts.embedProvider,
    embedDim: opts.embedDim,
    expectedMigration: opts.expectedMigration,
    repositories: opts.repository,
  };
  if (opts.config !== undefined) overrides.configPath = opts.config;
  if (opts.pgDsn !== undefined) overrides.pgDsn = opts.pgDsn;
  return overrides;
}

program
  .command('serve', { isDefault: true })
  .description('Start the stdio MCP server (default).')
  .action(async () => {
    await serve(readOverrides());
  });

program
  .command('probe <tool> [argsJson]')
  .description('Invoke a single tool from the command line and print its result. Bypasses the MCP transport — for local debugging.')
  .action(async (toolName: string, argsJson?: string) => {
    await probe(readOverrides(), toolName, argsJson);
  });

program
  .command('tools')
  .description('List available tools and their input schemas.')
  .action(async () => {
    await listToolsCommand();
  });

program.parseAsync(process.argv).catch((err: unknown) => {
  const e = err as { message?: string; code?: string };
  const msg = e?.message || e?.code || (typeof err === 'string' ? err : '') || 'unknown error';
  process.stderr.write(`codemcp: ${msg}\n`);
  process.exit(1);
});

import { z } from 'zod';
import { formatChunks } from './format.js';
import { resolveCommit, formatResolutionHeader } from './resolution.js';
import { effectiveRepo, pickReader, type ToolDeps } from './registry.js';

export const findSymbolSchema = z.object({
  name: z.string().min(1).describe('Exact symbol name to look up (class, function, component, message, etc.).'),
  repository: z.string().optional().describe('Repository to query (e.g. owner/repo). Defaults to git origin when it matches a registered name, else the first registration. REQUIRED when auto-detection failed — the tool refuses the call rather than guess. Resolve from chat context or ask the user.'),
  commit: z.string().optional().describe('Full commit SHA. When several distinct SHAs are indexed for the same repository and branch, this argument is required — use list_commits or ask the user. If only one SHA exists for that pair, it defaults automatically.'),
});

export type FindSymbolInput = z.infer<typeof findSymbolSchema>;

export async function findSymbol(input: FindSymbolInput, deps: ToolDeps): Promise<string> {
  const { defaultBranch, currentRepository } = deps;
  const repoName = effectiveRepo(input.repository, currentRepository);
  const { factory, repo } = pickReader(deps, repoName);
  await using conn = await factory.getConnection();

  const resolved = await resolveCommit(conn, repo, {
    branch: defaultBranch,
    repositoryInput: input.repository,
    currentRepository,
    commitOverride: input.commit,
  });
  if (resolved.kind === 'missing') return resolved.message;

  const chunks = await repo.findSymbol(conn, resolved.commitSha, input.name);
  return formatResolutionHeader(resolved) + formatChunks(chunks);
}

/**
 * Format a chunk as an LLM-friendly block with line-anchored citation and
 * governing CLAUDE.md files. Designed so an assistant can quote the result
 * without hallucinating line numbers.
 */
export function formatChunk(chunk: ChunkRow): string {
  const symbolPart = chunk.symbol ? ` ${chunk.symbol}` : '';
  const parentPart = chunk.parentSymbol ? ` (in ${chunk.parentSymbol})` : '';
  const scorePart = chunk.score !== undefined ? `  score=${chunk.score.toFixed(4)}` : '';
  const claudePart = chunk.claudeMd.length > 0
    ? `governed by: ${chunk.claudeMd.join(', ')}\n`
    : '';
  return [
    `[${chunk.path}:${chunk.startLine}-${chunk.endLine}] (${chunk.language} ${chunk.kind})${symbolPart}${parentPart}${scorePart}`,
    `commit: ${chunk.commitSha}  area: ${chunk.area}`,
    claudePart + '---',
    chunk.content,
  ].join('\n');
}

export function formatChunks(chunks: ChunkRow[]): string {
  if (chunks.length === 0) return '(no results)';
  return chunks.map(formatChunk).join('\n\n');
}

import { z } from 'zod';
import { formatChunks } from './format.js';
import { resolveCommit, formatResolutionHeader } from './resolution.js';
import { effectiveRepo, pickReader, type ToolDeps } from './registry.js';

export const getFileContextSchema = z.object({
  path: z.string().min(1).describe('Repository-relative file path (forward slashes), e.g. src/frontend/src/pages/Weather/WeatherPage.tsx'),
  repository: z.string().optional().describe('Repository to query (e.g. owner/repo). Defaults to git origin when it matches a registered name, else the first registration. REQUIRED when auto-detection failed — the tool refuses the call rather than guess. Resolve from chat context or ask the user.'),
  commit: z.string().optional().describe('Full commit SHA. When several distinct SHAs are indexed for the same repository and branch, this argument is required — use list_commits or ask the user. If only one SHA exists for that pair, it defaults automatically.'),
});

export type GetFileContextInput = z.infer<typeof getFileContextSchema>;

export async function getFileContext(input: GetFileContextInput, deps: ToolDeps): Promise<string> {
  const { defaultBranch, currentRepository } = deps;
  const repoName = effectiveRepo(input.repository, currentRepository);
  const { factory, repo } = pickReader(deps, repoName);
  await using conn = await factory.getConnection();

  const resolved = await resolveCommit(conn, repo, {
    branch: defaultBranch,
    repositoryInput: input.repository,
    currentRepository,
    commitOverride: input.commit,
  });
  if (resolved.kind === 'missing') return resolved.message;

  const chunks = await repo.getFileChunks(conn, resolved.commitSha, input.path);
  if (chunks.length === 0) {
    return formatResolutionHeader(resolved) + `(no chunks for ${input.path} in commit ${resolved.commitSha})`;
  }
  const claudeMd = chunks[0]?.claudeMd ?? [];
  const governance = claudeMd.length > 0
    ? `Governing CLAUDE.md files for this path:\n  ${claudeMd.join('\n  ')}\n\n`
    : '';
  return formatResolutionHeader(resolved) + governance + formatChunks(chunks);
}

import { z } from 'zod';
import type { DbConnectionFactory } from '../db/types.js';
import type { PgReaderRepository, CommitRow } from '../db/pgRepository.js';
import type { ToolDeps } from './registry.js';

export const listCommitsSchema = z.object({
  branch: z.string().optional().describe('Restrict to a single branch.'),
  repository: z.string().optional().describe(
    'Restrict to one registered repository name (`--repository name:path` name). Omit to aggregate all registered repos (file multi-repo).',
  ),
  limit: z.number().int().min(1).max(100).optional().default(10),
});

export type ListCommitsInput = z.infer<typeof listCommitsSchema>;

async function fetchCommits(
  factory: DbConnectionFactory,
  repo: PgReaderRepository,
  branch: string | null,
  repositoryFilter: string | null,
  limit: number,
): Promise<CommitRow[]> {
  await using conn = await factory.getConnection();
  return repo.listCommits(conn, branch, repositoryFilter, limit);
}

export async function listCommits(input: ListCommitsInput, deps: ToolDeps): Promise<string> {
  const { factory, repo, currentRepository, repoReaders } = deps;
  const repositoryFilter = input.repository?.trim().length ? input.repository.trim() : null;
  const branchFilter = input.branch ?? null;

  let rows: CommitRow[];

  if (repoReaders.size > 0) {
    // Multi-repo file backend: aggregate from each registered repository,
    // optionally filtered by the requested repository name.
    const readers = repositoryFilter !== null
      ? (repoReaders.has(repositoryFilter) ? [[repositoryFilter, repoReaders.get(repositoryFilter)!] as const] : [])
      : [...repoReaders.entries()];

    const allRows: CommitRow[] = [];
    for (const [repoName, reader] of readers) {
      const filterForReader = repositoryFilter ?? repoName;
      const partial = await fetchCommits(reader.factory, reader.repo, branchFilter, filterForReader, input.limit);
      allRows.push(...partial);
    }
    allRows.sort((a, b) => b.indexedAt.getTime() - a.indexedAt.getTime());
    rows = allRows.slice(0, input.limit);
  } else {
    // Single backend (Postgres or single-repo file): use the primary reader.
    await using conn = await factory.getConnection();
    rows = await repo.listCommits(conn, branchFilter, repositoryFilter, input.limit);
  }

  if (rows.length === 0) {
    const scope = [
      branchFilter ? `branch=${branchFilter}` : null,
      repositoryFilter ? `repository=${repositoryFilter}` : null,
    ].filter(Boolean).join(' ');
    return scope.length > 0 ? `(no indexed commits for ${scope})` : '(no indexed commits)';
  }
  const headerLines: string[] = [];
  if (repoReaders.size > 1) {
    headerLines.push(`registered repositories: ${[...repoReaders.keys()].join(', ')}`);
    headerLines.push(`default for search tools (repository omitted): ${currentRepository ?? '(none)'}`);
  } else if (repoReaders.size === 1) {
    const only = [...repoReaders.keys()][0];
    headerLines.push(`registered repository: ${only}`);
  } else if (currentRepository !== null) {
    headerLines.push(`current repository: ${currentRepository}`);
  }
  const header = headerLines.length > 0 ? `${headerLines.join('\n')}\n---\n` : '';
  const body = rows.map(r =>
    `${r.commitSha}  repository=${r.repository || '(none)'}  branch=${r.branch}  ` +
    `indexed_at=${r.indexedAt.toISOString()}  model=${r.embedModel}  ` +
    `files=${r.fileCount}  chunks=${r.chunkCount}`,
  ).join('\n');
  return header + body;
}

import { z } from 'zod';
import type { DbConnectionFactory } from '../db/types.js';
import type { PgReaderRepository } from '../db/pgRepository.js';
import type { EmbedAdapter } from '../embed.js';
import { searchCode, searchCodeSchema } from './search_code.js';
import { findSymbol, findSymbolSchema } from './find_symbol.js';
import { getFileContext, getFileContextSchema } from './get_file_context.js';
import { listCommits, listCommitsSchema } from './list_commits.js';

export interface ToolDeps {
  factory: DbConnectionFactory;
  repo: PgReaderRepository;
  embedder: EmbedAdapter;
  defaultBranch: string;
  /**
   * Repository auto-detected (or taken from the first `--repository` entry /
   * file-index discovery) at server startup. Used as the default repo filter
   * when a tool call omits `repository`. When git `origin` matches a registered
   * name, that name is used instead. `null` means unknown — `resolveCommit`
   * then refuses to silently search "any repository". Never substitute a guess
   * (e.g. basename).
   */
  currentRepository: string | null;
  /**
   * Per-repository readers for the file backend in multi-repo mode.
   * Keyed by repository name (e.g. "Platform/Rxo.Platform.Web.Sandbox") — the
   * `name` from each `--repository name:path` or from file-index discovery.
   * Search tools resolve one repo per call via {@link pickReader}; omitting
   * `repository` uses {@link currentRepository} (git origin when it matches a
   * registered name, else the first registration).
   * Empty for Postgres backend or single-repo legacy file mode.
   */
  repoReaders: Map<string, { factory: DbConnectionFactory; repo: PgReaderRepository }>;
}

/**
 * Returns the effective repository name from a tool call's explicit input
 * and the server's detected default. Mirrors the logic in resolveCommit so
 * callers can pick the right reader before opening a connection.
 */
export function effectiveRepo(
  repositoryInput: string | undefined,
  currentRepository: string | null,
): string | null {
  const explicit = repositoryInput?.trim();
  if (explicit && explicit.length > 0) return explicit;
  return currentRepository;
}

/**
 * Returns the `{factory, repo}` pair that should service a request for the
 * given repository name. Falls back to the primary (Postgres or single-file)
 * reader when the repo is not in `repoReaders`.
 */
export function pickReader(
  deps: ToolDeps,
  repoName: string | null,
): { factory: DbConnectionFactory; repo: PgReaderRepository } {
  if (repoName !== null && deps.repoReaders.has(repoName)) {
    return deps.repoReaders.get(repoName)!;
  }
  return { factory: deps.factory, repo: deps.repo };
}

export interface ToolDef {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  zodSchema: z.ZodTypeAny;
  handler: (input: unknown, deps: ToolDeps) => Promise<string>;
}

export const TOOLS: ToolDef[] = [
  {
    name: 'search_code',
    description: 'Semantic vector search over the indexed repository. Returns ranked code chunks with file path, line range, and governing CLAUDE.md files. Output is prefixed with a `repository: ... branch: ... commit: ...` header so the caller can see which slice of the index was queried. With multiple registered repositories (explicit `--repository` flags or auto-discovered from the file index), pass `repository` to choose which index to query; omitted uses git origin when it matches a registered name, otherwise the first registration. Use this when you need to find code by meaning, not exact symbol.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Natural-language or code-fragment query.' },
        k: { type: 'integer', minimum: 1, maximum: 50, default: 8 },
        area: { type: 'string', enum: ['api', 'backend', 'frontend', 'db', 'test', 'docs', 'tools', 'pipeline', 'minikube', 'root'] },
        kind: { type: 'string', enum: ['class', 'method', 'function', 'component', 'interface', 'record', 'section', 'statement', 'message', 'service', 'rpc', 'file', 'window', 'module'] },
        language: { type: 'string' },
        repository: { type: 'string', description: 'Repository id to query (e.g. owner/repo), matching the indexer / `--repository` name. With several registered repos (CLI or auto-discovered from the file index), pass one of those names to pick that index. If omitted, defaults to git `origin` when it matches a registered name, else the first registration (file) or git-origin detection (otherwise). REQUIRED when auto-detection failed — the tool refuses rather than guess.' },
        commit: { type: 'string', description: 'Specific commit SHA. Defaults to the sole indexed snapshot on `--branch` for this repository when unambiguous. REQUIRED when more than one distinct SHA is indexed for the same repository and branch — use `list_commits` or ask the user, then pass the full SHA.' },
      },
      required: ['query'],
    },
    zodSchema: searchCodeSchema,
    handler: (input, deps) => searchCode(searchCodeSchema.parse(input), deps),
  },
  {
    name: 'find_symbol',
    description: 'Exact-match symbol lookup (class, function, component, message, etc.) across the indexed repository. Faster and more precise than search_code when you know the name. With multiple registered repositories, pass `repository` to select the index. Output is prefixed with a `repository: ... branch: ... commit: ...` header.',
    inputSchema: {
      type: 'object',
      properties: {
        name: { type: 'string', description: 'Exact symbol name.' },
        repository: { type: 'string', description: 'Repository id to query; must match a registered name when several exist (CLI or auto-discovered). Defaults to matching git `origin` when possible, else the first registration. REQUIRED when auto-detection failed.' },
        commit: { type: 'string', description: 'Specific commit SHA. Defaults to the sole indexed snapshot on `--branch` for this repository when unambiguous. REQUIRED when more than one distinct SHA is indexed for the same repository and branch — use `list_commits` or ask the user, then pass the full SHA.' },
      },
      required: ['name'],
    },
    zodSchema: findSymbolSchema,
    handler: (input, deps) => findSymbol(findSymbolSchema.parse(input), deps),
  },
  {
    name: 'get_file_context',
    description: 'Return all chunks for a given file plus the governing CLAUDE.md files. Use this to understand a file before editing it. With multiple registered repositories, pass `repository` to select the index. Output is prefixed with a `repository: ... branch: ... commit: ...` header.',
    inputSchema: {
      type: 'object',
      properties: {
        path: { type: 'string', description: 'Repository-relative path, forward slashes.' },
        repository: { type: 'string', description: 'Repository id to query; must match a registered name when several exist (CLI or auto-discovered). Defaults to matching git `origin` when possible, else the first registration. REQUIRED when auto-detection failed.' },
        commit: { type: 'string', description: 'Specific commit SHA. Defaults to the sole indexed snapshot on `--branch` for this repository when unambiguous. REQUIRED when more than one distinct SHA is indexed for the same repository and branch — use `list_commits` or ask the user, then pass the full SHA.' },
      },
      required: ['path'],
    },
    zodSchema: getFileContextSchema,
    handler: (input, deps) => getFileContext(getFileContextSchema.parse(input), deps),
  },
  {
    name: 'list_commits',
    description: 'Enumerate indexed commit snapshots. With multiple file-backend registrations and no `repository` filter, aggregates across all of them. Use this to discover which repository names and commits are available before calling search_code / find_symbol / get_file_context.',
    inputSchema: {
      type: 'object',
      properties: {
        branch: { type: 'string', description: 'Restrict to a single branch.' },
        repository: { type: 'string', description: 'Restrict to one registered repository name. Omit to include every registered repo when using file multi-repo (explicit or auto-discovered).' },
        limit: { type: 'integer', minimum: 1, maximum: 100, default: 10 },
      },
    },
    zodSchema: listCommitsSchema,
    handler: (input, deps) => listCommits(listCommitsSchema.parse(input), deps),
  },
];

export function findTool(name: string): ToolDef | undefined {
  return TOOLS.find(t => t.name === name);
}

// Shared "what commit am I searching?" resolution for the three search tools.
// Picks the effective repository (explicit input → server-detected current →
// any) and the effective commit SHA (explicit input → latest indexed for the
// branch+repository pair), and renders the header that the tools prepend to
// their output so the caller can see which slice of the index they got.

import type { DbConnection } from '../db/types.js';
import type { PgReaderRepository } from '../db/pgRepository.js';

/** Enough rows to detect multiple SHAs for one repo+branch; not a hard cap on index size. */
const COMMIT_RESOLUTION_ROW_CAP = 500;

export interface ResolveCommitOptions {
  branch: string;
  repositoryInput: string | undefined;
  currentRepository: string | null;
  commitOverride: string | undefined;
}

export type ResolveCommitResult =
  | {
      kind: 'resolved';
      commitSha: string;
      branch: string;
      repository: string | null;
    }
  | {
      kind: 'missing';
      message: string;
    };

/**
 * Resolves to a concrete commit SHA + the labels the tools print in the
 * response header. Returns a `missing` result (with a user-facing message) when
 * no commit matches — callers should return that message verbatim instead of
 * querying chunks against a nonexistent commit.
 *
 * Repository precedence: explicit input > server-detected. If neither is set,
 * we refuse the query — searching "any repository" silently picks whatever
 * happens to be indexed and leads to the agent reasoning about the wrong code.
 * The returned message tells the caller exactly how to recover (pass
 * `repository`, or call `list_commits` to see what's available).
 *
 * When several distinct commit SHAs are indexed for the same repository **and**
 * git branch, omitting \`commit\` is ambiguous — the tool refuses until the
 * caller passes an explicit full SHA (from \`list_commits\` or the user).
 * Detection uses up to {@link COMMIT_RESOLUTION_ROW_CAP} newest rows per query.
 */
export async function resolveCommit(
  conn: DbConnection,
  repo: PgReaderRepository,
  opts: ResolveCommitOptions,
): Promise<ResolveCommitResult> {
  const explicit = opts.repositoryInput?.trim();
  const repository = explicit && explicit.length > 0 ? explicit : opts.currentRepository;

  if (repository === null) {
    return {
      kind: 'missing',
      message:
        `(repository not specified and could not be auto-detected from the server's cwd. ` +
        `Pass \`repository\` explicitly — e.g. resolve it from the workspace's git origin, ` +
        `or call \`list_commits\` to see what is indexed, or ask the user which repo they mean. ` +
        `Do NOT retry without \`repository\` — the answer will not change.)`,
    };
  }

  if (opts.commitOverride) {
    return {
      kind: 'resolved',
      commitSha: opts.commitOverride,
      branch: opts.branch,
      repository,
    };
  }

  const ambiguousMessage = (
    repoLabel: string,
    branchLabel: string,
    shas: string[],
  ): string => {
    const preview = shas.slice(0, 8).map((s) => s.slice(0, 12)).join(', ');
    const more = shas.length > 8 ? ` (+${shas.length - 8} more)` : '';
    return (
      `(Multiple indexed commit SHAs exist for repository=${repoLabel} branch=${branchLabel}. ` +
      `Pass the tool argument \`commit\` with the full SHA for the snapshot you need ` +
      `(see \`list_commits\` with the same \`repository\` filter, or ask the user). ` +
      `Indexed candidates include: ${preview}${more}. ` +
      `Do NOT retry without \`commit\` — picking "latest" would hide which revision is queried.)`
    );
  };

  const onDefaultBranch = await repo.listCommits(
    conn,
    opts.branch,
    repository,
    COMMIT_RESOLUTION_ROW_CAP,
  );
  const distinctOnDefault = new Set(onDefaultBranch.map((r) => r.commitSha));
  if (distinctOnDefault.size > 1) {
    return {
      kind: 'missing',
      message: ambiguousMessage(repository, opts.branch, [...distinctOnDefault].sort()),
    };
  }
  if (onDefaultBranch.length > 0) {
    const latest = onDefaultBranch[0]!;
    return {
      kind: 'resolved',
      commitSha: latest.commitSha,
      branch: latest.branch,
      repository: latest.repository.length > 0 ? latest.repository : repository,
    };
  }

  // `--branch` is a single global default; indexed snapshots record the real
  // git branch name. When they differ (common in multi-repo MCP configs),
  // fall back to the newest indexed commit for this repository on any branch.
  const anyBranch = await repo.listCommits(conn, null, repository, COMMIT_RESOLUTION_ROW_CAP);
  if (anyBranch.length === 0) {
    return {
      kind: 'missing',
      message:
        `(no indexed commits for repository=${repository} — ` +
        `run \`codeindex publish\` from that repo first, or call \`list_commits\` ` +
        `to see which repository/branch pairs are indexed)`,
    };
  }

  const latest = anyBranch[0]!;
  const onPickedBranch = anyBranch.filter((r) => r.branch === latest.branch);
  const distinctOnPicked = new Set(onPickedBranch.map((r) => r.commitSha));
  if (distinctOnPicked.size > 1) {
    return {
      kind: 'missing',
      message: ambiguousMessage(repository, latest.branch, [...distinctOnPicked].sort()),
    };
  }

  return {
    kind: 'resolved',
    commitSha: latest.commitSha,
    branch: latest.branch,
    repository: latest.repository.length > 0 ? latest.repository : repository,
  };
}

/**
 * One-line header all three search tools prepend so the caller can see which
 * repository / branch / commit was actually queried.
 */
export function formatResolutionHeader(resolved: Extract<ResolveCommitResult, { kind: 'resolved' }>): string {
  // `repository` can no longer be null on a resolved result — `resolveCommit`
  // refuses unknown-repo queries up front. The fallback is defensive only.
  const repoLabel = resolved.repository ?? '(unknown)';
  const shortSha = resolved.commitSha.slice(0, 12);
  return `repository: ${repoLabel}  branch: ${resolved.branch}  commit: ${shortSha}\n---\n`;
}

import { z } from 'zod';
import type { EmbedAdapter } from '../embed.js';
import { formatChunks } from './format.js';
import { resolveCommit, formatResolutionHeader } from './resolution.js';
import { effectiveRepo, pickReader, type ToolDeps } from './registry.js';

export const searchCodeSchema = z.object({
  query: z.string().min(1).describe('Natural-language or code-fragment query to search for.'),
  k: z.number().int().min(1).max(50).optional().default(8).describe('Number of results to return.'),
  area: z.string().optional().describe('Restrict to an area: api | backend | frontend | db | test | docs | tools | pipeline | minikube | root'),
  kind: z.string().optional().describe('Restrict to a chunk kind: class | method | function | component | interface | record | section | statement | message | service | rpc | file | window'),
  language: z.string().optional().describe('Restrict to a language: csharp | typescript | tsx | javascript | jsx | markdown | sql | protobuf | json'),
  repository: z.string().optional().describe('Repository to query (e.g. owner/repo). Defaults to git origin when it matches a registered name (including auto-discovered file index repos), else the first registration. REQUIRED when auto-detection failed — the tool refuses the call rather than guess. Resolve from chat context or ask the user.'),
  commit: z.string().optional().describe('Full commit SHA. When several distinct SHAs are indexed for the same repository and branch, this argument is required — use list_commits or ask the user. If only one SHA exists for that pair, it defaults automatically.'),
});

export type SearchCodeInput = z.infer<typeof searchCodeSchema>;

export interface SearchCodeDeps {
  embedder: EmbedAdapter;
  defaultBranch: string;
  currentRepository: string | null;
}

export async function searchCode(input: SearchCodeInput, deps: ToolDeps): Promise<string> {
  const { embedder, defaultBranch, currentRepository } = deps;
  const repoName = effectiveRepo(input.repository, currentRepository);
  const { factory, repo } = pickReader(deps, repoName);
  await using conn = await factory.getConnection();

  const resolved = await resolveCommit(conn, repo, {
    branch: defaultBranch,
    repositoryInput: input.repository,
    currentRepository,
    commitOverride: input.commit,
  });
  if (resolved.kind === 'missing') return resolved.message;

  const vector = await embedder.embedQuery(input.query);
  if (vector.length !== embedder.dim) {
    throw new Error(`Query embedding has dim ${vector.length}, expected ${embedder.dim}`);
  }

  const chunks = await repo.searchByEmbedding(conn, resolved.commitSha, vector, input.k, {
    area: input.area,
    kind: input.kind,
    language: input.language,
  });

  return formatResolutionHeader(resolved) + formatChunks(chunks);
}

import type { CodeMcpConfig } from './config.js';
import { repoFileDir } from './config.js';
import type { DbConnectionFactory } from './db/types.js';
import type { PgReaderRepository } from './db/pgRepository.js';
import { PgConnectionFactory } from './db/connectionFactory.js';
import { PgReaderRepositoryImpl } from './db/pgRepository.js';
import { FileConnectionFactory } from './db/file/fileConnectionFactory.js';
import { FileReaderRepositoryImpl } from './db/file/fileRepository.js';

export interface WiredReader {
  factory: DbConnectionFactory;
  repo: PgReaderRepository;
}

/**
 * Wires the primary backend reader.
 *
 * For the file backend in single-repo (legacy) mode this points to `config.fileDir`
 * (the package-root data directory). In multi-repo mode the callers should use
 * `wireMultiRepoReaders` for the per-repo readers; the primary reader returned
 * here is kept as a fallback / for Postgres usage.
 */
export function wireReader(config: CodeMcpConfig): WiredReader {
  if (config.backend === 'file') {
    // In multi-repo mode we still need a primary WiredReader for the serve()
    // shutdown path. Use the first configured repo's fileDir if available,
    // otherwise fall back to the package-root data directory (legacy).
    const firstRepo = config.repositories[0];
    const dir = firstRepo ? repoFileDir(firstRepo) : config.fileDir;
    return {
      factory: new FileConnectionFactory(dir),
      repo: new FileReaderRepositoryImpl(),
    };
  }
  return {
    factory: new PgConnectionFactory(config.connectionString),
    repo: new PgReaderRepositoryImpl(),
  };
}

/**
 * Builds a per-repository reader map for the file backend multi-repo mode.
 * Keyed by repository name (e.g. "Platform/Rxo.Platform.Web.Sandbox").
 * Each value has its own `FileConnectionFactory` pointing at
 * {@link repoFileDir} for that entry (package `data/` or `{localPath}/.codemcp/data/...`).
 */
export function wireMultiRepoReaders(
  config: CodeMcpConfig,
): Map<string, WiredReader> {
  const result = new Map<string, WiredReader>();
  for (const entry of config.repositories) {
    const dir = repoFileDir(entry);
    result.set(entry.name, {
      factory: new FileConnectionFactory(dir),
      repo: new FileReaderRepositoryImpl(),
    });
  }
  return result;
}

{
  "name": "@agent-local/fsmcp",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "MCP server exposing workspace-scoped filesystem and search tools (read/write/edit/list/glob/grep).",
  "bin": {
    "fsmcp": "./dist/server.js"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "start": "node dist/server.js",
    "dev": "tsc -p tsconfig.json --watch",
    "clean": "node -e \"require('node:fs').rmSync('dist',{recursive:true,force:true})\""
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.0.4",
    "fast-glob": "^3.3.2",
    "zod": "^3.23.8"
  },
  "devDependencies": {
    "@types/node": "^22.10.2",
    "typescript": "^5.7.2"
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "../workspace.js";

export const deleteFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file or directory to delete."),
  recursive: z
    .boolean()
    .optional()
    .default(false)
    .describe(
      "Required true to delete a directory and everything inside it. Ignored for files. " +
        "Deleting a directory without recursive:true is refused as a safety guard."
    ),
});

export type DeleteFileInput = z.infer<typeof deleteFileSchema>;

export interface DeleteFileResult {
  path: string;
  deleted: boolean;
  kind: "file" | "directory";
}

export class DeleteFileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DeleteFileError";
  }
}

export async function deleteFile(
  input: DeleteFileInput,
  workspace: Workspace
): Promise<DeleteFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);

  // Never let a delete remove the workspace root itself — that would wipe the
  // entire sandbox and is almost certainly a mistake, not an intent.
  if (path.resolve(absolutePath) === path.resolve(workspace.root)) {
    throw new DeleteFileError(
      "Refusing to delete the workspace root. Target a specific file or subdirectory instead."
    );
  }

  // Stat without following symlinks so a link is removed as a link, and so a
  // missing path fails loudly rather than silently succeeding.
  let stats;
  try {
    stats = await fs.lstat(absolutePath);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      throw new DeleteFileError(
        `No such file or directory: ${workspace.relativize(absolutePath)}`
      );
    }
    throw err;
  }

  if (stats.isDirectory()) {
    if (!input.recursive) {
      throw new DeleteFileError(
        `${workspace.relativize(absolutePath)} is a directory. ` +
          `Pass recursive: true to delete it and all of its contents.`
      );
    }
    await fs.rm(absolutePath, { recursive: true, force: false });
    return { path: workspace.relativize(absolutePath), deleted: true, kind: "directory" };
  }

  // Regular file or symlink: remove the entry itself.
  await fs.rm(absolutePath, { force: false });
  return { path: workspace.relativize(absolutePath), deleted: true, kind: "file" };
}

import fs from "node:fs/promises";
import { z } from "zod";

import type { Workspace } from "../workspace.js";

export const editFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to edit."),
  old_string: z
    .string()
    .min(1)
    .describe(
      "Exact text to replace. Must match the file's current content byte-for-byte and " +
        "must be unique within the file unless replace_all is true."
    ),
  new_string: z
    .string()
    .describe("Replacement text. May be empty to delete the matched region."),
  replace_all: z
    .boolean()
    .optional()
    .default(false)
    .describe("If true, replace every occurrence of old_string instead of requiring uniqueness."),
});

export type EditFileInput = z.infer<typeof editFileSchema>;

export interface EditFileResult {
  path: string;
  replacements: number;
}

export class EditFileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EditFileError";
  }
}

export async function editFile(
  input: EditFileInput,
  workspace: Workspace
): Promise<EditFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const original = await fs.readFile(absolutePath, "utf8");

  // Disallow editing if the target text never appears in the file.
  // The model must read the file first; otherwise we fail loudly so it can adjust.
  if (!original.includes(input.old_string)) {
    throw new EditFileError(
      `old_string was not found in ${workspace.relativize(absolutePath)}. ` +
        `Read the file first and copy the text exactly, including whitespace.`
    );
  }

  let updated: string;
  let replacements: number;

  if (input.replace_all) {
    const parts = original.split(input.old_string);
    replacements = parts.length - 1;
    updated = parts.join(input.new_string);
  } else {
    const occurrences = countOccurrences(original, input.old_string);

    if (occurrences > 1) {
      throw new EditFileError(
        `old_string appears ${occurrences} times in ${workspace.relativize(
          absolutePath
        )}. Provide more surrounding context to make it unique, or set replace_all: true.`
      );
    }

    updated = original.replace(input.old_string, input.new_string);
    replacements = 1;
  }

  await fs.writeFile(absolutePath, updated, "utf8");

  return {
    path: workspace.relativize(absolutePath),
    replacements,
  };
}

function countOccurrences(haystack: string, needle: string): number {
  if (needle.length === 0) return 0;
  let count = 0;
  let index = 0;
  while ((index = haystack.indexOf(needle, index)) !== -1) {
    count += 1;
    index += needle.length;
  }
  return count;
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "../workspace.js";

export const listDirSchema = z.object({
  path: z
    .string()
    .min(1)
    .default(".")
    .describe("Workspace-relative or absolute directory path. Defaults to the workspace root."),
  include_hidden: z
    .boolean()
    .optional()
    .default(false)
    .describe("If true, include entries that start with a dot (e.g. .git, .env)."),
  max_entries: z
    .number()
    .int()
    .positive()
    .optional()
    .default(500)
    .describe("Cap on the number of entries returned. Defaults to 500."),
});

export type ListDirInput = z.infer<typeof listDirSchema>;

export interface DirEntry {
  name: string;
  type: "file" | "directory" | "symlink" | "other";
  size_bytes?: number;
}

export interface ListDirResult {
  path: string;
  total_entries: number;
  truncated: boolean;
  entries: DirEntry[];
}

export async function listDir(
  input: ListDirInput,
  workspace: Workspace
): Promise<ListDirResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const raw = await fs.readdir(absolutePath, { withFileTypes: true });

  const filtered = input.include_hidden
    ? raw
    : raw.filter((entry) => !entry.name.startsWith("."));

  // Sort directories first, then files, then alphabetically — easier for the model to scan.
  filtered.sort((a, b) => {
    const aIsDir = a.isDirectory();
    const bIsDir = b.isDirectory();
    if (aIsDir !== bIsDir) return aIsDir ? -1 : 1;
    return a.name.localeCompare(b.name);
  });

  const limit = input.max_entries ?? 500;
  const truncated = filtered.length > limit;
  const visibleEntries = filtered.slice(0, limit);

  const entries: DirEntry[] = await Promise.all(
    visibleEntries.map(async (entry) => {
      const entryPath = path.join(absolutePath, entry.name);
      const type = classifyEntry(entry);

      // Only stat files — directory sizes aren't meaningful here and we'd pay extra IO.
      let sizeBytes: number | undefined;
      if (type === "file") {
        try {
          const stat = await fs.stat(entryPath);
          sizeBytes = stat.size;
        } catch {
          sizeBytes = undefined;
        }
      }

      return { name: entry.name, type, size_bytes: sizeBytes };
    })
  );

  return {
    path: workspace.relativize(absolutePath),
    total_entries: filtered.length,
    truncated,
    entries,
  };
}

function classifyEntry(entry: import("node:fs").Dirent): DirEntry["type"] {
  if (entry.isDirectory()) return "directory";
  if (entry.isFile()) return "file";
  if (entry.isSymbolicLink()) return "symlink";
  return "other";
}

import fs from "node:fs/promises";
import { z } from "zod";

import type { Workspace } from "../workspace.js";

export const readFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to read."),
  start_line: z
    .number()
    .int()
    .positive()
    .optional()
    .describe("1-indexed first line to return. Omit to start at line 1."),
  end_line: z
    .number()
    .int()
    .positive()
    .optional()
    .describe("1-indexed last line to return (inclusive). Omit to read to EOF."),
});

export type ReadFileInput = z.infer<typeof readFileSchema>;

export interface ReadFileResult {
  path: string;
  total_lines: number;
  returned_range: { start: number; end: number };
  content: string;
}

export async function readFile(
  input: ReadFileInput,
  workspace: Workspace
): Promise<ReadFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);
  const raw = await fs.readFile(absolutePath, "utf8");

  const lines = raw.split(/\r?\n/);
  const totalLines = lines.length;

  const startLine = input.start_line ?? 1;
  const endLine = Math.min(input.end_line ?? totalLines, totalLines);

  if (startLine > totalLines) {
    return {
      path: workspace.relativize(absolutePath),
      total_lines: totalLines,
      returned_range: { start: startLine, end: startLine - 1 },
      content: "",
    };
  }

  const slice = lines.slice(startLine - 1, endLine).join("\n");

  return {
    path: workspace.relativize(absolutePath),
    total_lines: totalLines,
    returned_range: { start: startLine, end: endLine },
    content: slice,
  };
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";

import type { Workspace } from "../workspace.js";

export const writeFileSchema = z.object({
  path: z
    .string()
    .min(1)
    .describe("Workspace-relative or absolute path to the file to create or overwrite."),
  content: z
    .string()
    .describe("Full file content. The file is written verbatim, no extra newline appended."),
  create_directories: z
    .boolean()
    .optional()
    .default(true)
    .describe("If true (default), create any missing parent directories."),
});

export type WriteFileInput = z.infer<typeof writeFileSchema>;

export interface WriteFileResult {
  path: string;
  bytes_written: number;
  created: boolean;
}

export async function writeFile(
  input: WriteFileInput,
  workspace: Workspace
): Promise<WriteFileResult> {
  const absolutePath = workspace.resolveSafe(input.path);

  // Track whether the file existed beforehand so we can report create vs overwrite.
  const existedBefore = await fileExists(absolutePath);

  if (input.create_directories !== false) {
    await fs.mkdir(path.dirname(absolutePath), { recursive: true });
  }

  await fs.writeFile(absolutePath, input.content, "utf8");

  const stat = await fs.stat(absolutePath);

  return {
    path: workspace.relativize(absolutePath),
    bytes_written: stat.size,
    created: !existedBefore,
  };
}

async function fileExists(absolutePath: string): Promise<boolean> {
  try {
    await fs.access(absolutePath);
    return true;
  } catch {
    return false;
  }
}

interface JsonSchemaNode {
  type?: string;
  description?: string;
  enum?: string[];
  default?: unknown;
  minimum?: number;
  exclusiveMinimum?: number;
  properties?: Record<string, JsonSchemaNode>;
  required?: string[];
  additionalProperties?: boolean;
}

export function zodToJsonSchema(schema: ZodTypeAny): JsonSchemaNode {
  return convertNode(schema);
}

function convertNode(node: ZodTypeAny): JsonSchemaNode {
  const description = node.description;

  if (node instanceof z.ZodObject) {
    return convertObject(node, description);
  }
  if (node instanceof z.ZodString) {
    return withDescription({ type: "string" }, description);
  }
  if (node instanceof z.ZodNumber) {
    return convertNumber(node, description);
  }
  if (node instanceof z.ZodBoolean) {
    return withDescription({ type: "boolean" }, description);
  }
  if (node instanceof z.ZodEnum) {
    return withDescription({ type: "string", enum: [...node.options] }, description);
  }
  if (node instanceof z.ZodOptional) {
    return convertNode(node.unwrap());
  }
  if (node instanceof z.ZodDefault) {
    const inner = convertNode(node.removeDefault());
    inner.default = node._def.defaultValue();
    return withDescription(inner, description ?? inner.description);
  }

  // Unknown node type — return an empty schema so callers don't blow up.
  return withDescription({}, description);
}

function convertObject(node: z.ZodObject<z.ZodRawShape>, description?: string): JsonSchemaNode {
  const shape = node.shape;
  const properties: Record<string, JsonSchemaNode> = {};
  const required: string[] = [];

  for (const [key, child] of Object.entries(shape)) {
    properties[key] = convertNode(child as ZodTypeAny);

    // A property is "required" only if it has neither .optional() nor .default().
    if (!isOptionalOrDefaulted(child as ZodTypeAny)) {
      required.push(key);
    }
  }

  const result: JsonSchemaNode = {
    type: "object",
    properties,
    additionalProperties: false,
  };

  if (required.length > 0) result.required = required;
  return withDescription(result, description);
}

function convertNumber(node: z.ZodNumber, description?: string): JsonSchemaNode {
  const checks = node._def.checks ?? [];
  const isInt = checks.some((check) => check.kind === "int");

  const schema: JsonSchemaNode = { type: isInt ? "integer" : "number" };

  for (const check of checks) {
    if (check.kind === "min") {
      if (check.inclusive) schema.minimum = check.value;
      else schema.exclusiveMinimum = check.value;
    }
  }

  return withDescription(schema, description);
}

function isOptionalOrDefaulted(node: ZodTypeAny): boolean {
  return node instanceof z.ZodOptional || node instanceof z.ZodDefault;
}

function withDescription(schema: JsonSchemaNode, description: string | undefined): JsonSchemaNode {
  if (description) schema.description = description;
  return schema;
}

export interface GlobResult {
  pattern: string;
  cwd: string;
  matches: string[];
  truncated: boolean;
}

export async function glob(input: GlobInput, workspace: Workspace): Promise<GlobResult> {
  const cwdAbsolute = workspace.resolveSafe(input.cwd ?? ".");
  const limit = input.max_results ?? 500;

  // fast-glob gives us paths relative to `cwd` when `absolute: false`.
  // We then turn them into workspace-relative paths so the model always
  // sees the same coordinate system.
  const rawMatches = await fastGlob(input.pattern, {
    cwd: cwdAbsolute,
    dot: input.include_hidden,
    onlyFiles: false,
    followSymbolicLinks: false,
    absolute: true,
    suppressErrors: true,
  });

  const matches: string[] = [];
  for (const absolute of rawMatches) {
    // Defence in depth: confirm every match is still inside the workspace.
    // fast-glob shouldn't escape, but symlinks and "../" patterns are worth guarding against.
    try {
      const safeAbsolute = workspace.resolveSafe(absolute);
      matches.push(workspace.relativize(safeAbsolute));
    } catch {
      continue;
    }

    if (matches.length >= limit) break;
  }

  return {
    pattern: input.pattern,
    cwd: workspace.relativize(cwdAbsolute),
    matches,
    truncated: rawMatches.length > matches.length,
  };
}

export interface GrepMatch {
  path: string;
  line_number: number;
  line: string;
}

export interface GrepResult {
  pattern: string;
  path_glob: string;
  matches: GrepMatch[];
  truncated: boolean;
  files_scanned: number;
}

// Cheap binary-file heuristic: if the first 4 KB contains a null byte we treat
// it as binary and skip it. Misses obscure formats but is fast and safe.
const BINARY_PROBE_BYTES = 4096;

export async function grep(input: GrepInput, workspace: Workspace): Promise<GrepResult> {
  const root = workspace.root;
  const limit = input.max_results ?? 200;

  const flags = input.case_insensitive ? "i" : "";
  let regex: RegExp;
  try {
    regex = new RegExp(input.pattern, flags);
  } catch (err) {
    throw new Error(
      `Invalid regular expression "${input.pattern}": ${(err as Error).message}`
    );
  }

  const candidatePaths = await fastGlob(input.path_glob ?? "**/*", {
    cwd: root,
    dot: false,
    onlyFiles: true,
    followSymbolicLinks: false,
    absolute: true,
    suppressErrors: true,
    ignore: ["**/node_modules/**", "**/.git/**", "**/dist/**"],
  });

  const matches: GrepMatch[] = [];
  let filesScanned = 0;
  let truncated = false;

  for (const absolutePath of candidatePaths) {
    let safeAbsolute: string;
    try {
      safeAbsolute = workspace.resolveSafe(absolutePath);
    } catch {
      continue;
    }

    if (await looksBinary(safeAbsolute)) continue;

    let content: string;
    try {
      content = await fs.readFile(safeAbsolute, "utf8");
    } catch {
      continue;
    }
    filesScanned += 1;

    const relativePath = workspace.relativize(safeAbsolute);
    const lines = content.split(/\r?\n/);

    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i];
      if (regex.test(line)) {
        matches.push({ path: relativePath, line_number: i + 1, line });
        if (matches.length >= limit) {
          truncated = true;
          break;
        }
      }
    }

    if (truncated) break;
  }

  return {
    pattern: input.pattern,
    path_glob: input.path_glob ?? "**/*",
    matches,
    truncated,
    files_scanned: filesScanned,
  };
}

async function looksBinary(absolutePath: string): Promise<boolean> {
  try {
    const handle = await fs.open(absolutePath, "r");
    try {
      const buffer = Buffer.alloc(BINARY_PROBE_BYTES);
      const { bytesRead } = await handle.read(buffer, 0, BINARY_PROBE_BYTES, 0);
      for (let i = 0; i < bytesRead; i += 1) {
        if (buffer[i] === 0) return true;
      }
      return false;
    } finally {
      await handle.close();
    }
  } catch {
    return true;
  }
}

#!/usr/bin/env node
/**
 * MCP tools server.
 *
 * This process is launched by the agent (or by any MCP-capable client that
 * reads mcp.json) over stdio. It registers a small set of filesystem and
 * search tools, all confined to the workspace directory configured via the
 * AGENT_WORKSPACE environment variable.
 *
 * Architecture role: Repository / External layer. No agent logic here — just
 * pure tool handlers and a thin MCP transport wrapper.
 */

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  type CallToolRequest,
  type ListToolsResult,
} from "@modelcontextprotocol/sdk/types.js";
import { zodToJsonSchema } from "./schema-helpers.js";

import { workspaceFromEnv, WorkspaceViolationError } from "./workspace.js";

import { readFile, readFileSchema } from "./fs/read-file.js";
import { writeFile, writeFileSchema } from "./fs/write-file.js";
import { editFile, editFileSchema, EditFileError } from "./fs/edit-file.js";
import { deleteFile, deleteFileSchema, DeleteFileError } from "./fs/delete-file.js";
import { listDir, listDirSchema } from "./fs/list-dir.js";
import { glob, globSchema } from "./search/glob.js";
import { grep, grepSchema } from "./search/grep.js";

import type { ZodTypeAny } from "zod";
import type { Workspace } from "./workspace.js";

/**
 * A registered tool, ready to be exposed over MCP.
 *
 * `defineTool` accepts a typed schema + typed handler and packs them into a
 * uniform shape: the runtime handler takes `unknown` arguments and does the
 * Zod parse itself. This keeps the tools array a single concrete type so
 * `Array.find` and `Array.map` don't tangle TypeScript with a generic union.
 */
interface RegisteredTool {
  name: string;
  description: string;
  inputSchema: ZodTypeAny;
  invoke: (rawArguments: unknown, workspace: Workspace) => Promise<unknown>;
}

function defineTool<Schema extends ZodTypeAny>(definition: {
  name: string;
  description: string;
  schema: Schema;
  handler: (input: ReturnType<Schema["parse"]>, workspace: Workspace) => Promise<unknown>;
}): RegisteredTool {
  return {
    name: definition.name,
    description: definition.description,
    inputSchema: definition.schema,
    invoke: async (rawArguments, workspace) => {
      const parsedInput = definition.schema.parse(rawArguments ?? {});
      return definition.handler(parsedInput, workspace);
    },
  };
}

async function main(): Promise<void> {
  const workspace = await workspaceFromEnv();

  const tools = [
    defineTool({
      name: "read_file",
      description:
        "Read a UTF-8 text file from the workspace. Supports optional line ranges. " +
        "Returns total_lines, the returned_range, and the file content.",
      schema: readFileSchema,
      handler: (input, ws) => readFile(input, ws),
    }),
    defineTool({
      name: "write_file",
      description:
        "Create or overwrite a UTF-8 text file in the workspace. Parent directories are " +
        "created automatically unless create_directories is set to false.",
      schema: writeFileSchema,
      handler: (input, ws) => writeFile(input, ws),
    }),
    defineTool({
      name: "edit_file",
      description:
        "Replace an exact substring within an existing file. The match must be unique " +
        "unless replace_all is true. Fails if old_string is not found verbatim.",
      schema: editFileSchema,
      handler: (input, ws) => editFile(input, ws),
    }),
    defineTool({
      name: "delete_file",
      description:
        "Delete a file or directory in the workspace. Files are removed directly; " +
        "deleting a directory requires recursive: true and removes all of its contents. " +
        "Refuses to delete the workspace root and fails if the path does not exist.",
      schema: deleteFileSchema,
      handler: (input, ws) => deleteFile(input, ws),
    }),
    defineTool({
      name: "list_dir",
      description:
        "List the contents of a directory inside the workspace. Directories are returned " +
        "first, then files, alphabetically.",
      schema: listDirSchema,
      handler: (input, ws) => listDir(input, ws),
    }),
    defineTool({
      name: "glob",
      description:
        'Find files in the workspace by glob pattern (e.g. "src/**/*.ts"). Returns paths ' +
        "relative to the workspace root.",
      schema: globSchema,
      handler: (input, ws) => glob(input, ws),
    }),
    defineTool({
      name: "grep",
      description:
        "Search file contents in the workspace using a JavaScript regular expression. " +
        "Skips binary files, node_modules, .git, and dist by default.",
      schema: grepSchema,
      handler: (input, ws) => grep(input, ws),
    }),
  ] as const;

  // Build the table the MCP list_tools handler returns: each entry has a JSON Schema
  // derived from the underlying Zod schema so MCP clients (and Ollama, via the bridge)
  // can pass arguments correctly. Every tool input is a ZodObject at the top level,
  // so the converter always produces `type: "object"` here — we cast accordingly to
  // satisfy the SDK's literal-typed `inputSchema` field.
  const toolListing: ListToolsResult = {
    tools: tools.map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: zodToJsonSchema(tool.inputSchema) as ListToolsResult["tools"][number]["inputSchema"],
    })),
  };

  const server = new Server(
    {
      name: "fsmcp",
      version: "0.1.0",
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  server.setRequestHandler(ListToolsRequestSchema, async () => toolListing);

  server.setRequestHandler(CallToolRequestSchema, async (request: CallToolRequest) => {
    const toolName = request.params.name;
    const tool = tools.find((candidate) => candidate.name === toolName);

    if (!tool) {
      return {
        isError: true,
        content: [
          {
            type: "text" as const,
            text: `Unknown tool: ${toolName}`,
          },
        ],
      };
    }

    try {
      const result = await tool.invoke(request.params.arguments, workspace);

      return {
        content: [
          {
            type: "text" as const,
            text: JSON.stringify(result, null, 2),
          },
        ],
      };
    } catch (err) {
      return {
        isError: true,
        content: [
          {
            type: "text" as const,
            text: formatToolError(err),
          },
        ],
      };
    }
  });

  const transport = new StdioServerTransport();
  await server.connect(transport);
}

function formatToolError(err: unknown): string {
  if (err instanceof WorkspaceViolationError) {
    return `Workspace violation: ${err.message}`;
  }
  if (err instanceof EditFileError) {
    return `Edit failed: ${err.message}`;
  }
  if (err instanceof DeleteFileError) {
    return `Delete failed: ${err.message}`;
  }
  if (err instanceof Error) {
    return `${err.name}: ${err.message}`;
  }
  return `Unknown error: ${String(err)}`;
}

main().catch((err) => {
  // Surfaces startup failures to whoever launched us (the parent agent).
  // We deliberately write to stderr so it doesn't corrupt the MCP stdio channel.
  process.stderr.write(`[fsmcp] fatal: ${(err as Error).stack ?? err}\n`);
  process.exit(1);
});

export class WorkspaceViolationError extends Error {
  constructor(requestedPath: string, workspaceRoot: string) {
    super(
      `Path "${requestedPath}" resolves outside the workspace root "${workspaceRoot}". ` +
        `Refusing the operation.`
    );
    this.name = "WorkspaceViolationError";
  }
}

export interface Workspace {
  readonly root: string;
  resolveSafe(userPath: string): string;
  relativize(absolutePath: string): string;
}

function resolveSafe(userPath: string): string {
  // Treat a bare "." or "" as "the workspace root itself".
  const candidate = userPath === "" || userPath === "." ? root : userPath;

  // If the caller passed a relative path, anchor it at the workspace root.
  const absolute = path.isAbsolute(candidate)
    ? path.resolve(candidate)
    : path.resolve(root, candidate);

  // Normalise both sides so "C:\\Foo" and "c:\\foo\\" compare correctly on Windows.
  const normalisedRoot = path.resolve(root) + path.sep;
  const normalisedAbsolute = absolute + path.sep;

  const isInside =
    normalisedAbsolute === normalisedRoot ||
    normalisedAbsolute.startsWith(normalisedRoot);

  if (!isInside) {
    throw new WorkspaceViolationError(userPath, root);
  }

  return absolute;
}

function relativize(absolutePath: string): string {
  const rel = path.relative(root, absolutePath);
  return rel === "" ? "." : rel;
}

/**
 * Convenience: read the workspace root from the environment, defaulting
 * to the process's current working directory.
 */
export async function workspaceFromEnv(): Promise<Workspace> {
  const raw = process.env.AGENT_WORKSPACE ?? ".";
  const workspace = createWorkspace(raw);

  // Confirm the directory exists so we fail fast on misconfiguration
  // rather than on the first tool call.
  await fs.access(workspace.root);
  return workspace;
}

